INSERT INTO `elixir_ontology` VALUES (1,'EDAM_Topic','{\"text\": \"Topic\", \"data\": {\"uri\": \"http://edamontology.org/topic_0003\"}, \"definition\": \"A category denoting a rather broad domain or field of interest, of study, application, work, data, or technology. Topics have no clearly defined borders between each other.\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"text\": \"Informatics\", \"data\": {\"uri\": \"http://edamontology.org/topic_0605\"}, \"children\": [{\"text\": \"Ontology and terminology\", \"data\": {\"uri\": \"http://edamontology.org/topic_0089\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [\"Applied ontology\", \"Ontologies\", \"Ontology\", \"Ontology relations\", \"Terminology\", \"Upper ontology\"], \"replaced_by\": [], \"consider\": [], \"definition\": \"The conceptualisation, categorisation and nomenclature (naming) of entities or phenomena within biology or bioinformatics. This includes formal ontologies, controlled vocabularies, structured glossary, symbols and terminology or other related resource.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"Bioinformatics\", \"data\": {\"uri\": \"http://edamontology.org/topic_0091\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"The archival, curation, processing and analysis of complex biological data.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"Laboratory information management\", \"data\": {\"uri\": \"http://edamontology.org/topic_0607\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [\"Laboratory resources\"], \"replaced_by\": [], \"consider\": [], \"definition\": \"Laboratory management and resources, for example, catalogues of biological resources for use in the lab including cell lines, viruses, plasmids, phages, DNA probes and primers and so on.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"Cheminformatics\", \"data\": {\"uri\": \"http://edamontology.org/topic_2258\"}, \"children\": [], \"exact_synonyms\": [\"Chemical informatics\", \"Chemoinformatics\"], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"The application of information technology to chemistry in biological research environment.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"Medical informatics\", \"data\": {\"uri\": \"http://edamontology.org/topic_3063\"}, \"children\": [], \"exact_synonyms\": [\"Biomedical informatics\", \"Clinical informatics\", \"Health and disease\", \"Health informatics\", \"Healthcare informatics\"], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"The application of information technology to health, disease and biomedicine.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"Biological databases\", \"data\": {\"uri\": \"http://edamontology.org/topic_3071\"}, \"children\": [{\"text\": \"Data submission, annotation and curation\", \"data\": {\"uri\": \"http://edamontology.org/topic_0219\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [\"Data curation\", \"Data provenance\", \"Database curation\"], \"replaced_by\": [], \"consider\": [], \"definition\": \"Deposition and curation of database accessions, including annotation, typically with terms from a controlled vocabulary.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"Workflows\", \"data\": {\"uri\": \"http://edamontology.org/topic_0769\"}, \"children\": [], \"exact_synonyms\": [\"Pipelines\"], \"narrow_synonyms\": [\"Software integration\", \"Tool integration\", \"Tool interoperability\"], \"replaced_by\": [], \"consider\": [], \"definition\": \"Biological or biomedical analytical workflows or pipelines.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"Data acquisition\", \"data\": {\"uri\": \"http://edamontology.org/topic_3077\"}, \"children\": [], \"exact_synonyms\": [\"Data collection\"], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"The acquisition of data, typically measurements of physical systems using any type of sampling system, or by another other means.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"Data security\", \"data\": {\"uri\": \"http://edamontology.org/topic_3263\"}, \"children\": [], \"exact_synonyms\": [\"Data privacy\"], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"The protection of data, such as patient health data, from damage or unwanted access from unauthorised users.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"Data identity and mapping\", \"data\": {\"uri\": \"http://edamontology.org/topic_3345\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"Topic concerning the identity of biological entities, or reports on such entities, and the mapping of entities and records in different databases.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"Data architecture, analysis and design\", \"data\": {\"uri\": \"http://edamontology.org/topic_3365\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [\"Data analysis\", \"Data architecture\", \"Data design\"], \"replaced_by\": [], \"consider\": [], \"definition\": \"The development of policies, models and standards that cover data acquisition, storage and integration, such that it can be put to use, typically through a process of systematically applying statistical and / or logical techniques to describe, illustrate, summarise or evaluate data.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"Data integration and warehousing\", \"data\": {\"uri\": \"http://edamontology.org/topic_3366\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [\"Data integration\", \"Data warehousing\"], \"replaced_by\": [], \"consider\": [], \"definition\": \"The combination and integration of data from different sources, for example into a central repository or warehouse, to provide users with a unified view of these data.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"Database management\", \"data\": {\"uri\": \"http://edamontology.org/topic_3489\"}, \"children\": [], \"exact_synonyms\": [\"Database administration\"], \"narrow_synonyms\": [\"Content management\", \"Data maintenance\", \"Document management\", \"Document, record and content management\", \"File management\", \"Record management\"], \"replaced_by\": [], \"consider\": [], \"definition\": \"The general handling of data stored in digital archives such as databanks, databases proper, web portals and other data resources.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"Data governance\", \"data\": {\"uri\": \"http://edamontology.org/topic_3571\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [\"Data stewardship\"], \"replaced_by\": [], \"consider\": [], \"definition\": \"The control of data entry and maintenance to ensure the data meets defined standards, qualities or constraints.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"Data quality management\", \"data\": {\"uri\": \"http://edamontology.org/topic_3572\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [\"Data clean-up\", \"Data cleaning\", \"Data integrity\", \"Data quality\"], \"replaced_by\": [], \"consider\": [], \"definition\": \"The quality, integrity, and cleaning up of data.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}], \"exact_synonyms\": [\"Data management\", \"Databases and information systems\", \"Information systems\"], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"The development and use of architectur