ri\": \"http://edamontology.org/topic_3077\", \"exact_synonyms\": [\"Data collection\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The protection of data, such as patient health data, from damage or unwanted access from unauthorised users.\", \"path\": [{\"name\": \"Topic||Informatics||Biological databases||Data security\", \"key\": \"topic_0003||topic_0605||topic_3071||topic_3263\"}], \"name\": \"Data security\", \"uri\": \"http://edamontology.org/topic_3263\", \"exact_synonyms\": [\"Data privacy\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Topic concerning the identity of biological entities, or reports on such entities, and the mapping of entities and records in different databases.\", \"path\": [{\"name\": \"Topic||Informatics||Biological databases||Data identity and mapping\", \"key\": \"topic_0003||topic_0605||topic_3071||topic_3345\"}], \"name\": \"Data identity and mapping\", \"uri\": \"http://edamontology.org/topic_3345\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The development of policies, models and standards that cover data acquisition, storage and integration, such that it can be put to use, typically through a process of systematically applying statistical and / or logical techniques to describe, illustrate, summarise or evaluate data.\", \"path\": [{\"name\": \"Topic||Informatics||Biological databases||Data architecture, analysis and design\", \"key\": \"topic_0003||topic_0605||topic_3071||topic_3365\"}], \"name\": \"Data architecture, analysis and design\", \"uri\": \"http://edamontology.org/topic_3365\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Data analysis\", \"Data architecture\", \"Data design\"], \"children\": []}, {\"definition\": \"The combination and integration of data from different sources, for example into a central repository or warehouse, to provide users with a unified view of these data.\", \"path\": [{\"name\": \"Topic||Informatics||Biological databases||Data integration and warehousing\", \"key\": \"topic_0003||topic_0605||topic_3071||topic_3366\"}], \"name\": \"Data integration and warehousing\", \"uri\": \"http://edamontology.org/topic_3366\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Data integration\", \"Data warehousing\"], \"children\": []}, {\"definition\": \"The general handling of data stored in digital archives such as databanks, databases proper, web portals and other data resources.\", \"path\": [{\"name\": \"Topic||Informatics||Biological databases||Database management\", \"key\": \"topic_0003||topic_0605||topic_3071||topic_3489\"}], \"name\": \"Database management\", \"uri\": \"http://edamontology.org/topic_3489\", \"exact_synonyms\": [\"Database administration\"], \"narrow_synonyms\": [\"Content management\", \"Data maintenance\", \"Document management\", \"Document, record and content management\", \"File management\", \"Record management\"], \"children\": []}, {\"definition\": \"The control of data entry and maintenance to ensure the data meets defined standards, qualities or constraints.\", \"path\": [{\"name\": \"Topic||Informatics||Biological databases||Data governance\", \"key\": \"topic_0003||topic_0605||topic_3071||topic_3571\"}], \"name\": \"Data governance\", \"uri\": \"http://edamontology.org/topic_3571\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Data stewardship\"], \"children\": []}, {\"definition\": \"The quality, integrity, and cleaning up of data.\", \"path\": [{\"name\": \"Topic||Informatics||Biological databases||Data quality management\", \"key\": \"topic_0003||topic_0605||topic_3071||topic_3572\"}], \"name\": \"Data quality management\", \"uri\": \"http://edamontology.org/topic_3572\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Data clean-up\", \"Data cleaning\", \"Data integrity\", \"Data quality\"], \"children\": []}, {\"definition\": \"Immunoinformatics is the field of computational biology that deals with the study of immunoloogical question