onyms\": [], \"narrow_synonyms\": [\"Eye disoders\"], \"children\": []}, {\"definition\": \"The branch of medicine that deals with the medical care of infants, children and adolescents.\", \"path\": [{\"name\": \"Topic||Medicine||Paediatrics\", \"key\": \"topic_0003||topic_3303||topic_3418\"}], \"name\": \"Paediatrics\", \"uri\": \"http://edamontology.org/topic_3418\", \"exact_synonyms\": [\"Child health\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The branch of medicine that deals with the mangement of mental illness, emotional disturbance and abnormal behaviour.\", \"path\": [{\"name\": \"Topic||Medicine||Psychiatry\", \"key\": \"topic_0003||topic_3303||topic_3419\"}], \"name\": \"Psychiatry\", \"uri\": \"http://edamontology.org/topic_3419\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Psychiatric disorders\"], \"children\": []}, {\"definition\": \"The health of the reproductive processes, functions and systems at all stages of life.\", \"path\": [{\"name\": \"Topic||Medicine||Reproductive health\", \"key\": \"topic_0003||topic_3303||topic_3420\"}], \"name\": \"Reproductive health\", \"uri\": \"http://edamontology.org/topic_3420\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Andrology\", \"Family planning\", \"Fertility medicine\", \"Reproductive disorders\"], \"children\": []}, {\"definition\": \"The use of operative, manual and instrumental techniques on a patient to investigate and/or treat a pathological condition or help improve bodily function or appearance.\", \"path\": [{\"name\": \"Topic||Medicine||Surgery\", \"key\": \"topic_0003||topic_3303||topic_3421\"}], \"name\": \"Surgery\", \"uri\": \"http://edamontology.org/topic_3421\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Transplantation\"], \"children\": []}, {\"definition\": \"The branches of medicine and physiology focussing on the function and disorders of the urinary system in males and females, the reproductive system in males, and the kidney.\", \"path\": [{\"name