scovery||Compound libraries and screening\", \"key\": \"topic_0003||topic_3344||topic_3376||topic_3336||topic_3343\"}, \"name\": \"Compound libraries and screening\", \"uri\": \"http://edamontology.org/topic_3343\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Chemical library\", \"Chemical screening\", \"Compound library\", \"Small chemical compounds libraries\", \"Small compounds libraries\", \"Target identification and validation\"], \"children\": []}, {\"definition\": \"The process of bringing a new drug to market once a lead compounds has been identified through drug discovery.\", \"path\": [{\"name\": \"Topic||Biomedical science||Medicines research and development||Drug development\", \"key\": \"topic_0003||topic_3344||topic_3376||topic_3373\"}], \"name\": \"Drug development\", \"uri\": \"http://edamontology.org/topic_3373\", \"exact_synonyms\": [\"Drug development science\", \"Medicine development\", \"Medicines development\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The process of formulating and administering a pharmaceutical compound to achieve a therapeutic effect.\", \"path\": [{\"name\": \"Topic||Biomedical science||Medicines research and development||Biotherapeutics\", \"key\": \"topic_0003||topic_3344||topic_3376||topic_3374\"}], \"name\": \"Biotherapeutics\", \"uri\": \"http://edamontology.org/topic_3374\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The study of how a drug interacts with the body.\", \"path\": [{\"name\": \"Topic||Biomedical science||Medicines research and development||Drug metabolism\", \"key\": \"topic_0003||topic_3344||topic_3376||topic_3375\"}], \"name\": \"Drug metabolism\", \"uri\": \"http://edamontology.org/topic_3375\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"ADME\", \"Drug absorption\", \"Drug distribution\", \"Drug excretion\", \"Pharmacodynamics\", \"Pharmacokinetics\", \"Pharmacokinetics and pharmacodynamics\"], \"children\": []}, {\"definition\": \"The safety (or lack) of drugs and other medical interventions.\", \"path\": [{\"name\": \"Topic||Biomedical science||Medicines research and development||Safety sciences\", \"key\": \"topic_0003||topic_3344||topic_3376||topic_3377\"}], \"name\": \"Safety sciences\", \"uri\": \"http://edamontology.org/topic_3377\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Drug safety\"], \"children\": [{\"name\": \"Toxicology\", \"uri\": \"http://edamontology.org/topic_2840\"}, {\"name\": \"Pharmacovigilance\", \"uri\": \"http://edamontology.org/topic_3378\"}]}, {\"definition\": \"Toxins and the adverse effects of these chemical substances on living organisms.\", \"path\": {\"name\": \"Topic||Biomedical science||Medicines research and development||Safety sciences||Toxicology\", \"key\": \"topic_0003||topic_3344||topic_3376||topic_3377||topic_2840\"}, \"name\": \"Toxicology\", \"uri\": \"http://edamontology.org/topic_2840\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Computational toxicology\", \"Toxicoinformatics\"], \"children\": []}, {\"definition\": \"The detection, assesment, understanding and prevention of adverse effects of medicines.\", \"path\": [{\"name\": \"Topic||Biomedical science||Medicines research and development||Safety sciences||Pharmacovigilance\", \"key\": \"topic_0003||topic_3344||topic_3376||topic_3377||topic_3378\"}], \"name\": \"Pharmacovigilance\", \"uri\": \"http://edamontology.org/topic_3378\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The testing of new medicines, vaccines or procedures on animals (preclinical) and humans (clinical) prior to their approval by regulatory authorities.\", \"path\": [{\"name\": \"Topic||Biomedical science||Medicines research and development||Preclinical and clinical studies\", \"key\": \"topic_0003||topic_3344||topic_3376||topic_3379\"}, {\"name\": \"Topic||Experimental design and studies||Preclinical and clinical studies\", \"key\": \"topic_0003||topic_3678||topic_3379\"}], \"name\": \"Preclinical and clinical studies\", \"uri\": \"http://edamontology.org/topic_3379\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Clinical studies\", \"Clinical study\", \"Clinical trial\", \"Drug trials\", \"Preclinical studies\", \"Preclinical study\"], \"children\": []}, {\"definition\": \"The processes that need to be in place to ensure the quality of products for human or animal use.\", \"path\": [{\"name\": \"Topic||Biomedical science||Medicines research and development||Quality affairs\", \"key\": \"topic_0003||topic_3344||topic_3376||topic_3393\"}], \"name\": \"Quality affairs\", \"uri\": \"http://edamontology.org/topic_3393\", \"exact_synonyms\": [\"Quality assurance\"], \"narrow_synonyms\": [\"Good clinical practice\", \"Good laboratory practice\", \"Good manufacturing practice\"], \"children\": []}, {\"definition\": \"The protection of public health by controlling the safety and efficacy of products in areas including pharmaceuticals, veterinary medicine, medical devices, pesticides, agrochemicals, cosmetics, and complementary medicines.\", \"path\": [{\"name\": \"Topic||Biomedical science||Medicines research and development||Regulatory affairs\", \"key\": \"topic_0003||topic_3344||topic_3376||topic_3394\"}], \"name\": \"Regulatory affairs\", \"uri\": \"http://edamontology.org/topic_3394\", \"exact_synonyms\": [\"Healthcare RA\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The design of vaccines to protect against a particular pathogen, including antigens, delivery systems, and adjuvants to elicit a predictable immune response against specific epitopes.\", \"path\": [{\"name\": \"Topic||Biomedical science||Medicines research and development||Vaccinology\", \"key\": \"topic_0003||topic_3344||topic_3376||topic_3966\"}], \"name\": \"Vaccinology\", \"uri\": \"http://edamontology.org/topic_3966\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Rational vaccine design\", \"Reverse vaccinology\", \"Structural vaccinology\", \"Structure-based immunogen design\", \"Vaccine design\"], \"children\": []}, {\"definition\": \"The use of animals and alternatives in experimental research.\", \"path\": [{\"name\": \"Topic||Biomedical science||Laboratory animal science\", \"key\": \"topic_0003||topic_3344||topic_3386\"}], \"name\": \"Laboratory animal science\", \"uri\": \"http://edamontology.org/topic_3386\", \"exact_synonyms\": [\"Animal experimentation\", \"Animal research\", \"Animal testing\", \"In vivo testing\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Animal study\", \"uri\": \"http://edamontology.org/topic_3679\"}]}, {\"definition\": \"The design of an experiment involving non-human animals.\", \"path\": [{\"name\": \"Topic||Biomedical science||Laboratory animal science||Animal study\", \"key\": \"topic_0003||topic_3344||topic_3386||topic_3679\"}, {\"name\": \"Topic||Experimental design and studies||Animal study\", \"key\": \"topic_0003||topic_3678||topic_3679\"}], \"name\": \"Animal study\", \"uri\": \"http://edamontology.org/topic_3679\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Challenge study\"], \"children\": []}, {\"definition\": \"The study of the effects of food components on the metabolism, health, performance and disease resistance of humans and animals.  It also includes the study of human behaviours related to food choices.\", \"path\": [{\"name\": \"Topic||Biomedical science||Nutritional science\", \"key\": \"topic_0003||topic_3344||topic_3390\"}], \"name\": \"Nutritional science\", \"uri\": \"http://edamontology.org/topic_3390\", \"exact_synonyms\": [\"Nutrition\", \"Nutrition science\"], \"narrow_synonyms\": [\"Dietetics\"], \"children\": []}, {\"definition\": \"Biomedical approaches to clinical interventions that involve the use of stem cells.\", \"path\": [{\"name\": \"Topic||Biomedical science||Regenerative medicine\", \"key\": \"topic_0003||topic_3344||topic_3395\"}], \"name\": \"Regenerative medicine\", \"uri\": \"http://edamontology.org/topi