tics\", \"key\": \"topic_0003||topic_3070||topic_3053||topic_3574\"}], \"name\": \"Human genetics\", \"uri\": \"http://edamontology.org/topic_3574\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3912\": {\"definition\": \"The application of biotechnology to directly manipulate an organism\'s genes.\", \"path\": [{\"name\": \"Topic||Biology||Genetics||Genetic engineering\", \"key\": \"topic_0003||topic_3070||topic_3053||topic_3912\"}, {\"name\": \"Topic||Biology||Biotechnology||Genetic engineering\", \"key\": \"topic_0003||topic_3070||topic_3297||topic_3912\"}], \"name\": \"Genetic engineering\", \"uri\": \"http://edamontology.org/topic_3912\", \"exact_synonyms\": [\"Genetic manipulation\", \"Genetic modification\"], \"narrow_synonyms\": [\"Genome editing\", \"Genome engineering\"], \"children\": []}, \"topic_3930\": {\"definition\": \"A biomedical field that bridges immunology and genetics, to study the genetic basis of the immune system.\", \"path\": [{\"name\": \"Topic||Biology||Genetics||Immunogenetics\", \"key\": \"topic_0003||topic_3070||topic_3053||topic_3930\"}, {\"name\": \"Topic||Biomedical science||Immunology||Immunogenetics\", \"key\": \"topic_0003||topic_3344||topic_0804||topic_3930\"}], \"name\": \"Immunogenetics\", \"uri\": \"http://edamontology.org/topic_3930\", \"exact_synonyms\": [\"Immune system genetics\", \"Immungenetics\", \"Immunology and genetics\"], \"narrow_synonyms\": [\"Immunogenes\"], \"children\": []}, \"topic_3064\": {\"definition\": \"How organisms grow and develop.\", \"path\": [{\"name\": \"Topic||Biology||Developmental biology\", \"key\": \"topic_0003||topic_3070||topic_3064\"}], \"name\": \"Developmental biology\", \"uri\": \"http://edamontology.org/topic_3064\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Development\"], \"children\": [{\"name\": \"Embryology\", \"uri\": \"http://edamontology.org/topic_3065\"}]}, \"topic_3065\": {\"definition\": \"The development of organisms between the one-cell