children\": []}, \"topic_0128\": {\"definition\": \"Protein-protein, protein-DNA/RNA and protein-ligand interactions, including analysis of known interactions and prediction of putative interactions.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Protein interactions\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_0128\"}, {\"name\": \"Topic||Computational biology||Molecular interactions, pathways and networks||Protein interactions\", \"key\": \"topic_0003||topic_3307||topic_0602||topic_0128\"}], \"name\": \"Protein interactions\", \"uri\": \"http://edamontology.org/topic_0128\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Protein interaction map\", \"Protein interaction networks\", \"Protein interactome\", \"Protein-DNA interaction\", \"Protein-DNA interactions\", \"Protein-RNA interaction\", \"Protein-RNA interactions\", \"Protein-ligand interactions\", \"Protein-nucleic acid interactions\", \"Protein-protein interactions\"], \"children\": []}, \"topic_0820\": {\"definition\": \"Lipoproteins (protein-lipid assemblies), and proteins or region of a protein that spans or are associated with a membrane.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Membrane and lipoproteins\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_0820\"}], \"name\": \"Membrane and lipoproteins\", \"uri\": \"http://edamontology.org/topic_0820\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Lipoproteins\", \"Membrane proteins\", \"Transmembrane proteins\"], \"children\": []}, \"topic_0821\": {\"definition\": \"Proteins that catalyze chemical reaction, the kinetics of enzyme-catalysed reactions, enzyme nomenclature etc.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Enzymes\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_0821\"}], \"name\": \"Enzymes\", \"uri\": \"http://edamontology.org/topic_0821\", \"exact_synonyms\": [\"Enzymology\"], \"narrow_synonyms\": [], \"children\": []}, \"topic_2814\": {\"defin