[\"Audiovestibular medicine\", \"Otolaryngology\", \"Otorhinolaryngology\"], \"narrow_synonyms\": [\"Head and neck disorders\"], \"children\": []}, \"topic_3407\": {\"definition\": \"The branch of medicine dealing with diseases of endocrine organs, hormone systems, their target organs, and disorders of the pathways of glucose and lipid metabolism.\", \"path\": [{\"name\": \"Topic||Medicine||Endocrinology and metabolism\", \"key\": \"topic_0003||topic_3303||topic_3407\"}], \"name\": \"Endocrinology and metabolism\", \"uri\": \"http://edamontology.org/topic_3407\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Endocrine disorders\", \"Endocrinology\", \"Metabolic disorders\", \"Metabolism\"], \"children\": []}, \"topic_3408\": {\"definition\": \"The branch of medicine that deals with the blood, blood-forming organs and blood diseases.\", \"path\": [{\"name\": \"Topic||Medicine||Haematology\", \"key\": \"topic_0003||topic_3303||topic_3408\"}], \"name\": \"Haematology\", \"uri\": \"http://edamontology.org/topic_3408\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Blood disorders\", \"Haematological disorders\"], \"children\": []}, \"topic_3409\": {\"definition\": \"The branch of medicine that deals with disorders of the oesophagus, stomach, duodenum, jejenum, ileum, large intestine, sigmoid colon and rectum.\", \"path\": [{\"name\": \"Topic||Medicine||Gastroenterology\", \"key\": \"topic_0003||topic_3303||topic_3409\"}], \"name\": \"Gastroenterology\", \"uri\": \"http://edamontology.org/topic_3409\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Gastrointestinal disorders\"], \"children\": []}, \"topic_3410\": {\"definition\": \"The study of the biological and physiological differences between males and females and how they effect differences in disease presentation and management.\", \"path\": [{\"name\": \"Topic||Medicine||Gender medicine\", \"key\": \"topic_0003||topic_3303||topic_3410\"}], \"name\": \"Gender medicine\", \"uri\": \"http://edamontology.org/topic_3410\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3411\": {\"definition\": \"The branch of medicine that deals with the health of the female reproductive system, pregnancy and birth.\", \"path\": [{\"name\": \"Topic||Medicine||Gynaecology and obstetrics\", \"key\": \"topic_0003||topic_3303||topic_3411\"}], \"name\": \"Gynaecology and obstetrics\", \"uri\": \"http://edamontology.org/topic_3411\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Gynaecological disorders\", \"Gynaecology\", \"Obstetrics\"], \"children\": []}, \"topic_3412\": {\"definition\": \"The branch of medicine that deals with the liver, gallbladder, bile ducts and bile.\", \"path\": [{\"name\": \"Topic||Medicine||Hepatic and biliary medicine\", \"key\": \"topic_0003||topic_3303||topic_3412\"}], \"name\": \"Hepatic and biliary medicine\", \"uri\": \"http://edamontology.org/topic_3412\", \"exact_synonyms\": [\"Hepatobiliary medicine\"], \"narrow_synonyms\": [\"Liver disorders\"], \"children\": []}, \"topic_3414\": {\"definition\": \"The branch of medicine that treats body wounds or shock produced by sudden physical injury, as from violence or accident.\", \"path\": [{\"name\": \"Topic||Medicine||Trauma medicine\", \"key\": \"topic_0003||topic_3303||topic_3414\"}], \"name\": \"Trauma medicine\", \"uri\": \"http://edamontology.org/topic_3414\", \"exact_synonyms\": [\"Traumatology\"], \"narrow_synonyms\": [], \"children\": []}, \"topic_3415\": {\"definition\": \"The branch of medicine that deals with the diagnosis, management and prevention of poisoning and other adverse health effects caused by medications, occupational and environmental toxins, and biological agents.\", \"path\": [{\"name\": \"Topic||Medicine||Medical toxicology\", \"key\": \"topic_0003||topic_3303||topic_3415\"}], \"name\": \"Medical toxicology\", \"uri\": \"http://edamontology.org/topic_3415\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3416\": {\"definition\": \"The branch of medicine that deals with the prevention, diagnosis, and treatment of disorders of the muscle, bone and connective tissue.  It incorporates aspects of orthopaedics, rheumatology, rehabilitation medicine and pain medicine.\", \"path\": [{\"name\": \"Topic||Medicine||Musculoskeletal medicine\", \"key\": \"topic_0003||topic_3303||topic_3416\"}], \"name\": \"Musculoskeletal medicine\", \"uri\": \"http://edamontology.org/topic_3416\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Musculoskeletal disorders\", \"Orthopaedics\", \"Rheumatology\"], \"children\": []}, \"topic_3417\": {\"definition\": \"The branch of medicine that deals with disorders of the eye, including eyelid, optic nerve/visual pathways and occular muscles.\", \"path\": [{\"name\": \"Topic||Medicine||Opthalmology\", \"key\": \"topic_0003||topic_3303||topic_3417\"}], \"name\": \"Opthalmology\", \"uri\": \"http://edamontology.org/topic_3417\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Eye disoders\"], \"children\": []}, \"topic_3418\": {\"definition\": \"The branch of medicine that deals with the medical care of infants, children and adolescents.\", \"path\": [{\"name\": \"Topic||Medicine||Paediatrics\", \"key\": \"topic_0003||topic_3303||topic_3418\"}], \"name\": \"Paediatrics\", \"uri\": \"http://edamontology.org/topic_3418\", \"exact_synonyms\": [\"Child health\"], \"narrow_synonyms\": [], \"children\": []}, \"topic_3419\": {\"definition\": \"The branch of medicine that deals with the mangement of mental illness, emotional disturbance and abnormal behaviour.\", \"path\": [{\"name\": \"Topic||Medicine||Psychiatry\", \"key\": \"topic_0003||topic_3303||topic_3419\"}], \"name\": \"Psychiatry\", \"uri\": \"http://edamontology.org/topic_3419\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Psychiatric disorders\"], \"children\": []}, \"topic_3420\": {\"definition\": \"The health of the reproductive processes, functions and systems at all stages of life.\", \"path\": [{\"name\": \"Topic||Medicine||Reproductive health\", \"key\": \"topic_0003||topic_3303||topic_3420\"}], \"name\": \"Reproductive health\", \"uri\": \"http://edamontology.org/topic_3420\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Andrology\", \"Family planning\", \"Fertility medicine\", \"Reproductive disorders\"], \"children\": []}, \"topic_3421\": {\"definition\": \"The use of operative, manual and instrumental techniques on a patient to investigate and/or treat a pathological condition or help improve bodily function or appearance.\", \"path\": [{\"name\": \"Topic||Medicine||Surgery\", \"key\": \"topic_0003||topic_3303||topic_3421\"}], \"name\": \"Surgery\", \"uri\": \"http://edamontology.org/topic_3421\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Transplantation\"], \"children\": []}, \"topic_3422\": {\"definition\": \"The branches of medicine and physiology focussing on the function and disorders of the urinary system in males and females, the reproductive system in males, and the kidney.\", \"path\": [{\"name\": \"Topic||Medicine||Urology and nephrology\", \"key\": \"topic_0003||topic_3303||topic_3422\"}], \"name\": \"Urology and nephrology\", \"uri\": \"http://edamontology.org/topic_3422\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Kidney disease\", \"Nephrology\", \"Urological disorders\", \"Urology\"], \"children\": []}, \"topic_3423\": {\"definition\": \"Medical therapies that fall beyond the scope of conventional medicine but may be used alongside it in the treatment of disease and ill health.\", \"path\": [{\"name\": \"Topic||Medicine||Complementary medicine\", \"key\": \"topic_0003||topic_3303||topic_3423\"}], \"name\": \"Complementary medicine\", \"uri\": \"http://edamontology.org/topic_3423\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3575\": {\"definition\": \"Health problems that are prevalent in tropical and subtropical regions.\", \"path\": [{\"name\": \"Topic||Medicine||Tropical medicine\", \"key\": \"topic_0003||topic_3303||topic_3575\"}], \"name\": \"Tropical medicine\", \"uri\": \"http://edamontology.org/topic_3575\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3577\": {\"definition\": \"An approach to medicine whereby decisions, practices and are tailored to the individual patient based on their predicted response or risk of disease.\", \"path\": [{\"name\": \"Topic||Medicine||Personalised medicine\", \"key\": \"topic_0003||topic_3303||topic_3577\"}], \"name\": \"Personalised medicine\", \"uri\": \"http://edamontology.org/topic_3577\", \"exact_synonyms\": [\"Precision medicine\"], \"narrow_synonyms\": [\"Molecular diagnostics\"], \"children\": []}, \"topic_3307\": {\"definition\": \"The development and application of theory, analytical methods, mathematical models and computational simulation of biological systems.\", \"path\": [{\"name\": \"Topic||Computational biology\", \"key\": \"topic_0003||topic_3307\"}], \"name\": \"Computational biology\", \"uri\": \"http://edamontology.org/topic_3307\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Biomathematics\", \"Mathematical biology\", \"Theoretical biology\"], \"children\": [{\"name\": \"Nucleic acids\", \"uri\": \"http://edamontology.org/topic_0077\"}, {\"name\": \"Proteins\", \"uri\": \"http://edamontology.org/topic_0078\"}, {\"name\": \"Sequence analysis\", \"uri\": \"http://edamontology.org/topic_0080\"}, {\"name\": \"Structure analysis\", \"uri\": \"http://edamontology.org/topic_0081\"}, {\"name\": \"Phylogeny\", \"uri\": \"http://edamontology.org/topic_0084\"}, {\"name\": \"Sequence sites, features and motifs\", \"uri\": \"http://edamontology.org/topic_0160\"}, {\"name\": \"Molecular interactions, pathways and networks\", \"uri\": \"http://edamontology.org/topic_0602\"}, {\"name\": \"Function analysis\", \"uri\": \"http://edamontology.org/topic_1775\"}, {\"name\": \"Molecular genetics\", \"uri\": \"http://edamontology.org/topic_3321\"}, {\"name\": \"Biomolecular simulation\", \"uri\"