, \"uri\": \"http://edamontology.org/topic_0108\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Translation\"], \"children\": [{\"name\": \"Protein targeting and localisation\", \"uri\": \"http://edamontology.org/topic_0140\"}, {\"name\": \"Protein modifications\", \"uri\": \"http://edamontology.org/topic_0601\"}, {\"name\": \"Protein variants\", \"uri\": \"http://edamontology.org/topic_3120\"}]}, \"topic_0140\": {\"definition\": \"The study of how proteins are transported within and without the cell, including signal peptides, protein subcellular localisation and export.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Protein expression||Protein targeting and localisation\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_0108||topic_0140\"}], \"name\": \"Protein targeting and localisation\", \"uri\": \"http://edamontology.org/topic_0140\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Protein localisation\", \"Protein sorting\", \"Protein targeting\"], \"children\": []}, \"topic_0601\": {\"definition\": \"Protein chemical modifications, e.g. post-translational modifications.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Protein expression||Protein modifications\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_0108||topic_0601\"}], \"name\": \"Protein modifications\", \"uri\": \"http://edamontology.org/topic_0601\", \"exact_synonyms\": [\"PTMs\", \"Post-translational modifications\", \"Protein post-translational modification\"], \"narrow_synonyms\": [\"Post-translation modifications\", \"Protein chemical modifications\", \"Protein post-translational modifications\"], \"children\": []}, \"topic_3120\": {\"definition\": \"Protein sequence variants produced e.g. from alternative splicing, alternative promoter usage, alternative initiation and ribosomal frameshifting.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Protein expression||Protein variants\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_0108||topic_3120\"}], \"name\": \"Protein variants\", \"uri\": \"http://edamontology.org/topic_3120\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_0123\": {\"definition\": \"The study of the physical and biochemical properties of peptides and proteins, for example the hydrophobic, hydrophilic and charge properties of a protein.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Protein properties\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_0123\"}], \"name\": \"Protein properties\", \"uri\": \"http://edamontology.org/topic_0123\", \"exact_synonyms\": [\"Protein physicochemistry\"], \"narrow_synonyms\": [\"Protein hydropathy\"], \"children\": []}, \"topic_0128\": {\"definition\": \"Protein-protein, protein-DNA/RNA and protein-ligand interactions, including analysis of known interactions and prediction of putative interactions.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Protein interactions\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_0128\"}, {\"name\": \"Topic||Computational biology||Molecular interactions, pathways and networks||Protein interactions\", \"key\": \"topic_0003||topic_3307||topic_0602||topic_0128\"}], \"name\": \"Protein interactions\", \"uri\": \"http://edamontology.org/topic_0128\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Protein interaction map\", \"Protein interaction networks\", \"Protein interactome\", \"Protein-DNA interaction\", \"Protein-DNA interactions\", \"Protein-RNA interaction\", \"Protein-RNA interactions\", \"Protein-ligand interactions\", \"Protein-nucleic acid interactions\", \"Protein-protein interactions\"], \"children\": []}, \"topic_0820\": {\"definition\": \"Lipoproteins (protein-lipid assemblies), and proteins or region of a protein that spans or are associated with a membrane.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Membrane and lipoproteins\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_0820\"}], \"name\": \"Membrane and lipoproteins\", \"uri\": \"http://edamontology.org/topic_0820\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Lipoproteins\", \"Membrane proteins\", \"Transmembrane proteins\"], \"children\": []}, \"topic_0821\": {\"definition\": \"Proteins that catalyze chemical reaction, the kinetics of enzyme-catalysed reactions, enzyme nomenclature etc.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Enzymes\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_0821\"}], \"name\": \"Enzymes\", \"uri\": \"http://edamontology.org/topic_0821\", \"exact_synonyms\": [\"Enzymology\"], \"narrow_synonyms\": [], \"children\": []}, \"topic_2814\": {\"definition\": \"Protein secondary or tertiary structural data and/or associated annotation.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Protein structure analysis\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_2814\"}, {\"name\": \"Topic||Computational biology||Structure analysis||Protein structure analysis\", \"key\": \"topic_0003||topic_3307||topic_0081||topic_2814\"}], \"name\": \"Protein structure analysis\", \"uri\": \"http://edamontology.org/topic_2814\", \"exact_synonyms\": [\"Protein structure\"], \"narrow_synonyms\": [\"Protein tertiary structure\"], \"children\": [{\"name\": \"Protein folding, stability and design\", \"uri\": \"http://edamontology.org/topic_0130\"}, {\"name\": \"Protein structural motifs and surfaces\", \"uri\": \"http://edamontology.org/topic_0166\"}, {\"name\": \"Protein folds and structural domains\", \"uri\": \"http://edamontology.org/topic_0736\"}, {\"name\": \"Protein disordered structure\", \"uri\": \"http://edamontology.org/topic_3538\"}, {\"name\": \"Protein secondary structure\", \"uri\": \"http://edamontology.org/topic_3542\"}]}, \"topic_0130\": {\"definition\": \"Protein stability, folding (in 3D space) and protein sequence-structure-function relationships.  This includes for example study of inter-atomic or inter-residue interactions in protein (3D) structures, the effect of mutation, and the design of proteins with specific properties, typically by designing changes (via site-directed mutagenesis) to an existing protein.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Protein structure analysis||Protein folding, stability and design\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_2814||topic_0130\"}, {\"name\": \"Topic||Computational biology||Structure analysis||Protein structure analysis||Protein folding, stability and design\", \"key\": \"topic_0003||topic_3307||topic_0081||topic_2814||topic_0130\"}], \"name\": \"Protein folding, stability and design\", \"uri\": \"http://edamontology.org/topic_0130\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Protein design\", \"Protein folding\", \"Protein residue interactions\", \"Protein stability\", \"Rational protein design\"], \"children\": []}, \"topic_0166\": {\"definition\": \"Structural features or common 3D motifs within protein structures, including the surface of a protein structure, such as biological interfaces with other molecules.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Protein structure analysis||Protein structural motifs and surfaces\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_2814||topic_0166\"}, {\"name\": \"Topic||Computational biology||Structure analysis||Protein structure analysis||Protein structural motifs and surfaces\", \"key\": \"topic_0003||topic_3307||topic_0081||topic_2814||topic_0166\"}], \"name\": \"Protein structural motifs and surfaces\", \"uri\": \"http://edamontology.org/topic_0166\", \"exact_synonyms\": [\"Protein 3D motifs\"], \"narrow_synonyms\": [\"Protein structural features\", \"Protein structural motifs\", \"Protein surfaces\", \"Structural motifs\"], \"children\": []}, \"topic_0736\": {\"definition\": \"Protein tertiary structural domains and folds in a protein or polypeptide chain.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Protein structure analysis||Protein folds and structural domains\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_2814||topic_0736\"}, {\"name\": \"Topic||Computational biology||Structure analysis||Protein structure analysis||Protein folds and structural domains\", \"key\": \"topic_0003||topic_3307||topic_0081||topic_2814||topic_0736\"}], \"name\": \"Protein folds and structural domains\", \"uri\": \"http://edamontology.org/topic_0736\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Intramembrane regions\", \"Protein domains\", \"Protein folds\", \"Protein membrane regions\", \"Protein structural domains\", \"Protein topological domains\", \"Protein transmembrane regions\", \"Transmembrane regions\"], \"children\": []}, \"topic_3538\": {\"definition\": \"Disordered structure in a protein.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Protein structure analysis||Protein disordered structure\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_2814||topic_3538\"}, {\"name\": \"Topic||Computational biology||Structure analysis||Protein structure analysis||Protein disordered structure\", \"key\": \"topic_0003||topic_3307||topic_0081||topic_2814||topic_3538\"}], \"name\": \"Protein disordered structure\", \"uri\": \"http://edamontology.org/topic_3538\", \"exact_synonyms\": [\"Protein features (disordered structure)\"], \"narrow_synonyms\": [], \"children\": []}, \"topic_3542\": {\"definition\": \"Secondary structure (predicted or real) of a protein, including super-secondary structure.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Protein structure analysis||Protein secondary structure\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_2814||topic_3542\"}, {\"name\": \"Topic||Computational biology||Structure analysis||Protein structure analysis||Protein secondary structure\", \"key\": \"topic_0003||topic_3307||topic_0081||topic_2814||topic_3542\"}], \"name\": \"Protein secondary structure\", \"uri\": \"http://edamontology.org/topic_3542\", \"exact_synonyms\": [\"Protein features (secondary structure)\"], \"narrow_synonyms\": [\"Protein super-secondary structure\"], \"children\": []}, \"topic_3510\": {\"definition\": \"The biology, archival, detection, prediction and analysis of positional features such as functional and other key sites, in protein sequences and the conserved patterns (motifs, profiles etc.) that may be used to describe them.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Protein sites, features and motifs\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_3510\"}, {\"name\": \"Topic||Computational biology||Sequence sites, features and motifs||Protein sites, features and motifs\", \"key\": \"topic_0003||topic_3307||topic_0160||topic_3510\"}], \"name\": \"Protein sites, features and motifs\", \"uri\": \"http://edamontology.org/topic_3510\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Protein sequence features\", \"Signal peptide cleavage sites\"], \"children\": [{\"name\": \"Protein binding sites\", \"uri\": \"http://edamontology.org/topic_3534\"}]}, \"topic_3534\": {\"definition\": \"Binding sites in proteins, including cleavage sites (for a proteolytic enzyme or agent), key residues involved in protein folding, catalytic residues (active site) of an enzyme, ligand-binding (non-catalytic) residues of a protein, such as sites that bind metal, prosthetic groups or lipids, RNA and DNA-binding proteins and binding sites etc.\", \"path\": [{\"name\": \"Topic||Computational biology||Proteins||Protein sites, features and motifs||Protein binding sites\", \"key\": \"topic_0003||topic_3307||topic_0078||topic_3510||topic_3534\"}, {\"name\": \"Topic||Computational biology||Sequence sites, features and motifs||Protein sites, features and motifs||Protein binding sites\", \"key\": \"topic_0003||topic_3307||topic_0160||topic_3510||topic_3534\"}], \"name\": \"Protein binding sites\", \"uri\": \"http://edamontology.org/topic_3534\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Enzyme active site\", \"Protein cleavage sites\", \"Protein functional sites\", \"Protein key folding sites\", \"Protein-nucleic acid binding sites\"], \"children\": []}, \"topic_0080\": {\"definition\": \"The archival, processing and analysis of molecular sequences (monomer composition of polymers) including molecular sequence data resources, sequence sites, alignments, motifs and profiles.\", \"path\": [{\"name\": \"Topic||Computational biology||Sequence analysis\", \"key\": \"topic_0003||topic_3307||topic_0080\"}], \"name\": \"Sequence analysis\", \"uri\": \"http://edamontology.org/topic_0080\", \"exact_synonyms\": [\"Sequences\"], \"narrow_synonyms\": [\"Biological sequences\", \"Sequence databases\"], \"children\": [{\"name\": \"Mapping\", \"uri\": \"http://edamontology.org/topic_0102\"}, {\"name\": \"Sequence composition, complexity and repeats\", \"uri\": \"http://edamontology.org/topic_0157\"}, {\"name\": \"Phylogenomics\", \"uri\": \"http://edamontology.org/topic_0194\"}, {\"name\": \"Sequence assembly\", \"uri\": \"http://edamontology.org/topic_0196\"}, {\"name\": \"Probes and primers\", \"uri\": \"http://edamontology.org/topic_0632\"}, {\"name\": \"Phylogenetics\", \"uri\": \"http://edamontology.org/topic_3293\"}, {\"name\": \"Cladistics\", \"uri\": \"http://edamontology.org/topic_3944\"}]}, \"topic_0102\": {\"definition\": \"The mapping of complete (typically nucleotide) sequences. Mapping (in the sense of short read alignment, or more generally, just alignment) has application in RNA-Seq analysis (mapping of transcriptomics reads), variant discovery (e.g. mapping of exome capture), and re-sequencing (mapping of WGS reads).\", \"path\": [{\"name\": \"Topic||Computational biology||Sequence analysis||Mapping\", \"key\": \"topic_0003||topic_3307||topic_0080||topic_0102\"}], \"name\": \"Mapping\", \"uri\": \"http://edamontology.org/topic_0102\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Genetic linkage\", \"Linkage\", \"Linkage mapping\", \"Synteny\"], \"children\": []}, \"topic_0157\": {\"definition\": \"The archival, processing and analysis of the basic character composition of molecular sequences, for example character or word frequency, ambiguity, complexity, particularly regions of low complexity, and repeats or the repetitive nature of molecular sequences.\", \"path\": [{\"name\": \"Topic||Computational biology||Sequence analysis||Sequence composition, complexity and repeats\", \"key\": \"topic_0003||topic_3307||topic_0080||topic_0157\"}], \"name\": \"Sequence composition, complexity and repeats\", \"uri\": \"http://edamontology.org/topic_0157\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Low complexity sequences\", \"Nucleic acid repeats\", \"Protein repeats\", \"Protein sequence repeats\", \"Repeat sequences\", \"Sequence complexity\", \"Sequence composition\", \"Sequence repeats\"], \"children\": []}, \"topic_0194\": {\"definition\": \"The integrated study of evolutionary relationships and whole genome data, for example, in the analysis of species trees, horizontal gene transfer and evolutionary reconstruction.\", \"path\": [{\"name\": \"Topic||Computational biology||Sequence analysis||Phylogenomics\", \"key\": \"topic_0003||topic_3307||topic_0080||topic_0194\"}, {\"name\": \"Topic||Omics||Genomics||Phylogenomics\", \"key\": \"topic_0003||topic_3391||topic_0622||topic_0194\"}], \"name\": \"Phylogenomics\", \"uri\": \"http://edamontology.org/topic_0194\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_0196\": {\"definition\": \"The assembly of fragments of a DNA sequence to reconstruct the original sequence.\", \"path\": [{\"name\": \"Topic||Computational biology||Sequence analysis||Sequence assembly\", \"key\": \"topic_0003||topic_3307||topic_0080||topic_0196\"}], \"name\": \"Sequence assembly\", \"uri\": \"http://edamontology.org/topic_0196\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Assembly\"