], \"p\": [{\"n\": \"Topic||Computational biology||Proteins||Membrane and lipoproteins\", \"k\": \"topic_0003||topic_3307||topic_0078||topic_0820\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0821\": {\"d\": \"Proteins that catalyze chemical reaction, the kinetics of enzyme-catalysed reactions, enzyme nomenclature etc.\", \"n\": \"Enzymes\", \"ns\": [], \"u\": \"topic_0821\", \"es\": [\"Enzymology\"], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Proteins||Enzymes\", \"k\": \"topic_0003||topic_3307||topic_0078||topic_0821\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_2814\": {\"d\": \"Protein secondary or tertiary structural data and/or associated annotation.\", \"n\": \"Protein structure analysis\", \"ns\": [\"Protein tertiary structure\"], \"u\": \"topic_2814\", \"es\": [\"Protein structure\"], \"ch\": [{\"n\": \"Protein folding, stability and design\", \"u\": \"topic_0130\"}, {\"n\": \"Protein structural motifs and surfaces\", \"u\": \"topic_0166\"}, {\"n\": \"Protein folds and structural domains\", \"u\": \"topic_0736\"}, {\"n\": \"Protein disordered structure\", \"u\": \"topic_3538\"}, {\"n\": \"Protein secondary structure\", \"u\": \"topic_3542\"}], \"p\": [{\"n\": \"Topic||Computational biology||Proteins||Protein structure analysis\", \"k\": \"topic_0003||topic_3307||topic_0078||topic_2814\"}, {\"n\": \"Topic||Computational biology||Structure analysis||Protein structure analysis\", \"k\": \"topic_0003||topic_3307||topic_0081||topic_2814\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0130\": {\"d\": \"Protein stability, folding (in 3D space) and protein sequence-structure-function relationships.  This includes for example study of inter-atomic or inter-residue interactions in protein (3D) structures, the effect of mutation, and the design of proteins with specific properties, typically by designing changes (via site-directed mutagenesis) to an existing protein.\", \"n\": \"Protein folding, stability and design\", \"ns\": [\"Protein design\", \"Protein folding\", \"Protein residue interactions\", \"Protein stability\", \"Rational protein design\"], \"u\": \"topic_0130\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Proteins||Protein structure analysis||Protein folding, stability and design\", \"k\": \"topic_0003||topic_3307||topic_0078||topic_2814||topic_0130\"}, {\"n\": \"Topic||Computational biology||Structure analysis||Protein structure analysis||Protein folding, stability and design\", \"k\": \"topic_0003||topic_3307||topic_0081||topic_2814||topic_0130\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0166\": {\"d\": \"Structural features or common 3D motifs within protein structures, including the surface of a protein structure, such as biological interfaces with other molecules.\", \"n\": \"Protein structural motifs and surfaces\", \"ns\": [\"Protein structural features\", \"Protein structural motifs\", \"Protein surfaces\", \"Structural motifs\"], \"u\": \"topic_0166\", \"es\": [\"Protein 3D motifs\"], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Proteins||Protein structure analysis||Protein structural motifs and surfaces\", \"k\": \"topic_0003||topic_3307||topic_0078||topic_2814||topic_0166\"}, {\"n\": \"Topic||Computational biology||Structure analysis||Protein structure analysis||Protein structural motifs and surfaces\", \"k\": \"topic_0003||topic_3307||topic_0081||topic_2814||topic_0166\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0736\": {\"d\": \"Protein tertiary structural domains and folds in a protein or polypeptide chain.\", \"n\": \"Protein folds and structural domains\", \"ns\": [\"Intramembrane regions\", \"Protein domains\", \"Protein folds\", \"Protein membrane regions\", \"Protein structural domains\", \"Protein topological domains\", \"Protein transmembrane regions\", \"Transmembrane regions\"], \"u\": \"topic_0736\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Proteins||Protein structure analysis||Protein folds and structural domains\", \"k\": \"topic_0003||topic_3307||topic_0078||topic_2814||topic_0736\"}, {\"n\": \"Topic||Computational biology||Structure analysis||Protein structure analysis||Protein folds and structural domains\", \"k\": \"topic_0003||topic_3307||topic_0081||topic_2814||topic_0736\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_3538\": {\"d\": \"Disordered structure in a protein.\", \"n\": \"Protein disordered structure\", \"ns\": [], \"u\": \"topic_3538\", \"es\": [\"Protein features (disordered structure)\"], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Proteins||Protein structure analysis||Protein disordered structure\", \"k\": \"topic_0003||topic_3307||topic_0078||topic_2814||topic_3538\"}, {\"n\": \"Topic||Computational biology||Structure analysis||Protein structure analysis||Protein disordered structure\", \"k\": \"topic_0003||topic_3307||topic_0081||topic_2814||topic_3538\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_3542\": {\"d\": \"Secondary structure (predicted or real) of a protein, including super-secondary structure.\", \"n\": \"Protein secondary structure\", \"ns\": [\"Protein super-secondary structure\"], \"u\": \"topic_3542\", \"es\": [\"Protein features (secondary structure)\"], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Proteins||Protein structure analysis||Protein secondary structure\", \"k\": \"topic_0003||topic_3307||topic_0078||topic_2814||topic_3542\"}, {\"n\": \"Topic||Computational biology||Structure analysis||Protein structure analysis||Protein secondary structure\", \"k\": \"topic_0003||topic_3307||topic_0081||topic_2814||topic_3542\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_3510\": {\"d\": \"The biology, archival, detection, prediction and analysis of positional features such as functional and other key sites, in protein sequences and the conserved patterns (motifs, profiles etc.) that may be used to describe them.\", \"n\": \"Protein sites, features and motifs\", \"ns\": [\"Protein sequence features\", \"Signal peptide cleavage sites\"], \"u\": \"topic_3510\", \"es\": [], \"ch\": [{\"n\": \"Protein binding sites\", \"u\": \"topic_3534\"}], \"p\": [{\"n\": \"Topic||Computational biology||Proteins||Protein sites, features and motifs\", \"k\": \"topic_0003||topic_3307||topic_0078||topic_3510\"}, {\"n\": \"Topic||Computational biology||Sequence sites, features and motifs||Protein sites, features and motifs\", \"k\": \"topic_0003||topic_3307||topic_0160||topic_3510\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_3534\": {\"d\": \"Binding sites in proteins, including cleavage sites (for a proteolytic enzyme or agent), key residues involved in protein folding, catalytic residues (active site) of an enzyme, ligand-binding (non-catalytic) residues of a protein, such as sites that bind metal, prosthetic groups or lipids, RNA and DNA-binding proteins and binding sites etc.\", \"n\": \"Protein binding sites\", \"ns\": [\"Enzyme active site\", \"Protein cleavage sites\", \"Protein functional sites\", \"Protein key folding sites\", \"Protein-nucleic acid binding sites\"], \"u\": \"topic_3534\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Proteins||Protein sites, features and motifs||Protein binding sites\", \"k\": \"topic_0003||topic_3307||topic_0078||topic_3510||topic_3534\"}, {\"n\": \"Topic||Computational biology||Sequence sites, features and motifs||Protein sites, features and motifs||Protein binding sites\", \"k\": \"topic_0003||topic_3307||topic_0160||topic_3510||topic_3534\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0080\": {\"d\": \"The archival, processing and analysis of molecular sequences (monomer composition of polymers) including molecular sequence data resources, sequence sites, alignments, motifs and profiles.\", \"n\": \"Sequence analysis\", \"ns\": [\"Biological sequences\", \"Sequence databases\"], \"u\": \"topic_0080\", \"es\": [\"Sequences\"], \"ch\": [{\"n\": \"Mapping\", \"u\": \"topic_0102\"}, {\"n\": \"Sequence composition, complexity and repeats\", \"u\": \"topic_0157\"}, {\"n\": \"Phylogenomics\", \"u\": \"topic_0194\"}, {\"n\": \"Sequence assembly\", \"u\": \"topic_0196\"}, {\"n\": \"Probes and primers\", \"u\": \"topic_0632\"}, {\"n\": \"Phylogenetics\", \"u\": \"topic_3293\"}, {\"n\": \"Cladistics\", \"u\": \"topic_3944\"}], \"p\": [{\"n\": \"Topic||Computational biology||Sequence analysis\", \"k\": \"topic_0003||topic_3307||topic_0080\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0102\": {\"d\": \"The mapping of complete (typically nucleotide) sequences. Mapping (in the sense of short read alignment, or more generally, just alignment) has application in RNA-Seq analysis (mapping of transcriptomics reads), variant discovery (e.g. mapping of exome capture), and re-sequencing (mapping of WGS reads).\", \"n\": \"Mapping\", \"ns\": [\"Genetic linkage\", \"Linkage\", \"Linkage mapping\", \"Synteny\"], \"u\": \"topic_0102\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Sequence analysis||Mapping\", \"k\": \"topic_0003||topic_3307||topic_0080||topic_0102\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0157\": {\"d\": \"The archival, processing and analysis of the basic character composition of molecular sequences, for example character or word frequency, ambiguity, complexity, particularly regions of low complexity, and repeats or the repetitive nature of molecular sequences.\", \"n\": \"Sequence composition, complexity and repeats\", \"ns\": [\"Low complexity sequences\", \"Nucleic acid repeats\", \"Protein repeats\", \"Protein sequence repeats\", \"Repeat sequences\", \"Sequence complexity\", \"Sequence composition\", \"Sequence repeats\"], \"u\": \"topic_0157\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Sequence analysis||Sequence composition, complexity and repeats\", \"k\": \"topic_0003||topic_3307||topic_0080||topic_0157\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0194\": {\"d\": \"The integrated study of evolutionary relationships and whole genome data, for example, in the analysis of species trees, horizontal gene transfer and evolutionary reconstruction.\", \"n\": \"Phylogenomics\", \"ns\": [], \"u\": \"topic_0194\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Sequence analysis||Phylogenomics\", \"k\": \"topic_0003||topic_3307||topic_0080||topic_0194\"}, {\"n\": \"Topic||Omics||Genomics||Phylogenomics\", \"k\": \"topic_0003||topic_3391||topic_0622||topic_0194\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0196\": {\"d\": \"The assembly of fragments of a DNA sequence to reconstruct the original sequence.\", \"n\": \"Sequence assembly\", \"ns\": [\"Assembly\"], \"u\": \"topic_0196\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Sequence analysis||Sequence assembly\", \"k\": \"topic_0003||topic_3307||topic_0080||topic_0196\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0632\": {\"d\": \"Molecular probes (e.g. a peptide probe or DNA microarray probe) or PCR primers and hybridisation oligos in a nucleic acid sequence.\", \"n\": \"Probes and primers\", \"ns\": [\"Primer quality\", \"Primers\", \"Probes\"], \"u\": \"topic_0632\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Sequence analysis||Probes and primers\", \"k\": \"topic_0003||topic_3307||topic_0080||topic_0632\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0081\": {\"d\": \"The curation, processing, analysis and prediction of data about the structure of biological molecules, typically proteins and nucleic acids and other macromolecules.\", \"n\": \"Structure analysis\", \"ns\": [\"Computational structural biology\", \"Molecular structure\", \"Structure data resources\", \"Structure databases\", \"Structures\"], \"u\": \"topic_0081\", \"es\": [\"Biomolecular structure\", \"Structural bioinformatics\"], \"ch\": [{\"n\": \"Structure prediction\", \"u\": \"topic_0082\"}, {\"n\": \"Nucleic acid