 \"ht\": []}, \"topic_2275\": {\"d\": \"The construction, analysis, evaluation, refinement etc. of models of a molecules properties or behaviour, including the modelling the structure of proteins in complex with small molecules or other macromolecules (docking).\", \"n\": \"Molecular modelling\", \"ns\": [\"Comparative modelling\", \"Docking\", \"Homology modeling\", \"Homology modelling\", \"Molecular docking\"], \"u\": \"topic_2275\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Structure analysis||Structure prediction||Molecular modelling\", \"k\": \"topic_0003||topic_3307||topic_0081||topic_0082||topic_2275\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0152\": {\"d\": \"Carbohydrates, typically including structural information.\", \"n\": \"Carbohydrates\", \"ns\": [], \"u\": \"topic_0152\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Structure analysis||Carbohydrates\", \"k\": \"topic_0003||topic_3307||topic_0081||topic_0152\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0153\": {\"d\": \"Lipids and their structures.\", \"n\": \"Lipids\", \"ns\": [], \"u\": \"topic_0153\", \"es\": [\"Lipidomics\"], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Structure analysis||Lipids\", \"k\": \"topic_0003||topic_3307||topic_0081||topic_0153\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0154\": {\"d\": \"Small molecules of biological significance, typically archival, curation, processing and analysis of structural information.\", \"n\": \"Small molecules\", \"ns\": [\"Amino acids\", \"Chemical structures\", \"Drug structures\", \"Drug targets\", \"Drugs and target structures\", \"Metabolite structures\", \"Peptides\", \"Peptides and amino acids\", \"Target structures\", \"Targets\", \"Toxins\", \"Toxins and targets\"], \"u\": \"topic_0154\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Structure analysis||Small molecules\", \"k\": \"topic_0003||topic_3307||topic_0081||to