], \"p\": [{\"n\": \"Topic||Computational biology||Sequence analysis||Sequence composition, complexity and repeats\", \"k\": \"topic_0003||topic_3307||topic_0080||topic_0157\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0194\": {\"d\": \"The integrated study of evolutionary relationships and whole genome data, for example, in the analysis of species trees, horizontal gene transfer and evolutionary reconstruction.\", \"n\": \"Phylogenomics\", \"ns\": [], \"u\": \"topic_0194\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Sequence analysis||Phylogenomics\", \"k\": \"topic_0003||topic_3307||topic_0080||topic_0194\"}, {\"n\": \"Topic||Omics||Genomics||Phylogenomics\", \"k\": \"topic_0003||topic_3391||topic_0622||topic_0194\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0196\": {\"d\": \"The assembly of fragments of a DNA sequence to reconstruct the original sequence.\", \"n\": \"Sequence assembly\", \"ns\": [\"Assembly\"], \"u\": \"topic_0196\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Sequence analysis||Sequence assembly\", \"k\": \"topic_0003||topic_3307||topic_0080||topic_0196\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0632\": {\"d\": \"Molecular probes (e.g. a peptide probe or DNA microarray probe) or PCR primers and hybridisation oligos in a nucleic acid sequence.\", \"n\": \"Probes and primers\", \"ns\": [\"Primer quality\", \"Primers\", \"Probes\"], \"u\": \"topic_0632\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Topic||Computational biology||Sequence analysis||Probes and primers\", \"k\": \"topic_0003||topic_3307||topic_0080||topic_0632\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0081\": {\"d\": \"The curation, processing, analysis and prediction of data about the structure of biological molecules, typically proteins and nucleic acids and other macromolecules.\", \"n\": \"Structure analysis\", \"ns\": [\"Computational structural biology\", \"Molecular structure\", \"Structure data reso