INSERT INTO `elixir_ontology` VALUES (14,'EDAM_Operation_1.25','{\"text\": \"Operation\", \"data\": {\"uri\": \"http://edamontology.org/operation_0004\"}, \"definition\": \"A function that processes a set of inputs and results in a set of outputs, or associates arguments (inputs) with values (outputs). Special cases are: a) An operation that consumes no input (has no input arguments). Such operation is either a constant function, or an operation depending only on the underlying state. b) An operation that may modify the underlying state but has no output. c) The singular-case operation with no input or output, that still may modify the underlying state.\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Computational procedure\", \"Computational subroutine\", \"Computational tool\", \"Computational operation\", \"Function (programming)\", \"Lambda abstraction\", \"sumo:Function\", \"Mathematical function\", \"Process\", \"Mathematical operation\", \"Function\", \"Computational method\"], \"children\": [{\"text\": \"Annotation\", \"data\": {\"uri\": \"http://edamontology.org/operation_0226\"}, \"children\": [{\"text\": \"Sequence annotation\", \"data\": {\"uri\": \"http://edamontology.org/operation_0361\"}, \"children\": [{\"text\": \"Genome annotation\", \"data\": {\"uri\": \"http://edamontology.org/operation_0362\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [\"Functional genome annotation\", \"Metagenome annotation\", \"Structural genome annotation\"], \"replaced_by\": [], \"consider\": [], \"definition\": \"Annotate a genome sequence with terms from a controlled vocabulary.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"SNP annotation\", \"data\": {\"uri\": \"http://edamontology.org/operation_3661\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"Predict the effect or function of an individual single nucleotide polymorphism (SNP).\", \"ha