, \"children\": []}, {\"definition\": \"Construct a phylogenetic tree using a specific method.\", \"path\": {\"name\": \"Operation||Generation||Phylogenetic inference||Phylogenetic inference (method centric)\", \"key\": \"operation_0004||operation_3429||operation_0323||operation_0539\"}, \"name\": \"Phylogenetic inference (method centric)\", \"uri\": \"http://edamontology.org/operation_0539\", \"exact_synonyms\": [\"Phylogenetic tree construction (method centric)\", \"Phylogenetic tree generation (method centric)\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Phylogenetic inference (parsimony methods)\", \"uri\": \"http://edamontology.org/operation_0545\"}, {\"name\": \"Phylogenetic inference (minimum distance methods)\", \"uri\": \"http://edamontology.org/operation_0546\"}, {\"name\": \"Phylogenetic inference (maximum likelihood and Bayesian methods)\", \"uri\": \"http://edamontology.org/operation_0547\"}, {\"name\": \"Phylogenetic inference (quartet methods)\", \"uri\": \"http://edamontology.org/operation_0548\"}, {\"name\": \"Phylogenetic inference (AI methods)\", \"uri\": \"http://edamontology.org/operation_0549\"}]}, {\"definition\": \"Construct a phylogenetic tree by computing a sequence alignment and searching for the tree with the fewest number of character-state changes from the alignment.\", \"path\": {\"name\": \"Operation||Generation||Phylogenetic inference||Phylogenetic inference (method centric)||Phylogenetic inference (parsimony methods)\", \"key\": \"operation_0004||operation_3429||operation_0323||operation_0539||operation_0545\"}, \"name\": \"Phylogenetic inference (parsimony methods)\", \"uri\": \"http://edamontology.org/operation_0545\", \"exact_synonyms\": [\"Phylogenetic tree construction (parsimony methods)\", \"Phylogenetic tree generation (parsimony methods)\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Construct a phylogenetic tree by computing (or using precomputed) distances between sequences and searching fo