ogy.org/operation_0461\"}]}, {\"definition\": \"Generate digest fragments for a nucleotide sequence containing restriction sites.\", \"path\": {\"name\": \"Operation||Calculation||Nucleic acid property calculation||Restriction digest\", \"key\": \"operation_0004||operation_3438||operation_0262||operation_0365\"}, \"name\": \"Restriction digest\", \"uri\": \"http://edamontology.org/operation_0365\", \"exact_synonyms\": [\"Nucleic acid restriction digest\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Calculate a thermodynamic property of DNA or DNA/RNA, such as melting temperature, enthalpy and entropy.\", \"path\": [{\"name\": \"Operation||Calculation||Nucleic acid property calculation||Nucleic acid thermodynamic property calculation\", \"key\": \"operation_0004||operation_3438||operation_0262||operation_0455\"}], \"name\": \"Nucleic acid thermodynamic property calculation\", \"uri\": \"http://edamontology.org/operation_0455\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Calculate and plot a DNA or DNA/RNA melting profile.\", \"path\": {\"name\": \"Operation||Calculation||Nucleic acid property calculation||Nucleic acid melting profile plotting\", \"key\": \"operation_0004||operation_3438||operation_0262||operation_0456\"}, \"name\": \"Nucleic acid melting profile plotting\", \"uri\": \"http://edamontology.org/operation_0456\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Nucleic acid stitch profile plotting\", \"uri\": \"http://edamontology.org/operation_0457\"}, {\"name\": \"Nucleic acid melting curve plotting\", \"uri\": \"http://edamontology.org/operation_0458\"}, {\"name\": \"Nucleic acid probability profile plotting\", \"uri\": \"http://edamontology.org/operation_0459\"}, {\"name\": \"Nucleic acid temperature profile plotting\", \"uri\": \"http://edamontology.org/operation_0460\"}]}, {\"definition\": \"Calculate and plot a DNA or DNA/RNA stitch profile.\", \"path\": {\"name\": \"Operation||Calculation||Nucleic acid property calculation||Nucleic acid melting profile plotting||Nucleic acid stitch profile plotting\", \"key\": \"operation_0004||operation_3438||operation_0262||operation_0456||operation_0457\"}, \"name\": \"Nucleic acid stitch profile plotting\", \"uri\": \"http://edamontology.org/operation_0457\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Calculate and plot a DNA or DNA/RNA melting curve.\", \"path\": {\"name\": \"Operation||Calculation||Nucleic acid property calculation||Nucleic acid melting profile plotting||Nucleic acid melting curve plotting\", \"key\": \"operation_0004||operation_3438||operation_0262||operation_0456||operation_0458\"}, \"name\": \"Nucleic acid melting curve plotting\", \"uri\": \"http://edamontology.org/operation_0458\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Calculate and plot a DNA or DNA/RNA probability profile.\", \"path\": {\"name\": \"Operation||Calculation||Nucleic acid property calculation||Nucleic acid melting profile plotting||Nucleic acid probability profile plotting\", \"key\": \"operation_0004||operation_3438||operation_0262||operation_0456||operation_0459\"}, \"name\": \"Nucleic acid probability profile plotting\", \"uri\": \"http://edamontology.org/operation_0459\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Calculate and plot a DNA or DNA/RNA temperature profile.\", \"path\": {\"name\": \"Operation||Calculation||Nucleic acid property calculation||Nucleic acid melting profile plotting||Nucleic acid temperature profile plotting\", \"key\": \"operation_0004||operation_3438||operation_0262||operation_0456||operation_0460\"}, \"name\": \"Nucleic acid temperature profile plotting\", \"uri\": \"http://edamontology.org/operation_0460\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Calculate curvature and flexibility / stiffness of a nucleotide sequence.\", \"path\": [{\"name\": \"Operation||Calculation||Nucleic acid property calculation||Nucleic acid curvature calculation\", \"key\": \"operation_0004||operation_3438||operation_0262||operation_0461\"}], \"name\": \"Nucleic acid curvature calculation\", \"uri\": \"http://edamontology.org/operation_0461\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Perform a statistical data operation of some type, e.g. calibration or validation.\", \"path\": [{\"name\": \"Operation||Calculation||Statistical calculation\", \"key\": \"operation_0004||operation_3438||operation_2238\"}], \"name\": \"Statistical calculation\", \"uri\": \"http://edamontology.org/operation_2238\", \"exact_synonyms\": [\"Significance testing\", \"Statistical analysis\", \"Statistical test\", \"Statistical testing\"], \"narrow_synonyms\": [\"Expectation maximisation\", \"Gibbs sampling\", \"Hypothesis testing\", \"Omnibus test\"], \"children\": [{\"name\": \"Standardisation and normalisation\", \"uri\": \"http://edamontology.org/operation_3435\"}, {\"name\": \"Imputation\", \"uri\": \"http://edamontology.org/operation_3557\"}, {\"name\": \"Statistical inference\", \"uri\": \"http://edamontology.org/operation_3658\"}, {\"name\": \"Regression analysis\", \"uri\": \"http://edamontology.org/operation_3659\"}, {\"name\": \"Statistical modelling\", \"uri\": \"http://edamontology.org/operation_3664\"}, {\"name\": \"Principal component analysis\", \"uri\": \"http://edamontology.org/operation_3960\"}]}, {\"definition\": \"Standardize or normalize data by some statistical method.\", \"path\": [{\"name\": \"Operation||Calculation||Statistical calculation||Standardisation and normalisation\", \"key\": \"operation_0004||operation_3438||operation_2238||operation_3435\"}], \"name\": \"Standardisation and normalisation\", \"uri\": \"http://edamontology.org/operation_3435\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Normalisation\", \"Standardisation\"], \"children\": []}, {\"definition\": \"Replace missing data with substituted values, usually by using some statistical or other mathematical approach.\", \"path\": [{\"name\": \"Operation||Calculation||Statistical calculation||Imputation\", \"key\": \"operation_0004||operation_3438||operation_2238||operation_3557\"}], \"name\": \"Imputation\", \"uri\": \"http://edamontology.org/operation_3557\", \"exact_synonyms\": [\"Data imputation\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Analyse data in order to deduce properties of an underlying distribution or population.\", \"path\": [{\"name\": \"Operation||Calculation||Statistical calculation||Statistical inference\", \"key\": \"operation_0004||operation_3438||operation_2238||operation_3658\"}], \"name\": \"Statistical inference\", \"uri\": \"http://edamontology.org/operation_3658\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Empirical Bayes\"], \"children\": []}, {\"definition\": \"A statistical calculation to estimate the relationships among variables.\", \"path\": [{\"name\": \"Operation||Calculation||Statistical calculation||Regression analysis\", \"key\": \"operation_0004||operation_3438||operation_2238||operation_3659\"}], \"name\": \"Regression analysis\", \"uri\": \"http://edamontology.org/operation_3659\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Regression\"], \"children\": []}, {\"definition\": \"Construction of a statistical model, or a set of assumptions around some observed data, usually by describing a set of probability distributions which approximate the distribution of data.\", \"path\": [{\"name\": \"Operation||Calculation||Statistical calculation||Statistical modelling\", \"key\": \"operation_0004||operation_3438||operation_2238||operation_3664\"}], \"name\": \"Statistical modelling\", \"uri\": \"http://edamontology.org/operation_3664\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A statistical procedure that uses an orthogonal transformation to convert a set of observations of possibly correlated variables into a set of values of linearly uncorrelated variables called principal components.\", \"path\": [{\"name\": \"Operation||Calculation||Statistical calculation||Principal component analysis\", \"key\": \"operation_0004||operation_3438||operation_2238||operation_3960\"}], \"name\": \"Principal component analysis\", \"uri\": \"http://edamontology.org/operation_3960\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Calculate the isotope distribution of a given chemical species.\", \"path\": [{\"name\": \"Operation||Calculation||Isotopic distributions calculation\", \"key\": \"operation_0004||operation_3438||operation_3632\"}], \"name\": \"Isotopic distributions calculation\", \"uri\": \"http://edamontology.org/operation_3632\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Prediction of retention time in a mass spectrometry experiment based on compositional and structural properties of the separated species.\", \"path\": [{\"name\": \"Operation||Calculation||Retention time prediction\", \"key\": \"operation_0004||operation_3438||operation_3633\"}], \"name\": \"Retention time prediction\", \"uri\": \"http://edamontology.org/operation_3633\", \"exact_synonyms\": [\"Retention time calculation\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The calculation of species richness for a number of individual samples, based on plots of the number of species as a function of the number of samples (rarefaction curves).\", \"path\": [{\"name\": \"Operation||Calculation||Rarefaction\", \"key\": \"operation_0004||operation_3438||operation_3797\"}], \"name\": \"Rarefaction\", \"uri\": \"http://edamontology.org/operation_3797\", \"exact_synonyms\": [\"Species richness assessment\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A process used in statistics, machine learning, and information theory that reduces the number of random variables by obtaining a set of principal variables.\", \"path\": [{\"name\": \"Operation||Calculation||Dimensionality reduction\", \"key\": \"operation_0004||operation_3438||operation_3935\"}], \"name\": \"Dimensionality reduction\", \"uri\": \"http://edamontology.org/operation_3935\", \"exact_synonyms\": [\"Dimension reduction\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Feature selection\", \"uri\": \"http://edamontology.org/operation_3936\"}, {\"name\": \"Feature extraction\", \"uri\": \"http://edamontology.org/operation_3937\"}]}, {\"definition\": \"A dimensionality reduction process that selects a subset of relevant features (variables, predictors) for use in model construction.\", \"path\": [{\"name\": \"Operation||Calculation||Dimensionality reduction||Feature selection\", \"key\": \"operation_0004||operation_3438||operation_3935||operation_3936\"}], \"name\": \"Feature selection\", \"uri\": \"http://edamontology.org/operation_3936\", \"exact_synonyms\": [\"Attribute selection\", \"Variable selection\", \"Variable subset selection\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A dimensionality reduction process which builds (ideally) informative and non-redundant values (features) from an initial set of measured data, to aid subsequent generalization, learning or interpretation.\", \"path\": [{\"name\": \"Operation||Calculation||Dimensionality reduction||Feature extraction\", \"key\": \"operation_0004||operation_3438||operation_3935||operation_3937\"}], \"name\": \"Feature extraction\", \"uri\": \"http://edamontology.org/operation_3937\", \"exact_synonyms\": [\"Feature projection\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Identify a correlation, i.e. a statistical relationship between two random variables or two sets of data.\", \"path\": [{\"name\": \"Operation||Correlation\", \"key\": \"operation_0004||operation_3465\"}], \"name\": \"Correlation\", \"uri\": \"http://edamontology.org/operation_3465\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Sequence alignment analysis (site correlation)\", \"uri\": \"http://edamontology.org/operation_0449\"}, {\"name\": \"Expression correlation analysis\", \"uri\": \"http://edamontology.org/operation_3463\"}]}, {\"definition\": \"Analyse correlations between sites in a molecular sequence alignment.\", \"path\": {\"name\": \"Operation||Correlation||Sequence alignment analysis (site correlation)\", \"key\": \"operation_0004||operation_3465||operation_0449\"}, \"name\": \"Sequence alignment analysis (site correlation)\", \"uri\": \"http://edamontology.org/operation_0449\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Analyse the correlation patterns among features/molecules across across a variety of experiments, samples etc.\", \"path\": {\"name\": \"Operation||Correlation||Expression correlation analysis\", \"key\": \"operation_0004||operation_3465||operation_3463\"}, \"name\": \"Expression correlation analysis\", \"uri\": \"http://edamontology.org/operation_3463\", \"exact_synonyms\": [\"Co-expression analysis\"], \"narrow_synonyms\": [\"Gene co-expression network analysis\", \"Gene expression correlation\", \"Gene expression correlation analysis\"], \"children\": []}, {\"definition\": \"Operations concerning the handling and use of other tools.\", \"path\": [{\"name\": \"Operation||Service management\", \"key\": \"operation_0004||operation_3760\"}], \"name\": \"Service management\", \"uri\": \"http://edamontology.org/operation_3760\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Endpoint management\"], \"children\": [{\"name\": \"Service discovery\", \"uri\": \"http://edamontology.org/operation_3761\"}, {\"name\": \"Service composition\", \"uri\": \"http://edamontology.org/operation_3762\"}, {\"name\": \"Service invocation\", \"uri\": \"http://edamontology.org/operation_3763\"}]}, {\"definition\": \"An operation supporting the browsing or discovery of other tools and services.\", \"path\": [{\"name\": \"Operation||Service management||Service discovery\", \"key\": \"operation_0004||operation_3760||operation_3761\"}], \"name\": \"Service discovery\", \"uri\": \"http://edamontology.org/operation_3761\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"An operation supporting the aggregation of other services (at least two) into a funtional unit, for the automation of some task.\", \"path\": [{\"name\": \"Operation||Service management||Service composition\", \"key\": \"operation_0004||operation_3760||operation_3762\"}], \"name\": \"Service composition\", \"uri\": \"http://edamontology.org/operation_3762\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"An operation supporting the calling (invocation) of other tools and services.\", \"path\": [{\"name\": \"Operation||Service management||Service invocation\", \"key\": \"operation_0004||operation_3760||operation_3763\"}], \"name\": \"Service invocation\", \"uri\": \"http://edamontology.org/operation_3763\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Counting and measuring experimentally determined observations into quantities.\", \"path\": [{\"name\": \"Operation||Quantification\", \"key\": \"operation_0004||operation_3799\"}], \"name\": \"Quantification\", \"uri\": \"http://edamontology.org/operation_3799\", \"exact_synonyms\": [\"Quantitation\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Protein quantification\", \"uri\": \"http://edamontology.org/operation_3630\"}, {\"name\": \"RNA-Seq quantification\", \"uri\": \"http://edamontology.org/operation_3800\"}]}, {\"definition\": \"Technique for determining the amount of proteins in a sample.\", \"path\": {\"name\": \"Operation||Quantification||Protein quantification\", \"key\": \"operation_0004||operation_3799||operation_3630\"}, \"name\": \"Protein quantification\", \"uri\": \"http://edamontology.org/operation_3630\", \"exact_synonyms\": [\"Protein quantitation\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Label-free quantification\", \"uri\": \"http://edamontology.org/operation_3634\"}, {\"name\": \"Labeled quantification\", \"uri\": \"http://edamontology.org/operation_3635\"}, {\"name\": \"MRM/SRM\", \"uri\": \"http://edamontology.org/operation_3636\"}]}, {\"definition\": \"Quantification without the use of chemical tags.\", \"path\": {\"name\": \"Operation||Quantification||Protein quantification||Label-free quantification\", \"key\": \"operation_0004||operation_3799||operation_3630||operation_3634\"}, \"name\": \"Label-free quantification\", \"uri\": \"http://edamontology.org/operation_3634\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Spectral counting\", \"uri\": \"http://edamontology.org/operation_3637\"}, {\"name\": \"Ion counting\", \"uri\": \"http://edamontology.org/operation_3704\"}]}, {\"definition\": \"Calculate number of identified MS2 spectra as approximation of peptide / protein quantity.\", \"path\": {\"name\": \"Operation||Quantification||Protein quantification||Label-free quantification||Spectral counting\", \"key\": \"operation_0004||operation_3799||operation_3630||operation_3634||operation_3637\"}, \"name\": \"Spectral counting\", \"uri\": \"http://edamontology.org/operation_3637\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Label-free quantification by integration of ion current (ion counting).\", \"path\": {\"name\": \"Operation||Quantification||Protein quantification||Label-free quantification||Ion counting\", \"key\": \"operation_0004||operation_3799||operation_3630||operation_3634||operation_3704\"}, \"name\": \"Ion counting\", \"uri\": \"http://edamontology.org/operation_3704\", \"exact_synonyms\": [\"Ion current integration\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Quantification based on the use of chemical tags.\", \"path\": {\"name\": \"Operation||Quantification||Protein quantification||Labeled quantification\", \"key\": \"operation_0004||operation_3799||operation_3630||operation_3635\"}, \"name\": \"Labeled quantification\", \"uri\": \"http://edamontology.org/operation_3635\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"SILAC\", \"uri\": \"http://edamontology.org/operation_3638\"}, {\"name\": \"iTRAQ\", \"uri\": \"http://edamontology.org/operation_3639\"}, {\"name\": \"18O labeling\", \"uri\": \"http://edamontology.org/operation_3640\"}, {\"name\": \"TMT-tag\", \"uri\": \"http://edamontology.org/operation_3641\"}, {\"name\": \"Dimethyl\", \"uri\": \"http://edamontology.org/operation_3642\"}, {\"name\": \"Isotope-coded protein label\", \"uri\": \"http://edamontology.org/operation_3705\"}, {\"name\": \"Metabolic labeling\", \"uri\": \"http://edamontology.org/operation_3715\"}]}, {\"definition\": \"Quantification analysis using stable isotope labeling by amino acids in cell culture.\", \"path\": {\"name\": \"Operation||Quantification||Protein quantification||Labeled quantification||SILAC\", \"key\": \"operation_0004||operation_3799||operation_3630||operation_3635||operation_3638\"}, \"name\": \"SILAC\", \"uri\": \"http://edamontology.org/operation_3638\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Quantification analysis using the AB SCIEX iTRAQ isobaric labelling workflow, wherein 2-8 reporter ions are measured in MS2 spectra near 114 m/z.\", \"path\": {\"name\": \"Operation||Quantification||Protein quantification||Labeled quantification||iTRAQ\", \"key\": \"operation_0004||operation_3799||operation_3630||operation_3635||operation_3639\"}, \"name\": \"iTRAQ\", \"uri\": \"http://edamontology.org/operation_3639\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Quantification analysis using labeling based on 18O-enriched H2O.\", \"path\": {\"name\": \"Operation||Quantification||Protein quantification||Labeled quantification||18O labeling\", \"key\": \"operation_0004||operation_3799||operation_3630||operation_3635||operation_3640\"}, \"name\": \"18O labeling\", \"uri\": \"http://edamontology.org/operation_3640\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Quantification analysis using the Thermo Fisher tandem mass tag labelling workflow.\", \"path\": {\"name\": \"Operation||Quantification||Protein quantification||Labeled quantification||TMT-tag\", \"key\": \"operation_0004||operation_3799||operation_3630||operation_3635||operation_3641\"}, \"name\": \"TMT-tag\", \"uri\": \"http://edamontology.org/operation_3641\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Quantification analysis using chemical labeling by stable isotope dimethylation\", \"path\": {\"name\": \"Operation||Quantification||Protein quantification||Labeled quantification||Dimethyl\", \"key\": \"operation_0004||operation_3799||operation_3630||operation_3635||operation_3642\"}, \"name\": \"Dimethyl\", \"uri\": \"http://edamontology.org/operation_3642\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Chemical tagging free amino groups of intact proteins with stable isotopes.\", \"path\": {\"name\": \"Operation||Quantification||Protein quantification||Labeled quantification||Isotope-coded protein label\", \"key\": \"operation_0004||operation_3799||operation_3630||operation_3635||operation_3705\"}, \"name\": \"Isotope-coded protein label\", \"uri\": \"http://edamontology.org/operation_3705\", \"exact_synonyms\": [\"ICPL\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Labeling all proteins and (possibly) all amino acids using C-13 or N-15 enriched grown medium or feed.\", \"path\": {\"name\": \"Operation||Quantification||Protein quantification||Labeled quantification||Metabolic labeling\", \"key\": \"operation_0004||operation_3799||operation_3630||operation_3635||operation_3715\"}, \"name\": \"Metabolic labeling\", \"uri\": \"http://edamontology.org/operation_3715\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"C-13 metabolic labeling\", \"N-15 metabolic labeling\"], \"children\": []}, {\"definition\": \"Quantification by Selected/multiple Reaction Monitoring workflow (XIC quantitation of precursor / fragment mass pair).\", \"path\": {\"name\": \"Operation||Quantification||Protein quantification||MRM/SRM\", \"key\": \"operation_0004||operation_3799||operation_3630||operation_3636\"}, \"name\": \"MRM/SRM\", \"uri\": \"http://edamontology.org/operation_3636\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Quantification of data arising from RNA-Seq high-throughput sequencing, typically the quantification of transcript abundances durnig transcriptome analysis in a gene expression study.\", \"path\": [{\"name\": \"Operation||Quantification||RNA-Seq quantification\", \"key\": \"operation_0004||operation_3799||operation_3800\"}], \"name\": \"RNA-Seq quantification\", \"uri\": \"http://edamontology.org/operation_3800\", \"exact_synonyms\": [\"RNA-Seq quantitation\"], \"narrow_synonyms\": [], \"children\": []}]','2025-08-27 12:52:45.714102');
INSERT INTO `elixir_ontology` VALUES (16,'flat_EDAM_Operation_1.25','[{\"definition\": \"A function that processes a set of inputs and results in a set of outputs, or associates arguments (inputs) with values (outputs). Special cases are: a) An operation that consumes no input (has no input arguments). Such operation is either a constant function, or an operation depending only on the underlying state. b) An operation that may modify the underlying state but has no output. c) The singular-case operation with no input or output, that still may modify the underlying state.\", \"path\": [{\"name\": \"Operation\", \"key\": \"operation_0004\"}], \"name\": \"Operation\", \"uri\": \"http://edamontology.org/operation_0004\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Computational procedure\", \"Computational subroutine\", \"Computational tool\", \"Computational operation\", \"Function (programming)\", \"Lambda abstraction\", \"sumo:Function\", \"Mathematical function\", \"Process\", \"Mathematical operation\", \"Function\", \"Computational method\"], \"children\": [{\"name\": \"Annotation\", \"uri\": \"http://edamontology.org/operation_0226\"}, {\"name\": \"Indexing\", \"uri\": \"http://edamontology.org/operation_0227\"}, {\"name\": \"Visualisation\", \"uri\": \"http://edamontology.org/operation_0337\"}, {\"name\": \"Data handling\", \"uri\": \"http://edamontology.org/operation_2409\"}, {\"name\": \"Prediction and recognition\", \"uri\": \"http://edamontology.org/operation_2423\"}, {\"name\": \"Comparison\", \"uri\": \"http://edamontology.org/operation_2424\"}, {\"name\": \"Optimisation and refinement\", \"uri\": \"http://edamontology.org/operation_2425\"}, {\"name\": \"Modelling and simulation\", \"uri\": \"http://edamontology.org/operation_2426\"}, {\"name\": \"Validation\", \"uri\": \"http://edamontology.org/operation_2428\"}, {\"name\": \"Mapping\", \"uri\": \"http://edamontology.org/operation_2429\"}, {\"name\": \"Design\", \"uri\": \"http://edamontology.org/oper