inition\": \"Analyse some aspect of RNA/DNA folding, typically by processing sequence and/or structural data.  For example, compute folding energies such as minimum folding energies for DNA or RNA sequences or energy landscape of RNA mutants.\", \"path\": {\"name\": \"Operation||Modelling and simulation||Nucleic acid folding analysis\", \"key\": \"operation_0004||operation_2426||operation_0279\"}, \"name\": \"Nucleic acid folding analysis\", \"uri\": \"http://edamontology.org/operation_0279\", \"exact_synonyms\": [\"Nucleic acid folding\", \"Nucleic acid folding modelling\", \"Nucleic acid folding prediction\"], \"narrow_synonyms\": [\"Nucleic acid folding energy calculation\"], \"children\": []}, {\"definition\": \"Build a three-dimensional protein model based on known (for example homologs) structures.\", \"path\": {\"name\": \"Operation||Modelling and simulation||Protein modelling\", \"key\": \"operation_0004||operation_2426||operation_0477\"}, \"name\": \"Protein modelling\", \"uri\": \"http://edamontology.org/operation_0477\", \"exact_synonyms\": [\"Comparative modelling\", \"Homology modelling\", \"Homology structure modelling\", \"Protein structure comparative modelling\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Backbone modelling\", \"uri\": \"http://edamontology.org/operation_0479\"}, {\"name\": \"Side chain modelling\", \"uri\": \"http://edamontology.org/operation_0480\"}, {\"name\": \"Loop modelling\", \"uri\": \"http://edamontology.org/operation_0481\"}]}, {\"definition\": \"Model protein backbone conformation.\", \"path\": {\"name\": \"Operation||Modelling and simulation||Protein modelling||Backbone modelling\", \"key\": \"operation_0004||operation_2426||operation_0477||operation_0479\"}, \"name\": \"Backbone modelling\", \"uri\": \"http://edamontology.org/operation_0479\", \"exact_synonyms\": [\"Protein modelling (backbone)\"], \"narrow_synonyms\": [\"Design optimization\", \"Epitope grafting\", \"Scaffold search\", \"Scaffold selection\"