_synonyms\": [], \"children\": []}, {\"definition\": \"Analysing the DNA methylation of specific genes or regions of interest.\", \"path\": [{\"name\": \"Operation||Analysis||Sequence analysis||Nucleic acid sequence analysis||Methylation analysis||Gene methylation analysis\", \"key\": \"operation_0004||operation_2945||operation_2403||operation_2478||operation_3204||operation_3207\"}], \"name\": \"Gene methylation analysis\", \"uri\": \"http://edamontology.org/operation_3207\", \"exact_synonyms\": [\"Gene-specific methylation analysis\", \"Methylation level analysis (gene-specific)\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Identify and assess specific genes or regulatory regions of interest that are differentially methylated.\", \"path\": [{\"name\": \"Operation||Analysis||Sequence analysis||Nucleic acid sequence analysis||Methylation analysis||DMR identification\", \"key\": \"operation_0004||operation_2945||operation_2403||operation_2478||operation_3204||operation_3809\"}], \"name\": \"DMR identification\", \"uri\": \"http://edamontology.org/operation_3809\", \"exact_synonyms\": [\"Differentially-methylated region identification\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The determination of cytosine methylation status of specific positions in a nucleic acid sequences (usually reads from a bisulfite sequencing experiment).\", \"path\": [{\"name\": \"Operation||Analysis||Sequence analysis||Nucleic acid sequence analysis||Methylation analysis||Methylation calling\", \"key\": \"operation_0004||operation_2945||operation_2403||operation_2478||operation_3204||operation_3919\"}], \"name\": \"Methylation calling\", \"uri\": \"http://edamontology.org/operation_3919\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Raw sequence data quality control.\", \"path\": {\"name\": \"Operation||Analysis||Sequence analysis||Nucleic acid sequence analysis||Sequencing quality control\", \"key\": \"op