ructure alignment\", \"uri\": \"http://edamontology.org/operation_0504\"}, {\"name\": \"Local structure alignment\", \"uri\": \"http://edamontology.org/operation_0509\"}, {\"name\": \"Global structure alignment\", \"uri\": \"http://edamontology.org/operation_0510\"}]}, {\"definition\": \"Align (superimpose) exactly two molecular tertiary structures.\", \"path\": {\"name\": \"Operation||Analysis||Structure analysis||Structure alignment||Pairwise structure alignment\", \"key\": \"operation_0004||operation_2945||operation_2480||operation_0295||operation_0503\"}, \"name\": \"Pairwise structure alignment\", \"uri\": \"http://edamontology.org/operation_0503\", \"exact_synonyms\": [\"Structure alignment (pairwise)\"], \"narrow_synonyms\": [\"Pairwise protein structure alignment\"], \"children\": []}, {\"definition\": \"Align (superimpose) more than two molecular tertiary structures.\", \"path\": {\"name\": \"Operation||Analysis||Structure analysis||Structure alignment||Multiple structure alignment\", \"key\": \"operation_0004||operation_2945||operation_2480||operation_0295||operation_0504\"}, \"name\": \"Multiple structure alignment\", \"uri\": \"http://edamontology.org/operation_0504\", \"exact_synonyms\": [\"Structure alignment (multiple)\"], \"narrow_synonyms\": [\"Multiple protein structure alignment\"], \"children\": []}, {\"definition\": \"Locally align (superimpose) two or more molecular tertiary structures.\", \"path\": {\"name\": \"Operation||Analysis||Structure analysis||Structure alignment||Local structure alignment\", \"key\": \"operation_0004||operation_2945||operation_2480||operation_0295||operation_0509\"}, \"name\": \"Local structure alignment\", \"uri\": \"http://edamontology.org/operation_0509\", \"exact_synonyms\": [\"Structure alignment (local)\"], \"narrow_synonyms\": [\"Local protein structure alignment\"], \"children\": []}, {\"definition\": \"Globally align (superimpose) two or more molecular tertiary structures.\", \"path\": {\"name\": \"Operation|