INSERT INTO `elixir_ontology` VALUES (17,'index_EDAM_Operation','{\"operation_0004\": {\"definition\": \"A function that processes a set of inputs and results in a set of outputs, or associates arguments (inputs) with values (outputs). Special cases are: a) An operation that consumes no input (has no input arguments). Such operation is either a constant function, or an operation depending only on the underlying state. b) An operation that may modify the underlying state but has no output. c) The singular-case operation with no input or output, that still may modify the underlying state.\", \"path\": [{\"name\": \"Operation\", \"key\": \"operation_0004\"}], \"name\": \"Operation\", \"uri\": \"http://edamontology.org/operation_0004\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Computational procedure\", \"Computational subroutine\", \"Computational tool\", \"Computational operation\", \"Function (programming)\", \"Lambda abstraction\", \"sumo:Function\", \"Mathematical function\", \"Process\", \"Mathematical operation\", \"Function\", \"Computational method\"], \"children\": [{\"name\": \"Annotation\", \"uri\": \"http://edamontology.org/operation_0226\"}, {\"name\": \"Indexing\", \"uri\": \"http://edamontology.org/operation_0227\"}, {\"name\": \"Visualisation\", \"uri\": \"http://edamontology.org/operation_0337\"}, {\"name\": \"Data handling\", \"uri\": \"http://edamontology.org/operation_2409\"}, {\"name\": \"Prediction and recognition\", \"uri\": \"http://edamontology.org/operation_2423\"}, {\"name\": \"Comparison\", \"uri\": \"http://edamontology.org/operation_2424\"}, {\"name\": \"Optimisation and refinement\", \"uri\": \"http://edamontology.org/operation_2425\"}, {\"name\": \"Modelling and simulation\", \"uri\": \"http://edamontology.org/operation_2426\"}, {\"name\": \"Validation\", \"uri\": \"http://edamontology.org/operation_2428\"}, {\"name\": \"Mapping\", \"uri\": \"http://edamontology.org/operation_2429\"}, {\"name\": \"Design\", \"uri\": \"http://edamo