nagement\", \"uri\": \"http://edamontology.org/operation_3760\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Endpoint management\"], \"children\": [{\"name\": \"Service discovery\", \"uri\": \"http://edamontology.org/operation_3761\"}, {\"name\": \"Service composition\", \"uri\": \"http://edamontology.org/operation_3762\"}, {\"name\": \"Service invocation\", \"uri\": \"http://edamontology.org/operation_3763\"}]}, \"operation_3761\": {\"definition\": \"An operation supporting the browsing or discovery of other tools and services.\", \"path\": [{\"name\": \"Operation||Service management||Service discovery\", \"key\": \"operation_0004||operation_3760||operation_3761\"}], \"name\": \"Service discovery\", \"uri\": \"http://edamontology.org/operation_3761\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3762\": {\"definition\": \"An operation supporting the aggregation of other services (at least two) into a funtional unit, for the automation of some task.\", \"path\": [{\"name\": \"Operation||Service management||Service composition\", \"key\": \"operation_0004||operation_3760||operation_3762\"}], \"name\": \"Service composition\", \"uri\": \"http://edamontology.org/operation_3762\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3763\": {\"definition\": \"An operation supporting the calling (invocation) of other tools and services.\", \"path\": [{\"name\": \"Operation||Service management||Service invocation\", \"key\": \"operation_0004||operation_3760||operation_3763\"}], \"name\": \"Service invocation\", \"uri\": \"http://edamontology.org/operation_3763\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3799\": {\"definition\": \"Counting and measuring experimentally determined observations into quantities.\", \"path\": [{\"name\": \"Operation||Quantification\", \"key\": \"operation_0004||operation_3799\"}], \"name\": \"Quantification\", \"uri\": \"http://edamontology.