INSERT INTO `elixir_ontology` VALUES (19,'min_EDAM_Operation','{\"t\": \"Operation\", \"data\": {\"uri\": \"operation_0004\"}, \"d\": \"A function that processes a set of inputs and results in a set of outputs, or associates arguments (inputs) with values (outputs). Special cases are: a) An operation that consumes no input (has no input arguments). Such operation is either a constant function, or an operation depending only on the underlying state. b) An operation that may modify the underlying state but has no output. c) The singular-case operation with no input or output, that still may modify the underlying state.\", \"es\": [], \"ns\": [\"Computational procedure\", \"Computational subroutine\", \"Computational tool\", \"Computational operation\", \"Function (programming)\", \"Lambda abstraction\", \"sumo:Function\", \"Mathematical function\", \"Process\", \"Mathematical operation\", \"Function\", \"Computational method\"], \"ch\": [{\"t\": \"Annotation\", \"data\": {\"uri\": \"operation_0226\"}, \"ch\": [{\"t\": \"Sequence annotation\", \"data\": {\"uri\": \"operation_0361\"}, \"ch\": [{\"t\": \"Genome annotation\", \"data\": {\"uri\": \"operation_0362\"}, \"ch\": [], \"es\": [], \"ns\": [\"Functional genome annotation\", \"Metagenome annotation\", \"Structural genome annotation\"], \"rb\": [], \"co\": [], \"d\": \"Annotate a genome sequence with terms from a controlled vocabulary.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SNP annotation\", \"data\": {\"uri\": \"operation_3661\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Predict the effect or function of an individual single nucleotide polymorphism (SNP).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Gene functional annotation\", \"data\": {\"uri\": \"operation_3672\"}, \"ch\": [], \"es\": [\"Sequence functional annotation\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Annotate one or more sequences with functional information, such as cellular processes or metaobolic pa