INSERT INTO `elixir_ontology` VALUES (22,'min_flat_EDAM_Operation_1.25','[{\"d\": \"A function that processes a set of inputs and results in a set of outputs, or associates arguments (inputs) with values (outputs). Special cases are: a) An operation that consumes no input (has no input arguments). Such operation is either a constant function, or an operation depending only on the underlying state. b) An operation that may modify the underlying state but has no output. c) The singular-case operation with no input or output, that still may modify the underlying state.\", \"n\": \"Operation\", \"ns\": [\"Computational procedure\", \"Computational subroutine\", \"Computational tool\", \"Computational operation\", \"Function (programming)\", \"Lambda abstraction\", \"sumo:Function\", \"Mathematical function\", \"Process\", \"Mathematical operation\", \"Function\", \"Computational method\"], \"u\": \"operation_0004\", \"es\": [], \"ch\": [{\"n\": \"Annotation\", \"u\": \"operation_0226\"}, {\"n\": \"Indexing\", \"u\": \"operation_0227\"}, {\"n\": \"Visualisation\", \"u\": \"operation_0337\"}, {\"n\": \"Data handling\", \"u\": \"operation_2409\"}, {\"n\": \"Prediction and recognition\", \"u\": \"operation_2423\"}, {\"n\": \"Comparison\", \"u\": \"operation_2424\"}, {\"n\": \"Optimisation and refinement\", \"u\": \"operation_2425\"}, {\"n\": \"Modelling and simulation\", \"u\": \"operation_2426\"}, {\"n\": \"Validation\", \"u\": \"operation_2428\"}, {\"n\": \"Mapping\", \"u\": \"operation_2429\"}, {\"n\": \"Design\", \"u\": \"operation_2430\"}, {\"n\": \"Alignment\", \"u\": \"operation_2928\"}, {\"n\": \"Analysis\", \"u\": \"operation_2945\"}, {\"n\": \"Classification\", \"u\": \"operation_2990\"}, {\"n\": \"Generation\", \"u\": \"operation_3429\"}, {\"n\": \"Clustering\", \"u\": \"operation_3432\"}, {\"n\": \"Conversion\", \"u\": \"operation_3434\"}, {\"n\": \"Calculation\", \"u\": \"operation_3438\"}, {\"n\": \"Correlation\", \"u\": \"operation_3465\"}, {\"n\": \"Service 