429||operation_3349\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3480\": {\"d\": \"Generate some data from a choosen probibalistic model, possibly to evaluate algorithms.\", \"n\": \"Probabilistic data generation\", \"ns\": [], \"u\": \"operation_3480\", \"es\": [], \"ch\": [{\"n\": \"Probabilistic sequence generation\", \"u\": \"operation_3481\"}], \"p\": [{\"n\": \"Operation||Generation||Probabilistic data generation\", \"k\": \"operation_0004||operation_3429||operation_3480\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3432\": {\"d\": \"Group together some data entities on the basis of similarities such that entities in the same group (cluster) are more similar to each other than to those in other groups (clusters).\", \"n\": \"Clustering\", \"ns\": [], \"u\": \"operation_3432\", \"es\": [], \"ch\": [{\"n\": \"Sequence clustering\", \"u\": \"operation_0291\"}, {\"n\": \"Expression profile clustering\", \"u\": \"operation_0313\"}, {\"n\": \"Structure clustering\", \"u\": \"operation_2844\"}, {\"n\": \"Document clustering\", \"u\": \"operation_3279\"}], \"p\": [{\"n\": \"Operation||Clustering\", \"k\": \"operation_0004||operation_3432\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_2844\": {\"d\": \"Build clusters of similar structures, typically using scores from structural alignment methods.\", \"n\": \"Structure clustering\", \"ns\": [], \"u\": \"operation_2844\", \"es\": [\"Structural clustering\"], \"ch\": [], \"p\": [{\"n\": \"Operation||Clustering||Structure clustering\", \"k\": \"operation_0004||operation_3432||operation_2844\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3434\": {\"d\": \"Convert a data set from one form to another.\", \"n\": \"Conversion\", \"ns\": [], \"u\": \"operation_3434\", \"es\": [], \"ch\": [{\"n\": \"Sequence conversion\", \"u\": \"operation_0233\"}, {\"n\": \"Sequence alignment conversion\", \"u\": \"operation_0260\"}, {\"n\": \"Sequence coordinate conversion\", \"u\": \"operation_3267\"}], \"p\": [{\"n\": \"Operation||Conversion\", \"k\": \"operation_0004||operation_3434\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3267\": {\"d\": \"Convert one set of sequence coordinates to another, e.g. convert coordinates of one assembly to another, cDNA to genomic, CDS to genomic, protein translation to genomic etc.\", \"n\": \"Sequence coordinate conversion\", \"ns\": [], \"u\": \"operation_3267\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Operation||Conversion||Sequence coordinate conversion\", \"k\": \"operation_0004||operation_3434||operation_3267\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3438\": {\"d\": \"Mathematical determination of the value of something, typically a properly of a  molecule.\", \"n\": \"Calculation\", \"ns\": [], \"u\": \"operation_3438\", \"es\": [], \"ch\": [{\"n\": \"Sequence composition calculation\", \"u\": \"operation_0236\"}, {\"n\": \"Protein property calculation\", \"u\": \"operation_0250\"}, {\"n\": \"Nucleic acid property calculation\", \"u\": \"operation_0262\"}, {\"n\": \"Statistical calculation\", \"u\": \"operation_2238\"}, {\"n\": \"Isotopic distributions calculation\", \"u\": \"operation_3632\"}, {\"n\": \"Retention time prediction\", \"u\": \"operation_3633\"}, {\"n\": \"Rarefaction\", \"u\": \"operation_3797\"}, {\"n\": \"Dimensionality reduction\", \"u\": \"operation_3935\"}], \"p\": [{\"n\": \"Operation||Calculation\", \"k\": \"operation_0004||operation_3438\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_0262\": {\"d\": \"Calculate or predict physical or chemical properties of nucleic acid molecules, including any non-positional properties of the molecular sequence.\", \"n\": \"Nucleic acid property calculation\", \"ns\": [], \"u\": \"operation_0262\", \"es\": [], \"ch\": [{\"n\": \"Restriction digest\", \"u\": \"operation_0365\"}, {\"n\": \"Nucleic acid thermodynamic property calculation\", \"u\": \"operation_0455\"}, {\"n\": \"Nucleic acid melting profile plotting\", \"u\": \"operation_0456\"}, {\"n\": \"Nucleic acid curvature calculation\", \"u\": \"operation_0461\"}], \"p\": [{\"n\": \"Operation||Calculation||Nucleic acid property calculation\", \"k\": \"operation_0004||operation_3438||operation_0262\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_0455\": {\"d\": \"Calculate a thermodynamic property of DNA or DNA/RNA, such as melting temperature, enthalpy and entropy.\", \"n\": \"Nucleic acid thermodynamic property calculation\", \"ns\": [], \"u\": \"operation_0455\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Operation||Calculation||Nucleic acid property calculation||Nucleic acid thermodynamic property calculation\", \"k\": \"operation_0004||operation_3438||operation_0262||operation_0455\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_0461\": {\"d\": \"Calculate curvature and flexibility / stiffness of a nucleotide sequence.\", \"n\": \"Nucleic acid curvature calculation\", \"ns\": [], \"u\": \"operation_0461\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Operation||Calculation||Nucleic acid property calculation||Nucleic acid curvature calculation\", \"k\": \"operation_0004||operation_3438||operation_0262||operation_0461\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_2238\": {\"d\": \"Perform a statistical data operation of some type, e.g. calibration or validation.\", \"n\": \"Statistical calculation\", \"ns\": [\"Expectation maximisation\", \"Gibbs sampling\", \"Hypothesis testing\", \"Omnibus test\"], \"u\": \"operation_2238\", \"es\": [\"Significance testing\", \"Statistical analysis\", \"Statistical test\", \"Statistical testing\"], \"ch\": [{\"n\": \"Standardisation and normalisation\", \"u\": \"operation_3435\"}, {\"n\": \"Imputation\", \"u\": \"operation_3557\"}, {\"n\": \"Statistical inference\", \"u\": \"operation_3658\"}, {\"n\": \"Regression analysis\", \"u\": \"operation_3659\"}, {\"n\": \"Statistical modelling\", \"u\": \"operation_3664\"}, {\"n\": \"Principal component analysis\", \"u\": \"operation_3960\"}], \"p\": [{\"n\": \"Operation||Calculation||Statistical calculation\", \"k\": \"operation_0004||operation_3438||operation_2238\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3435\": {\"d\": \"Standardize or normalize data by some statistical method.\", \"n\": \"Standardisation and normalisation\", \"ns\": [\"Normalisation\", \"Standardisation\"], \"u\": \"operation_3435\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Operation||Calculation||Statistical calculation||Standardisation and normalisation\", \"k\": \"operation_0004||operation_3438||operation_2238||operation_3435\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3557\": {\"d\": \"Replace missing data with substituted values, usually by using some statistical or other mathematical approach.\", \"n\": \"Imputation\", \"ns\": [], \"u\": \"operation_3557\", \"es\": [\"Data imputation\"], \"ch\": [], \"p\": [{\"n\": \"Operation||Calculation||Statistical calculation||Imputation\", \"k\": \"operation_0004||operation_3438||operation_2238||operation_3557\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3658\": {\"d\": \"Analyse data in order to deduce properties of an underlying distribution or population.\", \"n\": \"Statistical inference\", \"ns\": [\"Empirical Bayes\"], \"u\": \"operation_3658\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Operation||Calculation||Statistical calculation||Statistical inference\", \"k\": \"operation_0004||operation_3438||operation_2238||operation_3658\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3659\": {\"d\": \"A statistical calculation to estimate the relationships among variables.\", \"n\": \"Regression analysis\", \"ns\": [\"Regression\"], \"u\": \"operation_3659\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Operation||Calculation||Statistical calculation||Regression analysis\", \"k\": \"operation_0004||operation_3438||operation_2238||operation_3659\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3664\": {\"d\": \"Construction of a statistical model, or a set of assumptions around some observed data, usually by describing a set of probability distributions which approximate the distribution of data.\", \"n\": \"Statistical modelling\", \"ns\": [], \"u\": \"operation_3664\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Operation||Calculation||Statistical calculation||Statistical modelling\", \"k\": \"operation_0004||operation_3438||operation_2238||operation_3664\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3960\": {\"d\": \"A statistical procedure that uses an orthogonal transformation to convert a set of observations of possibly correlated variables into a set of values of linearly uncorrelated variables called principal components.\", \"n\": \"Principal component analysis\", \"ns\": [], \"u\": \"operation_3960\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Operation||Calculation||Statistical calculation||Principal component analysis\", \"k\": \"operation_0004||operation_3438||operation_2238||operation_3960\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3632\": {\"d\": \"Calculate the isotope distribution of a given chemical species.\", \"n\": \"Isotopic distributions calculation\", \"ns\": [], \"u\": \"operation_3632\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Operation||Calculation||Isotopic distributions calculation\", \"k\": \"operation_0004||operation_3438||operation_3632\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3633\": {\"d\": \"Prediction of retention time in a mass spectrometry experiment based on compositional and structural properties of the separated species.\", \"n\": \"Retention time prediction\", \"ns\": [], \"u\": \"operation_3633\", \"es\": [\"Retention time calculation\"], \"ch\": [], \"p\": [{\"n\": \"Operation||Calculation||Retention time prediction\", \"k\": \"operation_0004||operation_3438||operation_3633\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3797\": {\"d\": \"The calculation of species richness for a number of individual samples, based on plots of the number of species as a function of the number of samples (rarefaction curves).\", \"n\": \"Rarefaction\", \"ns\": [], \"u\": \"operation_3797\", \"es\": [\"Species richness assessment\"], \"ch\": [], \"p\": [{\"n\": \"Operation||Calculation||Rarefaction\", \"k\": \"operation_0004||operation_3438||operation_3797\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3935\": {\"d\": \"A process used in statistics, machine learning, and information theory that reduces the number of random variables by obtaining a set of principal variables.\", \"n\": \"Dimensionality reduction\", \"ns\": [], \"u\": \"operation_3935\", \"es\": [\"Dimension reduction\"], \"ch\": [{\"n\": \"Feature selection\", \"u\": \"operation_3936\"}, {\"n\": \"Feature extraction\", \"u\": \"operation_3937\"}], \"p\": [{\"n\": \"Operation||Calculation||Dimensionality reduction\", \"k\": \"operation_0004||operation_3438||operation_3935\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3936\": {\"d\": \"A dimensionality reduction process that selects a subset of relevant features (variables, predictors) for use in model construction.\", \"n\": \"Feature selection\", \"ns\": [], \"u\": \"operation_3936\", \"es\": [\"Attribute selection\", \"Variable selection\", \"Variable subset selection\"], \"ch\": [], \"p\": [{\"n\": \"Operation||Calculation||Dimensionality reduction||Feature selection\", \"k\": \"operation_0004||operation_3438||operation_3935||operation_3936\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3937\": {\"d\": \"A dimensionality reduction process which builds (ideally) informative and non-redundant values (features) from an initial set of measured data, to aid subsequent generalization, learning or interpretation.\", \"n\": \"Feature extraction\", \"ns\": [], \"u\": \"operation_3937\", \"es\": [\"Feature projection\"], \"ch\": [], \"p\": [{\"n\": \"Operation||Calculation||Dimensionality reduction||Feature extraction\", \"k\": \"operation_0004||operation_3438||operation_3935||operation_3937\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3465\": {\"d\": \"Identify a correlation, i.e. a statistical relationship between two random variables or two sets of data.\", \"n\": \"Correlation\", \"ns\": [], \"u\": \"operation_3465\", \"es\": [], \"ch\": [{\"n\": \"Sequence alignment analysis (site correlation)\", \"u\": \"operation_0449\"}, {\"n\": \"Expression correlation analysis\", \"u\": \"operation_3463\"}], \"p\": [{\"n\": \"Operation||Correlation\", \"k\": \"operation_0004||operation_3465\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3760\": {\"d\": \"Operations concerning the handling and use of other tools.\", \"n\": \"Service management\", \"ns\": [\"Endpoint management\"], \"u\": \"operation_3760\", \"es\": [], \"ch\": [{\"n\": \"Service discovery\", \"u\": \"operation_3761\"}, {\"n\": \"Service composition\", \"u\": \"operation_3762\"}, {\"n\": \"Service invocation\", \"u\": \"operation_3763\"}], \"p\": [{\"n\": \"Operation||Service management\", \"k\": \"operation_0004||operation_3760\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3761\": {\"d\": \"An operation supporting the browsing or discovery of other tools and services.\", \"n\": \"Service discovery\", \"ns\": [], \"u\": \"operation_3761\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Operation||Service management||Service discovery\", \"k\": \"operation_0004||operation_3760||operation_3761\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3762\": {\"d\": \"An operation supporting the aggregation of other services (at least two) into a funtional unit, for the automation of some task.\", \"n\": \"Service composition\", \"ns\": [], \"u\": \"operation_3762\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Operation||Service management||Service composition\", \"k\": \"operation_0004||operation_3760||operation_3762\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3763\": {\"d\": \"An operation supporting the calling (invocation) of other tools and services.\", \"n\": \"Service invo