nition\": \"An image from a cell migration track assay.\", \"path\": [{\"name\": \"Data||Image||Cell migration track image\", \"key\": \"data_0006||data_2968||data_3449\"}], \"name\": \"Cell migration track image\", \"uri\": \"http://edamontology.org/data_3449\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data concerning a biochemical reaction, typically data and more general annotation on the kinetics of enzyme-catalysed reaction.\", \"path\": [{\"name\": \"Data||Reaction data\", \"key\": \"data_0006||data_2978\"}], \"name\": \"Reaction data\", \"uri\": \"http://edamontology.org/data_2978\", \"exact_synonyms\": [\"Enzyme kinetics annotation\", \"Reaction annotation\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Enzyme kinetics data\", \"uri\": \"http://edamontology.org/data_2024\"}]}, {\"definition\": \"Data concerning chemical reaction(s) catalysed by enzyme(s).\", \"path\": {\"name\": \"Data||Reaction data||Enzyme kinetics data\", \"key\": \"data_0006||data_2978||data_2024\"}, \"name\": \"Enzyme kinetics data\", \"uri\": \"http://edamontology.org/data_2024\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Vmax\", \"uri\": \"http://edamontology.org/data_0909\"}, {\"name\": \"Km\", \"uri\": \"http://edamontology.org/data_0910\"}, {\"name\": \"Michaelis Menten plot\", \"uri\": \"http://edamontology.org/data_2025\"}, {\"name\": \"Hanes Woolf plot\", \"uri\": \"http://edamontology.org/data_2026\"}]}, {\"definition\": \"The maximum initial velocity or rate of a reaction. It is the limiting velocity as substrate concentrations get very large.\", \"path\": {\"name\": \"Data||Reaction data||Enzyme kinetics data||Vmax\", \"key\": \"data_0006||data_2978||data_2024||data_0909\"}, \"name\": \"Vmax\", \"uri\": \"http://edamontology.org/data_0909\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Km is the concentration (usually in Molar units) of substrate that leads to half-maximal velocity of an enzyme-catalysed reaction.\", \"path\": {\"name\": \"Data||Reaction data||Enzyme kinetics data||Km\", \"key\": \"data_0006||data_2978||data_2024||data_0910\"}, \"name\": \"Km\", \"uri\": \"http://edamontology.org/data_0910\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A plot giving an approximation of the kinetics of an enzyme-catalysed reaction, assuming simple kinetics (i.e. no intermediate or product inhibition, allostericity or cooperativity). It plots initial reaction rate to the substrate concentration (S) from which the maximum rate (vmax) is apparent.\", \"path\": {\"name\": \"Data||Reaction data||Enzyme kinetics data||Michaelis Menten plot\", \"key\": \"data_0006||data_2978||data_2024||data_2025\"}, \"name\": \"Michaelis Menten plot\", \"uri\": \"http://edamontology.org/data_2025\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A plot based on the Michaelis Menten equation of enzyme kinetics plotting the ratio of the initial substrate concentration (S) against the reaction velocity (v).\", \"path\": {\"name\": \"Data||Reaction data||Enzyme kinetics data||Hanes Woolf plot\", \"key\": \"data_0006||data_2978||data_2024||data_2026\"}, \"name\": \"Hanes Woolf plot\", \"uri\": \"http://edamontology.org/data_2026\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data concerning the classification, identification and naming of organisms.\", \"path\": [{\"name\": \"Data||Taxonomy\", \"key\": \"data_0006||data_3028\"}], \"name\": \"Taxonomy\", \"uri\": \"http://edamontology.org/data_3028\", \"exact_synonyms\": [\"Taxonomic data\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Raw data such as measurements or other results from laboratory experiments, as generated from laboratory hardware.\", \"path\": [{\"name\": \"Data||Experimental measurement\", \"key\": \"data_0006||data_3108\"}],