edamontology.org/data_2870\", \"exact_synonyms\": [\"RH map\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Regular expression pattern.\", \"path\": [{\"name\": \"Data||Regular expression\", \"key\": \"data_0006||data_1352\"}], \"name\": \"Regular expression\", \"uri\": \"http://edamontology.org/data_1352\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A numerical value, that is some type of scored value arising for example from a prediction method.\", \"path\": [{\"name\": \"Data||Score\", \"key\": \"data_0006||data_1772\"}], \"name\": \"Score\", \"uri\": \"http://edamontology.org/data_1772\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Sequence similarity score\", \"uri\": \"http://edamontology.org/data_0865\"}, {\"name\": \"Structure similarity score\", \"uri\": \"http://edamontology.org/data_0888\"}, {\"name\": \"Statistical estimate score\", \"uri\": \"http://edamontology.org/data_0951\"}, {\"name\": \"Alignment score or penalty\", \"uri\": \"http://edamontology.org/data_1394\"}, {\"name\": \"Localisation score\", \"uri\": \"http://edamontology.org/data_3756\"}]}, {\"definition\": \"A value representing molecular sequence similarity.\", \"path\": [{\"name\": \"Data||Score||Sequence similarity score\", \"key\": \"data_0006||data_1772||data_0865\"}], \"name\": \"Sequence similarity score\", \"uri\": \"http://edamontology.org/data_0865\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Sequence identity\", \"uri\": \"http://edamontology.org/data_1412\"}, {\"name\": \"Sequence similarity\", \"uri\": \"http://edamontology.org/data_1413\"}]}, {\"definition\": \"Sequence identity is the number (%) of matches (identical characters) in positions from an alignment of two molecular sequences.\", \"path\": [{\"name\": \"Data||Score||Sequence similarity score||Sequence identity\", \"key\": \"data_0006||data_1772||data_0865||data_1412\"}], \"name\": \"Sequence identity\", \"uri\": \"http://edamontology.org/data_1412\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Sequence similarity is the similarity (expressed as a percentage) of two molecular sequences calculated from their alignment, a scoring matrix for scoring characters substitutions and penalties for gap insertion and extension.\", \"path\": [{\"name\": \"Data||Score||Sequence similarity score||Sequence similarity\", \"key\": \"data_0006||data_1772||data_0865||data_1413\"}], \"name\": \"Sequence similarity\", \"uri\": \"http://edamontology.org/data_1413\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Bit score\", \"uri\": \"http://edamontology.org/data_2335\"}]}, {\"definition\": \"A score derived from the alignment of two sequences, which is then normalised with respect to the scoring system.\", \"path\": [{\"name\": \"Data||Score||Sequence similarity score||Sequence similarity||Bit score\", \"key\": \"data_0006||data_1772||data_0865||data_1413||data_2335\"}], \"name\": \"Bit score\", \"uri\": \"http://edamontology.org/data_2335\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A value representing molecular structure similarity, measured from structure alignment or some other type of structure comparison.\", \"path\": [{\"name\": \"Data||Score||Structure similarity score\", \"key\": \"data_0006||data_1772||data_0888\"}], \"name\": \"Structure similarity score\", \"uri\": \"http://edamontology.org/data_0888\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Root-mean-square deviation\", \"uri\": \"http://edamontology.org/data_1497\"}, {\"name\": \"Tanimoto similarity score\", \"uri\": \"http://edamontology.org/data_1498\"}]}, {\"definition\": \"Root-mean-square deviation (RMSD) is calculated to measure the average distance between superimposed macromolecular coordinates.\", \"path\": [{\"name\": \"Data||Score||Structure similarity score||Root-mean-square deviation\", \"key\": \"data_0006||data_1772||data_0888||data_1497\"}], \"name\": \"Root-mean-square deviation\", \"uri\": \"http://edamontology.org/data_1497\", \"exact_synonyms\": [\"RMSD\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A measure of the similarity between two ligand fingerprints.\", \"path\": [{\"name\": \"Data||Score||Structure similarity score||Tanimoto similarity score\", \"key\": \"data_0006||data_1772||data_0888||data_1498\"}], \"name\": \"Tanimoto similarity score\", \"uri\": \"http://edamontology.org/data_1498\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A value representing estimated statistical significance of some observed data; typically sequence database hits.\", \"path\": [{\"name\": \"Data||Score||Statistical estimate score\", \"key\": \"data_0006||data_1772||data_0951\"}], \"name\": \"Statistical estimate score\", \"uri\": \"http://edamontology.org/data_0951\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"E-value\", \"uri\": \"http://edamontology.org/data_1667\"}, {\"name\": \"Z-value\", \"uri\": \"http://edamontology.org/data_1668\"}, {\"name\": \"P-value\", \"uri\": \"http://edamontology.org/data_1669\"}, {\"name\": \"Q-value\", \"uri\": \"http://edamontology.org/data_3932\"}]}, {\"definition\": \"A simple floating point number defining the lower or upper limit of an expectation value (E-value).\", \"path\": [{\"name\": \"Data||Score||Statistical estimate score||E-value\", \"key\": \"data_0006||data_1772||data_0951||data_1667\"}], \"name\": \"E-value\", \"uri\": \"http://edamontology.org/data_1667\", \"exact_synonyms\": [\"Expectation value\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The z-value is the number of standard deviations a data value is above or below a mean value.\", \"path\": [{\"name\": \"Data||Score||Statistical estimate score||Z-value\", \"key\": \"data_0006||data_1772||data_0951||data_1668\"}], \"name\": \"Z-value\", \"uri\": \"http://edamontology.org/data_1668\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The P-value is the probability of obtaining by random chance a result that is at least as extreme as an observed result, assuming a NULL hypothesis is true.\", \"path\": [{\"name\": \"Data||Score||Statistical estimate score||P-value\", \"key\": \"data_0006||data_1772||data_0951||data_1669\"}], \"name\": \"P-value\", \"uri\": \"http://edamontology.org/data_1669\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A score derived from the P-value to ensure correction for multiple tests. The Q-value provides an estimate of the positive False Discovery Rate (pFDR), i.e. the rate of false positives among all the cases reported positive: pFDR = FP / (FP + TP).\", \"path\": [{\"name\": \"Data||Score||Statistical estimate score||Q-value\", \"key\": \"data_0006||data_1772||data_0951||data_3932\"}], \"name\": \"Q-value\", \"uri\": \"http://edamontology.org/data_3932\", \"exact_synonyms\": [\"Adjusted P-value\", \"FDR\", \"Padj\", \"pFDR\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A simple floating point number defining the penalty for opening or extending a gap in an alignment.\", \"path\": [{\"name\": \"Data||Score||Alignment score or penalty\", \"key\": \"data_0006||data_1772||data_1394\"}], \"name\": \"Alignment score or penalty\", \"uri\": \"http://edamontology.org/data_1394\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Match reward score\", \"uri\": \"http://edamontology.org/data_1401\"}, {\"name\": \"Mismatch penalty score\", \"uri\": \"http://edamontology.org/data_1402\"}, {\"name\": \"Drop off score\", \"uri\": \"http://edamontology.org/data_1403\"}, {\"name\": \"Gap penalty\", \"uri\": \"http://edamontology.org/data_2137\"}]}, {\"definition\": \"The score for a \'match\' used in various sequence database search applications with simple scoring schemes.\", \"path\": [{\"name\": \"Data||Score||Alignment score or penalty||Match reward score\", \"key\": \"data_0006||data_1772||data_1394||data_1401\"}], \"name\": \"Match reward score\", \"uri\": \"http://edamontology.org/data_1401\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The score (penalty) for a \'mismatch\' used in various alignment and sequence database search applications with simple scoring schemes.\", \"path\": [{\"name\": \"Data||Score||Alignment score or penalty||Mismatch penalty score\", \"key\": \"data_0006||data_1772||data_1394||data_1402\"}], \"name\": \"Mismatch penalty score\", \"uri\": \"http://edamontology.org/data_1402\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"This is the threshold drop in score at which extension of word alignment is halted.\", \"path\": [{\"name\": \"Data||Score||Alignment score or penalty||Drop off score\", \"key\": \"data_0006||data_1772||data_1394||data_1403\"}], \"name\": \"Drop off score\", \"uri\": \"http://edamontology.org/data_1403\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A penalty for introducing or extending a gap in an alignment.\", \"path\": [{\"name\": \"Data||Score||Alignment score or penalty||Gap penalty\", \"key\": \"data_0006||data_1772||data_1394||data_2137\"}], \"name\": \"Gap penalty\", \"uri\": \"http://edamontology.org/data_2137\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Gap opening penalty\", \"uri\": \"http://edamontology.org/data_1397\"}, {\"name\": \"Gap extension penalty\", \"uri\": \"http://edamontology.org/data_1398\"}, {\"name\": \"Gap separation penalty\", \"uri\": \"http://edamontology.org/data_1399\"}]}, {\"definition\": \"A penalty for opening a gap in an alignment.\", \"path\": [{\"name\": \"Data||Score||Alignment score or penalty||Gap penalty||Gap opening penalty\", \"key\": \"data_0006||data_1772||data_1394||data_2137||data_1397\"}], \"name\": \"Gap opening penalty\", \"uri\": \"http://edamontology.org/data_1397\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Terminal gap opening penalty\", \"uri\": \"http://edamontology.org/data_1410\"}]}, {\"definition\": \"A number defining the penalty for opening gaps at the termini of an alignment, either from the N/C terminal of protein or 5\'/3\' terminal of nucleotide sequences.\", \"path\": [{\"name\": \"Data||Score||Alignment score or penalty||Gap penalty||Gap opening penalty||Terminal gap opening penalty\", \"key\": \"data_0006||data_1772||data_1394||data_2137||data_1397||data_1410\"}], \"name\": \"Terminal gap opening penalty\", \"uri\": \"http://edamontology.org/data_1410\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A penalty for extending a gap in an alignment.\", \"path\": [{\"name\": \"Data||Score||Alignment score or penalty||Gap penalty||Gap extension penalty\", \"key\": \"data_0006||data_1772||data_1394||data_2137||data_1398\"}], \"name\": \"Gap extension penalty\", \"uri\": \"http://edamontology.org/data_1398\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Terminal gap extension penalty\", \"uri\": \"http://edamontology.org/data_1411\"}]}, {\"definition\": \"A number defining the penalty for extending gaps at the termini of an alignment, either from the N/C terminal of protein or 5\'/3\' terminal of nucleotide sequences.\", \"path\": [{\"name\": \"Data||Score||Alignment score or penalty||Gap penalty||Gap extension penalty||Terminal gap extension penalty\", \"key\": \"data_0006||data_1772||data_1394||data_2137||data_1398||data_1411\"}], \"name\": \"Terminal gap extension penalty\", \"uri\": \"http://edamontology.org/data_1411\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A penalty for gaps that are close toge