4||data_0919\"}], \"name\": \"Chromosome report\", \"uri\": \"http://edamontology.org/data_0919\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A human-readable collection of information about the linkage of alleles.\", \"path\": [{\"name\": \"Data||Report||Nucleic acid report||Genetic linkage report\", \"key\": \"data_0006||data_2048||data_2084||data_0927\"}], \"name\": \"Genetic linkage report\", \"uri\": \"http://edamontology.org/data_0927\", \"exact_synonyms\": [\"Gene annotation (linkage)\"], \"narrow_synonyms\": [\"Linkage disequilibrium (report)\"], \"children\": []}, {\"definition\": \"A human-readable collection of information about RNA/DNA folding, minimum folding energies for DNA or RNA sequences, energy landscape of RNA mutants etc.\", \"path\": [{\"name\": \"Data||Report||Nucleic acid report||Nucleic acid folding report\", \"key\": \"data_0006||data_2048||data_2084||data_1596\"}], \"name\": \"Nucleic acid folding report\", \"uri\": \"http://edamontology.org/data_1596\", \"exact_synonyms\": [\"Nucleic acid report (folding model)\", \"Nucleic acid report (folding)\"], \"narrow_synonyms\": [\"RNA secondary structure folding classification\", \"RNA secondary structure folding probablities\"], \"children\": []}, {\"definition\": \"A human-readable collection of information about regions within a nucleic acid sequence which form secondary or tertiary (3D) structures.\", \"path\": [{\"name\": \"Data||Report||Nucleic acid report||Nucleic acid structure report\", \"key\": \"data_0006||data_2048||data_2084||data_3128\"}, {\"name\": \"Data||Report||Structure report||Nucleic acid structure report\", \"key\": \"data_0006||data_2048||data_2085||data_3128\"}], \"name\": \"Nucleic acid structure report\", \"uri\": \"http://edamontology.org/data_3128\", \"exact_synonyms\": [\"Nucleic acid features (structure)\"], \"narrow_synonyms\": [\"Quadruplexes (report)\", \"Stem loop (report)\", \"d-loop (report)\"], \"children\": []}, {\"definition\": \"A human-readable collection of information about a particular family of genes, typically a set of genes with similar sequence that originate from duplication of a common ancestor gene, or any other classification of nucleic acid sequences or structures that reflects gene structure.\", \"path\": [{\"name\": \"Data||Report||Nucleic acid report||Gene family report\", \"key\": \"data_0006||data_2048||data_2084||data_3148\"}], \"name\": \"Gene family report\", \"uri\": \"http://edamontology.org/data_3148\", \"exact_synonyms\": [\"Gene annotation (homology information)\", \"Gene annotation (homology)\", \"Gene family annotation\", \"Gene homology (report)\", \"Homology information\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"RNA family report\", \"uri\": \"http://edamontology.org/data_2354\"}]}, {\"definition\": \"A human-readable collection of information about a specific RNA family or other group of classified RNA sequences.\", \"path\": [{\"name\": \"Data||Report||Nucleic acid report||Gene family report||RNA family report\", \"key\": \"data_0006||data_2048||data_2084||data_3148||data_2354\"}], \"name\": \"RNA family report\", \"uri\": \"http://edamontology.org/data_2354\", \"exact_synonyms\": [\"RNA family annotation\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A human-readable collection of information about one or more molecular tertiary (3D) structures.  It might include annotation on the structure, a computer-generated report of analysis of structural data, and metadata (data about primary data) or any other free (essentially unformatted) text, as distinct from the primary data itself.\", \"path\": [{\"name\": \"Data||Report||Structure report\", \"key\": \"data_0006||data_2048||data_2085\"}], \"name\": \"Structure report\", \"uri\": \"http://edamontology.org/data_2085\", \"exact_synonyms\": [\"Structure-derived report\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Small molecule report\", \"uri\": \"http:/