synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Basic information about one or more bioinformatics applications or packages, such as name, type, description, or other documentation.\", \"path\": [{\"name\": \"Data||Report||Resource metadata||Tool metadata\", \"key\": \"data_0006||data_2048||data_2337||data_0958\"}], \"name\": \"Tool metadata\", \"uri\": \"http://edamontology.org/data_0958\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Textual metadata on a software author or end-user, for example a person or other software.\", \"path\": [{\"name\": \"Data||Report||Resource metadata||User metadata\", \"key\": \"data_0006||data_2048||data_2337||data_0960\"}], \"name\": \"User metadata\", \"uri\": \"http://edamontology.org/data_0960\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Basic information on any arbitrary database entry.\", \"path\": [{\"name\": \"Data||Report||Resource metadata||Database entry metadata\", \"key\": \"data_0006||data_2048||data_2337||data_2193\"}], \"name\": \"Database entry metadata\", \"uri\": \"http://edamontology.org/data_2193\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data concerning a biological ontology.\", \"path\": [{\"name\": \"Data||Report||Resource metadata||Ontology metadata\", \"key\": \"data_0006||data_2048||data_2337||data_2223\"}], \"name\": \"Ontology metadata\", \"uri\": \"http://edamontology.org/data_2223\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Metadata concerning the software, hardware or other aspects of a computer system.\", \"path\": [{\"name\": \"Data||Report||Resource metadata||System metadata\", \"key\": \"data_0006||data_2048||data_2337||data_3106\"}], \"name\": \"System metadata\", \"uri\": \"http://edamontology.org/data_3106\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definiti