\": \"Data||Molecular property||Amino acid property||Amino acid index\", \"key\": \"data_0006||data_2087||data_2016||data_1501\"}], \"name\": \"Amino acid index\", \"uri\": \"http://edamontology.org/data_1501\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Amino acid index (chemical classes)\", \"uri\": \"http://edamontology.org/data_1502\"}, {\"name\": \"Amino acid index (molecular weight)\", \"uri\": \"http://edamontology.org/data_1505\"}, {\"name\": \"Amino acid index (hydropathy)\", \"uri\": \"http://edamontology.org/data_1506\"}, {\"name\": \"Amino acid index (White-Wimley data)\", \"uri\": \"http://edamontology.org/data_1507\"}, {\"name\": \"Amino acid index (van der Waals radii)\", \"uri\": \"http://edamontology.org/data_1508\"}]}, {\"definition\": \"Chemical classification (small, aliphatic, aromatic, polar, charged etc) of amino acids.\", \"path\": [{\"name\": \"Data||Matrix||Amino acid index||Amino acid index (chemical classes)\", \"key\": \"data_0006||data_2082||data_1501||data_1502\"}, {\"name\": \"Data||Molecular property||Amino acid property||Amino acid index||Amino acid index (chemical classes)\", \"key\": \"data_0006||data_2087||data_2016||data_1501||data_1502\"}], \"name\": \"Amino acid index (chemical classes)\", \"uri\": \"http://edamontology.org/data_1502\", \"exact_synonyms\": [\"Chemical classes (amino acids)\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Molecular weights of amino acids.\", \"path\": [{\"name\": \"Data||Matrix||Amino acid index||Amino acid index (molecular weight)\", \"key\": \"data_0006||data_2082||data_1501||data_1505\"}, {\"name\": \"Data||Molecular property||Amino acid property||Amino acid index||Amino acid index (molecular weight)\", \"key\": \"data_0006||data_2087||data_2016||data_1501||data_1505\"}], \"name\": \"Amino acid index (molecular weight)\", \"uri\": \"http://edamontology.org/data_1505\", \"exact_synonyms\": [\"Molecular weight (amino acids)\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Hydrophobic, hydrophilic or charge properties of amino acids.\", \"path\": [{\"name\": \"Data||Matrix||Amino acid index||Amino acid index (hydropathy)\", \"key\": \"data_0006||data_2082||data_1501||data_1506\"}, {\"name\": \"Data||Molecular property||Amino acid property||Amino acid index||Amino acid index (hydropathy)\", \"key\": \"data_0006||data_2087||data_2016||data_1501||data_1506\"}], \"name\": \"Amino acid index (hydropathy)\", \"uri\": \"http://edamontology.org/data_1506\", \"exact_synonyms\": [\"Hydropathy (amino acids)\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Experimental free energy values for the water-interface and water-octanol transitions for the amino acids.\", \"path\": [{\"name\": \"Data||Matrix||Amino acid index||Amino acid index (White-Wimley data)\", \"key\": \"data_0006||data_2082||data_1501||data_1507\"}, {\"name\": \"Data||Molecular property||Amino acid property||Amino acid index||Amino acid index (White-Wimley data)\", \"key\": \"data_0006||data_2087||data_2016||data_1501||data_1507\"}], \"name\": \"Amino acid index (White-Wimley data)\", \"uri\": \"http://edamontology.org/data_1507\", \"exact_synonyms\": [\"White-Wimley data (amino acids)\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Van der Waals radii of atoms for different amino acid residues.\", \"path\": [{\"name\": \"Data||Matrix||Amino acid index||Amino acid index (van der Waals radii)\", \"key\": \"data_0006||data_2082||data_1501||data_1508\"}, {\"name\": \"Data||Molecular property||Amino acid property||Amino acid index||Amino acid index (van der Waals radii)\", \"key\": \"data_0006||data_2087||data_2016||data_1501||data_1508\"}], \"name\": \"Amino acid index (van der Waals radii)\", \"uri\": \"http://edamontology.org/data_1508\", \"exact_synonyms\": [\"van der Waals radii (amino acids)\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A simple matrix of numbers, where each value (or column of values) is derived derived from analysis of the corresponding position in a sequence alignment.\", \"path\": {\"name\": \"Data||Matrix||Position-specific scoring matrix\", \"key\": \"data_0006||data_2082||data_2854\"}, \"name\": \"Position-specific scoring matrix\", \"uri\": \"http://edamontology.org/data_2854\", \"exact_synonyms\": [\"PSSM\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Position frequency matrix\", \"uri\": \"http://edamontology.org/data_1361\"}, {\"name\": \"Position weight matrix\", \"uri\": \"http://edamontology.org/data_1362\"}, {\"name\": \"Information content matrix\", \"uri\": \"http://edamontology.org/data_1363\"}, {\"name\": \"Fingerprint\", \"uri\": \"http://edamontology.org/data_1365\"}]}, {\"definition\": \"A profile (typically representing a sequence alignment) that is a simple matrix of nucleotide (or amino acid) counts per position.\", \"path\": {\"name\": \"Data||Matrix||Position-specific scoring matrix||Position frequency matrix\", \"key\": \"data_0006||data_2082||data_2854||data_1361\"}, \"name\": \"Position frequency matrix\", \"uri\": \"http://edamontology.org/data_1361\", \"exact_synonyms\": [\"PFM\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A profile (typically representing a sequence alignment) that is weighted matrix of nucleotide (or amino acid) counts per position.\", \"path\": {\"name\": \"Data||Matrix||Position-specific scoring matrix||Position weight matrix\", \"key\": \"data_0006||data_2082||data_2854||data_1362\"}, \"name\": \"Position weight matrix\", \"uri\": \"http://edamontology.org/data_1362\", \"exact_synonyms\": [\"PWM\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A profile (typically representing a sequence alignment) derived from a matrix of nucleotide (or amino acid) counts per position that reflects information content at each position.\", \"path\": {\"name\": \"Data||Matrix||Position-specific scoring matrix||Information content matrix\", \"key\": \"data_0006||data_2082||data_2854||data_1363\"}, \"name\": \"Information content matrix\", \"uri\": \"http://edamontology.org/data_1363\", \"exact_synonyms\": [\"ICM\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"One or more fingerprints (sequence classifiers) as used in the PRINTS database.\", \"path\": {\"name\": \"Data||Matrix||Position-specific scoring matrix||Fingerprint\", \"key\": \"data_0006||data_2082||data_2854||data_1365\"}, \"name\": \"Fingerprint\", \"uri\": \"http://edamontology.org/data_1365\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A matrix of distances between molecular entities, where a value (distance) is (typically) derived from comparison of two entities and reflects their similarity.\", \"path\": [{\"name\": \"Data||Matrix||Distance matrix\", \"key\": \"data_0006||data_2082||data_2855\"}], \"name\": \"Distance matrix\", \"uri\": \"http://edamontology.org/data_2855\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Sequence distance matrix\", \"uri\": \"http://edamontology.org/data_0870\"}, {\"name\": \"Protein distance matrix\", \"uri\": \"http://edamontology.org/data_1546\"}, {\"name\": \"Structural distance matrix\", \"uri\": \"http://edamontology.org/data_2856\"}]}, {\"definition\": \"A matrix of estimated evolutionary distance between molecular sequences, such as is suitable for phylogenetic tree calculation.\", \"path\": [{\"name\": \"Data||Matrix||Distance matrix||Sequence distance matrix\", \"key\": \"data_0006||data_2082||data_2855||data_0870\"}], \"name\": \"Sequence distance matrix\", \"uri\": \"http://edamontology.org/data_0870\", \"exact_synonyms\": [\"Phylogenetic distance matrix\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A matrix of distances between amino acid residues (for example the C-alpha atoms) in a protein structure.\", \"path\": [{\"name\": \"Data||Matrix||Distance matrix||Protein distanc