a.\", \"path\": [{\"name\": \"Data||Biodiversity data\", \"key\": \"data_0006||data_3707\"}, {\"name\": \"Data||Ecological data||Biodiversity data\", \"key\": \"data_0006||data_3736||data_3707\"}], \"name\": \"Biodiversity data\", \"uri\": \"http://edamontology.org/data_3707\", \"exact_synonyms\": [\"Biodiversity information\"], \"narrow_synonyms\": [\"OTU table\"], \"children\": [{\"name\": \"Alpha diversity data\", \"uri\": \"http://edamontology.org/data_3737\"}, {\"name\": \"Beta diversity data\", \"uri\": \"http://edamontology.org/data_3738\"}, {\"name\": \"Gamma diversity data\", \"uri\": \"http://edamontology.org/data_3739\"}]}, {\"definition\": \"The mean species diversity in sites or habitats at a local scale.\", \"path\": [{\"name\": \"Data||Biodiversity data||Alpha diversity data\", \"key\": \"data_0006||data_3707||data_3737\"}, {\"name\": \"Data||Ecological data||Biodiversity data||Alpha diversity data\", \"key\": \"data_0006||data_3736||data_3707||data_3737\"}], \"name\": \"Alpha diversity data\", \"uri\": \"http://edamontology.org/data_3737\", \"exact_synonyms\": [\"\\u03b1-diversity\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The ratio between regional and local species diversity.\", \"path\": [{\"name\": \"Data||Biodiversity data||Beta diversity data\", \"key\": \"data_0006||data_3707||data_3738\"}, {\"name\": \"Data||Ecological data||Biodiversity data||Beta diversity data\", \"key\": \"data_0006||data_3736||data_3707||data_3738\"}], \"name\": \"Beta diversity data\", \"uri\": \"http://edamontology.org/data_3738\", \"exact_synonyms\": [\"True beta diversity\", \"\\u03b2-diversity\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The total species diversity in a landscape.\", \"path\": [{\"name\": \"Data||Biodiversity data||Gamma diversity data\", \"key\": \"data_0006||data_3707||data_3739\"}, {\"name\": \"Data||Ecological data||Biodiversity data||Gamma diversity data\", \"key\": \"data_0006||data_3736||data_3707||data_3739\"}], \"name\": \"Gamma diversity data\", \"uri\": \"http://edamontology.org/data_3739\", \"exact_synonyms\": [\"\\u0263-diversity\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data concerning ecology; for example measurements and reports from the study of interactions among organisms and their environment.\", \"path\": [{\"name\": \"Data||Ecological data\", \"key\": \"data_0006||data_3736\"}], \"name\": \"Ecological data\", \"uri\": \"http://edamontology.org/data_3736\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Biodiversity data\", \"uri\": \"http://edamontology.org/data_3707\"}]}, {\"definition\": \"Machine-readable biodiversity data.\", \"path\": {\"name\": \"Data||Ecological data||Biodiversity data\", \"key\": \"data_0006||data_3736||data_3707\"}, \"name\": \"Biodiversity data\", \"uri\": \"http://edamontology.org/data_3707\", \"exact_synonyms\": [\"Biodiversity information\"], \"narrow_synonyms\": [\"OTU table\"], \"children\": [{\"name\": \"Alpha diversity data\", \"uri\": \"http://edamontology.org/data_3737\"}, {\"name\": \"Beta diversity data\", \"uri\": \"http://edamontology.org/data_3738\"}, {\"name\": \"Gamma diversity data\", \"uri\": \"http://edamontology.org/data_3739\"}]}, {\"definition\": \"The mean species diversity in sites or habitats at a local scale.\", \"path\": {\"name\": \"Data||Ecological data||Biodiversity data||Alpha diversity data\", \"key\": \"data_0006||data_3736||data_3707||data_3737\"}, \"name\": \"Alpha diversity data\", \"uri\": \"http://edamontology.org/data_3737\", \"exact_synonyms\": [\"\\u03b1-diversity\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The ratio between regional and local species diversity.\", \"path\": {\"name\": \"Data||Ecological data||Biodiversity data||Beta diversity data\", \"key\": \"data_0006||data_3736||data_3707||data_3738\"}, \"name\": \"Beta diversity data\", \"uri\": \"http://edamontology.org/data_3738\", \"exact_synonyms\": [\"True beta diversity\", \"\\u03b2-diversity\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The total species diversity in a landscape.\", \"path\": {\"name\": \"Data||Ecological data||Biodiversity data||Gamma diversity data\", \"key\": \"data_0006||data_3736||data_3707||data_3739\"}, \"name\": \"Gamma diversity data\", \"uri\": \"http://edamontology.org/data_3739\", \"exact_synonyms\": [\"\\u0263-diversity\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A ranked list of categories (usually ontology concepts), each associated with a statistical metric of over-/under-representation within the studied data.\", \"path\": [{\"name\": \"Data||Over-representation data\", \"key\": \"data_0006||data_3753\"}], \"name\": \"Over-representation data\", \"uri\": \"http://edamontology.org/data_3753\", \"exact_synonyms\": [\"Enrichment report\", \"Over-representation report\"], \"narrow_synonyms\": [\"Functional enrichment report\"], \"children\": [{\"name\": \"GO-term enrichment data\", \"uri\": \"http://edamontology.org/data_3754\"}, {\"name\": \"Pathway overrepresentation data\", \"uri\": \"http://edamontology.org/data_3953\"}]}, {\"definition\": \"A ranked list of Gene Ontology concepts, each associated with a p-value, concerning or derived from the analysis of e.g. a set of genes or proteins.\", \"path\": [{\"name\": \"Data||Over-representation data||GO-term enrichment data\", \"key\": \"data_0006||data_3753||data_3754\"}], \"name\": \"GO-term enrichment data\", \"uri\": \"http://edamontology.org/data_3754\", \"exact_synonyms\": [\"GO-term enrichment report\", \"Gene ontology concept over-representation report\", \"Gene ontology enrichment report\", \"Gene ontology term enrichment report\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A ranked list of pathways, each associated with z-score, p-value or similar, concerning or derived from the analysis of e.g. a set of genes or proteins.\", \"path\": [{\"name\": \"Data||Over-representation data||Pathway overrepresentation data\", \"key\": \"data_0006||data_3753||data_3953\"}], \"name\": \"Pathway overrepresentation data\", \"uri\": \"http://edamontology.org/data_3953\", \"exact_synonyms\": [\"Pathway analysis results\", \"Pathway enrichment report\", \"Pathway over-representation report\", \"Pathway report\", \"Pathway term enrichment report\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A structured query, in form of a script, that defines a database search task.\", \"path\": [{\"name\": \"Data||Query script\", \"key\": \"data_0006||data_3786\"}], \"name\": \"Query script\", \"uri\": \"http://edamontology.org/data_3786\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data coming from molecular simulations, computer \\\"experiments\\\" on model molecules.\", \"path\": [{\"name\": \"Data||Molecular simulation data\", \"key\": \"data_0006||data_3842\"}], \"name\": \"Molecular simulation data\", \"uri\": \"http://edamontology.org/data_3842\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data coming from molecular simulations, computer \\\"experiments\\\" on model molecules. Tipically formed by two separated but indivisible pieces of information: topology data (static) and trajectory data (dynamic).\", \"path\": [{\"name\": \"Data||Simulation\", \"key\": \"data_0006||data_3869\"}], \"name\": \"Simulation\", \"uri\": \"http://edamontology.org/data_3869\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Trajectory data\", \"uri\": \"http://edamontology.org/data_3870\"}, {\"name\": \"Forcefield parameters\", \"uri\": \"http://edamontology.org/data_3871\"}, {\"name\": \"Topology data\", \"uri\": \"http://edamontology.org/data_3872\"}]}, {\"definition\": \"Dynamic information of a structure molecular system coming from a molecular simulation: XYZ 3D coordinates (sometimes with their associated velocities) for every atom along time.\", \"path\": [{\"name\": \"Data||Simulation||Trajectory data\", \"key\": \"data_0006||data_3869||data_3870\"}], \"name\": \"Trajectory data\", \"uri\": \"http://edamontology.org/data_3870\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Force field parameters: charges, masses, radii, bond lengths, bond dihedrals, etc. define the structural molecular system, and are essential for the proper description and simulation of a molecular system.\", \"path\": [{\"name\": \"Data||Simulation||Forcefield parameters\", \"key\": \"data_0006||data_3869||data_3871\"}], \"name\": \"Forcefield parameters\", \"uri\": \"http://edamontology.org/data_3871\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Static information of a structure molecular system that is needed for a molecular simulation: the list of atoms, their non-bonded parameters for Van der Waals and electrostatic interactions, and the complete connectivity in terms of bonds, angles and dihedrals.\", \"path\": [{\"name\": \"Data||Simulation||Topology data\", \"key\": \"data_0006||data_3869||data_3872\"}], \"name\": \"Topology data\", \"uri\": \"http://edamontology.org/data_3872\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}]','2025-08-27 12:52:46.301625');
