nonyms\": [], \"children\": []}, \"data_0883\": {\"definition\": \"3D coordinate and associated data for a macromolecular tertiary (3D) structure or part of a structure.\", \"path\": [{\"name\": \"Data||Structure\", \"key\": \"data_0006||data_0883\"}], \"name\": \"Structure\", \"uri\": \"http://edamontology.org/data_0883\", \"exact_synonyms\": [\"Coordinate model\", \"Structure data\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Nucleic acid structure\", \"uri\": \"http://edamontology.org/data_1459\"}, {\"name\": \"Protein structure\", \"uri\": \"http://edamontology.org/data_1460\"}, {\"name\": \"Carbohydrate structure\", \"uri\": \"http://edamontology.org/data_1462\"}, {\"name\": \"Small molecule structure\", \"uri\": \"http://edamontology.org/data_1463\"}, {\"name\": \"Lipid structure\", \"uri\": \"http://edamontology.org/data_2850\"}, {\"name\": \"3D EM Map\", \"uri\": \"http://edamontology.org/data_3805\"}, {\"name\": \"3D EM Mask\", \"uri\": \"http://edamontology.org/data_3806\"}]}, \"data_1459\": {\"definition\": \"3D coordinate and associated data for a nucleic acid tertiary (3D) structure.\", \"path\": [{\"name\": \"Data||Structure||Nucleic acid structure\", \"key\": \"data_0006||data_0883||data_1459\"}], \"name\": \"Nucleic acid structure\", \"uri\": \"http://edamontology.org/data_1459\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"DNA structure\", \"uri\": \"http://edamontology.org/data_1464\"}, {\"name\": \"RNA structure\", \"uri\": \"http://edamontology.org/data_1465\"}]}, \"data_1464\": {\"definition\": \"3D coordinate and associated data for a DNA tertiary (3D) structure.\", \"path\": [{\"name\": \"Data||Structure||Nucleic acid structure||DNA structure\", \"key\": \"data_0006||data_0883||data_1459||data_1464\"}], \"name\": \"DNA structure\", \"uri\": \"http://edamontology.org/data_1464\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1465\": {\"definition\": \"3D coordinate and associated data for an RNA tertiary (3D) structure.\", \"path\": [{\"name\": \"Data||Structure||Nucleic acid structure||RNA structure\", \"key\": \"data_0006||data_0883||data_1459||data_1465\"}], \"name\": \"RNA structure\", \"uri\": \"http://edamontology.org/data_1465\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"RNA secondary structure\", \"uri\": \"http://edamontology.org/data_0880\"}, {\"name\": \"tRNA structure\", \"uri\": \"http://edamontology.org/data_1466\"}]}, \"data_0880\": {\"definition\": \"An informative report of secondary structure (predicted or real) of an RNA molecule.\", \"path\": [{\"name\": \"Data||Structure||Nucleic acid structure||RNA structure||RNA secondary structure\", \"key\": \"data_0006||data_0883||data_1459||data_1465||data_0880\"}], \"name\": \"RNA secondary structure\", \"uri\": \"http://edamontology.org/data_0880\", \"exact_synonyms\": [\"Secondary structure (RNA)\"], \"narrow_synonyms\": [], \"children\": []}, \"data_1466\": {\"definition\": \"3D coordinate and associated data for a tRNA tertiary (3D) structure, including tmRNA, snoRNAs etc.\", \"path\": [{\"name\": \"Data||Structure||Nucleic acid structure||RNA structure||tRNA structure\", \"key\": \"data_0006||data_0883||data_1459||data_1465||data_1466\"}], \"name\": \"tRNA structure\", \"uri\": \"http://edamontology.org/data_1466\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1460\": {\"definition\": \"3D coordinate and associated data for a protein tertiary (3D) structure, or part of a structure, possibly in complex with other molecules.\", \"path\": [{\"name\": \"Data||Structure||Protein structure\", \"key\": \"data_0006||data_0883||data_1460\"}], \"name\": \"Protein structure\", \"uri\": \"http://edamontology.org/data_1460\", \"exact_synonyms\": [\"Protein structures\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Protein-ligand complex\", \"uri\": \"http://edamontology.org/data_1461\"}, {\"name\": \"Protein