], \"narrow_synonyms\": [], \"children\": []}, \"data_1532\": {\"definition\": \"The optical density of a protein.\", \"path\": [{\"name\": \"Data||Molecular property||Protein property||Protein optical density\", \"key\": \"data_0006||data_2087||data_0897||data_1532\"}], \"name\": \"Protein optical density\", \"uri\": \"http://edamontology.org/data_1532\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1534\": {\"definition\": \"An report on allergenicity / immunogenicity of peptides and proteins.\", \"path\": [{\"name\": \"Data||Molecular property||Protein property||Peptide immunogenicity data\", \"key\": \"data_0006||data_2087||data_0897||data_1534\"}], \"name\": \"Peptide immunogenicity data\", \"uri\": \"http://edamontology.org/data_1534\", \"exact_synonyms\": [\"Peptide immunogenicity\", \"Peptide immunogenicity report\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Hopp and Woods plot\", \"uri\": \"http://edamontology.org/data_2957\"}]}, \"data_2957\": {\"definition\": \"A Hopp and Woods plot of predicted antigenicity of a peptide or protein.\", \"path\": [{\"name\": \"Data||Molecular property||Protein property||Peptide immunogenicity data||Hopp and Woods plot\", \"key\": \"data_0006||data_2087||data_0897||data_1534||data_2957\"}, {\"name\": \"Data||Plot||Hopp and Woods plot\", \"key\": \"data_0006||data_2884||data_2957\"}], \"name\": \"Hopp and Woods plot\", \"uri\": \"http://edamontology.org/data_2957\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1542\": {\"definition\": \"Data on the solvent accessible or buried surface area of a protein structure.\", \"path\": [{\"name\": \"Data||Molecular property||Protein property||Protein solvent accessibility\", \"key\": \"data_0006||data_2087||data_0897||data_1542\"}], \"name\": \"Protein solvent accessibility\", \"uri\": \"http://edamontology.org/data_1542\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1545\": {\"defin