.org/data_2849\"}, {\"name\": \"Bibliography\", \"uri\": \"http://edamontology.org/data_3505\"}, {\"name\": \"Text\", \"uri\": \"http://edamontology.org/data_3671\"}, {\"name\": \"Annotated text\", \"uri\": \"http://edamontology.org/data_3779\"}]}, \"data_0970\": {\"definition\": \"Bibliographic data that uniquely identifies a scientific article, book or other published material.\", \"path\": [{\"name\": \"Data||Text data||Citation\", \"key\": \"data_0006||data_2526||data_0970\"}], \"name\": \"Citation\", \"uri\": \"http://edamontology.org/data_0970\", \"exact_synonyms\": [\"Bibliographic reference\", \"Reference\"], \"narrow_synonyms\": [], \"children\": []}, \"data_0971\": {\"definition\": \"A scientific text, typically a full text article from a scientific journal.\", \"path\": [{\"name\": \"Data||Text data||Article\", \"key\": \"data_0006||data_2526||data_0971\"}, {\"name\": \"Data||Text data||Text||Article\", \"key\": \"data_0006||data_2526||data_3671||data_0971\"}], \"name\": \"Article\", \"uri\": \"http://edamontology.org/data_0971\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Article text\", \"Scientific article\"], \"children\": []}, \"data_2849\": {\"definition\": \"An abstract of a scientific article.\", \"path\": [{\"name\": \"Data||Text data||Abstract\", \"key\": \"data_0006||data_2526||data_2849\"}], \"name\": \"Abstract\", \"uri\": \"http://edamontology.org/data_2849\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_3505\": {\"definition\": \"A list of publications such as scientic papers or books.\", \"path\": [{\"name\": \"Data||Text data||Bibliography\", \"key\": \"data_0006||data_2526||data_3505\"}], \"name\": \"Bibliography\", \"uri\": \"http://edamontology.org/data_3505\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_3671\": {\"definition\": \"Any free or plain text, typically for human consumption and in English. Can instantiate also as a textual search query.\", \"path\": [{\"name\