amontology.org/data_2856\"}]}, \"data_0870\": {\"definition\": \"A matrix of estimated evolutionary distance between molecular sequences, such as is suitable for phylogenetic tree calculation.\", \"path\": [{\"name\": \"Data||Matrix||Distance matrix||Sequence distance matrix\", \"key\": \"data_0006||data_2082||data_2855||data_0870\"}], \"name\": \"Sequence distance matrix\", \"uri\": \"http://edamontology.org/data_0870\", \"exact_synonyms\": [\"Phylogenetic distance matrix\"], \"narrow_synonyms\": [], \"children\": []}, \"data_1546\": {\"definition\": \"A matrix of distances between amino acid residues (for example the C-alpha atoms) in a protein structure.\", \"path\": [{\"name\": \"Data||Matrix||Distance matrix||Protein distance matrix\", \"key\": \"data_0006||data_2082||data_2855||data_1546\"}, {\"name\": \"Data||Molecular property||Protein property||Protein interaction data||Protein distance matrix\", \"key\": \"data_0006||data_2087||data_0897||data_0906||data_1546\"}], \"name\": \"Protein distance matrix\", \"uri\": \"http://edamontology.org/data_1546\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_2856\": {\"definition\": \"Distances (values representing similarity) between a group of molecular structures.\", \"path\": [{\"name\": \"Data||Matrix||Distance matrix||Structural distance matrix\", \"key\": \"data_0006||data_2082||data_2855||data_2856\"}], \"name\": \"Structural distance matrix\", \"uri\": \"http://edamontology.org/data_2856\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_3112\": {\"definition\": \"The final processed (normalised) data for a set of hybridisations in a microarray experiment.\", \"path\": [{\"name\": \"Data||Matrix||Gene expression matrix\", \"key\": \"data_0006||data_2082||data_3112\"}, {\"name\": \"Data||Expression data||Gene expression matrix\", \"key\": \"data_0006||data_2603||data_3112\"}], \"name\": \"Gene expression matrix\", \"uri\": \"http://edamontology.org/data_311