definition\": \"Data on the net charge distribution (dipole moment) of a protein structure.\", \"path\": [{\"name\": \"Data||Molecular property||Protein property||Protein dipole moment\", \"key\": \"data_0006||data_2087||data_0897||data_1545\"}], \"name\": \"Protein dipole moment\", \"uri\": \"http://edamontology.org/data_1545\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_2024\": {\"definition\": \"Data concerning chemical reaction(s) catalysed by enzyme(s).\", \"path\": [{\"name\": \"Data||Molecular property||Protein property||Enzyme kinetics data\", \"key\": \"data_0006||data_2087||data_0897||data_2024\"}, {\"name\": \"Data||Reaction data||Enzyme kinetics data\", \"key\": \"data_0006||data_2978||data_2024\"}], \"name\": \"Enzyme kinetics data\", \"uri\": \"http://edamontology.org/data_2024\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Vmax\", \"uri\": \"http://edamontology.org/data_0909\"}, {\"name\": \"Km\", \"uri\": \"http://edamontology.org/data_0910\"}, {\"name\": \"Michaelis Menten plot\", \"uri\": \"http://edamontology.org/data_2025\"}, {\"name\": \"Hanes Woolf plot\", \"uri\": \"http://edamontology.org/data_2026\"}]}, \"data_0909\": {\"definition\": \"The maximum initial velocity or rate of a reaction. It is the limiting velocity as substrate concentrations get very large.\", \"path\": [{\"name\": \"Data||Molecular property||Protein property||Enzyme kinetics data||Vmax\", \"key\": \"data_0006||data_2087||data_0897||data_2024||data_0909\"}, {\"name\": \"Data||Reaction data||Enzyme kinetics data||Vmax\", \"key\": \"data_0006||data_2978||data_2024||data_0909\"}], \"name\": \"Vmax\", \"uri\": \"http://edamontology.org/data_0909\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_0910\": {\"definition\": \"Km is the concentration (usually in Molar units) of substrate that leads to half-maximal velocity of an enzyme-catalysed reaction.\", \"path\": [{\"name\": \"Data||Molecular property||Protein property||Enzyme kinetics data||Km\", \"key\": \"data_0006||data_2087||data_0897||data_2024||data_0910\"}, {\"name\": \"Data||Reaction data||Enzyme kinetics data||Km\", \"key\": \"data_0006||data_2978||data_2024||data_0910\"}], \"name\": \"Km\", \"uri\": \"http://edamontology.org/data_0910\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_2025\": {\"definition\": \"A plot giving an approximation of the kinetics of an enzyme-catalysed reaction, assuming simple kinetics (i.e. no intermediate or product inhibition, allostericity or cooperativity). It plots initial reaction rate to the substrate concentration (S) from which the maximum rate (vmax) is apparent.\", \"path\": [{\"name\": \"Data||Molecular property||Protein property||Enzyme kinetics data||Michaelis Menten plot\", \"key\": \"data_0006||data_2087||data_0897||data_2024||data_2025\"}, {\"name\": \"Data||Reaction data||Enzyme kinetics data||Michaelis Menten plot\", \"key\": \"data_0006||data_2978||data_2024||data_2025\"}], \"name\": \"Michaelis Menten plot\", \"uri\": \"http://edamontology.org/data_2025\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_2026\": {\"definition\": \"A plot based on the Michaelis Menten equation of enzyme kinetics plotting the ratio of the initial substrate concentration (S) against the reaction velocity (v).\", \"path\": [{\"name\": \"Data||Molecular property||Protein property||Enzyme kinetics data||Hanes Woolf plot\", \"key\": \"data_0006||data_2087||data_0897||data_2024||data_2026\"}, {\"name\": \"Data||Reaction data||Enzyme kinetics data||Hanes Woolf plot\", \"key\": \"data_0006||data_2978||data_2024||data_2026\"}], \"name\": \"Hanes Woolf plot\", \"uri\": \"http://edamontology.org/data_2026\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_2165\": {\"definition\": \"A plot of pK versus pH for a protein.\", \"path\": [{\"name\": \"Data||Molecular property||Protein property|