, {\"n\": \"Alignment score or penalty\", \"u\": \"data_1394\"}, {\"n\": \"Localisation score\", \"u\": \"data_3756\"}], \"p\": [{\"n\": \"Data||Score\", \"k\": \"data_0006||data_1772\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A value representing molecular sequence similarity.\", \"n\": \"Sequence similarity score\", \"ns\": [], \"u\": \"data_0865\", \"es\": [], \"ch\": [{\"n\": \"Sequence identity\", \"u\": \"data_1412\"}, {\"n\": \"Sequence similarity\", \"u\": \"data_1413\"}], \"p\": [{\"n\": \"Data||Score||Sequence similarity score\", \"k\": \"data_0006||data_1772||data_0865\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Sequence identity is the number (%) of matches (identical characters) in positions from an alignment of two molecular sequences.\", \"n\": \"Sequence identity\", \"ns\": [], \"u\": \"data_1412\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Score||Sequence similarity score||Sequence identity\", \"k\": \"data_0006||data_1772||data_0865||data_1412\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Sequence similarity is the similarity (expressed as a percentage) of two molecular sequences calculated from their alignment, a scoring matrix for scoring characters substitutions and penalties for gap insertion and extension.\", \"n\": \"Sequence similarity\", \"ns\": [], \"u\": \"data_1413\", \"es\": [], \"ch\": [{\"n\": \"Bit score\", \"u\": \"data_2335\"}], \"p\": [{\"n\": \"Data||Score||Sequence similarity score||Sequence similarity\", \"k\": \"data_0006||data_1772||data_0865||data_1413\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A score derived from the alignment of two sequences, which is then normalised with respect to the scoring system.\", \"n\": \"Bit score\", \"ns\": [], \"u\": \"data_2335\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Score||Sequence similarity score||Sequence similarity||Bit score\", \"k\": \"data_0006||data_1772||data_0865||data_1413||data_2335\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A value representing molecular structure similarity, measured from structure alignment or some other type of structure comparison.\", \"n\": \"Structure similarity score\", \"ns\": [], \"u\": \"data_0888\", \"es\": [], \"ch\": [{\"n\": \"Root-mean-square deviation\", \"u\": \"data_1497\"}, {\"n\": \"Tanimoto similarity score\", \"u\": \"data_1498\"}], \"p\": [{\"n\": \"Data||Score||Structure similarity score\", \"k\": \"data_0006||data_1772||data_0888\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Root-mean-square deviation (RMSD) is calculated to measure the average distance between superimposed macromolecular coordinates.\", \"n\": \"Root-mean-square deviation\", \"ns\": [], \"u\": \"data_1497\", \"es\": [\"RMSD\"], \"ch\": [], \"p\": [{\"n\": \"Data||Score||Structure similarity score||Root-mean-square deviation\", \"k\": \"data_0006||data_1772||data_0888||data_1497\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A measure of the similarity between two ligand fingerprints.\", \"n\": \"Tanimoto similarity score\", \"ns\": [], \"u\": \"data_1498\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Score||Structure similarity score||Tanimoto similarity score\", \"k\": \"data_0006||data_1772||data_0888||data_1498\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A value representing estimated statistical significance of some observed data; typically sequence database hits.\", \"n\": \"Statistical estimate score\", \"ns\": [], \"u\": \"data_0951\", \"es\": [], \"ch\": [{\"n\": \"E-value\", \"u\": \"data_1667\"}, {\"n\": \"Z-value\", \"u\": \"data_1668\"}, {\"n\": \"P-value\", \"u\": \"data_1669\"}, {\"n\": \"Q-value\", \"u\": \"data_3932\"}], \"p\": [{\"n\": \"Data||Score||Statistical estimate score\", \"k\": \"data_0006||data_1772||data_0951\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A simple floating point number defining the lower or upper limit of an expectation value (E-value).\", \"n\": \