nnotation\"], \"ch\": [{\"n\": \"Enzyme kinetics data\", \"u\": \"data_2024\"}], \"p\": [{\"n\": \"Data||Reaction data\", \"k\": \"data_0006||data_2978\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Data concerning chemical reaction(s) catalysed by enzyme(s).\", \"n\": \"Enzyme kinetics data\", \"ns\": [], \"u\": \"data_2024\", \"es\": [], \"ch\": [{\"n\": \"Vmax\", \"u\": \"data_0909\"}, {\"n\": \"Km\", \"u\": \"data_0910\"}, {\"n\": \"Michaelis Menten plot\", \"u\": \"data_2025\"}, {\"n\": \"Hanes Woolf plot\", \"u\": \"data_2026\"}], \"p\": {\"n\": \"Data||Reaction data||Enzyme kinetics data\", \"k\": \"data_0006||data_2978||data_2024\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The maximum initial velocity or rate of a reaction. It is the limiting velocity as substrate concentrations get very large.\", \"n\": \"Vmax\", \"ns\": [], \"u\": \"data_0909\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Data||Reaction data||Enzyme kinetics data||Vmax\", \"k\": \"data_0006||data_2978||data_2024||data_0909\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Km is the concentration (usually in Molar units) of substrate that leads to half-maximal velocity of an enzyme-catalysed reaction.\", \"n\": \"Km\", \"ns\": [], \"u\": \"data_0910\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Data||Reaction data||Enzyme kinetics data||Km\", \"k\": \"data_0006||data_2978||data_2024||data_0910\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A plot giving an approximation of the kinetics of an enzyme-catalysed reaction, assuming simple kinetics (i.e. no intermediate or product inhibition, allostericity or cooperativity). It plots initial reaction rate to the substrate concentration (S) from which the maximum rate (vmax) is apparent.\", \"n\": \"Michaelis Menten plot\", \"ns\": [], \"u\": \"data_2025\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Data||Reaction data||Enzyme kinetics data||Michaelis Menten plot\", \"k\": \"data_0006||data_2978||data_2024||data_2025\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A plot based on the Michaelis Menten equation of enzyme kinetics plotting the ratio of the initial substrate concentration (S) against the reaction velocity (v).\", \"n\": \"Hanes Woolf plot\", \"ns\": [], \"u\": \"data_2026\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Data||Reaction data||Enzyme kinetics data||Hanes Woolf plot\", \"k\": \"data_0006||data_2978||data_2024||data_2026\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Data concerning the classification, identification and naming of organisms.\", \"n\": \"Taxonomy\", \"ns\": [], \"u\": \"data_3028\", \"es\": [\"Taxonomic data\"], \"ch\": [], \"p\": [{\"n\": \"Data||Taxonomy\", \"k\": \"data_0006||data_3028\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Raw data such as measurements or other results from laboratory experiments, as generated from laboratory hardware.\", \"n\": \"Experimental measurement\", \"ns\": [\"Measurement metadata\", \"Raw experimental data\"], \"u\": \"data_3108\", \"es\": [\"Experimental measurement data\", \"Experimentally measured data\", \"Measured data\", \"Measurement\", \"Measurement data\"], \"ch\": [{\"n\": \"Protein interaction raw data\", \"u\": \"data_0905\"}, {\"n\": \"Sequence trace\", \"u\": \"data_0924\"}, {\"n\": \"RH scores\", \"u\": \"data_0926\"}, {\"n\": \"Volume map\", \"u\": \"data_0940\"}, {\"n\": \"Mass spectrometry data\", \"u\": \"data_2536\"}, {\"n\": \"Protein structure raw data\", \"u\": \"data_2537\"}, {\"n\": \"Raw microarray data\", \"u\": \"data_3110\"}, {\"n\": \"Physiology parameter\", \"u\": \"data_3722\"}, {\"n\": \"Morphology parameter\", \"u\": \"data_3723\"}, {\"n\": \"Cultivation parameter\", \"u\": \"data_3724\"}], \"p\": [{\"n\": \"Data||Experimental measurement\", \"k\": \"data_0006||data_3108\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Protein-protein interaction data from for example yeast two-hybrid analysis, protein microarrays, immunoaffinity