\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3949\": {\"d\": \"A profile HMM is a variant of a Hidden Markov model that is derived specifically from a set of (aligned) biological sequences. Profile HMMs provide the basis for a position-specific scoring system, which can be used to align sequences and search databases for related sequences.\", \"n\": \"Profile HMM\", \"ns\": [], \"u\": \"data_3949\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Sequence signature data||Sequence profile||Profile HMM\", \"k\": \"data_0006||data_0860||data_1354||data_3949\"}, {\"n\": \"Data||Mathematical model||Hidden Markov model||Profile HMM\", \"k\": \"data_0006||data_0950||data_1364||data_3949\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_0883\": {\"d\": \"3D coordinate and associated data for a macromolecular tertiary (3D) structure or part of a structure.\", \"n\": \"Structure\", \"ns\": [], \"u\": \"data_0883\", \"es\": [\"Coordinate model\", \"Structure data\"], \"ch\": [{\"n\": \"Nucleic acid structure\", \"u\": \"data_1459\"}, {\"n\": \"Protein structure\", \"u\": \"data_1460\"}, {\"n\": \"Carbohydrate structure\", \"u\": \"data_1462\"}, {\"n\": \"Small molecule structure\", \"u\": \"data_1463\"}, {\"n\": \"Lipid structure\", \"u\": \"data_2850\"}, {\"n\": \"3D EM Map\", \"u\": \"data_3805\"}, {\"n\": \"3D EM Mask\", \"u\": \"data_3806\"}], \"p\": [{\"n\": \"Data||Structure\", \"k\": \"data_0006||data_0883\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_1459\": {\"d\": \"3D coordinate and associated data for a nucleic acid tertiary (3D) structure.\", \"n\": \"Nucleic acid structure\", \"ns\": [], \"u\": \"data_1459\", \"es\": [], \"ch\": [{\"n\": \"DNA structure\", \"u\": \"data_1464\"}, {\"n\": \"RNA structure\", \"u\": \"data_1465\"}], \"p\": [{\"n\": \"Data||Structure||Nucleic acid structure\", \"k\": \"data_0006||data_0883||data_1459\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_1464\": {\"d\": \"3D coordinate and associated data for a DNA tertiary (3D) structure.\", \"n\": \"DNA structure\", \"ns\": [], \"u\": \"data_1464\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Structure||Nucleic acid structure||DNA structure\", \"k\": \"data_0006||data_0883||data_1459||data_1464\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_1465\": {\"d\": \"3D coordinate and associated data for an RNA tertiary (3D) structure.\", \"n\": \"RNA structure\", \"ns\": [], \"u\": \"data_1465\", \"es\": [], \"ch\": [{\"n\": \"RNA secondary structure\", \"u\": \"data_0880\"}, {\"n\": \"tRNA structure\", \"u\": \"data_1466\"}], \"p\": [{\"n\": \"Data||Structure||Nucleic acid structure||RNA structure\", \"k\": \"data_0006||data_0883||data_1459||data_1465\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_0880\": {\"d\": \"An informative report of secondary structure (predicted or real) of an RNA molecule.\", \"n\": \"RNA secondary structure\", \"ns\": [], \"u\": \"data_0880\", \"es\": [\"Secondary structure (RNA)\"], \"ch\": [], \"p\": [{\"n\": \"Data||Structure||Nucleic acid structure||RNA structure||RNA secondary structure\", \"k\": \"data_0006||data_0883||data_1459||data_1465||data_0880\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_1466\": {\"d\": \"3D coordinate and associated data for a tRNA tertiary (3D) structure, including tmRNA, snoRNAs etc.\", \"n\": \"tRNA structure\", \"ns\": [], \"u\": \"data_1466\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Structure||Nucleic acid structure||RNA structure||tRNA structure\", \"k\": \"data_0006||data_0883||data_1459||data_1465||data_1466\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_1460\": {\"d\": \"3D coordinate and associated data for a protein tertiary (3D) structure, or part of a structure, possibly in complex with other molecules.\", \"n\": \"Protein structure\", \"ns\": [], \"u\": \"data_1460\", \"es\": [\"Protein structures\"], \"ch\": [{\"n\": \"Protein-ligand complex\", \"u\": \"data_1461\"}, {\"n\": \"Protein chain\", \"u\": \"data_1467\"}, {\"n\": \"Protein domain\", \"u\": \"dat