data_2071\", \"es\": [\"Protein sequence motif\"], \"ch\": [], \"p\": [{\"n\": \"Data||Sequence signature data||Sequence motif||Sequence motif (protein)\", \"k\": \"data_0006||data_0860||data_1353||data_2071\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_1354\": {\"d\": \"Some type of statistical model representing a (typically multiple) sequence alignment.\", \"n\": \"Sequence profile\", \"ns\": [], \"u\": \"data_1354\", \"es\": [], \"ch\": [{\"n\": \"Position-specific scoring matrix\", \"u\": \"data_2854\"}, {\"n\": \"Profile HMM\", \"u\": \"data_3949\"}], \"p\": [{\"n\": \"Data||Sequence signature data||Sequence profile\", \"k\": \"data_0006||data_0860||data_1354\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_2854\": {\"d\": \"A simple matrix of numbers, where each value (or column of values) is derived derived from analysis of the corresponding position in a sequence alignment.\", \"n\": \"Position-specific scoring matrix\", \"ns\": [], \"u\": \"data_2854\", \"es\": [\"PSSM\"], \"ch\": [{\"n\": \"Position frequency matrix\", \"u\": \"data_1361\"}, {\"n\": \"Position weight matrix\", \"u\": \"data_1362\"}, {\"n\": \"Information content matrix\", \"u\": \"data_1363\"}, {\"n\": \"Fingerprint\", \"u\": \"data_1365\"}], \"p\": [{\"n\": \"Data||Sequence signature data||Sequence profile||Position-specific scoring matrix\", \"k\": \"data_0006||data_0860||data_1354||data_2854\"}, {\"n\": \"Data||Matrix||Position-specific scoring matrix\", \"k\": \"data_0006||data_2082||data_2854\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_1361\": {\"d\": \"A profile (typically representing a sequence alignment) that is a simple matrix of nucleotide (or amino acid) counts per position.\", \"n\": \"Position frequency matrix\", \"ns\": [], \"u\": \"data_1361\", \"es\": [\"PFM\"], \"ch\": [], \"p\": [{\"n\": \"Data||Sequence signature data||Sequence profile||Position-specific scoring matrix||Position frequency matrix\", \"k\": \"data_0006||data_0860||data_1354||data_2854||data_1361\