55||data_1276\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3134\": {\"d\": \"An informative report on features of a messenger RNA (mRNA) molecules including precursor RNA, primary (unprocessed) transcript and fully processed molecules. This includes reports on a specific gene transcript, clone or EST.\", \"n\": \"Gene transcript report\", \"ns\": [], \"u\": \"data_3134\", \"es\": [\"Clone or EST (report)\", \"Gene transcript annotation\", \"Nucleic acid features (mRNA features)\", \"Transcript (report)\", \"mRNA (report)\", \"mRNA features\"], \"ch\": [], \"p\": [{\"n\": \"Data||Sequence features||Nucleic acid features||Gene transcript report\", \"k\": \"data_0006||data_1255||data_1276||data_3134\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_1277\": {\"d\": \"An informative report on intrinsic positional features of a protein sequence.\", \"n\": \"Protein features\", \"ns\": [], \"u\": \"data_1277\", \"es\": [\"Feature table (protein)\", \"Protein feature table\"], \"ch\": [], \"p\": [{\"n\": \"Data||Sequence features||Protein features\", \"k\": \"data_0006||data_1255||data_1277\"}, {\"n\": \"Data||Report||Protein report||Protein features\", \"k\": \"data_0006||data_2048||data_0896||data_1277\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3002\": {\"d\": \"Annotation of one particular positional feature on a biomolecular (typically genome) sequence, suitable for import and display in a genome browser.\", \"n\": \"Annotation track\", \"ns\": [], \"u\": \"data_3002\", \"es\": [\"Genome annotation track\", \"Genome track\", \"Genome-browser track\", \"Genomic track\", \"Sequence annotation track\"], \"ch\": [], \"p\": [{\"n\": \"Data||Sequence features||Annotation track\", \"k\": \"data_0006||data_1255||data_3002\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_1274\": {\"d\": \"A map of (typically one) DNA sequence annotated with positional or non-positional features.\", \"n\": \"Map\", \"ns\": [], \"u\": \"data_1274\", \"es\": [\"DNA map\"], \"ch\": [{\"n\":