], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_0905\": {\"d\": \"Protein-protein interaction data from for example yeast two-hybrid analysis, protein microarrays, immunoaffinity chromatography followed by mass spectrometry, phage display etc.\", \"n\": \"Protein interaction raw data\", \"ns\": [], \"u\": \"data_0905\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Experimental measurement||Protein interaction raw data\", \"k\": \"data_0006||data_3108||data_0905\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_0926\": {\"d\": \"Radiation hybrid scores (RH) scores for one or more markers.\", \"n\": \"RH scores\", \"ns\": [], \"u\": \"data_0926\", \"es\": [\"Radiation Hybrid (RH) scores\"], \"ch\": [], \"p\": [{\"n\": \"Data||Experimental measurement||RH scores\", \"k\": \"data_0006||data_3108||data_0926\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_0940\": {\"d\": \"Volume map data from electron microscopy.\", \"n\": \"Volume map\", \"ns\": [], \"u\": \"data_0940\", \"es\": [\"3D volume map\", \"EM volume map\", \"Electron microscopy volume map\"], \"ch\": [], \"p\": [{\"n\": \"Data||Experimental measurement||Volume map\", \"k\": \"data_0006||data_3108||data_0940\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_2536\": {\"d\": \"Data concerning a mass spectrometry measurement.\", \"n\": \"Mass spectrometry data\", \"ns\": [], \"u\": \"data_2536\", \"es\": [], \"ch\": [{\"n\": \"Mass spectrum\", \"u\": \"data_0943\"}, {\"n\": \"Peptide mass fingerprint\", \"u\": \"data_0944\"}], \"p\": [{\"n\": \"Data||Experimental measurement||Mass spectrometry data\", \"k\": \"data_0006||data_3108||data_2536\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_0943\": {\"d\": \"Spectra from mass spectrometry.\", \"n\": \"Mass spectrum\", \"ns\": [], \"u\": \"data_0943\", \"es\": [\"Mass spectrometry spectra\"], \"ch\": [], \"p\": [{\"n\": \"Data||Experimental measurement||Mass spectrometry data||Mass spectrum\", \"k\": \"data_0006||data_3108||data_2536||data_0943\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_2537\": {\"d\": \"Raw data from experimental methods for determining protein structure.\", \"n\": \"Protein structure raw data\", \"ns\": [], \"u\": \"data_2537\", \"es\": [], \"ch\": [{\"n\": \"Electron density map\", \"u\": \"data_0937\"}, {\"n\": \"Raw NMR data\", \"u\": \"data_0938\"}, {\"n\": \"CD spectra\", \"u\": \"data_0939\"}], \"p\": [{\"n\": \"Data||Experimental measurement||Protein structure raw data\", \"k\": \"data_0006||data_3108||data_2537\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_0937\": {\"d\": \"X-ray crystallography data.\", \"n\": \"Electron density map\", \"ns\": [], \"u\": \"data_0937\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Experimental measurement||Protein structure raw data||Electron density map\", \"k\": \"data_0006||data_3108||data_2537||data_0937\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_0938\": {\"d\": \"Nuclear magnetic resonance (NMR) raw data, typically for a protein.\", \"n\": \"Raw NMR data\", \"ns\": [\"Protein NMR data\"], \"u\": \"data_0938\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Experimental measurement||Protein structure raw data||Raw NMR data\", \"k\": \"data_0006||data_3108||data_2537||data_0938\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_0939\": {\"d\": \"Protein secondary structure from protein coordinate or circular dichroism (CD) spectroscopic data.\", \"n\": \"CD spectra\", \"ns\": [], \"u\": \"data_0939\", \"es\": [\"CD spectrum\", \"Protein circular dichroism (CD) spectroscopic data\"], \"ch\": [], \"p\": [{\"n\": \"Data||Experimental measurement||Protein structure raw data||CD spectra\", \"k\": \"data_0006||data_3108||data_2537||data_0939\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3722\": {\"d\": \"Experimentally determined parameter of the physiology of an organism, e.g. substrate spectrum.\", \"n\": \"Physiology parameter\", \"ns\": [], \"u\": \"data_3722\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Experimental measurement||Physiology parameter\", \"k\": \"data_0006||data_3108||data_3722\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3723\": {\"d\": \"Experimentally determined parameter of the morphology of an organism, e.g. size & shape.\", \"n\": \"Morphology parameter\", \"ns\": [], \"u\": \"data_3723\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Experimental measurement||Morphology parameter\", \"k\": \"data_0006||data_3108||data_3723\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3724\": {\"d\": \"Experimental determined parameter for the cultivation of an organism.\", \"n\": \"Cultivation parameter\", \"ns\": [\"Carbon source\", \"Culture media composition\", \"Nitrogen source\", \"Salinity\", \"Temperature\", \"pH value\"], \"u\": \"data_3724\", \"es\": [\"Cultivation conditions\"], \"ch\": [], \"p\": [{\"n\": \"Data||Experimental measurement||Cultivation parameter\", \"k\": \"data_0006||data_3108||data_3724\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3483\": {\"d\": \"The spectrum of frequencies of electromagnetic radiation emitted from a molecule as a result of some spectroscopy experiment.\", \"n\": \"Spectrum\", \"ns\": [], \"u\": \"data_3483\", \"es\": [\"Spectra\"], \"ch\": [{\"n\": \"NMR spectrum\", \"u\": \"data_3488\"}], \"p\": [{\"n\": \"Data||Spectrum\", \"k\": \"data_0006||data_3483\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3488\": {\"d\": \"Spectral information for a molecule from a nuclear magnetic resonance experiment.\", \"n\": \"NMR spectrum\", \"ns\": [], \"u\": \"data_3488\", \"es\": [\"NMR spectra\"], \"ch\": [], \"p\": [{\"n\": \"Data||Spectrum||NMR spectrum\", \"k\": \"data_0006||data_3483||data_3488\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3498\": {\"d\": \"Data on gene sequence variations resulting large-scale genotyping and DNA sequencing projects.\", \"n\": \"Sequence variations\", \"ns\": [], \"u\": \"data_3498\", \"es\": [\"Gene sequence variations\"], \"ch\": [], \"p\": [{\"n\": \"Data||Sequence variations\", \"k\": \"data_0006||data_3498\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3669\": {\"d\": \"Some material that is used for educational (training) purposes.\", \"n\": \"Training material\", \"ns\": [\"OER\", \"Open educational resource\"], \"u\": \"data_3669\", \"es\": [], \"ch\": [{\"n\": \"Online course\", \"u\": \"data_3670\"}], \"p\": [{\"n\": \"Data||Training material\", \"k\": \"data_0006||data_3669\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3670\": {\"d\": \"A training course available for use on the Web.\", \"n\": \"Online course\", \"ns\": [\"MOOC\", \"Massive open online course\"], \"u\": \"data_3670\", \"es\": [\"On-line course\"], \"ch\": [], \"p\": [{\"n\": \"Data||Training material||Online course\", \"k\": \"data_0006||data_3669||data_3670\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3707\": {\"d\": \"Machine-readable biodiversity data.\", \"n\": \"Biodiversity data\", \"ns\": [\"OTU table\"], \"u\": \"data_3707\", \"es\": [\"Biodiversity information\"], \"ch\": [{\"n\": \"Alpha diversity data\", \"u\": \"data_3737\"}, {\"n\": \"Beta diversity data\", \"u\": \"data_3738\"}, {\"n\": \"Gamma diversity data\", \"u\": \"data_3739\"}], \"p\": [{\"n\": \"Data||Biodiversity data\", \"k\": \"data_0006||data_3707\"}, {\"n\": \"Data||Ecological data||Biodiversity data\", \"k\": \"data_0006||data_3736||data_3707\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3737\": {\"d\": \"The mean species diversity in sites or habitats at a local scale.\", \"n\": \"Alpha diversity data\", \"ns\": [], \"u\": \"data_3737\", \"es\": [\"\\u03b1-diversity\"], \"ch\": [], \"p\": [{\"n\": \"Data||Biodiversity data||Alpha diversity data\", \"k\": \"data_0006||data_3707||data_3737\"}, {\"n\": \"Data||Ecological data||Biodiversity data||Alpha diversity data\", \"k\": \"data_0006||data_3736||data_3707||data_3737\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3738\": {\"d\": \"The ratio between regional and local species diversity.\", \"n\": \"Beta diversity data\", \"ns\": [], \"u\": \"data_3738\", \"es\": [\"True beta diversity\", \"\\u03b2-diversity\"], \"ch\": [], \"p\": [{\"n\": \"Data||Biodiversity data||Beta diversity data\", \"k\": \"data_0006||data_3707||data_3738\"}, {\"n\": \"Data||Ecological data||Biodiversity data||Beta diversity data\", \"k\": \"data_0006||data_3736||data_3707||data_3738\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3739\": {\"d\": \"The total species diversity in a landscape.\", \"n\": \"Gamma diversity data\", \"ns\": [], \"u\": \"data_3739\", \"es\": [\"\\u0263-diversity\"], \"ch\": [], \"p\": [{\"n\": \"Data||Biodiversity data||Gamma diversity data\", \"k\": \"data_0006||data_3707||data_3739\"}, {\"n\": \"Data||Ecological data||Biodiversity data||Gamma diversity data\", \"k\": \"data_0006||data_3736||data_3707||data_3739\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3736\": {\"d\": \"Data concerning ecology; for example measurements and reports from the study of interactions among organisms and their environment.\", \"n\": \"Ecological data\", \"ns\": [], \"u\": \"data_3736\", \"es\": [], \"ch\": [{\"n\": \"Biodiversity data\", \"u\": \"data_3707\"}], \"p\": [{\"n\": \"Data||Ecological data\", \"k\": \"data_0006||data_3736\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3753\": {\"d\": \"A ranked list of categories (usually ontology concepts), each associated with a statistical metric of over-/under-representation within the studied data.\", \"n\": \"Over-representation data\", \"ns\": [\"Functional enrichment report\"], \"u\": \"data_3753\", \"es\": [\"Enrichment report\", \"Over-representation report\"], \"ch\": [{\"n\": \"GO-term enrichment data\", \"u\": \"data_3754\"}, {\"n\": \"Pathway overrepresentation data\", \"u\": \"data_3953\"}], \"p\": [{\"n\": \"Data||Over-representation data\", \"k\": \"data_0006||data_3753\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3754\": {\"d\": \"A ranked list of Gene Ontology concepts, each associated with a p-value, concerning or derived from the analysis of e.g. a set of genes or proteins.\", \"n\": \"GO-term enrichment data\", \"ns\": [], \"u\": \"data_3754\", \"es\": [\"GO-term enrichment report\", \"Gene ontology concept over-representation report\", \"Gene ontology enrichment report\", \"Gene ontology term enrichment report\"], \"ch\": [], \"p\": [{\"n\": \"Data||Over-representation data||GO-term enrichment data\", \"k\": \"data_0006||data_3753||data_3754\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3953\": {\"d\": \"A ranked list of pathways, each associated with z-score, p-value or similar, concerning or derived from the analysis of e.g. a set of genes or proteins.\", \"n\": \"Pathway overrepresentation data\", \"ns\": [], \"u\": \"data_3953\", \"es\": [\"Pathway analysis results\", \"Pathway enrichment report\", \"Pathway over-representation report\", \"Pathway report\", \"Pathway term enrichment report\"], \"ch\": [], \"p\": [{\"n\": \"Data||Over-representation data||Pathway overrepresentation data\", \"k\": \"data_0006||data_3753||data_3953\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3786\": {\"d\": \"A structured query, in form of a script, that defines a database search task.\", \"n\": \"Query script\", \"ns\": [], \"u\": \"data_3786\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Query script\", \"k\": \"data_0006||data_3786\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3842\": {\"d\": \"Data coming from molecular simulations, computer \\\"experiments\\\" on model molecules.\", \"n\": \"Molecular simulation data\", \"ns\": [], \"u\": \"data_3842\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Molecular simulation data\", \"k\": \"data_0006||data_3842\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3869\": {\"d\": \"Data coming from molecular simulations, computer \\\"experiments\\\" on model molecules. Tipically formed by two separated but indivisible pieces of information: topology data (static) and trajectory data (dynamic).\", \"n\": \"Simulation\", \"ns\": [], \"u\": \"data_3869\", \"es\": [], \"ch\": [{\"n\": \"Trajectory data\", \"u\": \"data_3870\"}, {\"n\": \"Forcefield parameters\", \"u\": \"data_3871\"}, {\"n\": \"Topology data\", \"u\": \"data_3872\"}], \"p\": [{\"n\": \"Data||Simulation\", \"k\": \"data_0006||data_3869\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3870\": {\"d\": \"Dynamic information of a structure molecular system coming from a molecular simulation: XYZ 3D coordinates (sometimes with their associated velocities) for every atom along time.\", \"n\": \"Trajectory data\", \"ns\": [], \"u\": \"data_3870\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Simulation||Trajectory data\", \"k\": \"data_0006||data_3869||data_3870\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3871\": {\"d\": \"Force field parameters: charges, masses, radii, bond lengths, bond dihedrals, etc. define the structural molecular system, and are essential for the proper description and simulation of a molecular system.\", \"n\": \"Forcefield parameters\", \"ns\": [], \"u\": \"data_3871\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Simulation||Forcefield parameters\", \"k\": \"data_0006||data_3869||data_3871\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"data_3872\": {\"d\": \"Static information of a structure molecular system that is needed for a molecular simulation: the list of atoms, their non-bonded parameters for Van der Waals and electrostatic interactions, and the complete connectivity in terms of bonds, angles and dihedrals.\", \"n\": \"Topology data\", \"ns\": [], \"u\": \"data_3872\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Data||Simulation||Topology data\", \"k\": \"data_0006||data_3869||data_3872\"}], \"hi\": [], \"ho\": [], \"ht\": []}}','2025-08-27 12:52:46.446733');
INSERT INTO `elixir_ontology` VALUES (37,'EDAM_Format','{\"text\": \"Format\", \"data\": {\"uri\": \"http://edamontology.org/format_1915\"}, \"definition\": \"A defined way or layout of representing and structuring data in a computer file, blob, string, message, or elsewhere. The main focus in EDAM lies on formats as means of structuring data exchanged between different tools or resources. The serialisation, compression, or encoding of concrete data formats/models is not in scope of EDAM. Format \'is format of\' Data.\", \"exact_synonyms\": [\"Exchange format\", \"Data format\"], \"narrow_synonyms\": [\"File format\"], \"children\": [{\"text\": \"Textual format\", \"data\": {\"uri\": \"http://edamontology.org/format_2330\"}, \"children\": [{\"text\": \"SMILES\", \"data\": {\"uri\": \"http://edamontology.org/format_1196\"}, \"children\": [{\"text\": \"smarts\", \"data\": {\"uri\": \"http://edamontology.org/format_1200\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"SMILES ARbitrary Target Specification (SMARTS) format for chemical structure specification, which is a subset of the SMILES line notation.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}], \"exact_synonyms\": [], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"Chemical structure specified in Simplified Molecular Input Line Entry System (SMILES) line notation.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"InChI\", \"data\": {\"uri\": \"http://edamontology.org/format_1197\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"Chemical structure specified in IUPAC International Chemical Identifier (InChI) line notation.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"mf\", \"data\": {\"uri\": \"http://edamontology.org/format_1198\"}, \"children\": [], \"exac