 \"has_topic\": []}, {\"text\": \"rgb\", \"data\": {\"uri\": \"http://edamontology.org/format_3600\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"RGB file format is the native raster graphics file format for Silicon Graphics workstations.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"pbm\", \"data\": {\"uri\": \"http://edamontology.org/format_3601\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"The PBM format is a lowest common denominator monochrome file format. It serves as the common language of a large family of bitmap image conversion filters.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"pgm\", \"data\": {\"uri\": \"http://edamontology.org/format_3602\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"The PGM format is a lowest common denominator grayscale file format.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"PNG\", \"data\": {\"uri\": \"http://edamontology.org/format_3603\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"PNG is a file format for image compression.\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"rast\", \"data\": {\"uri\": \"http://edamontology.org/format_3605\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"definition\": \"Sun Raster is a raster graphics file format used on SunOS by Sun Microsystems\", \"has_input\": [], \"has_output\": [], \"has_topic\": []}, {\"text\": \"bgzip\", \"data\": {\"uri\": \"http://edamontology.org/format_3615\"}, \"children\": [], \"exact_synonyms\": [], \"narrow_synonyms\": [], \"replaced_by\": [], \"consider\": [], \"defin