ck\", \"key\": \"format_1915||format_2350||format_1920||format_2919||format_3588\"}], \"name\": \"customtrack\", \"uri\": \"http://edamontology.org/format_3588\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences).\", \"path\": {\"name\": \"Format||Textual format||qual\", \"key\": \"format_1915||format_2330||format_3607\"}, \"name\": \"qual\", \"uri\": \"http://edamontology.org/format_3607\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"qualsolexa\", \"uri\": \"http://edamontology.org/format_3608\"}, {\"name\": \"qualillumina\", \"uri\": \"http://edamontology.org/format_3609\"}, {\"name\": \"qualsolid\", \"uri\": \"http://edamontology.org/format_3610\"}, {\"name\": \"qual454\", \"uri\": \"http://edamontology.org/format_3611\"}]}, {\"definition\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) for Solexa/Illumina 1.0 format.\", \"path\": {\"name\": \"Format||Textual format||qual||qualsolexa\", \"key\": \"format_1915||format_2330||format_3607||format_3608\"}, \"name\": \"qualsolexa\", \"uri\": \"http://edamontology.org/format_3608\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) from Illumina 1.5 and before Illumina 1.8.\", \"path\": {\"name\": \"Format||Textual format||qual||qualillumina\", \"key\": \"format_1915||format_2330||format_3607||format_3609\"}, \"name\": \"qualillumina\", \"uri\": \"http://edamontology.org/format_3609\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) for SOLiD data.\", \"path\": {\"name\": \"Format||Textual format||qual||qualsolid\", \"key\": \"format_1915||format_2330||format_3607||format_3610\"}, \"name\": \"qualsolid\", 