58||format_3243\"}, {\"name\": \"Format||Format (by type of data)||Protein interaction format||PSI MI XML (MIF)||PSI-PAR\", \"key\": \"format_1915||format_2350||format_2054||format_3158||format_3243\"}], \"name\": \"PSI-PAR\", \"uri\": \"http://edamontology.org/format_3243\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"phyloXML is a standardised XML format for phylogenetic trees, networks, and associated data.\", \"path\": [{\"name\": \"Format||XML||phyloXML\", \"key\": \"format_1915||format_2332||format_3159\"}, {\"name\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (XML)||phyloXML\", \"key\": \"format_1915||format_2350||format_2006||format_2557||format_3159\"}], \"name\": \"phyloXML\", \"uri\": \"http://edamontology.org/format_3159\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"NeXML is a standardised XML format for rich phyloinformatic data.\", \"path\": [{\"name\": \"Format||XML||NeXML\", \"key\": \"format_1915||format_2332||format_3160\"}, {\"name\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (XML)||NeXML\", \"key\": \"format_1915||format_2350||format_2006||format_2557||format_3160\"}], \"name\": \"NeXML\", \"uri\": \"http://edamontology.org/format_3160\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"MAGE-ML XML format for microarray expression data, standardised by MGED (now FGED).\", \"path\": [{\"name\": \"Format||XML||MAGE-ML\", \"key\": \"format_1915||format_2332||format_3161\"}, {\"name\": \"Format||Format (by type of data)||Gene expression report format||MAGE-ML\", \"key\": \"format_1915||format_2350||format_2058||format_3161\"}], \"name\": \"MAGE-ML\", \"uri\": \"http://edamontology.org/format_3161\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"GCDML XML format for genome and metagenome metadata according to MIGS/MIMS/MIMARKS information standards, standardised by the Genomic Standards Consortium (GSC).\", \"path\": [{\"name\": \"Format||XML||GCDML\", \"key\": \"format_1915||format_2332||format_3163\"}, {\"name\": \"Format||Format (by type of data)||Experiment annotation format||GCDML\", \"key\": \"format_1915||format_2350||format_3167||format_3163\"}], \"name\": \"GCDML\", \"uri\": \"http://edamontology.org/format_3163\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"CopasiML, the native format of COPASI.\", \"path\": [{\"name\": \"Format||XML||CopasiML\", \"key\": \"format_1915||format_2332||format_3239\"}, {\"name\": \"Format||Format (by type of data)||Biological pathway or network format||CopasiML\", \"key\": \"format_1915||format_2350||format_2013||format_3239\"}, {\"name\": \"Format||Format (by type of data)||Biological pathway or network report format||CopasiML\", \"key\": \"format_1915||format_2350||format_3166||format_3239\"}], \"name\": \"CopasiML\", \"uri\": \"http://edamontology.org/format_3239\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"CellML, the format for mathematical models of biological and other networks.\", \"path\": [{\"name\": \"Format||XML||CellML\", \"key\": \"format_1915||format_2332||format_3240\"}, {\"name\": \"Format||Format (by type of data)||Biological pathway or network format||CellML\", \"key\": \"format_1915||format_2350||format_2013||format_3240\"}], \"name\": \"CellML\", \"uri\": \"http://edamontology.org/format_3240\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"mzML format for raw spectrometer output data, standardised by HUPO PSI MSS.\", \"path\": [{\"name\": \"Format||XML||mzML\", \"key\": \"format_1915||format_2332||format_3244\"}, {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||mzML\", \"key\": \"format_1915||format_2350||format_3245||format_3244\"}], \"name\": \"mzML\", \"uri\": \"http://edamontology.org/format_3244\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"TraML (Transition Markup Language) is the format for mass spectrometry transitions, standardised by HUPO PSI MSS.\", \"path\": [{\"name\": \"Format||XML||TraML\", \"key\": \"format_1915||format_2332||format_3246\"}, {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||TraML\", \"key\": \"format_1915||format_2350||format_3245||format_3246\"}], \"name\": \"TraML\", \"uri\": \"http://edamontology.org/format_3246\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"mzIdentML is the exchange format for peptides and proteins identified from mass spectra, standardised by HUPO PSI PI. It can be used for outputs of proteomics search engines.\", \"path\": [{\"name\": \"Format||XML||mzIdentML\", \"key\": \"format_1915||format_2332||format_3247\"}, {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||mzIdentML\", \"key\": \"format_1915||format_2350||format_3245||format_3247\"}], \"name\": \"mzIdentML\", \"uri\": \"http://edamontology.org/format_3247\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"mzQuantML is the format for quantitation values associated with peptides, proteins and small molecules from mass spectra, standardised by HUPO PSI PI. It can be used for outputs of quantitation software for proteomics.\", \"path\": [{\"name\": \"Format||XML||mzQuantML\", \"key\": \"format_1915||format_2332||format_3248\"}, {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||mzQuantML\", \"key\": \"format_1915||format_2350||format_3245||format_3248\"}], \"name\": \"mzQuantML\", \"uri\": \"http://edamontology.org/format_3248\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"GelML is the format for describing the process of gel electrophoresis, standardised by HUPO PSI PS.\", \"path\": [{\"name\": \"Format||XML||GelML\", \"key\": \"format_1915||format_2332||format_3249\"}, {\"name\": \"Format||Format (by type of data)||Experiment annotation format||GelML\", \"key\": \"format_1915||format_2350||format_3167||format_3249\"}], \"name\": \"GelML\", \"uri\": \"http://edamontology.org/format_3249\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"spML is the format for describing proteomics sample processing, other than using gels, prior to mass spectrometric protein identification, standardised by HUPO PSI PS. It may also be applicable for metabolomics.\", \"path\": [{\"name\": \"Format||XML||spML\", \"key\": \"format_1915||format_2332||format_3250\"}, {\"name\": \"Format||Format (by type of data)||Experiment annotation format||spML\", \"key\": \"format_1915||format_2350||format_3167||format_3250\"}], \"name\": \"spML\", \"uri\": \"http://edamontology.org/format_3250\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Resource Description Framework (RDF) XML format.\", \"path\": [{\"name\": \"Format||XML||RDF/XML\", \"key\": \"format_1915||format_2332||format_3261\"}, {\"name\": \"Format||Format (by type of data)||Ontology format||RDF format||RDF/XML\", \"key\": \"format_1915||format_2350||format_2195||format_2376||format_3261\"}, {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||RDF/XML\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3261\"}, {\"name\": \"Format||RDF format||RDF/XML\", \"key\": \"format_1915||format_2376||format_3261\"}], \"name\": \"RDF/XML\", \"uri\": \"http://edamontology.org/format_3261\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"OWL ontology XML serialisation format.\", \"path\": [{\"name\": \"Format||XML||OWL/XML\", \"key\": \"format_1915||format_2332||format_3262\"}, {\"name\": \"Format||Format (by type of data)||Ontology 