onyms\": [], \"children\": []}, {\"definition\": \"An alignment format generated by PRANK/PRANKSTER consisting of four elements: newick, nodes, selection and model.\", \"path\": [{\"name\": \"Format||XML||HSAML\", \"key\": \"format_1915||format_2332||format_3845\"}, {\"name\": \"Format||Format (by type of data)||Alignment format||Alignment format (XML)||HSAML\", \"key\": \"format_1915||format_2350||format_1921||format_2555||format_3845\"}], \"name\": \"HSAML\", \"uri\": \"http://edamontology.org/format_3845\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Output xml file from the InterProScan sequence analysis application.\", \"path\": [{\"name\": \"Format||XML||InterProScan XML\", \"key\": \"format_1915||format_2332||format_3846\"}, {\"name\": \"Format||Format (by type of data)||Protein domain classification format||InterProScan XML\", \"key\": \"format_1915||format_2350||format_3097||format_3846\"}], \"name\": \"InterProScan XML\", \"uri\": \"http://edamontology.org/format_3846\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The KEGG Markup Language (KGML) is an exchange format of the KEGG pathway maps, which is converted from internally used KGML+ (KGML+SVG) format.\", \"path\": [{\"name\": \"Format||XML||KGML\", \"key\": \"format_1915||format_2332||format_3847\"}, {\"name\": \"Format||Format (by type of data)||Biological pathway or network format||KGML\", \"key\": \"format_1915||format_2350||format_2013||format_3847\"}], \"name\": \"KGML\", \"uri\": \"http://edamontology.org/format_3847\", \"exact_synonyms\": [\"KEGG Markup Language\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"XML format for collected entries from biobliographic databases MEDLINE and PubMed.\", \"path\": [{\"name\": \"Format||XML||PubMed XML\", \"key\": \"format_1915||format_2332||format_3848\"}, {\"name\": \"Format||Format (by type of data)||Bibliographic reference format||PubMed XML\", \"ke