", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"affymetrix-exp\", \"uri\": \"http://edamontology.org/format_1641\"}]}, {\"definition\": \"Affymetrix data file format for information about experimental conditions and protocols.\", \"path\": {\"name\": \"Format||Format (by type of data)||Experiment annotation format||Microarray experiment data format||affymetrix-exp\", \"key\": \"format_1915||format_2350||format_3167||format_2056||format_1641\"}, \"name\": \"affymetrix-exp\", \"uri\": \"http://edamontology.org/format_1641\", \"exact_synonyms\": [\"Affymetrix experimental conditions data file format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"GCDML XML format for genome and metagenome metadata according to MIGS/MIMS/MIMARKS information standards, standardised by the Genomic Standards Consortium (GSC).\", \"path\": {\"name\": \"Format||Format (by type of data)||Experiment annotation format||GCDML\", \"key\": \"format_1915||format_2350||format_3167||format_3163\"}, \"name\": \"GCDML\", \"uri\": \"http://edamontology.org/format_3163\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"GelML is the format for describing the process of gel electrophoresis, standardised by HUPO PSI PS.\", \"path\": {\"name\": \"Format||Format (by type of data)||Experiment annotation format||GelML\", \"key\": \"format_1915||format_2350||format_3167||format_3249\"}, \"name\": \"GelML\", \"uri\": \"http://edamontology.org/format_3249\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"spML is the format for describing proteomics sample processing, other than using gels, prior to mass spectrometric protein identification, standardised by HUPO PSI PS. It may also be applicable for metabolomics.\", \"path\": {\"name\": \"Format||Format (by type of data)||Experiment annotation format||spML\", \"key\": \"format_1915||format_2350||format_3167||format_3250\"}, \"name\": \"spML\", \"uri\": \"http://edamontology.org/format_3250\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"qcML is an XML format for quality-related data of mass spectrometry and other high-throughput measurements.\", \"path\": {\"name\": \"Format||Format (by type of data)||Experiment annotation format||qcML\", \"key\": \"format_1915||format_2350||format_3167||format_3683\"}, \"name\": \"qcML\", \"uri\": \"http://edamontology.org/format_3683\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"PRIDE XML is an XML format for mass spectra, peptide and protein identifications, and metadata about a corresponding measurement, sample, experiment.\", \"path\": {\"name\": \"Format||Format (by type of data)||Experiment annotation format||PRIDE XML\", \"key\": \"format_1915||format_2350||format_3167||format_3684\"}, \"name\": \"PRIDE XML\", \"uri\": \"http://edamontology.org/format_3684\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Simulation Experiment Description Markup Language (SED-ML) is an XML format for encoding simulation setups, according to the MIASE (Minimum Information About a Simulation Experiment) requirements.\", \"path\": {\"name\": \"Format||Format (by type of data)||Experiment annotation format||SED-ML\", \"key\": \"format_1915||format_2350||format_3167||format_3685\"}, \"name\": \"SED-ML\", \"uri\": \"http://edamontology.org/format_3685\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Open Modeling EXchange format (OMEX) is a ZIPped format for encapsulating all information necessary for a modeling and simulation project in systems biology.\", \"path\": {\"name\": \"Format||Format (by type of data)||Experiment annotation format||COMBINE OMEX\", \"key\": \"format_1915||format_2350||format_3167||format_3686\"}, \"name\": \"COMBINE OMEX\", \"uri\": \"http://edamontology.org/format_3686\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The Investigation / Study / Assay (ISA) tab-delimited (TAB) format incorporates metadata from\\nexperiments employing a combination of technologies.\", \"path\": {\"name\": \"Format||Format (by type of data)||Experiment annotation format||ISA-TAB\", \"key\": \"format_1915||format_2350||format_3167||format_3687\"}, \"name\": \"ISA-TAB\", \"uri\": \"http://edamontology.org/format_3687\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format for mass pectra and derived data, include peptide sequences etc.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Mass spectrometry data format\", \"key\": \"format_1915||format_2350||format_3245\"}], \"name\": \"Mass spectrometry data format\", \"uri\": \"http://edamontology.org/format_3245\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"mzML\", \"uri\": \"http://edamontology.org/format_3244\"}, {\"name\": \"TraML\", \"uri\": \"http://edamontology.org/format_3246\"}, {\"name\": \"mzIdentML\", \"uri\": \"http://edamontology.org/format_3247\"}, {\"name\": \"mzQuantML\", \"uri\": \"http://edamontology.org/format_3248\"}, {\"name\": \"netCDF\", \"uri\": \"http://edamontology.org/format_3650\"}, {\"name\": \"MGF\", \"uri\": \"http://edamontology.org/format_3651\"}, {\"name\": \"dta\", \"uri\": \"http://edamontology.org/format_3652\"}, {\"name\": \"pkl\", \"uri\": \"http://edamontology.org/format_3653\"}, {\"name\": \"mzXML\", \"uri\": \"http://edamontology.org/format_3654\"}, {\"name\": \"pepXML\", \"uri\": \"http://edamontology.org/format_3655\"}, {\"name\": \"mzTab\", \"uri\": \"http://edamontology.org/format_3681\"}, {\"name\": \"imzML metadata file\", \"uri\": \"http://edamontology.org/format_3682\"}, {\"name\": \"qcML\", \"uri\": \"http://edamontology.org/format_3683\"}, {\"name\": \"PRIDE XML\", \"uri\": \"http://edamontology.org/format_3684\"}, {\"name\": \"MSF\", \"uri\": \"http://edamontology.org/format_3702\"}, {\"name\": \"WIFF format\", \"uri\": \"http://edamontology.org/format_3710\"}, {\"name\": \"X!Tandem XML\", \"uri\": \"http://edamontology.org/format_3711\"}, {\"name\": \"Thermo RAW\", \"uri\": \"http://edamontology.org/format_3712\"}, {\"name\": \"Mascot .dat file\", \"uri\": \"http://edamontology.org/format_3713\"}, {\"name\": \"MaxQuant APL peaklist format\", \"uri\": \"http://edamontology.org/format_3714\"}, {\"name\": \"protXML\", \"uri\": \"http://edamontology.org/format_3747\"}, {\"name\": \"SEQUEST .out file\", \"uri\": \"http://edamontology.org/format_3758\"}, {\"name\": \"idXML\", \"uri\": \"http://edamontology.org/format_3764\"}, {\"name\": \"consensusXML\", \"uri\": \"http://edamontology.org/format_3832\"}, {\"name\": \"featureXML\", \"uri\": \"http://edamontology.org/format_3833\"}, {\"name\": \"mzData\", \"uri\": \"http://edamontology.org/format_3834\"}, {\"name\": \"TIDE TXT\", \"uri\": \"http://edamontology.org/format_3835\"}, {\"name\": \"ibd\", \"uri\": \"http://edamontology.org/format_3839\"}, {\"name\": \"Waters RAW\", \"uri\": \"http://edamontology.org/format_3858\"}, {\"name\": \"JCAMP-DX\", \"uri\": \"http://edamontology.org/format_3859\"}]}, {\"definition\": \"mzML format for raw spectrometer output data, standardised by HUPO PSI MSS.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||mzML\", \"key\": \"format_1915||format_2350||format_3245||format_3244\"}, \"name\": \"mzML\", \"uri\": \"http://edamontology.org/format_3244\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"TraML (Transition Markup Language) is the format for mass spectrometry transitions, standardised by HUPO PSI MSS.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||TraML\", \"key\": \"format_1915||format_2350||format_3245||format_3246\"}, \"name\": \"TraML\", \"uri\": \"http://edamontology.org/format_3246\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"mzIdentML is the exchange format for peptides and proteins identified from mass spectra, standardised by HUPO PSI PI. It can be used for outputs of proteomics search engines.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||mzIdentML\", \"key\": \"format_1915||format_2350||format_3245||format_3247\"}, \"name\": \"mzIdentML\", \"uri\": \"http://edamontology.org/format_3247\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"mzQuantML is the format for quantitation values associated with peptides, proteins and small molecules from mass spectra, standardised by HUPO PSI PI. It can be used for outputs of quantitation software for proteomics.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||mzQuantML\", \"key\": \"format_1915||format_2350||format_3245||format_3248\"}, \"name\": \"mzQuantML\", \"uri\": \"http://edamontology.org/format_3248\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format used by netCDF software  library for writing and reading chromatography-MS data files.  Also used to store trajectory atom coordinates information, such as the ones obtained by Molecular Dynamics simulations.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||netCDF\", \"key\": \"format_1915||format_2350||format_3245||format_3650\"}, \"name\": \"netCDF\", \"uri\": \"http://edamontology.org/format_3650\", \"exact_synonyms\": [\"ANDI-MS\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Mascot Generic Format.  Encodes multiple MS/MS spectra in a single file.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||MGF\", \"key\": \"format_1915||format_2350||format_3245||format_3651\"}], \"name\": \"MGF\", \"uri\": \"http://edamontology.org/format_3651\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Spectral data format file where each spectrum is written to a separate file.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||dta\", \"key\": \"format_1915||format_2350||format_3245||format_3652\"}], \"name\": \"dta\", \"uri\": \"http://edamontology.org/format_3652\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Spectral data file similar to dta.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||pkl\", \"key\": \"format_1915||format_2350||format_3245||format_3653\"}], \"name\": \"pkl\", \"uri\": \"http://edamontology.org/format_3653\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Common file format for proteomics mass spectrometric data developed at the Seattle Proteome Center/Institute for Systems Biology.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||mzXML\", \"key\": \"format_1915||format_2350||format_3245||format_3654\"}], \"name\": \"mzXML\", \"uri\": \"http://edamontology.org/format_3654\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Open data format for the storage, exchange, and processing of peptide sequence assignments of MS/MS scans, intended to provide a common data output format for many different MS/MS search engines and subsequent peptide-level analyses.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||pepXML\", \"key\": \"format_1915||format_2350||format_3245||format_3655\"}, \"name\": \"pepXML\", \"uri\": \"http://edamontology.org/format_3655\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"mzTab is a tab-delimited format for mass spectrometry-based proteomics and metabolomics results.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||mzTab\", \"key\": \"format_1915||format_2350||format_3245||format_3681\"}, \"name\": \"mzTab\", \"uri\": \"http://edamontology.org/format_3681\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"imzML metadata is a data format for mass spectrometry imaging metadata.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||imzML metadata file\", \"key\": \"format_1915||format_2350||format_3245||format_3682\"}, \"name\": \"imzML metadata file\", \"uri\": \"http://edamontology.org/format_3682\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"qcML is an XML format for quality-related data of mass spectrometry and other high-throughput measurements.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||qcML\", \"key\": \"format_1915||format_2350||format_3245||format_3683\"}, \"name\": \"qcML\", \"uri\": \"http://edamontology.org/format_3683\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"PRIDE XML is an XML format for mass spectra, peptide and protein identifications, and metadata about a corresponding measurement, sample, experiment.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||PRIDE XML\", \"key\": \"format_1915||format_2350||format_3245||format_3684\"}, \"name\": \"PRIDE XML\", \"uri\": \"http://edamontology.org/format_3684\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Proprietary mass-spectrometry format of Thermo Scientific\'s ProteomeDiscoverer software.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||MSF\", \"key\": \"format_1915||format_2350||format_3245||format_3702\"}], \"name\": \"MSF\", \"uri\": \"http://edamontology.org/format_3702\", \"exact_synonyms\": [\"Magellan storage file format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Mass spectrum file format from QSTAR and QTRAP instruments (ABI/Sciex).\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||WIFF format\", \"key\": \"format_1915||format_2350||format_3245||format_3710\"}, \"name\": \"WIFF format\", \"uri\": \"http://edamontology.org/format_3710\", \"exact_synonyms\": [\"wiff\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Output format used by X! series search engines that is based on the XML language BIOML.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||X!Tandem XML\", \"key\": \"format_1915||format_2350||format_3245||format_3711\"}, \"name\": \"X!Tandem XML\", \"uri\": \"http://edamontology.org/format_3711\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Proprietary file format for mass spectrometry data from Thermo Scientific.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||Thermo RAW\", \"key\": \"format_1915||format_2350||format_3245||format_3712\"}, \"name\": \"Thermo RAW\", \"uri\": \"http://edamontology.org/format_3712\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"\\\"Raw\\\" result file from Mascot database search.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||Mascot .dat file\", \"key\": \"format_1915||format_2350||format_3245||format_3713\"}, \"name\": \"Mascot .dat file\", \"uri\": \"http://edamontology.org/format_3713\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format of peak list files from Andromeda search engine (MaxQuant) that consist of arbitrarily many spectra.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||MaxQuant APL peaklist format\", \"key\": \"format_1915||format_2350||format_3245||format_3714\"}, \"name\": \"MaxQuant APL peaklist format\", \"uri\": \"http://edamontology.org/format_3714\", \"exact_synonyms\": [\"MaxQuant APL\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A format for storage, exchange, and processing of protein identifications created from ms/ms-derived peptide sequence data.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||protXML\", \"key\": \"format_1915||format_2350||format_3245||format_3747\"}, \"name\": \"protXML\", \"uri\": \"http://edamontology.org/format_3747\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"\\\"Raw\\\" result file from SEQUEST database search.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||SEQUEST .out file\", \"key\": \"format_1915||format_2350||format_3245||format_3758\"}, \"name\": \"SEQUEST .out file\", \"uri\": \"http://edamontology.org/format_3758\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"XML file format for files containing information about peptide identifications from mass spectrometry data analysis carried out with OpenMS.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||idXML\", \"key\": \"format_1915||format_2350||format_3245||format_3764\"}, \"name\": \"idXML\", \"uri\": \"http://edamontology.org/format_3764\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"OpenMS format for grouping features in one map or across several maps.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||consensusXML\", \"key\": \"format_1915||format_2350||format_3245||format_3832\"}, \"name\": \"consensusXML\", \"uri\": \"http://edamontology.org/format_3832\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"OpenMS format for quantitation results (LC/MS features).\", \"path\": 