row_synonyms\": [], \"children\": []}, {\"definition\": \"Microsoft Word format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Document format||docx\", \"key\": \"format_1915||format_2350||format_3507||format_3506\"}, \"name\": \"docx\", \"uri\": \"http://edamontology.org/format_3506\", \"exact_synonyms\": [\"Microsoft Word format\", \"doc\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Portable Document Format\", \"path\": {\"name\": \"Format||Format (by type of data)||Document format||PDF\", \"key\": \"format_1915||format_2350||format_3507||format_3508\"}, \"name\": \"PDF\", \"uri\": \"http://edamontology.org/format_3508\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"MS Excel spreadsheet format consisting of a set of XML documents stored in a ZIP-compressed file.\", \"path\": {\"name\": \"Format||Format (by type of data)||Document format||xlsx\", \"key\": \"format_1915||format_2350||format_3507||format_3620\"}, \"name\": \"xlsx\", \"uri\": \"http://edamontology.org/format_3620\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"ObjTables\", \"uri\": \"http://edamontology.org/format_3977\"}]}, {\"definition\": \"ObjTables is a toolkit for creating re-usable datasets that are both human and machine-readable, combining the ease of spreadsheets (e.g., Excel workbooks) with the rigor of schemas (classes, their attributes, the type of each attribute, and the possible relationships between instances of classes). ObjTables consists of a format for describing schemas for spreadsheets, numerous data types for science, a syntax for indicating the class and attribute represented by each table and column in a workbook, and software for using schemas to rigorously validate, merge, split, compare, and revision datasets.\", \"path\": {\"name\": \"Format||Format (by type of data)||Document format||xlsx||ObjTables\", \"key\": \"format_1915||format_2350||format_3507||format_3620||