_3592\"}, \"name\": \"BMP\", \"uri\": \"http://edamontology.org/format_3592\", \"exact_synonyms\": [\"bmp\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"IM is a format used by LabEye and other applications based on the IFUNC image processing library.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||im\", \"key\": \"format_1915||format_2350||format_3547||format_3593\"}, \"name\": \"im\", \"uri\": \"http://edamontology.org/format_3593\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Photo CD format, which is the highest resolution format for images on a CD.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||pcd\", \"key\": \"format_1915||format_2350||format_3547||format_3594\"}, \"name\": \"pcd\", \"uri\": \"http://edamontology.org/format_3594\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"PCX is an image file format that uses a simple form of run-length encoding. It is lossless.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||pcx\", \"key\": \"format_1915||format_2350||format_3547||format_3595\"}, \"name\": \"pcx\", \"uri\": \"http://edamontology.org/format_3595\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The PPM format is a lowest common denominator color image file format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||ppm\", \"key\": \"format_1915||format_2350||format_3547||format_3596\"}, \"name\": \"ppm\", \"uri\": \"http://edamontology.org/format_3596\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"PSD (Photoshop Document) is a proprietary file that allows the user to work with the images\' individual layers even after the file has been saved.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||psd\", \"key\": \"format_1915||format_2350||format_3547||format_3597\"}, \"name\": \"psd\", \"uri\": \"http://edamontology.org/format_3597\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"X BitMap is a plain text binary image format used by the X Window System used for storing cursor and icon bitmaps used in the X GUI.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||xbm\", \"key\": \"format_1915||format_2350||format_3547||format_3598\"}, \"name\": \"xbm\", \"uri\": \"http://edamontology.org/format_3598\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"X PixMap (XPM) is an image file format used by the X Window System, it is intended primarily for creating icon pixmaps, and supports transparent pixels.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||xpm\", \"key\": \"format_1915||format_2350||format_3547||format_3599\"}, \"name\": \"xpm\", \"uri\": \"http://edamontology.org/format_3599\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"RGB file format is the native raster graphics file format for Silicon Graphics workstations.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||rgb\", \"key\": \"format_1915||format_2350||format_3547||format_3600\"}, \"name\": \"rgb\", \"uri\": \"http://edamontology.org/format_3600\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The PBM format is a lowest common denominator monochrome file format. It serves as the common language of a large family of bitmap image conversion filters.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||pbm\", \"key\": \"format_1915||format_2350||format_3547||format_3601\"}, \"name\": \"pbm\", \"uri\": \"http://edamontology.org/format_3601\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The PGM format is a lowest common denominator grayscale file format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||pgm\", \"key\": \"format_1915||format_2350||format_3547||format_3602\"}, \"name\": \"pgm\", \"uri\": \"http://edamontology.org/format_3602\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"PNG is a file format for image compression.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||PNG\", \"key\": \"format_1915||format_2350||format_3547||format_3603\"}, \"name\": \"PNG\", \"uri\": \"http://edamontology.org/format_3603\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Scalable Vector Graphics (SVG) is an XML-based vector image format for two-dimensional graphics with support for interactivity and animation.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||SVG\", \"key\": \"format_1915||format_2350||format_3547||format_3604\"}, \"name\": \"SVG\", \"uri\": \"http://edamontology.org/format_3604\", \"exact_synonyms\": [\"Scalable Vector Graphics\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Sun Raster is a raster graphics file format used on SunOS by Sun Microsystems\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||rast\", \"key\": \"format_1915||format_2350||format_3547||format_3605\"}, \"name\": \"rast\", \"uri\": \"http://edamontology.org/format_3605\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Blocked GNU Zip format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||bgzip\", \"key\": \"format_1915||format_2350||format_3547||format_3615\"}, \"name\": \"bgzip\", \"uri\": \"http://edamontology.org/format_3615\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"TAB-delimited genome position file index format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||tabix\", \"key\": \"format_1915||format_2350||format_3547||format_3616\"}, \"name\": \"tabix\", \"uri\": \"http://edamontology.org/format_3616\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Image file format used by the Open Microscopy Environment (OME).\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||OME-TIFF\", \"key\": \"format_1915||format_2350||format_3547||format_3727\"}, \"name\": \"OME-TIFF\", \"uri\": \"http://edamontology.org/format_3727\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Microsoft Powerpoint format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||pptx\", \"key\": \"format_1915||format_2350||format_3547||format_3838\"}, \"name\": \"pptx\", \"uri\": \"http://edamontology.org/format_3838\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Vega is a visualization grammar, a declarative language for creating, saving, and sharing interactive visualization designs. With Vega, you can describe the visual appearance and interactive behavior of a visualization in a JSON format, and generate web-based views using Canvas or SVG.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Image format||Vega\", \"key\": \"format_1915||format_2350||format_3547||format_3969\"}, {\"name\": \"Format||JSON||Vega\", \"key\": \"format_1915||format_3464||format_3969\"}, {\"name\": \"Format||YAML||JSON||Vega\", \"key\": \"format_1915||format_3750||format_3464||format_3969\"}], \"name\": \"Vega\", \"uri\": \"http://edamontology.org/format_3969\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Vega-Lite is a high-level grammar of interactive graphics. It provides a concise JSON syntax for rapidly generating visualizations to support analysis. Vega-Lite specifications can be compiled to Vega specifications.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Image format||Vega-lite\", \"key\": \"format_1915||format_2350||format_3547||format_3970\"}, {\"name\": \"Format||JSON||Vega-lite\", \"key\": \"format_1915||format_3464||format_3970\"}, {\"name\": \"Format||YAML||JSON||Vega-lite\", \"key\": \"format_1915||format_3750||format_3464||format_3970\"}], \"name\": \"Vega-lite\", \"uri\": \"http://edamontology.org/format_3970\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The proprietary native video format of various Microsoft programs such as Windows Media Player.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||WMV\", \"key\": \"format_1915||format_2350||format_3547||format_3986\"}, \"name\": \"WMV\", \"uri\": \"http://edamontology.org/format_3986\", \"exact_synonyms\": [\"Windows Media Video format\", \"Windows movie file format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Zeiss\' proprietary image format based on TIFF.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||LSM\", \"key\": \"format_1915||format_2350||format_3547||format_3988\"}, \"name\": \"LSM\", \"uri\": \"http://edamontology.org/format_3988\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Audio Video Interleaved (AVI) format is a multimedia container format for AVI files, that allows synchronous audio-with-video playback.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||AVI\", \"key\": \"format_1915||format_2350||format_3547||format_3990\"}, \"name\": \"AVI\", \"uri\": \"http://edamontology.org/format_3990\", \"exact_synonyms\": [\"Audio Video Interleaved\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"STL is a file format native to the stereolithography CAD software created by 3D Systems.  The format is used to save and share surface-rendered 3D images and also for 3D printing.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||Stereolithography format\", \"key\": \"format_1915||format_2350||format_3547||format_3993\"}, \"name\": \"Stereolithography format\", \"uri\": \"http://edamontology.org/format_3993\", \"exact_synonyms\": [\"stl\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"U3D (Universal 3D) is a compressed file format and data structure for 3D computer graphics. It contains 3D model information such as triangle meshes, lighting, shading, motion data, lines and points with color and structure.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||U3D\", \"key\": \"format_1915||format_2350||format_3547||format_3994\"}, \"name\": \"U3D\", \"uri\": \"http://edamontology.org/format_3994\", \"exact_synonyms\": [\"Universal 3D\", \"Universal 3D format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Bitmap image format used for storing textures.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||Texture file format\", \"key\": \"format_1915||format_2350||format_3547||format_3995\"}, \"name\": \"Texture file format\", \"uri\": \"http://edamontology.org/format_3995\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A digital multimedia container format most commonly used to store video and audio.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||MPEG-4\", \"key\": \"format_1915||format_2350||format_3547||format_3997\"}, \"name\": \"MPEG-4\", \"uri\": \"http://edamontology.org/format_3997\", \"exact_synonyms\": [\"MP4\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"An open file format from the Neuroimaging Informatics Technology Initiative (NIfTI) commonly used to store brain imaging data obtained using Magnetic Resonance Imaging (MRI) methods.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||NIFTI format\", \"key\": \"format_1915||format_2350||format_3547||format_4001\"}, \"name\": \"NIFTI format\", \"uri\": \"http://edamontology.org/format_4001\", \"exact_synonyms\": [\"NIFTI\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Textual report format for sequence quality for reports from sequencing machines.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Sequence quality report format (text)\", \"key\": \"format_1915||format_2350||format_3606\"}], \"name\": \"Sequence quality report format (text)\", \"uri\": \"http://edamontology.org/format_3606\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"qual\", \"uri\": \"http://edamontology.org/format_3607\"}]}, {\"definition\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences).\", \"path\": {\"name\": \"Format||Format (by type of data)||Sequence quality report format (text)||qual\", \"key\": \"format_1915||format_2350||format_3606||format_3607\"}, \"name\": \"qual\", \"uri\": \"http://edamontology.org/format_3607\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"qualsolexa\", \"uri\": \"http://edamontology.org/format_3608\"}, {\"name\": \"qualillumina\", \"uri\": \"http://edamontology.org/format_3609\"}, {\"name\": \"qualsolid\", \"uri\": \"http://edamontology.org/format_3610\"}, {\"name\": \"qual454\", \"uri\": \"http://edamontology.org/format_3611\"}]}, {\"definition\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) for Solexa/Illumina 1.0 format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Sequence quality report format (text)||qual||qualsolexa\", \"key\": \"format_1915||format_2350||format_3606||format_3607||format_3608\"}, \"name\": \"qualsolexa\", \"uri\": \"http://edamontology.org/format_3608\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) from Illumina 1.5 and before Illumina 1.8.\", \"path\": {\"name\": \"Format||Format (by type of data)||Sequence quality report format (tex