ildren\": []}, {\"definition\": \"A list of k-mers and their occurences in a dataset. Can also be used as an implicit De Bruijn graph.\", \"path\": {\"name\": \"Format||Format (by type of data)||Graph format||K-mer countgraph\", \"key\": \"format_1915||format_2350||format_3617||format_3665\"}, \"name\": \"K-mer countgraph\", \"uri\": \"http://edamontology.org/format_3665\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data format for biodiversity data.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Biodiversity data format\", \"key\": \"format_1915||format_2350||format_3706\"}], \"name\": \"Biodiversity data format\", \"uri\": \"http://edamontology.org/format_3706\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"ABCD format\", \"uri\": \"http://edamontology.org/format_3708\"}, {\"name\": \"BIOM format\", \"uri\": \"http://edamontology.org/format_3746\"}, {\"name\": \"MCPD\", \"uri\": \"http://edamontology.org/format_3777\"}]}, {\"definition\": \"Exchange format of the Access to Biological Collections Data (ABCD) Schema; a standard for the access to and exchange of data about specimens and observations (primary biodiversity data).\", \"path\": [{\"name\": \"Format||Format (by type of data)||Biodiversity data format||ABCD format\", \"key\": \"format_1915||format_2350||format_3706||format_3708\"}], \"name\": \"ABCD format\", \"uri\": \"http://edamontology.org/format_3708\", \"exact_synonyms\": [\"ABCD\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The BIological Observation Matrix (BIOM) is a format for representing biological sample by observation contingency tables in broad areas of comparative omics. The primary use of this format is to represent OTU tables and metagenome tables.\", \"path\": {\"name\": \"Format||Format (by type of data)||Biodiversity data format||BIOM format\", \"key\": \"format_1915||format_2350||format_3706||format_3746\"}, \"name\": \"BIOM format\", \"uri\": \"http://edamontology.org/format_3746\", \"exact_synonyms\": [\"BIological Observation Matrix format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The FAO/Bioversity/IPGRI Multi-Crop Passport Descriptors (MCPD) is an international standard format for exchange of germplasm information.\", \"path\": {\"name\": \"Format||Format (by type of data)||Biodiversity data format||MCPD\", \"key\": \"format_1915||format_2350||format_3706||format_3777\"}, \"name\": \"MCPD\", \"uri\": \"http://edamontology.org/format_3777\", \"exact_synonyms\": [\"Bioversity MCPD\", \"FAO MCPD\", \"MCPD format\", \"Multi-Crop Passport Descriptors\", \"Multi-Crop Passport Descriptors format\"], \"narrow_synonyms\": [\"IPGRI MCPD\", \"MCPD V.1\", \"MCPD V.2\"], \"children\": []}, {\"definition\": \"A linked data format enables publishing structured data as linked data (Linked Data), so that the data can be interlinked and become more useful through semantic queries.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Linked data format\", \"key\": \"format_1915||format_2350||format_3748\"}], \"name\": \"Linked data format\", \"uri\": \"http://edamontology.org/format_3748\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"RDF format\", \"uri\": \"http://edamontology.org/format_2376\"}, {\"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\"}]}, {\"definition\": \"A serialisation format conforming to the Resource Description Framework (RDF) model.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format\", \"key\": \"format_1915||format_2350||format_3748||format_2376\"}, \"name\": \"RDF format\", \"uri\": \"http://edamontology.org/format_2376\", \"exact_synonyms\": [\"Resource Description Framework format\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"OWL format\", \"uri\": \"http://edamontology.org/format_2197\"}, {\"name\": \"Turtle\", \"uri\": \"http://edamontology.org/format_3255\"}, {\"name\": \"N-Triples\", \"uri\": \"http://edamontology.org/format_3256\"}, {\"name\": \"Notation3\", \"uri\": \"http://edamontology.org/format_3257\"}, {\"name\": \"RDF/XML\", \"uri\": \"http://edamontology.org/format_3261\"}, {\"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\"}, {\"name\": \"UniProtKB RDF\", \"uri\": \"http://edamontology.org/format_3771\"}, {\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}, {\"name\": \"N-Quads\", \"uri\": \"http://edamontology.org/format_3956\"}]}, {\"definition\": \"A serialisation format conforming to the Web Ontology Language (OWL) model.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||OWL format\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_2197\"}, \"name\": \"OWL format\", \"uri\": \"http://edamontology.org/format_2197\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"OWL Functional Syntax\", \"uri\": \"http://edamontology.org/format_3252\"}, {\"name\": \"Manchester OWL Syntax\", \"uri\": \"http://edamontology.org/format_3253\"}, {\"name\": \"OWL/XML\", \"uri\": \"http://edamontology.org/format_3262\"}]}, {\"definition\": \"A human-readable encoding for the Web Ontology Language (OWL).\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||OWL format||OWL Functional Syntax\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_2197||format_3252\"}, \"name\": \"OWL Functional Syntax\", \"uri\": \"http://edamontology.org/format_3252\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A syntax for writing OWL class expressions.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||OWL format||Manchester OWL Syntax\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_2197||format_3253\"}, \"name\