ion\": \"Resource Description Framework (RDF) XML format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||RDF/XML\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3261\"}, \"name\": \"RDF/XML\", \"uri\": \"http://edamontology.org/format_3261\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"JSON-LD, or JavaScript Object Notation for Linked Data, is a method of encoding Linked Data using JSON.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||JSON-LD\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3749\"}, \"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\", \"exact_synonyms\": [\"JavaScript Object Notation for Linked Data\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}]}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||JSON-LD||Open Annotation format\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3749||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"UniProtKB RDF sequence features format is an RDF format available for downloading UniProt entries (in RDF/XML).\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||UniProtKB RDF\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3771\"}, \"name\": \"UniProtKB RDF\", \"uri\": \"http://edamontology.org/format_3771\", \"exact_synonyms\": [\"UniProt RDF\", \"UniProt RDF format\", \"UniProtKB RDF format\"], \"narrow_synonyms\": [\"UniProt RDF/XML\", \"UniProt RDF/XML format\", \"UniProtKB RDF/XML\", \"UniProtKB RDF/XML format\"], \"children\": []}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||Open Annotation format\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"N-Quads is a line-based, plain text format for encoding an RDF dataset. It includes information about the graph each triple belongs to.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||N-Quads\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3956\"}, \"name\": \"N-Quads\", \"uri\": \"http://edamontology.org/format_3956\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"JSON-LD, or JavaScript Object Notation for Linked Data, is a method of encoding Linked Data using JSON.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||JSON-LD\", \"key\": \"format_1915||format_2350||format_3748||format_3749\"}, \"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\", \"exact_synonyms\": [\"JavaScript Object Notation for Linked Data\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}]}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||JSON-LD||Open Annotation format\", \"key\": \"format_1915||format_2350||format_3748||format_3749||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data format of an annotated text, e.g. with recognised entities, concepts, and relations.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Annotated text format\", \"key\": \"format_1915||format_2350||format_3780\"}], \"name\": \"Annotated text format\", \"uri\": \"http://edamontology.org/format_3780\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"OSCAR format\", \"uri\": \"http://edamontology.org/format_1741\"}, {\"name\": \"PubAnnotation format\", \"uri\": \"http://edamontology.org/format_3781\"}, {\"name\": \"BioC\", \"uri\": \"http://edamontology.org/format_3782\"}, {\"name\": \"PubTator format\", \"uri\": \"http://edamontology.org/format_3783\"}, {\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}, {\"name\": \"BioNLP Shared Task format\", \"uri\": \"http://edamontology.org/format_3785\"}]}, {\"definition\": \"OSCAR format of annotated chemical text.\", \"path\": {\"name\": \"Format||Format (by type of data)||Annotated text format||OSCAR format\", \"key\": \"format_1915||format_2350||format_3780||format_1741\"}, \"name\": \"OSCAR format\", \"uri\": \"http://edamontology.org/format_1741\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"JSON format of annotated scientific text used by PubAnnotations and other tools.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Annotated text format||PubAnnotation format\", \"key\": \"format_1915||format_2350||format_3780||format_3781\"}, {\"name\": \"Format||JSON||PubAnnotation format\", \"key\": \"format_1915||format_3464||format_3781\"}, {\"name\": \"Format||YAML||JSON||PubAnnotation format\", \"key\": \"format_1915||format_3750||format_3464||format_3781\"}], \"name\": \"PubAnnotation format\", \"uri\": \"http://edamontology.org/format_3781\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"BioC is a standardised XML format for sharing and integrating text data and annotations.\", \"path\": {\"name\": \"Format||Format (by type of data)||Annotated text format||BioC\", \"key\": \"format_1915||format_2350||format_3780||format_3782\"}, \"name\": \"BioC\", \"uri\": \"http://edamontology.org/format_3782\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Native textual export format of annotated scientific text from PubTator.\", \"path\": {\"name\": \"Format||Format (by type of data)||Annotated text format||PubTator format\", \"key\": \"format_1915||format_2350||format_3780||format_3783\"}, \"name\": \"PubTator format\", \"uri\": \"http://edamontology.org/format_3783\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||Format (by type of data)||Annotated text format||Open Annotation format\", \"key\": \"format_1915||format_2350||format_3780||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A family of similar formats of text annotation, used by BRAT and other tools, known as BioNLP Shared Task format (BioNLP 2009 Shared Task on Event Extraction, BioNLP Shared Task 2011, BioNLP Shared Task 2013), BRAT format, BRAT standoff format, and similar.\", \"path\": {\"name\": \"Format||Format (by type of data)||Annotated text format||BioNLP Shared Task format\", \"key\": \"format_1915||format_2350||format_3780||format_3785\"}, \"name\": \"BioNLP Shared Task format\", \"uri\": \"http://edamontology.org/format_3785\", \"exact_synonyms\": [\"BRAT format\", \"BRAT standoff format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A query language (format) for structured database queries.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Query language\", \"key\": \"format_1915||format_2350||format_3787\"}], \"name\": \"Query language\", \"uri\": \"http://edamontology.org/format_3787\", \"exact_synonyms\": [\"Query format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data format for raw data from a nuclear magnetic resonance (NMR) spectroscopy experiment.\", \"path\": [{\"name\": \"Format||Format (by type of data)||NMR data format\", \"key\": \"format_1915||format_2350||format_3824\"}], \"name\": \"NMR data format\", \"uri\": \"http://edamontology.org/format_3824\", \"exact_synonyms\": [\"Nuclear magnetic resonance spectroscopy data format\"], \"narrow_synonyms\": [\"NMR peak assignment data\", \"NMR processed data format\", \"NMR raw data format\", \"Processed NMR data format\", \"Raw NMR data format\"], \"children\": [{\"name\": \"nmrML\", \"uri\": \"http://edamontology.org/format_3825\"}, {\"name\": \"NMReDATA\", \"uri\": \"http://edamontology.org/format_3906\"}]}, {\"definition\": \"nmrML is an MSI supported XML-based open access format for metabolomics NMR raw and processed spectral data. It is accompanies by an nmrCV (controlled vocabulary) to allow ontology-based annotations.\", \"path\": {\"name\": \"Format||Format (by type of data)||NMR data format||nmrML\", \"key\": \"format_1915||format_2350||format_3824||format_3825\"}, \"name\": \"nmrML\", \"uri\": \"http://edamontology.org/format_3825\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"MReData is a text based data standard for processed NMR data. It is relying on SDF molecule data and allows to store assignments of NMR peaks to molecule features.  The NMR-extracted data (or \\\"NMReDATA\\\") includes: Chemical shift,scalar coupling, 2D correlation, assignment, etc.\", \"path\": {\"name\": \"Format||Format (by type of data)||NMR data format||NMReDATA\", \"key\": \"format_1915||format_2350||format_3824||format_3906\"}, \"name\": \"NMReDATA\", \"uri\": \"http://edamontology.org/format_3906\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data format for raw microarray data.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Raw microarray data format\", \"key\": \"format_1915||format_2350||format_3828\"}], \"name\": \"Raw microarray data format\", \"uri\": \"http://edamontology.org/format_3828\", \"exact_synonyms\": [\"Microarray data format\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"GPR\", \"uri\": \"http://edamontology.org/format_3829\"}]}, {\"definition\": \"GenePix Results (GPR) text file format developed by Axon Instruments that is used to save GenePix Results data.\", \"path\": {\"name\": \"Format||Format (by type of data)||Raw microarray data format||GPR\", \"key\": \"format_1915||format_2350||format_3828||format_3829\"}, \"name\": \"GPR\", \"uri\": \"http://edamontology.org/format_3829\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data format used in Natural Language Processing.\", \"path\": [{\"name\": \"Format||Format (by type of data)||NLP format\", \"key\": \"format_1915||format_2350||format_3841\"}], \"name\": \"NLP format\", \"uri\": \"http://edamontology.org/format_3841\", \"exact_synonyms\": [\"Natural Language Processing format\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"NLP annotation format\", \"uri\": \"http://edamontology.org/format_3862\"}]}, {\"definition\": \"An NLP format used for annotated textual documents.\", \"path\": [{\"name\": \"Format||Format (by type of data)||NLP format||NLP annotation format\", \"key\": \"format_1915||format_2350||format_3841||format_3862\"}], \"name\": \"NLP annotation format\", \"uri\": \"http://edamontology.org/format_3862\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"NLP corpus format\", \"uri\": \"http://edamontology.org/format_3863\"}]}, {\"definition\": \"NLP format used by a specific type of corpus (collection of texts).\", \"path\": [{\"name\": \"Format||Format (by type of data)||NLP format||NLP annotation format||NLP corpus format\", \"key\": \"format_1915||format_2350||format_3841||format_3862||format_3863\"}], \"name\": \"NLP corpus format\", \"uri\": \"http://edamontology.org/format_3863\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A \\\"placeholder\\\" concept for formats of annotated RNA data, including e.g. microRNA and RNA-Seq data.\", \"path\": [{\"name\": \"Format||Format (by type of data)||RNA annotation format\", \"key\": \"format_1915||format_2350||format_3865\"}], \"name\": \"RNA annotation format\", \"uri\": \"http://edamontology.org/format_3865\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"miRNA data format\", \"microRNA data format\"], \"children\": [{\"name\": \"mirGFF3\", \"uri\": \"http://edamontology.org/format_3864\"}]}, {\"definition\": \"mirGFF3 is a common format for microRNA data resulting from small-RNA RNA-Seq workflows.\", \"path\": {\"name\": \"Format||Format (by type of data)||RNA annotation format||mirGFF3\", \"key\": \"format_1915||format_2350||format_3865||format_3864\"}, \"name\": \"mirGFF3\", \"uri\": \"http://edamontology.org/format_3864\", \"exact_synonyms\": [\"miRTop format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"File format to store trajectory information for a 3D structure .\", \"path\": [{\"name\": \"Format||Format (by type of data)||Trajectory format\", \"key\": \"format_1915||format_2350||format_3866\"}], \"name\": \"Trajectory format\", \"uri\": \"http://edamontology.org/format_3866\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"CG trajectory formats\", \"MD trajectory formats\", \"NA trajectory formats\", \"Protein trajectory formats\"], \"children\": [{\"name\": \"Trajectory format (binary)\", \"uri\": \"http://edamontology.org/format_3867\"}, {\"name\": \"Trajectory format (text)\", \"uri\": \"http://edamontology.org/format_3868\"}]}, {\"definition\": \"Binary file format to store trajectory information for a 3D structure .\", \"path\": [{\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)\", \"key\": \"format_1915||format_2350||format_3866||format_3867\"}], \"name\": \"Trajectory format (binary)\", \"uri\": \"http://edamontology.org/format_3867\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"HDF5\", \"uri\": \"http://edamontology.org/format_3590\"}, {\"name\": \"netCDF\", \"uri\": \"http://edamontology.org/format_3650\"}, {\"name\": \"HDF\", \"uri\": \"http://edamontology.org/format_3873\"}, {\"name\": \"PCAzip\", \"uri\": \"http://edamontology.org/format_3874\"}, {\"name\": \"XTC\", \"uri\": \"http://edamontology.org/format_3875\"}, {\"name\": \"TNG\", \"uri\": \"http://edamontology.org/format_3876\"}, {\"name\": \"BinPos\", \"uri\": \"http://edamontology.org/format_3885\"}]}, {\"definition\": \"HDF5 is a data model, library, and file format for storing and managing data, based on Hierarchical Data Format (HDF).\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||HDF5\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3590\"}, \"name\": \"HDF5\", \"uri\": \"http://edamontology.org/format_3590\", \"exact_synonyms\": [\"h5\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Loom\", \"uri\": \"http://edamontology.org/format_3913\"}]}, {\"definition\": \"The Loom file format is based on HDF5, a standard for storing large numerical datasets. The Loom format is designed to efficiently hold large omics datasets. Typically, such data takes the form of a large matrix of numbers, along with metadata for the rows and columns.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||HDF5||Loom\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3590||format_3913\"}, \"name\": \"Loom\", \"uri\": \"http://edamontology.org/format_3913\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format used by netCDF software  library for writing and reading chromatography-MS data files.  Also used to store trajectory atom coordinates information, such as the ones obtained by Molecular Dynamics simulations.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||netCDF\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3650\"}, \"name\": \"netCDF\", \"uri\": \"http://edamontology.org/format_3650\", \"exact_synonyms\": [\"ANDI-MS\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"HDF is the name of a set of file formats and libraries designed to store and organize large amounts of numerical data, originally developed at the National Center for Supercomputing Applications at the University of Illinois.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||HDF\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3873\"}, \"name\": \"HDF\", \"uri\": \"http://edamontology.org/format_3873\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"PCAZip format is a binary compressed file to store atom coordinates based on Essential Dynamics (ED) and Principal Component Analysis (PCA).\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||PCAzip\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3874\"}, \"name\": \"PCAzip\", \"uri\": \"http://edamontology.org/format_3874\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Portable binary format for trajectories produced by GROMACS package.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||XTC\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3875\"}, \"name\": \"XTC\", \"uri\": \"http://edamontology.org/format_3875\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Trajectory Next Generation (TNG) is a format for storage of molecular simulation data. It is designed and implemented by the GROMACS development group, and it is called to be the substitute of the XTC format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||TNG\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3876\"}, \"name\": \"TNG\", \"uri\": \"http://edamontology.org/format_3876\", \"exact_synonyms\": [\"Trajectory Next Generation format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Scripps Research Institute BinPos format is a binary formatted file to store atom coordinates.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||BinPos\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3885\"}, \"name\": \"BinPos\", \"uri\": \"http://edamontology.org/format_3885\", \"exact_synonyms\": [\"Scripps Research Institute BinPos\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Textual file format to store trajectory information for a 3D structure .\", \"path\": [{\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (text)\", \"key\": \"format_1915||format_2350||format_3866||format_3868\"}], \"name\": \"Trajectory format (text)\", \"uri\": \"http://edamontology.org/format_3868\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"XYZ\", \"uri\": \"http://edamontology.org/format_3877\"}, {\"name\": \"mdcrd\", \"uri\": \"http://edamontology.org/format_3878\"}, {\"name\": \"RST\", \"uri\": \"http://edamontology.org/format_3886\"}, {\"name\": \"trr\", \"uri\": \"http://edamontology.org/format_3910\"}]}, {\"definition\": \"The XYZ chemical file format is widely supported by many programs, although many slightly different XYZ file formats coexist (Tinker XYZ, UniChem XYZ, etc.). Basic information stored for each atom in the system are x, y and z coordinates and atom element/atomic number.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (text)||XYZ\", \"key\": \"format_1915||format_2350||format_3866||format_3868||format_3877\"}, \"name\": \"XYZ\", \"uri\": \"http://edamontology.org/format_3877\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"AMBER trajectory (also called mdcrd), with 10 coordinates per line and format F8.3 (fixed point notation with field width 8 and 3 decimal places).\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (text)||mdcrd\", \"key\": \"format_1915||format_2350||format_3866||format_3868||format_3878\"}, \"name\": \"mdcrd\", \"uri\": \"http://edamontology.org/format_3878\", \"exact_synonyms\": [\"AMBER trajectory format\", \"inpcrd\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"AMBER coordinate/restart file with 6 coordinates per line and decimal format F12.7 (fixed point notation with field width 12 and 7 decimal places)\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (text)||RST\", \"key\": \"format_1915||format_2350||format_3866||format_3868||format_3886\"}, \"name\": \"RST\", \"uri\": \"http://edamontology.org/format_3886\", \"exact_synonyms\": [\"restrt\", \"rst7\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format of trr files that contain the trajectory of a simulation experiment used by GROMACS.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (text)||trr\", \"key\": \"format_1915||format_2350||format_3866||format_3868||format_3910\"}, \"name\": \"trr\", \"uri\": \"http://edamontology.org/format_3910\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format of topology files; containing the static information of a structure molecular system that is needed for a molecular simulation.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Topology format\", \"key\": \"format_1915||format_2350||format_3879\"}], \"name\": \"Topology format\", \"uri\": \"http://edamontology.org/format_3879\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"CG topology format\", \"MD topology format\", \"NA topology format\", \"Protein topology format\"], \"children\": [{\"name\": \"GROMACS top\", \"uri\": \"http://edamontology.org/format_3880\"}, {\"name\": \"AMBER top\", \"uri\": \"http://edamontology.org/format_3881\"}, {\"name\": \"PSF\", \"uri\": \"http://edamontology.org/format_3882\"}, {\"name\": \"GROMACS itp\", \"uri\": \"http://edamontology.org/format_3883\"}, {\"name\": \"CHARMM rtf\", \"uri\": \"http://edamontology.org/format_3887\"}]}, {\"definition\": \"GROMACS MD package top textual files define an entire structure system topology, either directly, or by including itp files.\", \"path\": {\"name\": \"Format||Format (by type of data)||Topology format||GROMACS top\", \"key\": \"format_1915||format_2350||format_3879||format_3880\"}, \"name\": \"GROMACS top\", \"uri\": \"http://edamontology.org/format_3880\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"AMBER Prmtop file (version 7) is a structure topology text file divided in several sections designed to be parsed easily using simple Fortran code. Each section contains particular topology information, such as atom name, charge, mass, angles, dihedrals, etc.\", \"path\": {\"name\": \"Format||Format (by type of data)||Topology format||AMBER top\", \"key\": \"format_1915||format_2350||format_3879||format_3881\"}, \"name\": \"AMBER top\", \"uri\": \"http://edamontology.org/format_3881\", \"exact_synonyms\": [\"AMBER Parm\", \"AMBER Parm7\", \"Parm7\", \"Prmtop\", \"Prmtop7\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"X-Plor Protein Structure Files (PSF) are structure topology files used by NAMD and CHARMM molecular simulations programs. PSF files contain six main sections of interest: atoms, bonds, angles, dihedrals, improper dihedrals (force terms used to maintain planarity) and cross-terms.\", \"path\": {\"name\": \"Format||Format (by type of data)||Topology format||PSF\", \"key\": \"format_1915||format_2350||format_3879||format_3882\"}, \"name\": \"PSF\", \"uri\": \"http://edamontology.org/format_3882\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"GROMACS itp files (include topology) contain structure topology information, and are tipically included in GROMACS topology files (GROMACS top). Itp files are used to define individual (or multiple) components of a topology as a separate file. This is particularly useful if there is a molecule that is used frequently, and also reduces the size of the system topology file, splitting it in different parts.\", \"path\": {\"name\": \"Format||Format (by type of data)||Topology format||GROMACS itp\", \"key\": \"format_1915||format_2350||format_3879||format_3883\"}, \"name\": \"GROMACS itp\", \"uri\": \"http://edamontology.org/format_3883\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format of CHARMM Residue Topology Files (RTF), which define groups by including the atoms, the properties of the group, and bond and charge information.\", \"path\": {\"name\": \"Format||Format (by type of data)||Topology format||CHARMM rtf\", \"key\": \"format_1915||format_2350||format_3879||format_3887\"}, \"name\": \"CHARMM rtf\", \"uri\": \"http://edamontology.org/format_3887\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format of force field parameter files, which store the set of parameters (charges, masses, radii, bond lengths, bond dihedrals, etc.) that are essential for the proper description and simulation of a molecular system.\", \"path\": [{\"name\": \"Format||Format (by type of data)||FF parameter format\", \"key\": \"format_1915||format_2350||format_3884\"}], \"name\": \"FF parameter format\", \"uri\": \"http://edamontology.org/format_3884\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"GROMACS itp\", \"uri\": \"http://edamontology.org/format_3883\"}, {\"name\": \"AMBER frcmod\", \"uri\": \"http://edamontology.org/format_3888\"}, {\"name\": \"AMBER off\", \"uri\": \"http://edamontology.org/format_3889\"}]}, {\"definition\": \"GROMACS itp files (include topology) contain structure topology information, and are tipically included in GROMACS topology files (GROMACS top). Itp files are used to define individual (or multiple) components of a topology as a separate file. This is particularly useful if there is a molecule that is used frequently, and also reduces the size of the system topology file, splitting it in different parts.\", \"path\": {\"name\": \"Format||Format (by type of data)||FF parameter format||GROMACS itp\", \"key\": \"format_1915||format_2350||format_3884||format_3883\"}, \"name\": \"GROMACS itp\", \"uri\": \"http://edamontology.org/format_3883\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"AMBER frcmod (Force field Modification) is a file format to store any modification to the standard force field needed for a particular molecule to be properly represented in the simulation.\", \"path\": {\"name\": \"Format||Format (by type of data)||FF parameter format||AMBER frcmod\", \"key\": \"format_1915||format_2350||format_3884||format_3888\"}, \"name\": \"AMBER frcmod\", \"uri\": \"http://edamontology.org/format_3888\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"AMBER Object File Format library files (OFF library files) store residue libraries (forcefield residue parameters).\", \"path\": {\"name\": \"Format||Format (by type of data)||FF parameter format||AMBER off\", \"key\": \"format_1915||format_2350||format_3884||format_3889\"}, \"name\": \"AMBER off\", \"uri\": \"http://edamontology.org/format_3889\", \"exact_synonyms\": [\"AMBER Object File Format\", \"AMBER lib\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A serialisation format conforming to the Resource Description Framework (RDF) model.\", \"path\": {\"name\": \"Format||RDF format\", \"key\": \"format_1915||format_2376\"}, \"name\": \"RDF format\", \"uri\": \"http://edamontology.org/format_2376\", \"exact_synonyms\": [\"Resource Description Framework format\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"OWL format\", \"uri\": \"http://edamontology.org/format_2197\"}, {\"name\": \"Turtle\", \"uri\": \"http://edamontology.org/format_3255\"}, {\"name\": \"N-Triples\", \"uri\": \"http://edamontology.org/format_3256\"}, {\"name\": \"Notation3\", \"uri\": \"http://edamontology.org/format_3257\"}, {\"name\": \"RDF/XML\", \"uri\": \"http://edamontology.org/format_3261\"}, {\"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\"}, {\"name\": \"UniProtKB RDF\", \"uri\": \"http://edamontology.org/format_3771\"}, {\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}, {\"name\": \"N-Quads\", \"uri\": \"http://edamontology.org/format_3956\"}]}, {\"definition\": \"A serialisation format conforming to the Web Ontology Language (OWL) model.\", \"path\": {\"name\": \"Format||RDF format||OWL format\", \"key\": \"format_1915||format_2376||format_2197\"}, \"name\": \"OWL format\", \"uri\": \"http://edamontology.org/format_2197\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"OWL Functional Syntax\", \"uri\": \"http://edamontology.org/format_3252\"}, {\"name\": \"Manchester OWL Syntax\", \"uri\": \"http://edamontology.org/format_3253\"}, {\"name\": \"OWL/XML\", \"uri\": \"http://edamontology.org/format_3262\"}]}, {\"definition\": \"A human-readable encoding for the Web Ontology Language (OWL).\", \"path\": {\"name\": \"Format||RDF format||OWL format||OWL Functional Syntax\", \"key\": \"format_1915||format_2376||format_2197||format_3252\"}, \"name\": \"OWL Functional Syntax\", \"uri\": \"http://edamontology.org/format_3252\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A syntax for writing OWL class expressions.\", \"path\": {\"name\": \"Format||RDF format||OWL format||Manchester OWL Syntax\", \"key\": \"format_1915||format_2376||format_2197||format_3253\"}, \"name\": \"Manchester OWL Syntax\", \"uri\": \"http://edamontology.org/format_3253\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"OWL ontology XML serialisation format.\", \"path\": {\"name\": \"Format||RDF format||OWL format||OWL/XML\", \"key\": \"format_1915||format_2376||format_2197||format_3262\"}, \"name\": \"OWL/XML\", \"uri\": \"http://edamontology.org/format_3262\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"OWL\"], \"children\": []}, {\"definition\": \"The Terse RDF Triple Language (Turtle) is a human-friendly serialisation format for RDF (Resource Description Framework) graphs.\", \"path\": {\"name\": \"Format||RDF format||Turtle\", \"key\": \"format_1915||format_2376||format_3255\"}, \"name\": \"Turtle\", \"uri\": \"http://edamontology.org/format_3255\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A plain text serialisation format for RDF (Resource Description Framework) graphs, and a subset of the Turtle (Terse RDF Triple Language) format.\", \"path\": {\"name\": \"Format||RDF format||N-Triples\", \"key\": \"format_1915||format_2376||format_3256\"}, \"name\": \"N-Triples\", \"uri\": \"http://edamontology.org/format_3256\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A shorthand non-XML serialisation of Resource Description Framework model, designed with human-readability in mind.\", \"path\": {\"name\": \"Format||RDF format||Notation3\", \"key\": \"format_1915||format_2376||format_3257\"}, \"name\": \"Notation3\", \"uri\": \"http://edamontology.org/format_3257\", \"exact_synonyms\": [\"N3\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Resource Description Framework (RDF) XML format.\", \"path\": {\"name\": \"Format||RDF format||RDF/XML\", \"key\": \"format_1915||format_2376||format_3261\"}, \"name\": \"RDF/XML\", \"uri\": \"http://edamontology.org/format_3261\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"JSON-LD, or JavaScript Object Notation for Linked Data, is a method of encoding Linked Data using JSON.\", \"path\": {\"name\": \"Format||RDF format||JSON-LD\", \"key\": \"format_1915||format_2376||format_3749\"}, \"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\", \"exact_synonyms\": [\"JavaScript Object Notation for Linked Data\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}]}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||RDF format||JSON-LD||Open Annotation format\", \"key\": \"format_1915||format_2376||format_3749||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"UniProtKB RDF sequence features format is an RDF format available for downloading UniProt entries (in RDF/XML).\", \"path\": {\"name\": \"Format||RDF format||UniProtKB RDF\", \"key\": \"format_1915||format_2376||format_3771\"}, \"name\": \"UniProtKB RDF\", \"uri\": \"http://edamontology.org/format_3771\", \"exact_synonyms\": [\"UniProt RDF\", \"UniProt RDF format\", \"UniProtKB RDF format\"], \"narrow_synonyms\": [\"UniProt RDF/XML\", \"UniProt RDF/XML format\", \"UniProtKB RDF/XML\", \"UniProtKB RDF/XML format\"], \"children\": []}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||RDF format||Open Annotation format\", \"key\": \"format_1915||format_2376||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"N-Quads is a line-based, plain text format for encoding an RDF dataset. It includes information about the graph each triple belongs to.\", \"path\": {\"name\": \"Format||RDF format||N-Quads\", \"key\": \"format_1915||format_2376||format_3956\"}, \"name\": \"N-Quads\", \"uri\": \"http://edamontology.org/format_3956\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"JavaScript Object Notation format; a lightweight, text-based format to represent tree-structured data using key-value pairs.\", \"path\": [{\"name\": \"Format||JSON\", \"key\": \"format_1915||format_3464\"}, {\"name\": \"Format||YAML||JSON\", \"key\": \"format_1915||format_3750||format_3464\"}], \"name\": \"JSON\", \"uri\": \"http://edamontology.org/format_3464\", \"exact_synonyms\": [\"JavaScript Object Notation\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\"}, {\"name\": \"BioJSON (BioXSD)\", \"uri\": \"http://edamontology.org/format_3772\"}, {\"name\": \"BioJSON (Jalview)\", \"uri\": \"http://edamontology.org/format_3774\"}, {\"name\": \"PubAnnotation format\", \"uri\": \"http://edamontology.org/format_3781\"}, {\"name\": \"Vega\", \"uri\": \"http://edamontology.org/format_3969\"}, {\"name\": \"Vega-lite\", \"uri\": \"http://edamontology.org/format_3970\"}]}, {\"definition\": \"JSON-LD, or JavaScript Object Notation for Linked Data, is a method of encoding Linked Data using JSON.\", \"path\": {\"name\": \"Format||JSON||JSON-LD\", \"key\": \"format_1915||format_3464||format_3749\"}, \"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\", \"exact_synonyms\": [\"JavaScript Object Notation for Linked Data\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}]}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||JSON||JSON-LD||Open Annotation format\", \"key\": \"format_1915||format_3464||format_3749||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"BioJSON is a BioXSD-schema-based JSON format of sequence-based data and some other common data - sequence records, alignments, feature records, references to resources, and more - optimised for integrative bioinformatics, web applications and APIs, and object-oriented programming.\", \"path\": {\"name\": \"Format||JSON||BioJSON (BioXSD)\", \"key\": \"format_1915||format_3464||format_3772\"}, \"name\": \"BioJSON (BioXSD)\", \"uri\": \"http://edamontology.org/format_3772\", \"exact_synonyms\": [\"BioJSON (BioXSD data model)\", \"BioJSON format (BioXSD)\", \"BioXSD BioJSON\", \"BioXSD BioJSON format\", \"BioXSD JSON\", \"BioXSD JSON format\", \"BioXSD in JSON\", \"BioXSD in JSON format\", \"BioXSD+JSON\", \"BioXSD/GTrack BioJSON\", \"BioXSD|BioJSON|BioYAML BioJSON\", \"BioXSD|GTrack BioJSON\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"BioJSON is a JSON format of single multiple sequence alignments, with their annotations, features, and custom visualisation and application settings for the Jalview workbench.\", \"path\": {\"name\": \"Format||JSON||BioJSON (Jalview)\", \"key\": \"format_1915||format_3464||format_3774\"}, \"name\": \"BioJSON (Jalview)\", \"uri\": \"http://edamontology.org/format_3774\", \"exact_synonyms\": [\"BioJSON format (Jalview)\", \"JSON (Jalview)\", \"JSON format (Jalview)\", \"Jalview BioJSON\", \"Jalview BioJSON format\", \"Jalview JSON\", \"Jalview JSON format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"JSON format of annotated scientific text used by PubAnnotations and other tools.\", \"path\": {\"name\": \"Format||JSON||PubAnnotation format\", \"key\": \"format_1915||format_3464||format_3781\"}, \"name\": \"PubAnnotation format\", \"uri\": \"http://edamontology.org/format_3781\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Vega is a visualization grammar, a declarative language for creating, saving, and sharing interactive visualization designs. With Vega, you can describe the visual appearance and interactive behavior of a visualization in a JSON format, and generate web-based views using Canvas or SVG.\", \"path\": {\"name\": \"Format||JSON||Vega\", \"key\": \"format_1915||format_3464||format_3969\"}, \"name\": \"Vega\", \"uri\": \"http://edamontology.org/format_3969\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Vega-Lite is a high-level grammar of interactive graphics. It provides a concise JSON syntax for rapidly generating visualizations to support analysis. Vega-Lite specifications can be compiled to Vega specifications.\", \"path\": {\"name\": \"Format||JSON||Vega-lite\", \"key\": \"format_1915||format_3464||format_3970\"}, \"name\": \"Vega-lite\", \"uri\": \"http://edamontology.org/format_3970\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"YAML (YAML Ain\'t Markup Language) is a human-readable tree-structured 