path\": {\"name\": \"Format||YAML||JSON||PubAnnotation format\", \"key\": \"format_1915||format_3750||format_3464||format_3781\"}, \"name\": \"PubAnnotation format\", \"uri\": \"http://edamontology.org/format_3781\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Vega is a visualization grammar, a declarative language for creating, saving, and sharing interactive visualization designs. With Vega, you can describe the visual appearance and interactive behavior of a visualization in a JSON format, and generate web-based views using Canvas or SVG.\", \"path\": {\"name\": \"Format||YAML||JSON||Vega\", \"key\": \"format_1915||format_3750||format_3464||format_3969\"}, \"name\": \"Vega\", \"uri\": \"http://edamontology.org/format_3969\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Vega-Lite is a high-level grammar of interactive graphics. It provides a concise JSON syntax for rapidly generating visualizations to support analysis. Vega-Lite specifications can be compiled to Vega specifications.\", \"path\": {\"name\": \"Format||YAML||JSON||Vega-lite\", \"key\": \"format_1915||format_3750||format_3464||format_3970\"}, \"name\": \"Vega-lite\", \"uri\": \"http://edamontology.org/format_3970\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"BioYAML is a BioXSD-schema-based YAML format of sequence-based data and some other common data - sequence records, alignments, feature records, references to resources, and more - optimised for integrative bioinformatics, web APIs, human readability and editting, and object-oriented programming.\", \"path\": {\"name\": \"Format||YAML||BioYAML\", \"key\": \"format_1915||format_3750||format_3773\"}, \"name\": \"BioYAML\", \"uri\": \"http://edamontology.org/format_3773\", \"exact_synonyms\": [\"BioXSD BioYAML\", \"BioXSD BioYAML format\", \"BioXSD YAML\", \"BioXSD YAML format\", \"BioXSD in YAML\", \"BioXSD in YAML format\", \"BioXSD+YAML\", \"BioXSD/GTrack BioYAML\", \"BioXSD|BioJSON|BioYAML BioYAML\", \"BioXSD|GTrack BioYAML\", \"BioYAML (BioXSD data model)\", \"BioYAML (BioXSD)\", \"BioYAML format\", \"BioYAML format (BioXSD)\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Common Workflow Language (CWL) format for description of command-line tools and workflows.\", \"path\": {\"name\": \"Format||YAML||CWL\", \"key\": \"format_1915||format_3750||format_3857\"}, \"name\": \"CWL\", \"uri\": \"http://edamontology.org/format_3857\", \"exact_synonyms\": [\"Common Workflow Language\", \"CommonWL\"], \"narrow_synonyms\": [], \"children\": []}]','2025-08-27 12:52:46.725681');
INSERT INTO `elixir_ontology` VALUES (40,'flat_EDAM_Format_1.25','[{\"definition\": \"A defined way or layout of representing and structuring data in a computer file, blob, string, message, or elsewhere. The main focus in EDAM lies on formats as means of structuring data exchanged between different tools or resources. The serialisation, compression, or encoding of concrete data formats/models is not in scope of EDAM. Format \'is format of\' Data.\", \"path\": [{\"name\": \"Format\", \"key\": \"format_1915\"}], \"name\": \"Format\", \"uri\": \"http://edamontology.org/format_1915\", \"exact_synonyms\": [\"Exchange format\", \"Data format\"], \"narrow_synonyms\": [\"File format\"], \"children\": [{\"name\": \"Textual format\", \"uri\": \"http://edamontology.org/format_2330\"}, {\"name\": \"HTML\", \"uri\": \"http://edamontology.org/format_2331\"}, {\"name\": \"XML\", \"uri\": \"http://edamontology.org/format_2332\"}, {\"name\": \"Binary format\", \"uri\": \"http://edamontology.org/format_2333\"}, {\"name\": \"Format (by type of data)\", \"uri\": \"http://edamontology.org/format_2350\"}, {\"name\": \"RDF format\", \"uri\": \"http://edamontology.org/format_2376\"}, {\"name\": \"JSON\", \"uri\": \"http://edamontology.org/format_3464\"}, {\"name\": \"YAML\", \"uri\": \"http://edamontology.org/format_3750\"}]}, {\"definition\": \"Textual format.\", \"path\": [{\"name\": \"Format||Textual format\", \"key\": \"format_1915||format_2330\"}], \"name\": \"Textual format\", \"uri\": \"http://edamontology.org/format_2330\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Plain text format\", \"txt\"], \"children\": [{\"name\": \"SMILES\", \"uri\": \"http://edamontology.org/format_1196\"}, {\"name\": \"InChI\", \"uri\": \"http://edamontology.org/format_1197\"}, {\"name\": \"mf\", \"uri\": \"http://edamontology.org/format_1198\"}, {\"name\": \"InChIKey\", \"uri\": \"http://edamontology.org/format_1199\"}, {\"name\": \"nucleotide\", \"uri\": \"http://edamontology.org/format_1207\"}, {