, \"children\": []}, {\"definition\": \"A format resembling GenBank entry (plain text) format.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Sequence record format||GenBank-like format\", \"key\": \"format_1915||format_2350||format_1919||format_2559\"}], \"name\": \"GenBank-like format\", \"uri\": \"http://edamontology.org/format_2559\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"GenBank-like format (text)\", \"uri\": \"http://edamontology.org/format_2205\"}, {\"name\": \"GenBank-HTML\", \"uri\": \"http://edamontology.org/format_2532\"}]}, {\"definition\": \"A text format resembling GenBank entry (plain text) format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Sequence record format||GenBank-like format||GenBank-like format (text)\", \"key\": \"format_1915||format_2350||format_1919||format_2559||format_2205\"}, \"name\": \"GenBank-like format (text)\", \"uri\": \"http://edamontology.org/format_2205\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"GenBank format\", \"uri\": \"http://edamontology.org/format_1936\"}, {\"name\": \"genpept\", \"uri\": \"http://edamontology.org/format_1937\"}]}, {\"definition\": \"Genbank entry format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Sequence record format||GenBank-like format||GenBank-like format (text)||GenBank format\", \"key\": \"format_1915||format_2350||format_1919||format_2559||format_2205||format_1936\"}, \"name\": \"GenBank format\", \"uri\": \"http://edamontology.org/format_1936\", \"exact_synonyms\": [\"GenBank\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Genpept protein entry format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Sequence record format||GenBank-like format||GenBank-like format (text)||genpept\", \"key\": \"format_1915||format_2350||format_1919||format_2559||format_2205||format_1937\"}, \"name\": \"genpept\", \"uri\": \"http://edamontology.org/format_1937