ntology.org/format_3587\"}]}, {\"definition\": \"Browser Extensible Data (BED) format of sequence annotation track that strictly does not contain non-standard fields beyond the first 3 columns.\", \"path\": {\"name\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||BED||bedstrict\", \"key\": \"format_1915||format_2350||format_1920||format_2919||format_3003||format_3584\"}, \"name\": \"bedstrict\", \"uri\": \"http://edamontology.org/format_3584\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"bed6\", \"uri\": \"http://edamontology.org/format_3585\"}, {\"name\": \"bed12\", \"uri\": \"http://edamontology.org/format_3586\"}]}, {\"definition\": \"BED file format where each feature is described by chromosome, start, end, name, score, and strand.\", \"path\": {\"name\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||BED||bedstrict||bed6\", \"key\": \"format_1915||format_2350||format_1920||format_2919||format_3003||format_3584||format_3585\"}, \"name\": \"bed6\", \"uri\": \"http://edamontology.org/format_3585\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"ENCODE peak format\", \"uri\": \"http://edamontology.org/format_3612\"}]}, {\"definition\": \"Human ENCODE peak format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||BED||bedstrict||bed6||ENCODE peak format\", \"key\": \"format_1915||format_2350||format_1920||format_2919||format_3003||format_3584||format_3585||format_3612\"}, \"name\": \"ENCODE peak format\", \"uri\": \"http://edamontology.org/format_3612\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"ENCODE narrow peak format\", \"uri\": \"http://edamontology.org/format_3613\"}, {\"name\": \"ENCODE broad peak format\", \"uri\": \"http://edamontology.org/format_3614\"}]}, {\"defin