xact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"mzIdentML is the exchange format for peptides and proteins identified from mass spectra, standardised by HUPO PSI PI. It can be used for outputs of proteomics search engines.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||mzIdentML\", \"key\": \"format_1915||format_2350||format_3245||format_3247\"}, \"name\": \"mzIdentML\", \"uri\": \"http://edamontology.org/format_3247\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"mzQuantML is the format for quantitation values associated with peptides, proteins and small molecules from mass spectra, standardised by HUPO PSI PI. It can be used for outputs of quantitation software for proteomics.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||mzQuantML\", \"key\": \"format_1915||format_2350||format_3245||format_3248\"}, \"name\": \"mzQuantML\", \"uri\": \"http://edamontology.org/format_3248\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format used by netCDF software  library for writing and reading chromatography-MS data files.  Also used to store trajectory atom coordinates information, such as the ones obtained by Molecular Dynamics simulations.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||netCDF\", \"key\": \"format_1915||format_2350||format_3245||format_3650\"}, \"name\": \"netCDF\", \"uri\": \"http://edamontology.org/format_3650\", \"exact_synonyms\": [\"ANDI-MS\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Mascot Generic Format.  Encodes multiple MS/MS spectra in a single file.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||MGF\", \"key\": \"format_1915||format_2350||format_3245||format_3651\"}], \"name\": \"MGF\", \"uri\": \"http://edamontology.org/format_3651\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Spectral data format file where each spectrum is written to a separate file.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||dta\", \"key\": \"format_1915||format_2350||format_3245||format_3652\"}], \"name\": \"dta\", \"uri\": \"http://edamontology.org/format_3652\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Spectral data file similar to dta.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||pkl\", \"key\": \"format_1915||format_2350||format_3245||format_3653\"}], \"name\": \"pkl\", \"uri\": \"http://edamontology.org/format_3653\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Common file format for proteomics mass spectrometric data developed at the Seattle Proteome Center/Institute for Systems Biology.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||mzXML\", \"key\": \"format_1915||format_2350||format_3245||format_3654\"}], \"name\": \"mzXML\", \"uri\": \"http://edamontology.org/format_3654\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Open data format for the storage, exchange, and processing of peptide sequence assignments of MS/MS scans, intended to provide a common data output format for many different MS/MS search engines and subsequent peptide-level analyses.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||pepXML\", \"key\": \"format_1915||format_2350||format_3245||format_3655\"}, \"name\": \"pepXML\", \"uri\": \"http://edamontology.org/format_3655\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"mzTab is a tab-delimited format for mass spectrometry-based proteomics and metabolomics results.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||mzTab\", \"key\": \"format_1915||format_2350||format_3245||format_3681\"}, \"name\": \"mzTab\", \"uri\": \"http://edamontology.org/format_3681\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"imzML metadata is a data format for mass spectrometry imaging metadata.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||imzML metadata file\", \"key\": \"format_1915||format_2350||format_3245||format_3682\"}, \"name\": \"imzML metadata file\", \"uri\": \"http://edamontology.org/format_3682\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"qcML is an XML format for quality-related data of mass spectrometry and other high-throughput measurements.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||qcML\", \"key\": \"format_1915||format_2350||format_3245||format_3683\"}, \"name\": \"qcML\", \"uri\": \"http://edamontology.org/format_3683\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"PRIDE XML is an XML format for mass spectra, peptide and protein identifications, and metadata about a corresponding measurement, sample, experiment.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||PRIDE XML\", \"key\": \"format_1915||format_2350||format_3245||format_3684\"}, \"name\": \"PRIDE XML\", \"uri\": \"http://edamontology.org/format_3684\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Proprietary mass-spectrometry format of Thermo Scientific\'s ProteomeDiscoverer software.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||MSF\", \"key\": \"format_1915||format_2350||format_3245||format_3702\"}], \"name\": \"MSF\", \"uri\": \"http://edamontology.org/format_3702\", \"exact_synonyms\": [\"Magellan storage file format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Mass spectrum file format from QSTAR and QTRAP instruments (ABI/Sciex).\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||WIFF format\", \"key\": \"format_1915||format_2350||format_3245||format_3710\"}, \"name\": \"WIFF format\", \"uri\": \"http://edamontology.org/format_3710\", \"exact_synonyms\": [\"wiff\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Output format used by X! series search engines that is based on the XML language BIOML.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||X!Tandem XML\", \"key\": \"format_1915||format_2350||format_3245||format_3711\"}, \"name\": \"X!Tandem XML\", \"uri\": \"http://edamontology.org/format_3711\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Proprietary file format for mass spectrometry data from Thermo Scientific.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||Thermo RAW\", \"key\": \"format_1915||format_2350||format_3245||format_3712\"}, \"name\": \"Thermo RAW\", \"uri\": \"http://edamontology.org/format_3712\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"\\\"Raw\\\" result file from Mascot database search.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||Mascot .dat file\", \"key\": \"format_1915||format_2350||format_3245||format_3713\"}, \"name\": \"Mascot .dat file\", \"uri\": \"http://edamontology.org/format_3713\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format of peak list files from Andromeda search engine (MaxQuant) that consist of arbitrarily many spectra.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||MaxQuant APL peaklist format\", \"key\": \"format_1915||format_2350||format_3245||format_3714\"}, \"name\": \"MaxQuant APL peaklist format\", \"uri\": \"http://edamontology.org/format_3714\", \"exact_synonyms\": [\"MaxQuant APL\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A format for storage, exchange, and processing of protein identifications created from ms/ms-derived peptide sequence data.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||protXML\", \"key\": \"format_1915||format_2350||format_3245||format_3747\"}, \"name\": \"protXML\", \"uri\": \"http://edamontology.org/format_3747\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"\\\"Raw\\\" result file from SEQUEST database search.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||SEQUEST .out file\", \"key\": \"format_1915||format_2350||format_3245||format_3758\"}, \"name\": \"SEQUEST .out file\", \"uri\": \"http://edamontology.org/format_3758\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"XML file format for files containing information about peptide identifications from mass spectrometry data analysis carried out with OpenMS.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||idXML\", \"key\": \"format_1915||format_2350||format_3245||format_3764\"}, \"name\": \"idXML\", \"uri\": \"http://edamontology.org/format_3764\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"OpenMS format for grouping features in one map or across several maps.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||consensusXML\", \"key\": \"format_1915||format_2350||format_3245||format_3832\"}, \"name\": \"consensusXML\", \"uri\": \"http://edamontology.org/format_3832\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"OpenMS format for quantitation results (LC/MS features).\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||featureXML\", \"key\": \"format_1915||format_2350||format_3245||format_3833\"}, \"name\": \"featureXML\", \"uri\": \"http://edamontology.org/format_3833\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Now deprecated data format of the HUPO Proteomics Standards Initiative.  Replaced by mzML (format_3244).\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||mzData\", \"key\": \"format_1915||format_2350||format_3245||format_3834\"}, \"name\": \"mzData\", \"uri\": \"http://edamontology.org/format_3834\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format supported by the Tide tool for identifying peptides from tandem mass spectra.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||TIDE TXT\", \"key\": \"format_1915||format_2350||format_3245||format_3835\"}, \"name\": \"TIDE TXT\", \"uri\": \"http://edamontology.org/format_3835\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"ibd is a data format for mass spectrometry imaging data.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||ibd\", \"key\": \"format_1915||format_2350||format_3245||format_3839\"}, \"name\": \"ibd\", \"uri\": \"http://edamontology.org/format_3839\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Proprietary file format for mass spectrometry data from Waters.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||Waters RAW\", \"key\": \"format_1915||format_2350||format_3245||format_3858\"}, \"name\": \"Waters RAW\", \"uri\": \"http://edamontology.org/format_3858\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A standardized file format for data exchange in mass spectrometry, initially developed for infrared spectrometry.\", \"path\": {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||JCAMP-DX\", \"key\": \"format_1915||format_2350||format_3245||format_3859\"}, \"name\": \"JCAMP-DX\", \"uri\": \"http://edamontology.org/format_3859\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data format for a metadata on an individual and their genetic data.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Individual genetic data format\", \"key\": \"format_1915||format_2350||format_3287\"}], \"name\": \"Individual genetic data format\", \"uri\": \"http://edamontology.org/format_3287\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"PED/MAP\", \"uri\": \"http://edamontology.org/format_3288\"}]}, {\"definition\": \"The PED/MAP file describes data used by the Plink package.\", \"path\": {\"name\": \"Format||Format (by type of data)||Individual genetic data format||PED/MAP\", \"key\": \"format_1915||format_2350||format_3287||format_3288\"}, \"name\": \"PED/MAP\", \"uri\": \"http://edamontology.org/format_3288\", \"exact_synonyms\": [\"Plink PED/MAP\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"MAP\", \"uri\": \"http://edamontology.org/format_3285\"}, {\"name\": \"PED\", \"uri\": \"http://edamontology.org/format_3286\"}]}, {\"definition\": \"The MAP file describes SNPs and is used by the Plink package.\", \"path\": {\"name\": \"Format||Format (by type of data)||Individual genetic data format||PED/MAP||MAP\", \"key\": \"format_1915||format_2350||format_3287||format_3288||format_3285\"}, \"name\": \"MAP\", \"uri\": \"http://edamontology.org/format_3285\", \"exact_synonyms\": [\"Plink MAP\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The PED file describes individuals and genetic data and is used by the Plink package.\", \"path\": {\"name\": \"Format||Format (by type of data)||Individual genetic data for