org/format_3491\", \"exact_synonyms\": [\"Bowtie long index format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"An index of a genome database, indexed for use by the snpeff tool.\", \"path\": {\"name\": \"Format||Format (by type of data)||Data index format||snpeffdb\", \"key\": \"format_1915||format_2350||format_3326||format_3624\"}, \"name\": \"snpeffdb\", \"uri\": \"http://edamontology.org/format_3624\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Index file format used by the samtools package to index TAB-delimited genome position files.\", \"path\": {\"name\": \"Format||Format (by type of data)||Data index format||Tabix index file format\", \"key\": \"format_1915||format_2350||format_3326||format_3700\"}, \"name\": \"Tabix index file format\", \"uri\": \"http://edamontology.org/format_3700\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format of documents including word processor, spreadsheet and presentation.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Document format\", \"key\": \"format_1915||format_2350||format_3507\"}], \"name\": \"Document format\", \"uri\": \"http://edamontology.org/format_3507\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"xls\", \"uri\": \"http://edamontology.org/format_3468\"}, {\"name\": \"docx\", \"uri\": \"http://edamontology.org/format_3506\"}, {\"name\": \"PDF\", \"uri\": \"http://edamontology.org/format_3508\"}, {\"name\": \"xlsx\", \"uri\": \"http://edamontology.org/format_3620\"}, {\"name\": \"latex\", \"uri\": \"http://edamontology.org/format_3817\"}]}, {\"definition\": \"Microsoft Excel spreadsheet format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Document format||xls\", \"key\": \"format_1915||format_2350||format_3507||format_3468\"}, \"name\": \"xls\", \"uri\": \"http://edamontology.org/format_3468\", \"exact_synonyms\": [\"Microsoft Excel format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Microsoft Word format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Document format||docx\", \"key\": \"format_1915||format_2350||format_3507||format_3506\"}, \"name\": \"docx\", \"uri\": \"http://edamontology.org/format_3506\", \"exact_synonyms\": [\"Microsoft Word format\", \"doc\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Portable Document Format\", \"path\": {\"name\": \"Format||Format (by type of data)||Document format||PDF\", \"key\": \"format_1915||format_2350||format_3507||format_3508\"}, \"name\": \"PDF\", \"uri\": \"http://edamontology.org/format_3508\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"MS Excel spreadsheet format consisting of a set of XML documents stored in a ZIP-compressed file.\", \"path\": {\"name\": \"Format||Format (by type of data)||Document format||xlsx\", \"key\": \"format_1915||format_2350||format_3507||format_3620\"}, \"name\": \"xlsx\", \"uri\": \"http://edamontology.org/format_3620\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"ObjTables\", \"uri\": \"http://edamontology.org/format_3977\"}]}, {\"definition\": \"ObjTables is a toolkit for creating re-usable datasets that are both human and machine-readable, combining the ease of spreadsheets (e.g., Excel workbooks) with the rigor of schemas (classes, their attributes, the type of each attribute, and the possible relationships between instances of classes). ObjTables consists of a format for describing schemas for spreadsheets, numerous data types for science, a syntax for indicating the class and attribute represented by each table and column in a workbook, and software for using schemas to rigorously validate, merge, split, compare, and revision datasets.\", \"path\": {\"name\": \"Format||Format (by type of data)||Document format||xlsx||ObjTables\", \"key\": \"format_1915||format_2350||format_3507||format_3620||format_3977\"}, \"name\": \"ObjTables\", \"uri\": \"http://edamontology.org/format_3977\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"format for the LaTeX document preparation system\", \"path\": {\"name\": \"Format||Format (by type of data)||Document format||latex\", \"key\": \"format_1915||format_2350||format_3507||format_3817\"}, \"name\": \"latex\", \"uri\": \"http://edamontology.org/format_3817\", \"exact_synonyms\": [\"LaTeX format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format used for images and image metadata.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Image format\", \"key\": \"format_1915||format_2350||format_3547\"}], \"name\": \"Image format\", \"uri\": \"http://edamontology.org/format_3547\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"DICOM format\", \"uri\": \"http://edamontology.org/format_3548\"}, {\"name\": \"nii\", \"uri\": \"http://edamontology.org/format_3549\"}, {\"name\": \"mhd\", \"uri\": \"http://edamontology.org/format_3550\"}, {\"name\": \"nrrd\", \"uri\": \"http://edamontology.org/format_3551\"}, {\"name\": \"JPG\", \"uri\": \"http://edamontology.org/format_3579\"}, {\"name\": \"TIFF\", \"uri\": \"http://edamontology.org/format_3591\"}, {\"name\": \"BMP\", \"uri\": \"http://edamontology.org/format_3592\"}, {\"name\": \"im\", \"uri\": \"http://edamontology.org/format_3593\"}, {\"name\": \"pcd\", \"uri\": \"http://edamontology.org/format_3594\"}, {\"name\": \"pcx\", \"uri\": \"http://edamontology.org/format_3595\"}, {\"name\": \"ppm\", \"uri\": \"http://edamontology.org/format_3596\"}, {\"name\": \"psd\", \"uri\": \"http://edamontology.org/format_3597\"}, {\"name\": \"xbm\", \"uri\": \"http://edamontology.org/format_3598\"}, {\"name\": \"xpm\", \"uri\": \"http://edamontology.org/format_3599\"}, {\"name\": \"rgb\", \"uri\": \"http://edamontology.org/format_3600\"}, {\"name\": \"pbm\", \"uri\": \"http://edamontology.org/format_3601\"}, {\"name\": \"pgm\", \"uri\": \"http://edamontology.org/format_3602\"}, {\"name\": \"PNG\", \"uri\": \"http://edamontology.org/format_3603\"}, {\"name\": \"SVG\", \"uri\": \"http://edamontology.org/format_3604\"}, {\"name\": \"rast\", \"uri\": \"http://edamontology.org/format_3605\"}, {\"name\": \"bgzip\", \"uri\": \"http://edamontology.org/format_3615\"}, {\"name\": \"tabix\", \"uri\": \"http://edamontology.org/format_3616\"}, {\"name\": \"OME-TIFF\", \"uri\": \"http://edamontology.org/format_3727\"}, {\"name\": \"pptx\", \"uri\": \"http://edamontology.org/format_3838\"}, {\"name\": \"Vega\", \"uri\": \"http://edamontology.org/format_3969\"}, {\"name\": \"Vega-lite\", \"uri\": \"http://edamontology.org/format_3970\"}, {\"name\": \"WMV\", \"uri\": \"http://edamontology.org/format_3986\"}, {\"name\": \"LSM\", \"uri\": \"http://edamontology.org/format_3988\"}, {\"name\": \"AVI\", \"uri\": \"http://edamontology.org/format_3990\"}, {\"name\": \"Stereolithography format\", \"uri\": \"http://edamontology.org/format_3993\"}, {\"name\": \"U3D\", \"uri\": \"http://edamontology.org/format_3994\"}, {\"name\": \"Texture file format\", \"uri\": \"http://edamontology.org/format_3995\"}, {\"name\": \"MPEG-4\", \"uri\": \"http://edamontology.org/format_3997\"}, {\"name\": \"NIFTI format\", \"uri\": \"http://edamontology.org/format_4001\"}]}, {\"definition\": \"Medical image format corresponding to the Digital Imaging and Communications in Medicine (DICOM) standard.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||DICOM format\", \"key\": \"format_1915||format_2350||format_3547||format_3548\"}, \"name\": \"DICOM format\", \"uri\": \"http://edamontology.org/format_3548\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Medical image and metadata format of the Neuroimaging Informatics Technology Initiative.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||nii\", \"key\": \"format_1915||format_2350||format_3547||format_3549\"}, \"name\": \"nii\", \"uri\": \"http://edamontology.org/format_3549\", \"exact_synonyms\": [\"NIfTI-1 format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Text-based tagged file format for medical images generated using the MetaImage software package.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||mhd\", \"key\": \"format_1915||format_2350||format_3547||format_3550\"}, \"name\": \"mhd\", \"uri\": \"http://edamontology.org/format_3550\", \"exact_synonyms\": [\"Metalmage format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Nearly Raw Rasta Data format designed to support scientific visualisation and image processing involving N-dimensional raster data.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||nrrd\", \"key\": \"format_1915||format_2350||format_3547||format_3551\"}, \"name\": \"nrrd\", \"uri\": \"http://edamontology.org/format_3551\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Joint Picture Group file format for lossy graphics file.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||JPG\", \"key\": \"format_1915||format_2350||format_3547||format_3579\"}, \"name\": \"JPG\", \"uri\": \"http://edamontology.org/format_3579\", \"exact_synonyms\": [\"JPEG\", \"jpeg\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A versatile bitmap format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||TIFF\", \"key\": \"format_1915||format_2350||format_3547||format_3591\"}, \"name\": \"TIFF\", \"uri\": \"http://edamontology.org/format_3591\", \"exact_synonyms\": [\"tiff\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Standard bitmap storage format in the Microsoft Windows environment.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||BMP\", \"key\": \"format_1915||format_2350||format_3547||format_3592\"}, \"name\": \"BMP\", \"uri\": \"http://edamontology.org/format_3592\", \"exact_synonyms\": [\"bmp\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"IM is a format used by LabEye and other applications based on the IFUNC image processing library.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||im\", \"key\": \"format_1915||format_2350||format_3547||format_3593\"}, \"name\": \"im\", \"uri\": \"http://edamontology.org/format_3593\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Photo CD format, which is the highest resolution format for images on a CD.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||pcd\", \"key\": \"format_1915||format_2350||format_3547||format_3594\"}, \"name\": \"pcd\", \"uri\": \"http://edamontology.org/format_3594\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"PCX is an image file format that uses a simple form of run-length encoding. It is lossless.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||pcx\", \"key\": \"format_1915||format_2350||format_3547||format_3595\"}, \"name\": \"pcx\", \"uri\": \"http://edamontology.org/format_3595\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The PPM format is a lowest common denominator color image file format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||ppm\", \"key\": \"format_1915||format_2350||format_3547||format_3596\"}, \"name\": \"ppm\", \"uri\": \"http://edamontology.org/format_3596\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"PSD (Photoshop Document) is a proprietary file that allows the user to work with the images\' individual layers even after the file has been saved.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||psd\", \"key\": \"format_1915||format_2350||format_3547||format_3597\"}, \"name\": \"psd\", \"uri\": \"http://edamontology.org/format_3597\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"X BitMap is a plain text binary image format used by the X Window System used for storing cursor and icon bitmaps used in the X GUI.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||xbm\", \"key\": \"format_1915||format_2350||format_3547||format_3598\"}, \"name\": \"xbm\", \"uri\": \"http://edamontology.org/format_3598\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"X PixMap (XPM) is an image file format used by the X Window System, it is intended primarily for creating icon pixmaps, and supports transparent pixels.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||xpm\", \"key\": \"format_1915||format_2350||format_3547||format_3599\"}, \"name\": \"xpm\", \"uri\": \"http://edamontology.org/format_3599\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"RGB file format is the native raster graphics file format for Silicon Graphics workstations.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||rgb\", \"key\": \"format_1915||format_2350||format_3547||format_3600\"}, \"name\": \"rgb\", \"uri\": \"http://edamontology.org/format_3600\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The PBM format is a lowest common denominator monochrome file format. It serves as the common language of a large family of bitmap image conversion filters.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||pbm\", \"key\": \"format_1915||format_2350||format_3547||format_3601\"}, \"name\": \"pbm\", \"uri\": \"http://edamontology.org/format_3601\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The PGM format is a lowest common denominator grayscale file format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||pgm\", \"key\": \"format_1915||format_2350||format_3547||format_3602\"}, \"name\": \"pgm\", \"uri\": \"http://edamontology.org/format_3602\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"PNG is a file format for image compression.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||PNG\", \"key\": \"format_1915||format_2350||format_3547||format_3603\"}, \"name\": \"PNG\", \"uri\": \"http://edamontology.org/format_3603\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Scalable Vector Graphics (SVG) is an XML-based vector image format for two-dimensional graphics with support for interactivity and animation.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||SVG\", \"key\": \"format_1915||format_2350||format_3547||format_3604\"}, \"name\": \"SVG\", \"uri\": \"http://edamontology.org/format_3604\", \"exact_synonyms\": [\"Scalable Vector Graphics\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Sun Raster is a raster graphics file format used on SunOS by Sun Microsystems\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||rast\", \"key\": \"format_1915||format_2350||format_3547||format_3605\"}, \"name\": \"rast\", \"uri\": \"http://edamontology.org/format_3605\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Blocked GNU Zip format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||bgzip\", \"key\": \"format_1915||format_2350||format_3547||format_3615\"}, \"name\": \"bgzip\", \"uri\": \"http://edamontology.org/format_3615\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"TAB-delimited genome position file index format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||tabix\", \"key\": \"format_1915||format_2350||format_3547||format_3616\"}, \"name\": \"tabix\", \"uri\": \"http://edamontology.org/format_3616\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Image file format used by the Open Microscopy Environment (OME).\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||OME-TIFF\", \"key\": \"format_1915||format_2350||format_3547||format_3727\"}, \"name\": \"OME-TIFF\", \"uri\": \"http://edamontology.org/format_3727\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Microsoft Powerpoint format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||pptx\", \"key\": \"format_1915||format_2350||format_3547||format_3838\"}, \"name\": \"pptx\", \"uri\": \"http://edamontology.org/format_3838\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Vega is a visualization grammar, a declarative language for creating, saving, and sharing interactive visualization designs. With Vega, you can describe the visual appearance and interactive behavior of a visualization in a JSON format, and generate web-based views using Canvas or SVG.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Image format||Vega\", \"key\": \"format_1915||format_2350||format_3547||format_3969\"}, {\"name\": \"Format||JSON||Vega\", \"key\": \"format_1915||format_3464||format_3969\"}, {\"name\": \"Format||YAML||JSON||Vega\", \"key\": \"format_1915||format_3750||format_3464||format_3969\"}], \"name\": \"Vega\", \"uri\": \"http://edamontology.org/format_3969\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Vega-Lite is a high-level grammar of interactive graphics. It provides a concise JSON syntax for rapidly generating visualizations to support analysis. Vega-Lite specifications can be compiled to Vega specifications.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Image format||Vega-lite\", \"key\": \"format_1915||format_2350||format_3547||format_3970\"}, {\"name\": \"Format||JSON||Vega-lite\", \"key\": \"format_1915||format_3464||format_3970\"}, {\"name\": \"Format||YAML||JSON||Vega-lite\", \"key\": \"format_1915||format_3750||format_3464||format_3970\"}], \"name\": \"Vega-lite\", \"uri\": \"http://edamontology.org/format_3970\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The proprietary native video format of various Microsoft programs such as Windows Media Player.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||WMV\", \"key\": \"format_1915||format_2350||format_3547||format_3986\"}, \"name\": \"WMV\", \"uri\": \"http://edamontology.org/format_3986\", \"exact_synonyms\": [\"Windows Media Video format\", \"Windows movie file format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Zeiss\' proprietary image format based on TIFF.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||LSM\", \"key\": \"format_1915||format_2350||format_3547||format_3988\"}, \"name\": \"LSM\", \"uri\": \"http://edamontology.org/format_3988\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Audio Video Interleaved (AVI) format is a multimedia container format for AVI files, that allows synchronous audio-with-video playback.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||AVI\", \"key\": \"format_1915||format_2350||format_3547||format_3990\"}, \"name\": \"AVI\", \"uri\": \"http://edamontology.org/format_3990\", \"exact_synonyms\": [\"Audio Video Interleaved\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"STL is a file format native to the stereolithography CAD software created by 3D Systems.  The format is used to save and share surface-rendered 3D images and also for 3D printing.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||Stereolithography format\", \"key\": \"format_1915||format_2350||format_3547||format_3993\"}, \"name\": \"Stereolithography format\", \"uri\": \"http://edamontology.org/format_3993\", \"exact_synonyms\": [\"stl\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"U3D (Universal 3D) is a compressed file format and data structure for 3D computer graphics. It contains 3D model information such as triangle meshes, lighting, shading, motion data, lines and points with color and structure.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||U3D\", \"key\": \"format_1915||format_2350||format_3547||format_3994\"}, \"name\": \"U3D\", \"uri\": \"http://edamontology.org/format_3994\", \"exact_synonyms\": [\"Universal 3D\", \"Universal 3D format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Bitmap image format used for storing textures.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||Texture file format\", \"key\": \"format_1915||format_2350||format_3547||format_3995\"}, \"name\": \"Texture file format\", \"uri\": \"http://edamontology.org/format_3995\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A digital multimedia container format most commonly used to store video and audio.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||MPEG-4\", \"key\": \"format_1915||format_2350||format_3547||format_3997\"}, \"name\": \"MPEG-4\", \"uri\": \"http://edamontology.org/format_3997\", \"exact_synonyms\": [\"MP4\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"An open file format from the Neuroimaging Informatics Technology Initiative (NIfTI) commonly used to store brain imaging data obtained using Magnetic Resonance Imaging (MRI) methods.\", \"path\": {\"name\": \"Format||Format (by type of data)||Image format||NIFTI format\", \"key\": \"format_1915||format_2350||format_3547||format_4001\"}, \"name\": \"NIFTI format\", \"uri\": \"http://edamontology.org/format_4001\", \"exact_synonyms\": [\"NIFTI\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Textual report format for sequence quality for reports from sequencing machines.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Sequence quality report format (text)\", \"key\": \"format_1915||format_2350||format_3606\"}], \"name\": \"Sequence quality report format (text)\", \"uri\": \"http://edamontology.org/format_3606\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"qual\", \"uri\": \"http://edamontology.org/format_3607\"}]}, {\"definition\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences).\", \"path\": {\"name\": \"Format||Format (by type of data)||Sequence quality report format (text)||qual\", \"key\": \"format_1915||format_2350||format_3606||format_3607\"}, \"name\": \"qual\", \"uri\": \"http://edamontology.org/format_3607\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"qualsolexa\", \"uri\": \"http://edamontology.org/format_3608\"}, {\"name\": \"qualillumina\", \"uri\": \"http://edamontology.org/format_3609\"}, {\"name\": \"qualsolid\", \"uri\": \"http://edamontology.org/format_3610\"}, {\"name\": \"qual454\", \"uri\": \"http://edamontology.org/format_3611\"}]}, {\"definition\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) for Solexa/Illumina 1.0 format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Sequence quality report format (text)||qual||qualsolexa\", \"key\": \"format_1915||format_2350||format_3606||format_3607||format_3608\"}, \"name\": \"qualsolexa\", \"uri\": \"http://edamontology.org/format_3608\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) from Illumina 1.5 and before Illumina 1.8.\", \"path\": {\"name\": \"Format||Format (by type of data)||Sequence quality report format (text)||qual||qualillumina\", \"key\": \"format_1915||format_2350||format_3606||format_3607||format_3609\"}, \"name\": \"qualillumina\", \"uri\": \"http://edamontology.org/format_3609\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) for SOLiD data.\", \"path\": {\"name\": \"Format||Format (by type of data)||Sequence quality report format (text)||qual||qualsolid\", \"key\": \"format_1915||format_2350||format_3606||format_3607||format_3610\"}, \"name\": \"qualsolid\", \"uri\": \"http://edamontology.org/format_3610\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) from 454 sequencers.\", \"path\": {\"name\": \"Format||Format (by type of data)||Sequence quality report format (text)||qual||qual454\", \"key\": \"format_1915||format_2350||format_3606||format_3607||format_3611\"}, \"name\": \"qual454\", \"uri\": \"http://edamontology.org/format_3611\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data format for graph data.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Graph format\", \"key\": \"format_1915||format_2350||format_3617\"}], \"name\": \"Graph format\", \"uri\": \"http://edamontology.org/format_3617\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"xgmml\", \"uri\": \"http://edamontology.org/format_3618\"}, {\"name\": \"K-mer countgraph\", \"uri\": \"http://edamontology.org/format_3665\"}]}, {\"definition\": \"XML-based format used to store graph descriptions within Galaxy.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Graph format||xgmml\", \"key\": \"format_1915||format_2350||format_3617||format_3618\"}], \"name\": \"xgmml\", \"uri\": \"http://edamontology.org/format_3618\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A list of k-mers and their occurences in a dataset. Can also be used as an implicit De Bruijn graph.\", \"path\": {\"name\": \"Format||Format (by type of data)||Graph format||K-mer countgraph\", \"key\": \"format_1915||format_2350||format_3617||format_3665\"}, \"name\": \"K-mer countgraph\", \"uri\": \"http://edamontology.org/format_3665\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data format for biodiversity data.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Biodiversity data format\", \"key\": \"format_1915||format_2350||format_3706\"}], \"name\": \"Biodiversity data format\", \"uri\": \"http://edamontology.org/format_3706\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"ABCD format\", \"uri\": \"http://edamontology.org/format_3708\"}, {\"name\": \"BIOM format\", \"uri\": \"http://edamontology.org/format_3746\"}, {\"name\": \"MCPD\", \"uri\": \"http://edamontology.org/format_3777\"}]}, {\"definition\": \"Exchange format of the Access to Biological Collections Data (ABCD) Schema; a standard for the access to and exchange of data about specimens and observations (primary biodiversity data).\", \"path\": [{\"name\": \"Format||Format (by type of data)||Biodiversity data format||ABCD format\", \"key\": \"format_1915||format_2350||format_3706||format_3708\"}], \"name\": \"ABCD format\", \"uri\": \"http://edamontology.org/format_3708\", \"exact_synonyms\": [\"ABCD\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The BIological Observation Matrix (BIOM) is a format for representing biological sample by observation contingency tables in broad areas of comparative omics. The primary use of this format is to represent OTU tables and metagenome tables.\", \"path\": {\"name\": \"Format||Format (by type of data)||Biodiversity data format||BIOM format\", \"key\": \"format_1915||format_2350||format_3706||format_3746\"}, \"name\": \"BIOM format\", \"uri\": \"http://edamontology.org/format_3746\", \"exact_synonyms\": [\"BIological Observation Matrix format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The FAO/Bioversity/IPGRI Multi-Crop Passport Descriptors (MCPD) is an international standard format for exchange of germplasm information.\", \"path\": {\"name\": \"Format||Format (by type of data)||Biodiversity data format||MCPD\", \"key\": \"format_1915||format_2350||format_3706||format_3777\"}, \"name\": \"MCPD\", \"uri\": \"http://edamontology.org/format_3777\", \"exact_synonyms\": [\"Bioversity MCPD\", \"FAO MCPD\", \"MCPD format\", \"Multi-Crop Passport Descriptors\", \"Multi-Crop Passport Descriptors format\"], \"narrow_synonyms\": [\"IPGRI MCPD\", \"MCPD V.1\", \"MCPD V.2\"], \"children\": []}, {\"definition\": \"A linked data format enables publishing structured data as linked data (Linked Data), so that the data can be interlinked and become more useful through semantic queries.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Linked data format\", \"key\": \"format_1915||format_2350||format_3748\"}], \"name\": \"Linked data format\", \"uri\": \"http://edamontology.org/format_3748\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"RDF format\", \"uri\": \"http://edamontology.org/format_2376\"}, {\"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\"}]}, {\"definition\": \"A serialisation format conforming to the Resource Description Framework (RDF) model.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format\", \"key\": \"format_1915||format_2350||format_3748||format_2376\"}, \"name\": \"RDF format\", \"uri\": \"http://edamontology.org/format_2376\", \"exact_synonyms\": [\"Resource Description Framework format\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"OWL format\", \"uri\": \"http://edamontology.org/format_2197\"}, {\"name\": \"Turtle\", \"uri\": \"http://edamontology.org/format_3255\"}, {\"name\": \"N-Triples\", \"uri\": \"http://edamontology.org/format_3256\"}, {\"name\": \"Notation3\", \"uri\": \"http://edamontology.org/format_3257\"}, {\"name\": \"RDF/XML\", \"uri\": \"http://edamontology.org/format_3261\"}, {\"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\"}, {\"name\": \"UniProtKB RDF\", \"uri\": \"http://edamontology.org/format_3771\"}, {\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}, {\"name\": \"N-Quads\", \"uri\": \"http://edamontology.org/format_3956\"}]}, {\"definition\": \"A serialisation format conforming to the Web Ontology Language (OWL) model.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||OWL format\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_2197\"}, \"name\": \"OWL format\", \"uri\": \"http://edamontology.org/format_2197\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"OWL Functional Syntax\", \"uri\": \"http://edamontology.org/format_3252\"}, {\"name\": \"Manchester OWL Syntax\", \"uri\": \"http://edamontology.org/format_3253\"}, {\"name\": \"OWL/XML\", \"uri\": \"http://edamontology.org/format_3262\"}]}, {\"definition\": \"A human-readable encoding for the Web Ontology Language (OWL).\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||OWL format||OWL Functional Syntax\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_2197||format_3252\"}, \"name\": \"OWL Functional Syntax\", \"uri\": \"http://edamontology.org/format_3252\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A syntax for writing OWL class expressions.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||OWL format||Manchester OWL Syntax\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_2197||format_3253\"}, \"name\": \"Manchester OWL Syntax\", \"uri\": \"http://edamontology.org/format_3253\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"OWL ontology XML serialisation format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||OWL format||OWL/XML\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_2197||format_3262\"}, \"name\": \"OWL/XML\", \"uri\": \"http://edamontology.org/format_3262\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"OWL\"], \"children\": []}, {\"definition\": \"The Terse RDF Triple Language (Turtle) is a human-friendly serialisation format for RDF (Resource Description Framework) graphs.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||Turtle\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3255\"}, \"name\": \"Turtle\", \"uri\": \"http://edamontology.org/format_3255\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A plain text serialisation format for RDF (Resource Description Framework) graphs, and a subset of the Turtle (Terse RDF Triple Language) format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||N-Triples\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3256\"}, \"name\": \"N-Triples\", \"uri\": \"http://edamontology.org/format_3256\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A shorthand non-XML serialisation of Resource Description Framework model, designed with human-readability in mind.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||Notation3\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3257\"}, \"name\": \"Notation3\", \"uri\": \"http://edamontology.org/format_3257\", \"exact_synonyms\": [\"N3\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Resource Description Framework (RDF) XML format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||RDF/XML\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3261\"}, \"name\": \"RDF/XML\", \"uri\": \"http://edamontology.org/format_3261\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"JSON-LD, or JavaScript Object Notation for Linked Data, is a method of encoding Linked Data using JSON.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||JSON-LD\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3749\"}, \"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\", \"exact_synonyms\": [\"JavaScript Object Notation for Linked Data\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}]}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||JSON-LD||Open Annotation format\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3749||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"UniProtKB RDF sequence features format is an RDF format available for downloading UniProt entries (in RDF/XML).\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||UniProtKB RDF\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3771\"}, \"name\": \"UniProtKB RDF\", \"uri\": \"http://edamontology.org/format_3771\", \"exact_synonyms\": [\"UniProt RDF\", \"UniProt RDF format\", \"UniProtKB RDF format\"], \"narrow_synonyms\": [\"UniProt RDF/XML\", \"UniProt RDF/XML format\", \"UniProtKB RDF/XML\", \"UniProtKB RDF/XML format\"], \"children\": []}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||Open Annotation format\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"N-Quads is a line-based, plain text format for encoding an RDF dataset. It includes information about the graph each triple belongs to.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||N-Quads\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3956\"}, \"name\": \"N-Quads\", \"uri\": \"http://edamontology.org/format_3956\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"JSON-LD, or JavaScript Object Notation for Linked Data, is a method of encoding Linked Data using JSON.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||JSON-LD\", \"key\": \"format_1915||format_2350||format_3748||format_3749\"}, \"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\", \"exact_synonyms\": [\"JavaScript Object Notation for Linked Data\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}]}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||Format (by type of data)||Linked data format||JSON-LD||Open Annotation format\", \"key\": \"format_1915||format_2350||format_3748||format_3749||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data format of an annotated text, e.g. with recognised entities, concepts, and relations.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Annotated text format\", \"key\": \"format_1915||format_2350||format_3780\"}], \"name\": \"Annotated text format\", \"uri\": \"http://edamontology.org/format_3780\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"OSCAR format\", \"uri\": \"http://edamontology.org/format_1741\"}, {\"name\": \"PubAnnotation format\", \"uri\": \"http://edamontology.org/format_3781\"}, {\"name\": \"BioC\", \"uri\": \"http://edamontology.org/format_3782\"}, {\"name\": \"PubTator format\", \"uri\": \"http://edamontology.org/format_3783\"}, {\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}, {\"name\": \"BioNLP Shared Task format\", \"uri\": \"http://edamontology.org/format_3785\"}]}, {\"definition\": \"OSCAR format of annotated chemical text.\", \"path\": {\"name\": \"Format||Format (by type of data)||Annotated text format||OSCAR format\", \"key\": \"format_1915||format_2350||format_3780||format_1741\"}, \"name\": \"OSCAR format\", \"uri\": \"http://edamontology.org/format_1741\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"JSON format of annotated scientific text used by PubAnnotations and other tools.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Annotated text format||PubAnnotation format\", \"key\": \"format_1915||format_2350||format_3780||format_3781\"}, {\"name\": \"Format||JSON||PubAnnotation format\", \"key\": \"format_1915||format_3464||format_3781\"}, {\"name\": \"Format||YAML||JSON||PubAnnotation format\", \"key\": \"format_1915||format_3750||format_3464||format_3781\"}], \"name\": \"PubAnnotation format\", \"uri\": \"http://edamontology.org/format_3781\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"BioC is a standardised XML format for sharing and integrating text data and annotations.\", \"path\": {\"name\": \"Format||Format (by type of data)||Annotated text format||BioC\", \"key\": \"format_1915||format_2350||format_3780||format_3782\"}, \"name\": \"BioC\", \"uri\": \"http://edamontology.org/format_3782\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Native textual export format of annotated scientific text from PubTator.\", \"path\": {\"name\": \"Format||Format (by type of data)||Annotated text format||PubTator format\", \"key\": \"format_1915||format_2350||format_3780||format_3783\"}, \"name\": \"PubTator format\", \"uri\": \"http://edamontology.org/format_3783\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||Format (by type of data)||Annotated text format||Open Annotation format\", \"key\": \"format_1915||format_2350||format_3780||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A family of similar formats of text annotation, used by BRAT and other tools, known as BioNLP Shared Task format (BioNLP 2009 Shared Task on Event Extraction, BioNLP Shared Task 2011, BioNLP Shared Task 2013), BRAT format, BRAT standoff format, and similar.\", \"path\": {\"name\": \"Format||Format (by type of data)||Annotated text format||BioNLP Shared Task format\", \"key\": \"format_1915||format_2350||format_3780||format_3785\"}, \"name\": \"BioNLP Shared Task format\", \"uri\": \"http://edamontology.org/format_3785\", \"exact_synonyms\": [\"BRAT format\", \"BRAT standoff format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A query language (format) for structured database queries.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Query language\", \"key\": \"format_1915||format_2350||format_3787\"}], \"name\": \"Query language\", \"uri\": \"http://edamontology.org/format_3787\", \"exact_synonyms\": [\"Query format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data format for raw data from a nuclear magnetic resonance (NMR) spectroscopy experiment.\", \"path\": [{\"name\": \"Format||Format (by type of data)||NMR data format\", \"key\": \"format_1915||format_2350||format_3824\"}], \"name\": \"NMR data format\", \"uri\": \"http://edamontology.org/format_3824\", \"exact_synonyms\": [\"Nuclear magnetic resonance spectroscopy data format\"], \"narrow_synonyms\": [\"NMR peak assignment data\", \"NMR processed data format\", \"NMR raw data format\", \"Processed NMR data format\", \"Raw NMR data format\"], \"children\": [{\"name\": \"nmrML\", \"uri\": \"http://edamontology.org/format_3825\"}, {\"name\": \"NMReDATA\", \"uri\": \"http://edamontology.org/format_3906\"}]}, {\"definition\": \"nmrML is an MSI supported XML-based open access format for metabolomics NMR raw and processed spectral data. It is accompanies by an nmrCV (controlled vocabulary) to allow ontology-based annotations.\", \"path\": {\"name\": \"Format||Format (by type of data)||NMR data format||nmrML\", \"key\": \"format_1915||format_2350||format_3824||format_3825\"}, \"name\": \"nmrML\", \"uri\": \"http://edamontology.org/format_3825\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"MReData is a text based data standard for processed NMR data. It is relying on SDF molecule data and allows to store assignments of NMR peaks to molecule features.  The NMR-extracted data (or \\\"NMReDATA\\\") includes: Chemical shift,scalar coupling, 2D correlation, assignment, etc.\", \"path\": {\"name\": \"Format||Format (by type of data)||NMR data format||NMReDATA\", \"key\": \"format_1915||format_2350||format_3824||format_3906\"}, \"name\": \"NMReDATA\", \"uri\": \"http://edamontology.org/format_3906\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data format for raw microarray data.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Raw microarray data format\", \"key\": \"format_1915||format_2350||format_3828\"}], \"name\": \"Raw microarray data format\", \"uri\": \"http://edamontology.org/format_3828\", \"exact_synonyms\": [\"Microarray data format\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"GPR\", \"uri\": \"http://edamontology.org/format_3829\"}]}, {\"definition\": \"GenePix Results (GPR) text file format developed by Axon Instruments that is used to save GenePix Results data.\", \"path\": {\"name\": \"Format||Format (by type of data)||Raw microarray data format||GPR\", \"key\": \"format_1915||format_2350||format_3828||format_3829\"}, \"name\": \"GPR\", \"uri\": \"http://edamontology.org/format_3829\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Data format used in Natural Language Processing.\", \"path\": [{\"name\": \"Format||Format (by type of data)||NLP format\", \"key\": \"format_1915||format_2350||format_3841\"}], \"name\": \"NLP format\", \"uri\": \"http://edamontology.org/format_3841\", \"exact_synonyms\": [\"Natural Language Processing format\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"NLP annotation format\", \"uri\": \"http://edamontology.org/format_3862\"}]}, {\"definition\": \"An NLP format used for annotated textual documents.\", \"path\": [{\"name\": \"Format||Format (by type of data)||NLP format||NLP annotation format\", \"key\": \"format_1915||format_2350||format_3841||format_3862\"}], \"name\": \"NLP annotation format\", \"uri\": \"http://edamontology.org/format_3862\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"NLP corpus format\", \"uri\": \"http://edamontology.org/format_3863\"}]}, {\"definition\": \"NLP format used by a specific type of corpus (collection of texts).\", \"path\": [{\"name\": \"Format||Format (by type of data)||NLP format||NLP annotation format||NLP corpus format\", \"key\": \"format_1915||format_2350||format_3841||format_3862||format_3863\"}], \"name\": \"NLP corpus format\", \"uri\": \"http://edamontology.org/format_3863\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A \\\"placeholder\\\" concept for formats of annotated RNA data, including e.g. microRNA and RNA-Seq data.\", \"path\": [{\"name\": \"Format||Format (by type of data)||RNA annotation format\", \"key\": \"format_1915||format_2350||format_3865\"}], \"name\": \"RNA annotation format\", \"uri\": \"http://edamontology.org/format_3865\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"miRNA data format\", \"microRNA data format\"], \"children\": [{\"name\": \"mirGFF3\", \"uri\": \"http://edamontology.org/format_3864\"}]}, {\"definition\": \"mirGFF3 is a common format for microRNA data resulting from small-RNA RNA-Seq workflows.\", \"path\": {\"name\": \"Format||Format (by type of data)||RNA annotation format||mirGFF3\", \"key\": \"format_1915||format_2350||format_3865||format_3864\"}, \"name\": \"mirGFF3\", \"uri\": \"http://edamontology.org/format_3864\", \"exact_synonyms\": [\"miRTop format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"File format to store trajectory information for a 3D structure .\", \"path\": [{\"name\": \"Format||Format (by type of data)||Trajectory format\", \"key\": \"format_1915||format_2350||format_3866\"}], \"name\": \"Trajectory format\", \"uri\": \"http://edamontology.org/format_3866\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"CG trajectory formats\", \"MD trajectory formats\", \"NA trajectory formats\", \"Protein trajectory formats\"], \"children\": [{\"name\": \"Trajectory format (binary)\", \"uri\": \"http://edamontology.org/format_3867\"}, {\"name\": \"Trajectory format (text)\", \"uri\": \"http://edamontology.org/format_3868\"}]}, {\"definition\": \"Binary file format to store trajectory information for a 3D structure .\", \"path\": [{\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)\", \"key\": \"format_1915||format_2350||format_3866||format_3867\"}], \"name\": \"Trajectory format (binary)\", \"uri\": \"http://edamontology.org/format_3867\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"HDF5\", \"uri\": \"http://edamontology.org/format_3590\"}, {\"name\": \"netCDF\", \"uri\": \"http://edamontology.org/format_3650\"}, {\"name\": \"HDF\", \"uri\": \"http://edamontology.org/format_3873\"}, {\"name\": \"PCAzip\", \"uri\": \"http://edamontology.org/format_3874\"}, {\"name\": \"XTC\", \"uri\": \"http://edamontology.org/format_3875\"}, {\"name\": \"TNG\", \"uri\": \"http://edamontology.org/format_3876\"}, {\"name\": \"BinPos\", \"uri\": \"http://edamontology.org/format_3885\"}]}, {\"definition\": \"HDF5 is a data model, library, and file format for storing and managing data, based on Hierarchical Data Format (HDF).\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||HDF5\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3590\"}, \"name\": \"HDF5\", \"uri\": \"http://edamontology.org/format_3590\", \"exact_synonyms\": [\"h5\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Loom\", \"uri\": \"http://edamontology.org/format_3913\"}]}, {\"definition\": \"The Loom file format is based on HDF5, a standard for storing large numerical datasets. The Loom format is designed to efficiently hold large omics datasets. Typically, such data takes the form of a large matrix of numbers, along with metadata for the rows and columns.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||HDF5||Loom\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3590||format_3913\"}, \"name\": \"Loom\", \"uri\": \"http://edamontology.org/format_3913\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format used by netCDF software  library for writing and reading chromatography-MS data files.  Also used to store trajectory atom coordinates information, such as the ones obtained by Molecular Dynamics simulations.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||netCDF\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3650\"}, \"name\": \"netCDF\", \"uri\": \"http://edamontology.org/format_3650\", \"exact_synonyms\": [\"ANDI-MS\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"HDF is the name of a set of file formats and libraries designed to store and organize large amounts of numerical data, originally developed at the National Center for Supercomputing Applications at the University of Illinois.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||HDF\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3873\"}, \"name\": \"HDF\", \"uri\": \"http://edamontology.org/format_3873\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"PCAZip format is a binary compressed file to store atom coordinates based on Essential Dynamics (ED) and Principal Component Analysis (PCA).\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||PCAzip\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3874\"}, \"name\": \"PCAzip\", \"uri\": \"http://edamontology.org/format_3874\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Portable binary format for trajectories produced by GROMACS package.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||XTC\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3875\"}, \"name\": \"XTC\", \"uri\": \"http://edamontology.org/format_3875\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Trajectory Next Generation (TNG) is a format for storage of molecular simulation data. It is designed and implemented by the GROMACS development group, and it is called to be the substitute of the XTC format.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||TNG\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3876\"}, \"name\": \"TNG\", \"uri\": \"http://edamontology.org/format_3876\", \"exact_synonyms\": [\"Trajectory Next Generation format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Scripps Research Institute BinPos format is a binary formatted file to store atom coordinates.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||BinPos\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3885\"}, \"name\": \"BinPos\", \"uri\": \"http://edamontology.org/format_3885\", \"exact_synonyms\": [\"Scripps Research Institute BinPos\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Textual file format to store trajectory information for a 3D structure .\", \"path\": [{\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (text)\", \"key\": \"format_1915||format_2350||format_3866||format_3868\"}], \"name\": \"Trajectory format (text)\", \"uri\": \"http://edamontology.org/format_3868\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"XYZ\", \"uri\": \"http://edamontology.org/format_3877\"}, {\"name\": \"mdcrd\", \"uri\": \"http://edamontology.org/format_3878\"}, {\"name\": \"RST\", \"uri\": \"http://edamontology.org/format_3886\"}, {\"name\": \"trr\", \"uri\": \"http://edamontology.org/format_3910\"}]}, {\"definition\": \"The XYZ chemical file format is widely supported by many programs, although many slightly different XYZ file formats coexist (Tinker XYZ, UniChem XYZ, etc.). Basic information stored for each atom in the system are x, y and z coordinates and atom element/atomic number.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (text)||XYZ\", \"key\": \"format_1915||format_2350||format_3866||format_3868||format_3877\"}, \"name\": \"XYZ\", \"uri\": \"http://edamontology.org/format_3877\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"AMBER trajectory (also called mdcrd), with 10 coordinates per line and format F8.3 (fixed point notation with field width 8 and 3 decimal places).\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (text)||mdcrd\", \"key\": \"format_1915||format_2350||format_3866||format_3868||format_3878\"}, \"name\": \"mdcrd\", \"uri\": \"http://edamontology.org/format_3878\", \"exact_synonyms\": [\"AMBER trajectory format\", \"inpcrd\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"AMBER coordinate/restart file with 6 coordinates per line and decimal format F12.7 (fixed point notation with field width 12 and 7 decimal places)\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (text)||RST\", \"key\": \"format_1915||format_2350||format_3866||format_3868||format_3886\"}, \"name\": \"RST\", \"uri\": \"http://edamontology.org/format_3886\", \"exact_synonyms\": [\"restrt\", \"rst7\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format of trr files that contain the trajectory of a simulation experiment used by GROMACS.\", \"path\": {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (text)||trr\", \"key\": \"format_1915||format_2350||format_3866||format_3868||format_3910\"}, \"name\": \"trr\", \"uri\": \"http://edamontology.org/format_3910\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format of topology files; containing the static information of a structure molecular system that is needed for a molecular simulation.\", \"path\": [{\"name\": \"Format||Format (by type of data)||Topology format\", \"key\": \"format_1915||format_2350||format_3879\"}], \"name\": \"Topology format\", \"uri\": \"http://edamontology.org/format_3879\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"CG topology format\", \"MD topology format\", \"NA topology format\", \"Protein topology format\"], \"children\": [{\"name\": \"GROMACS top\", \"uri\": \"http://edamontology.org/format_3880\"}, {\"name\": \"AMBER top\", \"uri\": \"http://edamontology.org/format_3881\"}, {\"name\": \"PSF\", \"uri\": \"http://edamontology.org/format_3882\"}, {\"name\": \"GROMACS itp\", \"uri\": \"http://edamontology.org/format_3883\"}, {\"name\": \"CHARMM rtf\", \"uri\": \"http://edamontology.org/format_3887\"}]}, {\"definition\": \"GROMACS MD package top textual files define an entire structure system topology, either directly, or by including itp files.\", \"path\": {\"name\": \"Format||Format (by type of data)||Topology format||GROMACS top\", \"key\": \"format_1915||format_2350||format_3879||format_3880\"}, \"name\": \"GROMACS top\", \"uri\": \"http://edamontology.org/format_3880\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"AMBER Prmtop file (version 7) is a structure topology text file divided in several sections designed to be parsed easily using simple Fortran code. Each section contains particular topology information, such as atom name, charge, mass, angles, dihedrals, etc.\", \"path\": {\"name\": \"Format||Format (by type of data)||Topology format||AMBER top\", \"key\": \"format_1915||format_2350||format_3879||format_3881\"}, \"name\": \"AMBER top\", \"uri\": \"http://edamontology.org/format_3881\", \"exact_synonyms\": [\"AMBER Parm\", \"AMBER Parm7\", \"Parm7\", \"Prmtop\", \"Prmtop7\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"X-Plor Protein Structure Files (PSF) are structure topology files used by NAMD and CHARMM molecular simulations programs. PSF files contain six main sections of interest: atoms, bonds, angles, dihedrals, improper dihedrals (force terms used to maintain planarity) and cross-terms.\", \"path\": {\"name\": \"Format||Format (by type of data)||Topology format||PSF\", \"key\": \"format_1915||format_2350||format_3879||format_3882\"}, \"name\": \"PSF\", \"uri\": \"http://edamontology.org/format_3882\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"GROMACS itp files (include topology) contain structure topology information, and are tipically included in GROMACS topology files (GROMACS top). Itp files are used to define individual (or multiple) components of a topology as a separate file. This is particularly useful if there is a molecule that is used frequently, and also reduces the size of the system topology file, splitting it in different parts.\", \"path\": {\"name\": \"Format||Format (by type of data)||Topology format||GROMACS itp\", \"key\": \"format_1915||format_2350||format_3879||format_3883\"}, \"name\": \"GROMACS itp\", \"uri\": \"http://edamontology.org/format_3883\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format of CHARMM Residue Topology Files (RTF), which define groups by including the atoms, the properties of the group, and bond and charge information.\", \"path\": {\"name\": \"Format||Format (by type of data)||Topology format||CHARMM rtf\", \"key\": \"format_1915||format_2350||format_3879||format_3887\"}, \"name\": \"CHARMM rtf\", \"uri\": \"http://edamontology.org/format_3887\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Format of force field parameter files, which store the set of parameters (charges, masses, radii, bond lengths, bond dihedrals, etc.) that are essential for the proper description and simulation of a molecular system.\", \"path\": [{\"name\": \"Format||Format (by type of data)||FF parameter format\", \"key\": \"format_1915||format_2350||format_3884\"}], \"name\": \"FF parameter format\", \"uri\": \"http://edamontology.org/format_3884\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"GROMACS itp\", \"uri\": \"http://edamontology.org/format_3883\"}, {\"name\": \"AMBER frcmod\", \"uri\": \"http://edamontology.org/format_3888\"}, {\"name\": \"AMBER off\", \"uri\": \"http://edamontology.org/format_3889\"}]}, {\"definition\": \"GROMACS itp files (include topology) contain structure topology information, and are tipically included in GROMACS topology files (GROMACS top). Itp files are used to define individual (or multiple) components of a topology as a separate file. This is particularly useful if there is a molecule that is used frequently, and also reduces the size of the system topology file, splitting it in different parts.\", \"path\": {\"name\": \"Format||Format (by type of data)||FF parameter format||GROMACS itp\", \"key\": \"format_1915||format_2350||format_3884||format_3883\"}, \"name\": \"GROMACS itp\", \"uri\": \"http://edamontology.org/format_3883\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"AMBER frcmod (Force field Modification) is a file format to store any modification to the standard force field needed for a particular molecule to be properly represented in the simulation.\", \"path\": {\"name\": \"Format||Format (by type of data)||FF parameter format||AMBER frcmod\", \"key\": \"format_1915||format_2350||format_3884||format_3888\"}, \"name\": \"AMBER frcmod\", \"uri\": \"http://edamontology.org/format_3888\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"AMBER Object File Format library files (OFF library files) store residue libraries (forcefield residue parameters).\", \"path\": {\"name\": \"Format||Format (by type of data)||FF parameter format||AMBER off\", \"key\": \"format_1915||format_2350||format_3884||format_3889\"}, \"name\": \"AMBER off\", \"uri\": \"http://edamontology.org/format_3889\", \"exact_synonyms\": [\"AMBER Object File Format\", \"AMBER lib\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A serialisation format conforming to the Resource Description Framework (RDF) model.\", \"path\": {\"name\": \"Format||RDF format\", \"key\": \"format_1915||format_2376\"}, \"name\": \"RDF format\", \"uri\": \"http://edamontology.org/format_2376\", \"exact_synonyms\": [\"Resource Description Framework format\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"OWL format\", \"uri\": \"http://edamontology.org/format_2197\"}, {\"name\": \"Turtle\", \"uri\": \"http://edamontology.org/format_3255\"}, {\"name\": \"N-Triples\", \"uri\": \"http://edamontology.org/format_3256\"}, {\"name\": \"Notation3\", \"uri\": \"http://edamontology.org/format_3257\"}, {\"name\": \"RDF/XML\", \"uri\": \"http://edamontology.org/format_3261\"}, {\"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\"}, {\"name\": \"UniProtKB RDF\", \"uri\": \"http://edamontology.org/format_3771\"}, {\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}, {\"name\": \"N-Quads\", \"uri\": \"http://edamontology.org/format_3956\"}]}, {\"definition\": \"A serialisation format conforming to the Web Ontology Language (OWL) model.\", \"path\": {\"name\": \"Format||RDF format||OWL format\", \"key\": \"format_1915||format_2376||format_2197\"}, \"name\": \"OWL format\", \"uri\": \"http://edamontology.org/format_2197\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": [{\"name\": \"OWL Functional Syntax\", \"uri\": \"http://edamontology.org/format_3252\"}, {\"name\": \"Manchester OWL Syntax\", \"uri\": \"http://edamontology.org/format_3253\"}, {\"name\": \"OWL/XML\", \"uri\": \"http://edamontology.org/format_3262\"}]}, {\"definition\": \"A human-readable encoding for the Web Ontology Language (OWL).\", \"path\": {\"name\": \"Format||RDF format||OWL format||OWL Functional Syntax\", \"key\": \"format_1915||format_2376||format_2197||format_3252\"}, \"name\": \"OWL Functional Syntax\", \"uri\": \"http://edamontology.org/format_3252\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A syntax for writing OWL class expressions.\", \"path\": {\"name\": \"Format||RDF format||OWL format||Manchester OWL Syntax\", \"key\": \"format_1915||format_2376||format_2197||format_3253\"}, \"name\": \"Manchester OWL Syntax\", \"uri\": \"http://edamontology.org/format_3253\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"OWL ontology XML serialisation format.\", \"path\": {\"name\": \"Format||RDF format||OWL format||OWL/XML\", \"key\": \"format_1915||format_2376||format_2197||format_3262\"}, \"name\": \"OWL/XML\", \"uri\": \"http://edamontology.org/format_3262\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"OWL\"], \"children\": []}, {\"definition\": \"The Terse RDF Triple Language (Turtle) is a human-friendly serialisation format for RDF (Resource Description Framework) graphs.\", \"path\": {\"name\": \"Format||RDF format||Turtle\", \"key\": \"format_1915||format_2376||format_3255\"}, \"name\": \"Turtle\", \"uri\": \"http://edamontology.org/format_3255\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A plain text serialisation format for RDF (Resource Description Framework) graphs, and a subset of the Turtle (Terse RDF Triple Language) format.\", \"path\": {\"name\": \"Format||RDF format||N-Triples\", \"key\": \"format_1915||format_2376||format_3256\"}, \"name\": \"N-Triples\", \"uri\": \"http://edamontology.org/format_3256\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A shorthand non-XML serialisation of Resource Description Framework model, designed with human-readability in mind.\", \"path\": {\"name\": \"Format||RDF format||Notation3\", \"key\": \"format_1915||format_2376||format_3257\"}, \"name\": \"Notation3\", \"uri\": \"http://edamontology.org/format_3257\", \"exact_synonyms\": [\"N3\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Resource Description Framework (RDF) XML format.\", \"path\": {\"name\": \"Format||RDF format||RDF/XML\", \"key\": \"format_1915||format_2376||format_3261\"}, \"name\": \"RDF/XML\", \"uri\": \"http://edamontology.org/format_3261\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"JSON-LD, or JavaScript Object Notation for Linked Data, is a method of encoding Linked Data using JSON.\", \"path\": {\"name\": \"Format||RDF format||JSON-LD\", \"key\": \"format_1915||format_2376||format_3749\"}, \"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\", \"exact_synonyms\": [\"JavaScript Object Notation for Linked Data\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}]}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||RDF format||JSON-LD||Open Annotation format\", \"key\": \"format_1915||format_2376||format_3749||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"UniProtKB RDF sequence features format is an RDF format available for downloading UniProt entries (in RDF/XML).\", \"path\": {\"name\": \"Format||RDF format||UniProtKB RDF\", \"key\": \"format_1915||format_2376||format_3771\"}, \"name\": \"UniProtKB RDF\", \"uri\": \"http://edamontology.org/format_3771\", \"exact_synonyms\": [\"UniProt RDF\", \"UniProt RDF format\", \"UniProtKB RDF format\"], \"narrow_synonyms\": [\"UniProt RDF/XML\", \"UniProt RDF/XML format\", \"UniProtKB RDF/XML\", \"UniProtKB RDF/XML format\"], \"children\": []}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||RDF format||Open Annotation format\", \"key\": \"format_1915||format_2376||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"N-Quads is a line-based, plain text format for encoding an RDF dataset. It includes information about the graph each triple belongs to.\", \"path\": {\"name\": \"Format||RDF format||N-Quads\", \"key\": \"format_1915||format_2376||format_3956\"}, \"name\": \"N-Quads\", \"uri\": \"http://edamontology.org/format_3956\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"JavaScript Object Notation format; a lightweight, text-based format to represent tree-structured data using key-value pairs.\", \"path\": [{\"name\": \"Format||JSON\", \"key\": \"format_1915||format_3464\"}, {\"name\": \"Format||YAML||JSON\", \"key\": \"format_1915||format_3750||format_3464\"}], \"name\": \"JSON\", \"uri\": \"http://edamontology.org/format_3464\", \"exact_synonyms\": [\"JavaScript Object Notation\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\"}, {\"name\": \"BioJSON (BioXSD)\", \"uri\": \"http://edamontology.org/format_3772\"}, {\"name\": \"BioJSON (Jalview)\", \"uri\": \"http://edamontology.org/format_3774\"}, {\"name\": \"PubAnnotation format\", \"uri\": \"http://edamontology.org/format_3781\"}, {\"name\": \"Vega\", \"uri\": \"http://edamontology.org/format_3969\"}, {\"name\": \"Vega-lite\", \"uri\": \"http://edamontology.org/format_3970\"}]}, {\"definition\": \"JSON-LD, or JavaScript Object Notation for Linked Data, is a method of encoding Linked Data using JSON.\", \"path\": {\"name\": \"Format||JSON||JSON-LD\", \"key\": \"format_1915||format_3464||format_3749\"}, \"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\", \"exact_synonyms\": [\"JavaScript Object Notation for Linked Data\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}]}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||JSON||JSON-LD||Open Annotation format\", \"key\": \"format_1915||format_3464||format_3749||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"BioJSON is a BioXSD-schema-based JSON format of sequence-based data and some other common data - sequence records, alignments, feature records, references to resources, and more - optimised for integrative bioinformatics, web applications and APIs, and object-oriented programming.\", \"path\": {\"name\": \"Format||JSON||BioJSON (BioXSD)\", \"key\": \"format_1915||format_3464||format_3772\"}, \"name\": \"BioJSON (BioXSD)\", \"uri\": \"http://edamontology.org/format_3772\", \"exact_synonyms\": [\"BioJSON (BioXSD data model)\", \"BioJSON format (BioXSD)\", \"BioXSD BioJSON\", \"BioXSD BioJSON format\", \"BioXSD JSON\", \"BioXSD JSON format\", \"BioXSD in JSON\", \"BioXSD in JSON format\", \"BioXSD+JSON\", \"BioXSD/GTrack BioJSON\", \"BioXSD|BioJSON|BioYAML BioJSON\", \"BioXSD|GTrack BioJSON\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"BioJSON is a JSON format of single multiple sequence alignments, with their annotations, features, and custom visualisation and application settings for the Jalview workbench.\", \"path\": {\"name\": \"Format||JSON||BioJSON (Jalview)\", \"key\": \"format_1915||format_3464||format_3774\"}, \"name\": \"BioJSON (Jalview)\", \"uri\": \"http://edamontology.org/format_3774\", \"exact_synonyms\": [\"BioJSON format (Jalview)\", \"JSON (Jalview)\", \"JSON format (Jalview)\", \"Jalview BioJSON\", \"Jalview BioJSON format\", \"Jalview JSON\", \"Jalview JSON format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"JSON format of annotated scientific text used by PubAnnotations and other tools.\", \"path\": {\"name\": \"Format||JSON||PubAnnotation format\", \"key\": \"format_1915||format_3464||format_3781\"}, \"name\": \"PubAnnotation format\", \"uri\": \"http://edamontology.org/format_3781\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Vega is a visualization grammar, a declarative language for creating, saving, and sharing interactive visualization designs. With Vega, you can describe the visual appearance and interactive behavior of a visualization in a JSON format, and generate web-based views using Canvas or SVG.\", \"path\": {\"name\": \"Format||JSON||Vega\", \"key\": \"format_1915||format_3464||format_3969\"}, \"name\": \"Vega\", \"uri\": \"http://edamontology.org/format_3969\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Vega-Lite is a high-level grammar of interactive graphics. It provides a concise JSON syntax for rapidly generating visualizations to support analysis. Vega-Lite specifications can be compiled to Vega specifications.\", \"path\": {\"name\": \"Format||JSON||Vega-lite\", \"key\": \"format_1915||format_3464||format_3970\"}, \"name\": \"Vega-lite\", \"uri\": \"http://edamontology.org/format_3970\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"YAML (YAML Ain\'t Markup Language) is a human-readable tree-structured data serialisation language.\", \"path\": [{\"name\": \"Format||YAML\", \"key\": \"format_1915||format_3750\"}], \"name\": \"YAML\", \"uri\": \"http://edamontology.org/format_3750\", \"exact_synonyms\": [\"YAML Ain\'t Markup Language\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"JSON\", \"uri\": \"http://edamontology.org/format_3464\"}, {\"name\": \"BioYAML\", \"uri\": \"http://edamontology.org/format_3773\"}, {\"name\": \"CWL\", \"uri\": \"http://edamontology.org/format_3857\"}]}, {\"definition\": \"JavaScript Object Notation format; a lightweight, text-based format to represent tree-structured data using key-value pairs.\", \"path\": {\"name\": \"Format||YAML||JSON\", \"key\": \"format_1915||format_3750||format_3464\"}, \"name\": \"JSON\", \"uri\": \"http://edamontology.org/format_3464\", \"exact_synonyms\": [\"JavaScript Object Notation\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\"}, {\"name\": \"BioJSON (BioXSD)\", \"uri\": \"http://edamontology.org/format_3772\"}, {\"name\": \"BioJSON (Jalview)\", \"uri\": \"http://edamontology.org/format_3774\"}, {\"name\": \"PubAnnotation format\", \"uri\": \"http://edamontology.org/format_3781\"}, {\"name\": \"Vega\", \"uri\": \"http://edamontology.org/format_3969\"}, {\"name\": \"Vega-lite\", \"uri\": \"http://edamontology.org/format_3970\"}]}, {\"definition\": \"JSON-LD, or JavaScript Object Notation for Linked Data, is a method of encoding Linked Data using JSON.\", \"path\": {\"name\": \"Format||YAML||JSON||JSON-LD\", \"key\": \"format_1915||format_3750||format_3464||format_3749\"}, \"name\": \"JSON-LD\", \"uri\": \"http://edamontology.org/format_3749\", \"exact_synonyms\": [\"JavaScript Object Notation for Linked Data\"], \"narrow_synonyms\": [], \"children\": [{\"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\"}]}, {\"definition\": \"A format of text annotation using the linked-data Open Annotation Data Model, serialised typically in RDF or JSON-LD.\", \"path\": {\"name\": \"Format||YAML||JSON||JSON-LD||Open Annotation format\", \"key\": \"format_1915||format_3750||format_3464||format_3749||format_3784\"}, \"name\": \"Open Annotation format\", \"uri\": \"http://edamontology.org/format_3784\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"BioJSON is a BioXSD-schema-based JSON format of sequence-based data and some other common data - sequence records, alignments, feature records, references to resources, and more - optimised for integrative bioinformatics, web applications and APIs, and object-oriented programming.\", \"path\": {\"name\": \"Format||YAML||JSON||BioJSON (BioXSD)\", \"key\": \"format_1915||format_3750||format_3464||format_3772\"}, \"name\": \"BioJSON (BioXSD)\", \"uri\": \"http://edamontology.org/format_3772\", \"exact_synonyms\": [\"BioJSON (BioXSD data model)\", \"BioJSON format (BioXSD)\", \"BioXSD BioJSON\", \"BioXSD BioJSON format\", \"BioXSD JSON\", \"BioXSD JSON format\", \"BioXSD in JSON\", \"BioXSD in JSON format\", \"BioXSD+JSON\", \"BioXSD/GTrack BioJSON\", \"BioXSD|BioJSON|BioYAML BioJSON\", \"BioXSD|GTrack BioJSON\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"BioJSON is a JSON format of single multiple sequence alignments, with their annotations, features, and custom visualisation and application settings for the Jalview workbench.\", \"path\": {\"name\": \"Format||YAML||JSON||BioJSON (Jalview)\", \"key\": \"format_1915||format_3750||format_3464||format_3774\"}, \"name\": \"BioJSON (Jalview)\", \"uri\": \"http://edamontology.org/format_3774\", \"exact_synonyms\": [\"BioJSON format (Jalview)\", \"JSON (Jalview)\", \"JSON format (Jalview)\", \"Jalview BioJSON\", \"Jalview BioJSON format\", \"Jalview JSON\", \"Jalview JSON format\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"JSON format of annotated scientific text used by PubAnnotations and other tools.\", \"path\": {\"name\": \"Format||YAML||JSON||PubAnnotation format\", \"key\": \"format_1915||format_3750||format_3464||format_3781\"}, \"name\": \"PubAnnotation format\", \"uri\": \"http://edamontology.org/format_3781\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Vega is a visualization grammar, a declarative language for creating, saving, and sharing interactive visualization designs. With Vega, you can describe the visual appearance and interactive behavior of a visualization in a JSON format, and generate web-based views using Canvas or SVG.\", \"path\": {\"name\": \"Format||YAML||JSON||Vega\", \"key\": \"format_1915||format_3750||format_3464||format_3969\"}, \"name\": \"Vega\", \"uri\": \"http://edamontology.org/format_3969\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Vega-Lite is a high-level grammar of interactive graphics. It provides a concise JSON syntax for rapidly generating visualizations to support analysis. Vega-Lite specifications can be compiled to Vega specifications.\", \"path\": {\"name\": \"Format||YAML||JSON||Vega-lite\", \"key\": \"format_1915||format_3750||format_3464||format_3970\"}, \"name\": \"Vega-lite\", \"uri\": \"http://edamontology.org/format_3970\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"BioYAML is a BioXSD-schema-based YAML format of sequence-based data and some other common data - sequence records, alignments, feature records, references to resources, and more - optimised for integrative bioinformatics, web APIs, human readability and editting, and object-oriented programming.\", \"path\": {\"name\": \"Format||YAML||BioYAML\", \"key\": \"format_1915||format_3750||format_3773\"}, \"name\": \"BioYAML\", \"uri\": \"http://edamontology.org/format_3773\", \"exact_synonyms\": [\"BioXSD BioYAML\", \"BioXSD BioYAML format\", \"BioXSD YAML\", \"BioXSD YAML format\", \"BioXSD in YAML\", \"BioXSD in YAML format\", \"BioXSD+YAML\", \"BioXSD/GTrack BioYAML\", \"BioXSD|BioJSON|BioYAML BioYAML\", \"BioXSD|GTrack BioYAML\", \"BioYAML (BioXSD data model)\", \"BioYAML (BioXSD)\", \"BioYAML format\", \"BioYAML format (BioXSD)\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Common Workflow Language (CWL) format for description of command-line tools and workflows.\", \"path\": {\"name\": \"Format||YAML||CWL\", \"key\": \"format_1915||format_3750||format_3857\"}, \"name\": \"CWL\", \"uri\": \"http://edamontology.org/format_3857\", \"exact_synonyms\": [\"Common Workflow Language\", \"CommonWL\"], \"narrow_synonyms\": [], \"children\": []}]','2025-08-27 12:52:46.750573');
INSERT INTO `elixir_ontology` VALUES (41,'index_EDAM_Format','{\"format_1915\": {\"definition\": \"A defined way or layout of representing and structuring data in a computer file, blob, string, message, or elsewhere. The main focus in EDAM lies on formats as means of structuring data exchanged between different tools or resources. The serialisation, compression, or encoding of concrete data formats/models is not in scope of EDAM. Format \'is format of\' Data.\", \"path\": [{\"name\": \"Format\", \"key\": \"format_1915\"}], \"name\": \"Format\", \"uri\": \"http://edamontology.org/format_1915\", \"exact_synonyms\": [\"Exchange format\", \"Data format\"], \"narrow_synonyms\": [\"File format\"], \"children\": [{\"name\": \"Textual format\", \"uri\": \"http://edamontology.org/format_2330\"}, {\"name\": \"HTML\", \"uri\": \"http://edamontology.org/format_2331\"}, {\"name\": \"XML\", \"uri\": \"http://edamontology.org/format_2332\"}, {\"name\": \"Binary format\", \"uri\": \"http://edamontology.org/format_2333\"}, {\"name\": \"Format (by type of data)\", \"uri\": \"http://edamontology.org/format_2350\"}, {\"name\": \"RDF format\", \"uri\": \"http://edamontology.org/format_2376\"}, {\"name\": \"JSON\", \"uri\": \"http://edamontology.org/format_3464\"}, {\"name\": \"YAML\", \"uri\": \"http://edamontology.org/format_3750\"}]}, \"format_2330\": {\"definition\": \"Textual format.\", \"path\": [{\"name\": \"Format||Textual format\", \"key\": \"format_1915||format_2330\"}], \"name\": \"Textual format\", \"uri\": \"http://edamontology.org/format_2330\", \"exact_synonyms\": [], \"narrow_synonyms\": [\"Plain text format\", \"txt\"], \"children\": [{\"name\": \"SMILES\", \"uri\": \"http://edamontology.org/format_1196\"}, {\"name\": \"InChI\", \"uri\": \"http://edamontology.org/format_1197\"}, {\"name\": \"mf\", \"uri\": \"http://edamontology.org/format_1198\"}, {\"name\": \"InChIKey\", \"uri\": \"http://edamontology.org/format_1199\"}, {\"name\": \"nucleotide\", \"uri\": \"http://edam