49\"}], \"name\": \"GelML\", \"uri\": \"http://edamontology.org/format_3249\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3250\": {\"definition\": \"spML is the format for describing proteomics sample processing, other than using gels, prior to mass spectrometric protein identification, standardised by HUPO PSI PS. It may also be applicable for metabolomics.\", \"path\": [{\"name\": \"Format||XML||spML\", \"key\": \"format_1915||format_2332||format_3250\"}, {\"name\": \"Format||Format (by type of data)||Experiment annotation format||spML\", \"key\": \"format_1915||format_2350||format_3167||format_3250\"}], \"name\": \"spML\", \"uri\": \"http://edamontology.org/format_3250\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3261\": {\"definition\": \"Resource Description Framework (RDF) XML format.\", \"path\": [{\"name\": \"Format||XML||RDF/XML\", \"key\": \"format_1915||format_2332||format_3261\"}, {\"name\": \"Format||Format (by type of data)||Ontology format||RDF format||RDF/XML\", \"key\": \"format_1915||format_2350||format_2195||format_2376||format_3261\"}, {\"name\": \"Format||Format (by type of data)||Linked data format||RDF format||RDF/XML\", \"key\": \"format_1915||format_2350||format_3748||format_2376||format_3261\"}, {\"name\": \"Format||RDF format||RDF/XML\", \"key\": \"format_1915||format_2376||format_3261\"}], \"name\": \"RDF/XML\", \"uri\": \"http://edamontology.org/format_3261\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3262\": {\"definition\": \"OWL ontology XML serialisation format.\", \"path\": [{\"name\": \"Format||XML||OWL/XML\", \"key\": \"format_1915||format_2332||format_3262\"}, {\"name\": \"Format||Format (by type of data)||Ontology format||OWL format||OWL/XML\", \"key\": \"format_1915||format_2350||format_2195||format_2197||format_3262\"}, {\"name\": \"Format||Format (by type of data)||Ontology format||RDF format||OWL format||OWL/XML\", \"key\"