\"nrrd\", \"uri\": \"http://edamontology.org/format_3551\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3554\": {\"definition\": \"File format used for scripts written in the R programming language for execution within the R software environment, typically for statistical computation and graphics.\", \"path\": [{\"name\": \"Format||Textual format||R file format\", \"key\": \"format_1915||format_2330||format_3554\"}], \"name\": \"R file format\", \"uri\": \"http://edamontology.org/format_3554\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3555\": {\"definition\": \"File format used for scripts for the Statistical Package for the Social Sciences.\", \"path\": [{\"name\": \"Format||Textual format||SPSS\", \"key\": \"format_1915||format_2330||format_3555\"}], \"name\": \"SPSS\", \"uri\": \"http://edamontology.org/format_3555\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3580\": {\"definition\": \"Reporter Code Count-A data file (.csv) output by the Nanostring nCounter Digital Analyzer, which contains gene sample information, probe information and probe counts.\", \"path\": [{\"name\": \"Format||Textual format||rcc\", \"key\": \"format_1915||format_2330||format_3580\"}, {\"name\": \"Format||Format (by type of data)||Gene expression report format||rcc\", \"key\": \"format_1915||format_2350||format_2058||format_3580\"}], \"name\": \"rcc\", \"uri\": \"http://edamontology.org/format_3580\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3581\": {\"definition\": \"ARFF (Attribute-Relation File Format) is an ASCII text file format that describes a list of instances sharing a set of attributes.\", \"path\": [{\"name\": \"Format||Textual format||arff\", \"key\": \"format_1915||format_2330||format_3581\"}], \"name\": \"arff\", \"uri\": \"http://edamontology.org/format_3581\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_