\": \"NIFTI format\", \"uri\": \"http://edamontology.org/format_4001\"}, {\"name\": \"pickle\", \"uri\": \"http://edamontology.org/format_4002\"}, {\"name\": \"NumPy format\", \"uri\": \"http://edamontology.org/format_4003\"}, {\"name\": \"SimTools repertoire file format\", \"uri\": \"http://edamontology.org/format_4004\"}, {\"name\": \"Zstandard format\", \"uri\": \"http://edamontology.org/format_4006\"}]}, \"format_1628\": {\"definition\": \"A format of raw sequence read data from an Applied Biosystems sequencing machine.\", \"path\": [{\"name\": \"Format||Binary format||ABI\", \"key\": \"format_1915||format_2333||format_1628\"}, {\"name\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||ABI\", \"key\": \"format_1915||format_2350||format_1919||format_2057||format_1628\"}], \"name\": \"ABI\", \"uri\": \"http://edamontology.org/format_1628\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_1632\": {\"definition\": \"Staden Chromatogram Files format (SCF) of base-called sequence reads, qualities, and other metadata.\", \"path\": [{\"name\": \"Format||Binary format||SCF\", \"key\": \"format_1915||format_2333||format_1632\"}, {\"name\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||SCF\", \"key\": \"format_1915||format_2350||format_1919||format_2057||format_1632\"}], \"name\": \"SCF\", \"uri\": \"http://edamontology.org/format_1632\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_2572\": {\"definition\": \"BAM format, the binary, BGZF-formatted compressed version of SAM format for alignment of nucleotide sequences (e.g. sequencing reads) to (a) reference sequence(s). May contain base-call and alignment qualities and other data.\", \"path\": [{\"name\": \"Format||Binary format||BAM\", \"key\": \"format_1915||format_2333||format_2572\"}, {\"name\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||BAM\", \"key\": \"format_1915||format_2350||format_1919||format_2057||format_2572\"}, {\"name\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||BAM\", \"key\": \"format_1915||format_2350||format_1921||format_2920||format_2572\"}], \"name\": \"BAM\", \"uri\": \"http://edamontology.org/format_2572\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3000\": {\"definition\": \"AB1 binary format of raw DNA sequence reads (output of Applied Biosystems\' sequencing analysis software). Contains an electropherogram and the DNA base sequence.\", \"path\": [{\"name\": \"Format||Binary format||AB1\", \"key\": \"format_1915||format_2333||format_3000\"}, {\"name\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||AB1\", \"key\": \"format_1915||format_2350||format_1919||format_2057||format_3000\"}], \"name\": \"AB1\", \"uri\": \"http://edamontology.org/format_3000\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3004\": {\"definition\": \"bigBed format for large sequence annotation tracks, similar to textual BED format.\", \"path\": [{\"name\": \"Format||Binary format||bigBed\", \"key\": \"format_1915||format_2333||format_3004\"}, {\"name\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||bigBed\", \"key\": \"format_1915||format_2350||format_1920||format_2919||format_3004\"}], \"name\": \"bigBed\", \"uri\": \"http://edamontology.org/format_3004\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3006\": {\"definition\": \"bigWig format for large sequence annotation tracks that consist of a value for each sequence position. Similar to textual WIG format.\", \"path\": [{\"name\": \"Format||Binary format||bigWig\", \"key\": \"format_1915||format_2333||format_3006\"}, {\"name\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||bigWig\", \"key\": \"format_1915||format_2350||format_1920||format_2919||format_3006\"}], \"name\": \"bigWig\", \"uri\": \"http://edamontology.org/format_3006\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3009\": {\"definition\": \"2bit binary format of nucleotide sequences using 2 bits per nucleotide. In addition encodes unknown nucleotides and lower-case \'masking\'.\", \"path\": [{\"name\": \"Format||Binary format||2bit\", \"key\": \"format_1915||format_2333||format_3009\"}, {\"name\": \"Format||Format (by type of data)||Raw sequence format||2bit\", \"key\": \"format_1915||format_2350||format_2571||format_3009\"}], \"name\": \"2bit\", \"uri\": \"http://edamontology.org/format_3009\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3010\": {\"definition\": \".nib (nibble) binary format of a nucleotide sequence using 4 bits per nucleotide (including unknown) and its lower-case \'masking\'.\", \"path\": [{\"name\": \"Format||Binary format||.nib\", \"key\": \"format_1915||format_2333||format_3010\"}, {\"name\": \"Format||Format (by type of data)||Raw sequence format||.nib\", \"key\": \"format_1915||format_2350||format_2571||format_3010\"}], \"name\": \".nib\", \"uri\": \"http://edamontology.org/format_3010\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3017\": {\"definition\": \"Sequence Read Format (SRF) of sequence trace data. Supports submission to the NCBI Short Read Archive.\", \"path\": [{\"name\": \"Format||Binary format||SRF\", \"key\": \"format_1915||format_2333||format_3017\"}, {\"name\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||SRF\", \"key\": \"format_1915||format_2350||format_1919||format_2057||format_3017\"}], \"name\": \"SRF\", \"uri\": \"http://edamontology.org/format_3017\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3018\": {\"definition\": \"ZTR format for storing chromatogram data from DNA sequencing instruments.\", \"path\": [{\"name\": \"Format||Binary format||ZTR\", \"key\": \"format_1915||format_2333||format_3018\"}, {\"name\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||ZTR\", \"key\": \"format_1915||format_2350||format_1919||format_2057||format_3018\"}], \"name\": \"ZTR\", \"uri\": \"http://edamontology.org/format_3018\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3020\": {\"definition\": \"BCF, the binary version of Variant Call Format (VCF) for sequence variation (indels, polymorphisms, structural variation).\", \"path\": [{\"name\": \"Format||Binary format||BCF\", \"key\": \"format_1915||format_2333||format_3020\"}, {\"name\": \"Format||Format (by type of data)||Sequence variation annotation format||BCF\", \"key\": \"format_1915||format_2350||format_2921||format_3020\"}], \"name\": \"BCF\", \"uri\": \"http://edamontology.org/format_3020\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3284\": {\"definition\": \"Standard flowgram format (SFF) is a binary file format used to encode results of pyrosequencing from the 454 Life Sciences platform for high-throughput sequencing.\", \"path\": [{\"name\": \"Format||Binary format||SFF\", \"key\": \"format_1915||format_2333||format_3284\"}, {\"name\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||SFF\", \"key\": \"format_1915||format_2350||format_1919||format_2057||format_3284\"}], \"name\": \"SFF\", \"uri\": \"http://edamontology.org/format_3284\", \"exact_synonyms\": [\"Standard flowgram format\"], \"narrow_synonyms\": [], \"children\": []}, \"format_3327\": {\"definition\": \"BAM indexing format\", \"path\": [{\"name\": \"Format||Binary format||BAI\", \"key\": \"format_1915||format_2333||format_3327\"}, {\"name\": \"Format||Format (by type of data)||Data index format||BAI\", \"key\": \"format_1915||format_2350||format_3326||format_3327\"}], \"name\": \"BAI\", \"uri\": \"http://edamontology.org/format_3327\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3462\": {\"definition\": \"Reference-based compression of alignment format\", \"path\": [{\"name\": \"Format||Binary format||CRAM\", \"key\": \"format_1915||format_2333||format_3462\"}, {\"name\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||CRAM\", \"key\": \"format_1915||format_2350||format_1921||format_2920||format_3462\"}], \"name\": \"CRAM\", \"uri\": \"http://edamontology.org/format_3462\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3467\": {\"definition\": \"Graphics Interchange Format.\", \"path\": [{\"name\": \"Format||Binary format||GIF\", \"key\": \"format_1915||format_2333||format_3467\"}], \"name\": \"GIF\", \"uri\": \"http://edamontology.org/format_3467\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3484\": {\"definition\": \"Bowtie format for indexed reference genome for \\\"small\\\" genomes.\", \"path\": [{\"name\": \"Format||Binary format||ebwt\", \"key\": \"format_1915||format_2333||format_3484\"}, {\"name\": \"Format||Format (by type of data)||Data index format||ebwt\", \"key\": \"format_1915||format_2350||format_3326||format_3484\"}], \"name\": \"ebwt\", \"uri\": \"http://edamontology.org/format_3484\", \"exact_synonyms\": [\"Bowtie index format\"], \"narrow_synonyms\": [], \"children\": []}, \"format_3491\": {\"definition\": \"Bowtie format for indexed reference genome for \\\"large\\\" genomes.\", \"path\": [{\"name\": \"Format||Binary format||ebwtl\", \"key\": \"format_1915||format_2333||format_3491\"}, {\"name\": \"Format||Format (by type of data)||Data index format||ebwtl\", \"key\": \"format_1915||format_2350||format_3326||format_3491\"}], \"name\": \"ebwtl\", \"uri\": \"http://edamontology.org/format_3491\", \"exact_synonyms\": [\"Bowtie long index format\"], \"narrow_synonyms\": [], \"children\": []