2333||format_3698\"}], \"name\": \"SRA format\", \"uri\": \"http://edamontology.org/format_3698\", \"exact_synonyms\": [\"SRA\", \"SRA archive format\"], \"narrow_synonyms\": [], \"children\": []}, \"format_3699\": {\"definition\": \"VDB (\'vertical database\') is the native format used for export from the NCBI Sequence Read Archive.\", \"path\": [{\"name\": \"Format||Binary format||VDB\", \"key\": \"format_1915||format_2333||format_3699\"}], \"name\": \"VDB\", \"uri\": \"http://edamontology.org/format_3699\", \"exact_synonyms\": [\"SRA native format\"], \"narrow_synonyms\": [], \"children\": []}, \"format_3700\": {\"definition\": \"Index file format used by the samtools package to index TAB-delimited genome position files.\", \"path\": [{\"name\": \"Format||Binary format||Tabix index file format\", \"key\": \"format_1915||format_2333||format_3700\"}, {\"name\": \"Format||Format (by type of data)||Data index format||Tabix index file format\", \"key\": \"format_1915||format_2350||format_3326||format_3700\"}], \"name\": \"Tabix index file format\", \"uri\": \"http://edamontology.org/format_3700\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3710\": {\"definition\": \"Mass spectrum file format from QSTAR and QTRAP instruments (ABI/Sciex).\", \"path\": [{\"name\": \"Format||Binary format||WIFF format\", \"key\": \"format_1915||format_2333||format_3710\"}, {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||WIFF format\", \"key\": \"format_1915||format_2350||format_3245||format_3710\"}], \"name\": \"WIFF format\", \"uri\": \"http://edamontology.org/format_3710\", \"exact_synonyms\": [\"wiff\"], \"narrow_synonyms\": [], \"children\": []}, \"format_3712\": {\"definition\": \"Proprietary file format for mass spectrometry data from Thermo Scientific.\", \"path\": [{\"name\": \"Format||Binary format||Thermo RAW\", \"key\": \"format_1915||format_2333||format_3712\"}, {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||Thermo RAW\", \"key\": \"format_1915||format_2350||format_3245||format_3712\"}], \"name\": \"Thermo RAW\", \"uri\": \"http://edamontology.org/format_3712\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3727\": {\"definition\": \"Image file format used by the Open Microscopy Environment (OME).\", \"path\": [{\"name\": \"Format||Binary format||OME-TIFF\", \"key\": \"format_1915||format_2333||format_3727\"}, {\"name\": \"Format||Format (by type of data)||Image format||OME-TIFF\", \"key\": \"format_1915||format_2350||format_3547||format_3727\"}], \"name\": \"OME-TIFF\", \"uri\": \"http://edamontology.org/format_3727\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3776\": {\"definition\": \"BTrack is an HDF5-based binary format for genome or sequence feature tracks and their collections, suitable for integrative multi-track analysis. BTrack is a binary, compressed alternative to the GTrack and GSuite formats.\", \"path\": [{\"name\": \"Format||Binary format||BTrack\", \"key\": \"format_1915||format_2333||format_3776\"}, {\"name\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||BTrack\", \"key\": \"format_1915||format_2350||format_1920||format_2548||format_3776\"}, {\"name\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||BTrack\", \"key\": \"format_1915||format_2350||format_1920||format_2919||format_3776\"}, {\"name\": \"Format||Format (by type of data)||Sequence feature annotation format||BTrack\", \"key\": \"format_1915||format_2350||format_1920||format_3776\"}], \"name\": \"BTrack\", \"uri\": \"http://edamontology.org/format_3776\", \"exact_synonyms\": [\"BTrack (GTrack ecosystem of formats)\", \"BTrack format\", \"BioXSD/GTrack BTrack\", \"BioXSD|GTrack BTrack\", \"GTrack|BTrack|GSuite BTrack\", \"GTrack|GSuite|BTrack BTrack\"], \"narrow_synonyms\": [], \"children\": []}, \"format_3826\": {\"definition\": \". proBAM is an adaptation of BAM (format_2572), which was extended to meet specific requirements entailed by proteomics data.\", \"path\": [{\"name\": \"Format||Binary format||proBAM\", \"key\": \"format_1915||format_2333||format_3826\"}, {\"name\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||proBAM\", \"key\": \"format_1915||format_2350||format_1919||format_2057||format_3826\"}, {\"name\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||proBAM\", \"key\": \"format_1915||format_2350||format_1921||format_2920||format_3826\"}], \"name\": \"proBAM\", \"uri\": \"http://edamontology.org/format_3826\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3830\": {\"definition\": \"Binary format used by the ARB software suite\", \"path\": [{\"name\": \"Format||Binary format||ARB\", \"key\": \"format_1915||format_2333||format_3830\"}, {\"name\": \"Format||Format (by type of data)||Alignment format||ARB\", \"key\": \"format_1915||format_2350||format_1921||format_3830\"}], \"name\": \"ARB\", \"uri\": \"http://edamontology.org/format_3830\", \"exact_synonyms\": [\"ARB binary format\"], \"narrow_synonyms\": [], \"children\": []}, \"format_3839\": {\"definition\": \"ibd is a data format for mass spectrometry imaging data.\", \"path\": [{\"name\": \"Format||Binary format||ibd\", \"key\": \"format_1915||format_2333||format_3839\"}, {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||ibd\", \"key\": \"format_1915||format_2350||format_3245||format_3839\"}], \"name\": \"ibd\", \"uri\": \"http://edamontology.org/format_3839\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3849\": {\"definition\": \"A set of XML compliant markup components for describing multiple sequence alignments.\", \"path\": [{\"name\": \"Format||Binary format||MSAML\", \"key\": \"format_1915||format_2333||format_3849\"}, {\"name\": \"Format||Format (by type of data)||Alignment format||MSAML\", \"key\": \"format_1915||format_2350||format_1921||format_3849\"}], \"name\": \"MSAML\", \"uri\": \"http://edamontology.org/format_3849\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3858\": {\"definition\": \"Proprietary file format for mass spectrometry data from Waters.\", \"path\": [{\"name\": \"Format||Binary format||Waters RAW\", \"key\": \"format_1915||format_2333||format_3858\"}, {\"name\": \"Format||Format (by type of data)||Mass spectrometry data format||Waters RAW\", \"key\": \"format_1915||format_2350||format_3245||format_3858\"}], \"name\": \"Waters RAW\", \"uri\": \"http://edamontology.org/format_3858\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3873\": {\"definition\": \"HDF is the name of a set of file formats and libraries designed to store and organize large amounts of numerical data, originally developed at the National Center for Supercomputing Applications at the University of Illinois.\", \"path\": [{\"name\": \"Format||Binary format||HDF\", \"key\": \"format_1915||format_2333||format_3873\"}, {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||HDF\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3873\"}], \"name\": \"HDF\", \"uri\": \"http://edamontology.org/format_3873\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3874\": {\"definition\": \"PCAZip format is a binary compressed file to store atom coordinates based on Essential Dynamics (ED) and Principal Component Analysis (PCA).\", \"path\": [{\"name\": \"Format||Binary format||PCAzip\", \"key\": \"format_1915||format_2333||format_3874\"}, {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||PCAzip\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3874\"}], \"name\": \"PCAzip\", \"uri\": \"http://edamontology.org/format_3874\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3875\": {\"definition\": \"Portable binary format for trajectories produced by GROMACS package.\", \"path\": [{\"name\": \"Format||Binary format||XTC\", \"key\": \"format_1915||format_2333||format_3875\"}, {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||XTC\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3875\"}], \"name\": \"XTC\", \"uri\": \"http://edamontology.org/format_3875\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3876\": {\"definition\": \"Trajectory Next Generation (TNG) is a format for storage of molecular simulation data. It is designed and implemented by the GROMACS development group, and it is called to be the substitute of the XTC format.\", \"path\": [{\"name\": \"Format||Binary format||TNG\", \"key\": \"format_1915||format_2333||format_3876\"}, {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||TNG\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3876\"}], \"name\": \"TNG\", \"uri\": \"http://edamontology.org/format_3876\", \"exact_synonyms\": [\"Trajectory Next Generation format\"], \"narrow_synonyms\": [], \"children\": []}, \"format_3885\": {\"definition\": \"Scripps Research Institute BinPos format is a binary formatted file to store atom coordinates.\", \"path\": [{\"name\": \"Format||Binary format||BinPos\", \"key\": \"format_1915||format_2333||format_3885\"}, {\"name\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||BinPos\", \"key\": \"format_1915||format_2350||format_3866||format_3867||format_3885\"}], \"name\": \"BinPos\", \"uri\": \"http://edamontology.org/format_3885\", \"exact_synonyms\": [\"Scripps Research Institute BinPos\"], \"narrow_synonyms\": [], \"children\": []}, \"format_3911\": {\"definition\": \"Mash sketch is a format for sequence / sequence checksum information. To make a sketch, each k-mer in a sequence is hashed, which creates a pseudo-random identifier. By sorting these hashes, a small subset from the top of the sorted list can represent the entire sequence.\", \"path\": [{\"name\": \"Format||Binary format||msh\", \"key\": \"format_1915||format_2333||format_3911\"}, {\"name\": \"Format||Format (by type of data)||Raw sequence format||msh\", \"key\": \"format_1915||format_2350||format_2571||format_3911\"}], \"name\": \"msh\", \"uri\": \"http://edamontology.org/format_3911\", \"exact_synonyms\": [\"Mash sketch\", \"min-hash sketch\"], \"narrow_synonyms\": [], \"children\": []}, \"format_3915\": {\"definition\": \"The Zarr format is an implementation of chunked, compressed, N-dimensional arrays for storing data.\", \"path\": [{\"name\": \"Format||Binary format||Zarr\", \"key\": \"format_1915||format_2333||format_3915\"}, {\"name\": \"Format||Format (by type of data)||Gene expression report format||Zarr\", \"key\": \"format_1915||format_2350||format_2058||format_3915\"}, {\"name\": \"Format||Format (by type of data)||Matrix format||Zarr\", \"key\": \"format_1915||format_2350||format_3033||format_3915\"}], \"name\": \"Zarr\", \"uri\": \"http://edamontology.org/format_3915\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3973\": {\"definition\": \"A Docker image is a file, comprised of multiple layers, that is used to execute code in a Docker container. An image is essentially built from the instructions for a complete and executable version of an application, which relies on the host OS kernel.\", \"path\": [{\"name\": \"Format||Binary format||Docker image format\", \"key\": \"format_1915||format_2333||format_3973\"}, {\"name\": \"Format||Format (by type of data)||Raw sequence format||Docker image format\", \"key\": \"format_1915||format_2350||format_2571||format_3973\"}], \"name\": \"Docker image format\", \"uri\": \"http://edamontology.org/format_3973\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3981\": {\"definition\": \"TAR archive file format generated by the Unix-based utility tar.\", \"path\": [{\"name\": \"Format||Binary format||TAR format\", \"key\": \"format_1915||format_2333||format_3981\"}], \"name\": \"TAR format\", \"uri\": \"http://edamontology.org/format_3981\", \"exact_synonyms\": [\"TAR\", \"Tarball\"], \"narrow_synonyms\": [], \"children\": []}, \"format_3986\": {\"definition\": \"The proprietary native video format of various Microsoft programs such as Windows Media Player.\", \"path\": [{\"name\": \"Format||Binary format||WMV\", \"key\": \"format_1915||format_2333||format_3986\"}, {\"name\": \"Format||Format (by type of data)||Image format||WMV\", \"key\": \"format_1915||format_2350||format_3547||format_3986\"}], \"name\": \"WMV\", \"uri\": \"http://edamontology.org/format_3986\", \"exact_synonyms\": [\"Windows Media Video format\", \"Windows movie file format\"], \"narrow_synonyms\": [], \"children\": []}, \"format_3987\": {\"definition\": \"ZIP is an archive file format that supports lossless data compression.\", \"path\": [{\"name\": \"Format||Binary format||ZIP format\", \"key\": \"format_1915||format_2333||format_3987\"}], \"name\": \"ZIP format\", \"uri\": \"http://edamontology.org/format_3987\", \"exact_synonyms\": [\"ZIP\"], \"narrow_synonyms\": [], \"children\": []}, \"format_3988\": {\"definition\": \"Zeiss\' proprietary image format based on TIFF.\", \"path\": [{\"name\": \"Format||Binary format||LSM\", \"key\": \"format_1915||format_2333||format_3988\"}, {\"name\": \"Format||Format (by type of data)||Image format||LSM\", \"key\": \"format_1915||format_2350||format_3547||format_3988\"}], \"name\": \"LSM\", \"uri\": \"http://edamontology.org/format_3988\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"format_3989\": {\"definition\": \"GNU zip compressed file format common to Unix-based operating systems.\", 