312\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format for the Genetic Data Environment (GDE).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Cytoscape input file format\", \"data\": {\"uri\": \"format_3477\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of the cytoscape input file of gene expression ratios or values are specified over one or more experiments.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GCG format variant\", \"data\": {\"uri\": \"format_3486\"}, \"ch\": [{\"t\": \"GCG\", \"data\": {\"uri\": \"format_1935\"}, \"ch\": [], \"es\": [\"GCG SSF\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"GCG sequence file format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GCG MSF\", \"data\": {\"uri\": \"format_1947\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"GCG MSF (multiple sequence file) file format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"RSF\", \"data\": {\"uri\": \"format_3485\"}, \"ch\": [], \"es\": [\"GCG RSF\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Rich sequence format.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Some format based on the GCG format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Ensembl variation file format\", \"data\": {\"uri\": \"format_3499\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Ensembl standard format for variation data.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"mhd\", \"data\": {\"uri\": \"format_3550\"}, \"ch\": [], \"es\": [\"Metalmage format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Text-based tagged file format for medical images generated using the MetaImage software package.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"nrrd\", \"data\": {\"uri\": \"format_3551\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Nearly Raw Rasta Data format designed to support scientific visualisation and image processing involving N-dimensional raster data.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"R file format\", \"data\": {\"uri\": \"format_3554\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"File format used for scripts written in the R programming language for execution within the R software environment, typically for statistical computation and graphics.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SPSS\", \"data\": {\"uri\": \"format_3555\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"File format used for scripts for the Statistical Package for the Social Sciences.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"rcc\", \"data\": {\"uri\": \"format_3580\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Reporter Code Count-A data file (.csv) output by the Nanostring nCounter Digital Analyzer, which contains gene sample information, probe information and probe counts.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"arff\", \"data\": {\"uri\": \"format_3581\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"ARFF (Attribute-Relation File Format) is an ASCII text file format that describes a list of instances sharing a set of attributes.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"afg\", \"data\": {\"uri\": \"format_3582\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"AFG is a single text-based file assembly format  that holds read and consensus information together\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"bedgraph\", \"data\": {\"uri\": \"format_3583\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The bedGraph format allows display of continuous-valued data in track format. This display type is useful for probability scores and transcriptome data\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"chrominfo\", \"data\": {\"uri\": \"format_3587\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Tabular format of chromosome names and sizes used by Galaxy.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"customtrack\", \"data\": {\"uri\": \"format_3588\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Custom Sequence annotation track format used by Galaxy.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"qual\", \"data\": {\"uri\": \"format_3607\"}, \"ch\": [{\"t\": \"qualsolexa\", \"data\": {\"uri\": \"format_3608\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) for Solexa/Illumina 1.0 format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"qualillumina\", \"data\": {\"uri\": \"format_3609\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) from Illumina 1.5 and before Illumina 1.8.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"qualsolid\", \"data\": {\"uri\": \"format_3610\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) for SOLiD data.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"qual454\", \"data\": {\"uri\": \"format_3611\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) from 454 sequencers.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"mzTab\", \"data\": {\"uri\": \"format_3681\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"mzTab is a tab-delimited format for mass spectrometry-based proteomics and metabolomics results.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"ISA-TAB\", \"data\": {\"uri\": \"format_3687\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The Investigation / Study / Assay (ISA) tab-delimited (TAB) format incorporates metadata from\\nexperiments employing a combination of technologies.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SBtab\", \"data\": {\"uri\": \"format_3688\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"SBtab is a tabular format for biochemical network models.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BEL\", \"data\": {\"uri\": \"format_3691\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Biological Expression Language (BEL) is a textual format for representing scientific findings in life sciences in a computable form.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"AGP\", \"data\": {\"uri\": \"format_3693\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"AGP is a tabular format for a sequence assembly (a contig, a scaffold/supercontig, or a chromosome).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"PS\", \"data\": {\"uri\": \"format_3696\"}, \"ch\": [{\"t\": \"EPS\", \"data\": {\"uri\": \"format_3466\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Encapsulated PostScript format\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [\"PostScript\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PostScript format\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GCT/Res format\", \"data\": {\"uri\": \"format_3709\"}, \"ch\": [], \"es\": [\"GCT format\", \"Res format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Tab-delimited text files of GenePattern that contain a column for each sample, a row for each gene, and an expression value for each gene in each sample.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Mascot .dat file\", \"data\": {\"uri\": \"format_3713\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"\\\"Raw\\\" result file from Mascot database search.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"MaxQuant APL peaklist format\", \"data\": {\"uri\": \"format_3714\"}, \"ch\": [], \"es\": [\"MaxQuant APL\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of peak list files from Andromeda search engine (MaxQuant) that consist of arbitrarily many spectra.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"LocARNA PP\", \"data\": {\"uri\": \"format_3728\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The LocARNA PP format combines sequence or alignment information and (respectively, single or consensus) ensemble probabilities into an PP 2.0 record.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"dbGaP format\", \"data\": {\"uri\": \"format_3729\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Input format used by the Database of Genotypes and Phenotypes (dbGaP).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BIOM format\", \"data\": {\"uri\": \"format_3746\"}, \"ch\": [], \"es\": [\"BIological Observation Matrix format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The BIological Observation Matrix (BIOM) is a format for representing biological sample by observation contingency tables in broad areas of comparative omics. The primary use of this format is to represent OTU tables and metagenome tables.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"DSV\", \"data\": {\"uri\": \"format_3751\"}, \"ch\": [{\"t\": \"TSV\", \"data\": {\"uri\": \"format_3475\"}, \"ch\": [{\"t\": \"MAGE-TAB\", \"data\": {\"uri\": \"format_3162\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"MAGE-TAB textual format for microarray expression data, standardised by MGED (now FGED).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"WEGO\", \"data\": {\"uri\": \"format_3979\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"WEGO native format used by the Web Gene Ontology Annotation Plot application.   Tab-delimited format with gene names and others GO IDs (columns) with one annotation record per line.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"RPKM\", \"data\": {\"uri\": \"format_3980\"}, \"ch\": [], \"es\": [\"Gene expression levels table format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Tab-delimited format for gene expression levels table, calculated as Reads Per Kilobase per Million (RPKM) mapped reads.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [\"Tab-delimited\", \"Tab-separated values\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Tabular data represented as tab-separated values in a text file.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"CSV\", \"data\": {\"uri\": \"format_3752\"}, \"ch\": [], \"es\": [\"Comma-separated values\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Tabular data represented as comma-separated values in a text file.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [\"Delimiter-separated values\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Tabular data represented as values in a text file delimited by some character.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SEQUEST .out file\", \"data\": {\"uri\": \"format_3758\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"\\\"Raw\\\" result file from SEQUEST database search.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GSuite\", \"data\": {\"uri\": \"format_3775\"}, \"ch\": [], \"es\": [\"BioXSD/GTrack GSuite\", \"BioXSD|GTrack GSuite\", \"GSuite (GTrack ecosystem of formats)\", \"GSuite format\", \"GTrack|BTrack|GSuite GSuite\", \"GTrack|GSuite|BTrack GSuite\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"GSuite is a tabular format for collections of genome or sequence feature tracks, suitable for integrative multi-track analysis. GSuite contains links to genome/sequence tracks, with additional metadata.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"MCPD\", \"data\": {\"uri\": \"format_3777\"}, \"ch\": [], \"es\": [\"Bioversity MCPD\", \"FAO MCPD\", \"MCPD format\", \"Multi-Crop Passport Descriptors\", \"Multi-Crop Passport Descriptors format\"], \"ns\": [\"IPGRI MCPD\", \"MCPD V.1\", \"MCPD V.2\"], \"rb\": [], \"co\": [], \"d\": \"The FAO/Bioversity/IPGRI Multi-Crop Passport Descriptors (MCPD) is an international standard format for exchange of germplasm information.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"PubTator format\", \"data\": {\"uri\": \"format_3783\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Native textual export format of annotated scientific text from PubTator.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BioNLP Shared Task format\", \"data\": {\"uri\": \"format_3785\"}, \"ch\": [], \"es\": [\"BRAT format\", \"BRAT standoff format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A family of similar formats of text annotation, used by BRAT and other tools, known as BioNLP Shared Task format (BioNLP 2009 Shared Task on Event Extraction, BioNLP Shared Task 2011, BioNLP Shared Task 2013), BRAT format, BRAT standoff format, and similar.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SQL\", \"data\": {\"uri\": \"format_3788\"}, \"ch\": [], \"es\": [\"Structured Query Language\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"SQL (Structured Query Language) is the de-facto standard query language (format of queries) for querying and manipulating data in relational databases.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"XQuery\", \"data\": {\"uri\": \"format_3789\"}, \"ch\": [], \"es\": [\"XML Query\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"XQuery (XML Query) is a query language (format of queries) for querying and manipulating structured and unstructured data, usually in the form of XML, text, and with vendor-specific extensions for other data formats (JSON, binary, etc.).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SPARQL\", \"data\": {\"uri\": \"format_3790\"}, \"ch\": [], \"es\": [\"SPARQL Protocol and RDF Query Language\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"SPARQL (SPARQL Protocol and RDF Query Language) is a semantic query language for querying and manipulating data stored in Resource Description Framework (RDF) format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GEN\", \"data\": {\"uri\": \"format_3812\"}, \"ch\": [], \"es\": [\"Genotype file format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The GEN file format contains genetic data and describes SNPs.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SAMPLE file format\", \"data\": {\"uri\": \"format_3813\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The SAMPLE file format contains information about each individual i.e. individual IDs, covariates, phenotypes and missing data proportions, from a GWAS study.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SDF\", \"data\": {\"uri\": \"format_3814\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"SDF is one of a family of chemical-data file formats developed by MDL Information Systems; it is intended especially for structural information.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Molfile\", \"data\": {\"uri\": \"format_3815\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"An MDL Molfile is a file format for holding information about the atoms, bonds, connectivity and coordinates of a molecule.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Mol2\", \"data\": {\"uri\": \"format_3816\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Complete, portable representation of a SYBYL molecule. ASCII file which contains all the information needed to reconstruct a SYBYL molecule.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"latex\", \"data\": {\"uri\": \"format_3817\"}, \"ch\": [], \"es\": [\"LaTeX format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"format for the LaTeX document preparation system\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"ELAND format\", \"data\": {\"uri\": \"format_3818\"}, \"ch\": [], \"es\": [\"ELAND\", \"eland\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Tab-delimited text file format used by Eland - the read-mapping program distributed by Illumina with its sequencing analysis pipeline - which maps short Solexa sequence reads to the human reference genome.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GML\", \"data\": {\"uri\": \"format_3822\"}, \"ch\": [], \"es\": [\"GML format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"GML (Graph Modeling Language) is a text file format supporting network data with a very easy syntax. It is used by Graphlet, Pajek, yEd, LEDA and NetworkX.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"FASTG\", \"data\": {\"uri\": \"format_3823\"}, \"ch\": [], \"es\": [\"FASTG assembly graph format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"FASTG is a format for faithfully representing genome assemblies in the face of allelic polymorphism and assembly uncertainty.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"proBED\", \"data\": {\"uri\": \"format_3827\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \". proBED is an adaptation of BED (format_3003), which was extended to meet specific requirements entailed by proteomics data.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GPR\", \"data\": {\"uri\": \"format_3829\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"GenePix Results (GPR) text file format developed by Axon Instruments that is used to save GenePix Results data.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"JCAMP-DX\", \"data\": {\"uri\": \"format_3859\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A standardized file format for data exchange in mass spectrometry, initially developed for infrared spectrometry.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"XYZ\", \"data\": {\"uri\": \"format_3877\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The XYZ chemical file format is widely supported by many programs, although many slightly different XYZ file formats coexist (Tinker XYZ, UniChem XYZ, etc.). Basic information stored for each atom in the system are x, y and z coordinates and atom element/atomic number.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"mdcrd\", \"data\": {\"uri\": \"format_3878\"}, \"ch\": [], \"es\": [\"AMBER trajectory format\", \"inpcrd\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"AMBER trajectory (also called mdcrd), with 10 coordinates per line and format F8.3 (fixed point notation with field width 8 and 3 decimal places).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GROMACS top\", \"data\": {\"uri\": \"format_3880\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"GROMACS MD package top textual files define an entire structure system topology, either directly, or by including itp files.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"AMBER top\", \"data\": {\"uri\": \"format_3881\"}, \"ch\": [], \"es\": [\"AMBER Parm\", \"AMBER Parm7\", \"Parm7\", \"Prmtop\", \"Prmtop7\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"AMBER Prmtop file (version 7) is a structure topology text file divided in several sections designed to be parsed easily using simple Fortran code. Each section contains particular topology information, such as atom name, charge, mass, angles, dihedrals, etc.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"PSF\", \"data\": {\"uri\": \"format_3882\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"X-Plor Protein Structure Files (PSF) are structure topology files used by NAMD and CHARMM molecular simulations programs. PSF files contain six main sections of interest: atoms, bonds, angles, dihedrals, improper dihedrals (force terms used to maintain planarity) and cross-terms.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GROMACS itp\", \"data\": {\"uri\": \"format_3883\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"GROMACS itp files (include topology) contain structure topology information, and are tipically included in GROMACS topology files (GROMACS top). Itp files are used to define individual (or multiple) components of a topology as a separate file. This is particularly useful if there is a molecule that is used frequently, and also reduces the size of the system topology file, splitting it in different parts.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"RST\", \"data\": {\"uri\": \"format_3886\"}, \"ch\": [], \"es\": [\"restrt\", \"rst7\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"AMBER coordinate/restart file with 6 coordinates per line and decimal format F12.7 (fixed point notation with field width 12 and 7 decimal places)\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"CHARMM rtf\", \"data\": {\"uri\": \"format_3887\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of CHARMM Residue Topology Files (RTF), which define groups by including the atoms, the properties of the group, and bond and charge information.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"AMBER frcmod\", \"data\": {\"uri\": \"format_3888\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"AMBER frcmod (Force field Modification) is a file format to store any modification to the standard force field needed for a particular molecule to be properly represented in the simulation.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"AMBER off\", \"data\": {\"uri\": \"format_3889\"}, \"ch\": [], \"es\": [\"AMBER Object File Format\", \"AMBER lib\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"AMBER Object File Format library files (OFF library files) store residue libraries (forcefield residue parameters).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"NMReDATA\", \"data\": {\"uri\": \"format_3906\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"MReData is a text based data standard for processed NMR data. It is relying on SDF molecule data and allows to store assignments of NMR peaks to molecule features.  The NMR-extracted data (or \\\"NMReDATA\\\") includes: Chemical shift,scalar coupling, 2D correlation, assignment, etc.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BpForms\", \"data\": {\"uri\": \"format_3909\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"BpForms is a string format for concretely representing the primary structures of biopolymers, including DNA, RNA, and proteins that include non-canonical nucleic and amino acids. See https://www.bpforms.org for more information.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"trr\", \"data\": {\"uri\": \"format_3910\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of trr files that contain the trajectory of a simulation experiment used by GROMACS.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"MTX\", \"data\": {\"uri\": \"format_3916\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The Matrix Market matrix (MTX) format stores numerical or pattern matrices in a dense (array format) or sparse (coordinate format) representation.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BcForms\", \"data\": {\"uri\": \"format_3951\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"BcForms is a format for abstractly describing the molecular structure (atoms and bonds) of macromolecular complexes as a collection of subunits and crosslinks. Each subunit can be described with BpForms (format_3909) or SMILES (data_2301). BcForms uses an ontology of crosslinks to abstract the chemical details of crosslinks from the descriptions of complexes (see https://bpforms.org/crosslink.html).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"N-Quads\", \"data\": {\"uri\": \"format_3956\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"N-Quads is a line-based, plain text format for encoding an RDF dataset. It includes information about the graph each triple belongs to.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BNGL\", \"data\": {\"uri\": \"format_3972\"}, \"ch\": [], \"es\": [\"BioNetGen Language\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"BioNetGen is a format for the specification and simulation of rule-based models of biochemical systems, including signal transduction, metabolic, and genetic regulatory networks.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GFA 1\", \"data\": {\"uri\": \"format_3975\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Graphical Fragment Assembly captures sequence graphs as the product of an assembly, a representation of variation in genomes, splice graphs in genes, or even overlap between reads from long-read sequencing technology.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GFA 2\", \"data\": {\"uri\": \"format_3976\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Graphical Fragment Assembly captures sequence graphs as the product of an assembly, a representation of variation in genomes, splice graphs in genes, or even overlap between reads from long-read sequencing technology.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"CONTIG\", \"data\": {\"uri\": \"format_3978\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The CONTIG format used for output of the SOAPdenovo alignment program. It contains contig sequences generated without using mate pair information.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"CHAIN\", \"data\": {\"uri\": \"format_3982\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The CHAIN format describes a pairwise alignment that allow gaps in both sequences simultaneously and is used by the UCSC Genome Browser.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"NET\", \"data\": {\"uri\": \"format_3983\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The NET file format is used to describe the data that underlie the net alignment annotations in the UCSC Genome Browser.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"QMAP\", \"data\": {\"uri\": \"format_3984\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of QMAP files generated for methylation data from an internal BGI pipeline.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"gxformat2\", \"data\": {\"uri\": \"format_3985\"}, \"ch\": [], \"es\": [\"Galaxy workflow format\", \"GalaxyWF\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"An emerging format for high-level Galaxy workflow description.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"CIGAR format\", \"data\": {\"uri\": \"format_3992\"}, \"ch\": [], \"es\": [\"CIGAR\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Compact Idiosyncratic Gapped Alignment Report format is a compressed (run-length encoded) pairwise alignment format. It is useful for representing long (e.g. genomic) pairwise alignments.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Python script\", \"data\": {\"uri\": \"format_3996\"}, \"ch\": [], \"es\": [\"Python\", \"Python program\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format for scripts writtenin Python - a widely used high-level programming language for general-purpose programming.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Perl script\", \"data\": {\"uri\": \"format_3998\"}, \"ch\": [], \"es\": [\"Perl\", \"Perl program\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format for scripts written in Perl - a family of high-level, general-purpose, interpreted, dynamic programming languages.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"R script\", \"data\": {\"uri\": \"format_3999\"}, \"ch\": [], \"es\": [\"R\", \"R program\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format for scripts written in the R language - an open source programming language and software environment for statistical computing and graphics that is supported by the R Foundation for Statistical Computing.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"R markdown\", \"data\": {\"uri\": \"format_4000\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A file format for making dynamic documents (R Markdown scripts) with the R language.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Configuration file format\", \"data\": {\"uri\": \"format_4005\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A configuration file used by various programs to store settings that are specific to their respective software.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"MATLAB script\", \"data\": {\"uri\": \"format_4007\"}, \"ch\": [], \"es\": [\"MATLAB\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The file format for MATLAB scripts or functions.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [\"Plain text format\", \"txt\"], \"rb\": [], \"co\": [], \"d\": \"Textual format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"HTML\", \"data\": {\"uri\": \"format_2331\"}, \"ch\": [{\"t\": \"iHOP format\", \"data\": {\"uri\": \"format_1740\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The format of iHOP (Information Hyperlinked over Proteins) text-mining result.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"FASTA-HTML\", \"data\": {\"uri\": \"format_2310\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"FASTA format wrapped in HTML elements.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"EMBL-HTML\", \"data\": {\"uri\": \"format_2311\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"EMBL entry format wrapped in HTML elements.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GenBank-HTML\", \"data\": {\"uri\": \"format_2532\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Genbank entry format wrapped in HTML elements.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"MHTML\", \"data\": {\"uri\": \"format_3556\"}, \"ch\": [], \"es\": [\"HTML email format\", \"HTML email message format\", \"MHT\", \"MHT format\", \"MHTML format\", \"MIME  HTML\", \"MIME  HTML format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"MIME  HTML format for Web pages, which can include external resources, including images, Flash animations and so on.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [\"Hypertext Markup Language\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"HTML format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"XML\", \"data\": {\"uri\": \"format_2332\"}, \"ch\": [{\"t\": \"PDBML\", \"data\": {\"uri\": \"format_1478\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Entry format of PDB database in PDBML (XML) format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Taverna workflow format\", \"data\": {\"uri\": \"format_1665\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of Taverna workflows.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"iHOP format\", \"data\": {\"uri\": \"format_1740\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The format of iHOP (Information Hyperlinked over Proteins) text-mining result.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"OSCAR format\", \"data\": {\"uri\": \"format_1741\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"OSCAR format of annotated chemical text.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"DAS format\", \"data\": {\"uri\": \"format_1967\"}, \"ch\": [], \"es\": [\"das sequence format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"DAS sequence (XML) format (any type).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"dasdna\", \"data\": {\"uri\": \"format_1968\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"DAS sequence (XML) format (nucleotide-only).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"DASGFF\", \"data\": {\"uri\": \"form