], \"d\": \"Synthetic Biology Open Language (SBOL) is an XML format for the specification and exchange of biological design information in synthetic biology.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"PMML\", \"data\": {\"uri\": \"format_3726\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PMML uses XML to represent mining models. The structure of the models is described by an XML Schema.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"protXML\", \"data\": {\"uri\": \"format_3747\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A format for storage, exchange, and processing of protein identifications created from ms/ms-derived peptide sequence data.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"idXML\", \"data\": {\"uri\": \"format_3764\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"XML file format for files containing information about peptide identifications from mass spectrometry data analysis carried out with OpenMS.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"UniProtKB XML\", \"data\": {\"uri\": \"format_3770\"}, \"ch\": [], \"es\": [\"UniProt XML\", \"UniProt XML format\", \"UniProtKB XML format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"UniProtKB XML sequence features format is an XML format available for downloading UniProt entries.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BioC\", \"data\": {\"uri\": \"format_3782\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"BioC is a standardised XML format for sharing and integrating text data and annotations.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"xsd\", \"data\": {\"uri\": \"format_3804\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"XML format for XML Schema.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"VisML\", \"data\": {\"uri\": \"format_3821\"}, \"ch\": [], \"es\": [\"VisANT xml\", \"VisANT xml format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Default XML format of VisANT, containing all the network information.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"nmrML\", \"data\": {\"uri\": \"format_3825\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"nmrML is an MSI supported XML-based open access format for metabolomics NMR raw and processed spectral data. It is accompanies by an nmrCV (controlled vocabulary) to allow ontology-based annotations.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"consensusXML\", \"data\": {\"uri\": \"format_3832\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"OpenMS format for grouping features in one map or across several maps.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"featureXML\", \"data\": {\"uri\": \"format_3833\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"OpenMS format for quantitation results (LC/MS features).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"mzData\", \"data\": {\"uri\": \"format_3834\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Now deprecated data format of the HUPO Proteomics Standards Initiative.  Replaced by mzML (format_3244).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"TIDE TXT\", \"data\": {\"uri\": \"format_3835\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format supported by the Tide tool for identifying peptides from tandem mass spectra.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BLAST XML v2 results format\", \"data\": {\"uri\": \"format_3836\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"XML format as produced by the NCBI Blast package v2.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"pptx\", \"data\": {\"uri\": \"format_3838\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Microsoft Powerpoint format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BEAST\", \"data\": {\"uri\": \"format_3843\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"XML input file format for BEAST Software (Bayesian Evolutionary Analysis Sampling Trees).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Chado-XML\", \"data\": {\"uri\": \"format_3844\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Chado-XML format is a direct mapping of the Chado relational schema into XML.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"HSAML\", \"data\": {\"uri\": \"format_3845\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"An alignment format generated by PRANK/PRANKSTER consisting of four elements: newick, nodes, selection and model.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"InterProScan XML\", \"data\": {\"uri\": \"format_3846\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Output xml file from the InterProScan sequence analysis application.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"KGML\", \"data\": {\"uri\": \"format_3847\"}, \"ch\": [], \"es\": [\"KEGG Markup Language\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The KEGG Markup Language (KGML) is an exchange format of the KEGG pathway maps, which is converted from internally used KGML+ (KGML+SVG) format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"PubMed XML\", \"data\": {\"uri\": \"format_3848\"}, \"ch\": [], \"es\": [\"MEDLINE XML\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"XML format for collected entries from biobliographic databases MEDLINE and PubMed.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"OrthoXML\", \"data\": {\"uri\": \"format_3850\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"OrthoXML is designed broadly to allow the storage and comparison of orthology data from any ortholog database. It establishes a structure for describing orthology relationships while still allowing flexibility for database-specific information to be encapsulated in the same format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"PSDML\", \"data\": {\"uri\": \"format_3851\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Tree structure of Protein Sequence Database Markup Language generated using Matra software.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SeqXML\", \"data\": {\"uri\": \"format_3852\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"SeqXML is an XML Schema to describe biological sequences, developed by the Stockholm Bioinformatics Centre.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"UniParc XML\", \"data\": {\"uri\": \"format_3853\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"XML format for the UniParc database.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"UniRef XML\", \"data\": {\"uri\": \"format_3854\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"XML format for the UniRef reference clusters.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"NeuroML\", \"data\": {\"uri\": \"format_3971\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A model description language for computational neuroscience.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [\"eXtensible Markup Language\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"eXtensible Markup Language (XML) format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Binary format\", \"data\": {\"uri\": \"format_2333\"}, \"ch\": [{\"t\": \"ABI\", \"data\": {\"uri\": \"format_1628\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A format of raw sequence read data from an Applied Biosystems sequencing machine.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SCF\", \"data\": {\"uri\": \"format_1632\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Staden Chromatogram Files format (SCF) of base-called sequence reads, qualities, and other metadata.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BAM\", \"data\": {\"uri\": \"format_2572\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"BAM format, the binary, BGZF-formatted compressed version of SAM format for alignment of nucleotide sequences (e.g. sequencing reads) to (a) reference sequence(s). May contain base-call and alignment qualities and other data.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"AB1\", \"data\": {\"uri\": \"format_3000\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"AB1 binary format of raw DNA sequence reads (output of Applied Biosystems\' sequencing analysis software). Contains an electropherogram and the DNA base sequence.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"bigBed\", \"data\": {\"uri\": \"format_3004\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"bigBed format for large sequence annotation tracks, similar to textual BED format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"bigWig\", \"data\": {\"uri\": \"format_3006\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"bigWig format for large sequence annotation tracks that consist of a value for each sequence position. Similar to textual WIG format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"2bit\", \"data\": {\"uri\": \"format_3009\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"2bit binary format of nucleotide sequences using 2 bits per nucleotide. In addition encodes unknown nucleotides and lower-case \'masking\'.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \".nib\", \"data\": {\"uri\": \"format_3010\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \".nib (nibble) binary format of a nucleotide sequence using 4 bits per nucleotide (including unknown) and its lower-case \'masking\'.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SRF\", \"data\": {\"uri\": \"format_3017\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Sequence Read Format (SRF) of sequence trace data. Supports submission to the NCBI Short Read Archive.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"ZTR\", \"data\": {\"uri\": \"format_3018\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"ZTR format for storing chromatogram data from DNA sequencing instruments.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BCF\", \"data\": {\"uri\": \"format_3020\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"BCF, the binary version of Variant Call Format (VCF) for sequence variation (indels, polymorphisms, structural variation).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SFF\", \"data\": {\"uri\": \"format_3284\"}, \"ch\": [], \"es\": [\"Standard flowgram format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Standard flowgram format (SFF) is a binary file format used to encode results of pyrosequencing from the 454 Life Sciences platform for high-throughput sequencing.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BAI\", \"data\": {\"uri\": \"format_3327\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"BAM indexing format\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"CRAM\", \"data\": {\"uri\": \"format_3462\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Reference-based compression of alignment format\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GIF\", \"data\": {\"uri\": \"format_3467\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Graphics Interchange Format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"ebwt\", \"data\": {\"uri\": \"format_3484\"}, \"ch\": [], \"es\": [\"Bowtie index format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Bowtie format for indexed reference genome for \\\"small\\\" genomes.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"ebwtl\", \"data\": {\"uri\": \"format_3491\"}, \"ch\": [], \"es\": [\"Bowtie long index format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Bowtie format for indexed reference genome for \\\"large\\\" genomes.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"PDF\", \"data\": {\"uri\": \"format_3508\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Portable Document Format\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"DICOM format\", \"data\": {\"uri\": \"format_3548\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Medical image format corresponding to the Digital Imaging and Communications in Medicine (DICOM) standard.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"nii\", \"data\": {\"uri\": \"format_3549\"}, \"ch\": [], \"es\": [\"NIfTI-1 format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Medical image and metadata format of the Neuroimaging Informatics Technology Initiative.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"IDAT\", \"data\": {\"uri\": \"format_3578\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Proprietary file format for (raw) BeadArray data used by genomewide profiling platforms from Illumina Inc. This format is output directly from the scanner and stores summary intensities for each probe-type on an array.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"JPG\", \"data\": {\"uri\": \"format_3579\"}, \"ch\": [], \"es\": [\"JPEG\", \"jpeg\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Joint Picture Group file format for lossy graphics file.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"HDF5\", \"data\": {\"uri\": \"format_3590\"}, \"ch\": [{\"t\": \"Loom\", \"data\": {\"uri\": \"format_3913\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The Loom file format is based on HDF5, a standard for storing large numerical datasets. The Loom format is designed to efficiently hold large omics datasets. Typically, such data takes the form of a large matrix of numbers, along with metadata for the rows and columns.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [\"h5\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"HDF5 is a data model, library, and file format for storing and managing data, based on Hierarchical Data Format (HDF).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"TIFF\", \"data\": {\"uri\": \"format_3591\"}, \"ch\": [], \"es\": [\"tiff\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A versatile bitmap format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BMP\", \"data\": {\"uri\": \"format_3592\"}, \"ch\": [], \"es\": [\"bmp\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Standard bitmap storage format in the Microsoft Windows environment.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"im\", \"data\": {\"uri\": \"format_3593\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"IM is a format used by LabEye and other applications based on the IFUNC image processing library.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"pcd\", \"data\": {\"uri\": \"format_3594\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Photo CD format, which is the highest resolution format for images on a CD.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"pcx\", \"data\": {\"uri\": \"format_3595\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PCX is an image file format that uses a simple form of run-length encoding. It is lossless.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"ppm\", \"data\": {\"uri\": \"format_3596\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The PPM format is a lowest common denominator color image file format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"psd\", \"data\": {\"uri\": \"format_3597\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PSD (Photoshop Document) is a proprietary file that allows the user to work with the images\' individual layers even after the file has been saved.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"xbm\", \"data\": {\"uri\": \"format_3598\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"X BitMap is a plain text binary image format used by the X Window System used for storing cursor and icon bitmaps used in the X GUI.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"xpm\", \"data\": {\"uri\": \"format_3599\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"X PixMap (XPM) is an image file format used by the X Window System, it is intended primarily for creating icon pixmaps, and supports transparent pixels.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"rgb\", \"data\": {\"uri\": \"format_3600\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"RGB file format is the native raster graphics file format for Silicon Graphics workstations.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"pbm\", \"data\": {\"uri\": \"format_3601\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The PBM format is a lowest common denominator monochrome file format. It serves as the common language of a large family of bitmap image conversion filters.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"pgm\", \"data\": {\"uri\": \"format_3602\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The PGM format is a lowest common denominator grayscale file format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"PNG\", \"data\": {\"uri\": \"format_3603\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PNG is a file format for image compression.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"rast\", \"data\": {\"uri\": \"format_3605\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Sun Raster is a raster graphics file format used on SunOS by Sun Microsystems\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"bgzip\", \"data\": {\"uri\": \"format_3615\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Blocked GNU Zip format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"tabix\", \"data\": {\"uri\": \"format_3616\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"TAB-delimited genome position file index format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"xlsx\", \"data\": {\"uri\": \"format_3620\"}, \"ch\": [{\"t\": \"ObjTables\", \"data\": {\"uri\": \"format_3977\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"ObjTables is a toolkit for creating re-usable datasets that are both human and machine-readable, combining the ease of spreadsheets (e.g., Excel workbooks) with the rigor of schemas (classes, their attributes, the type of each attribute, and the possible relationships between instances of classes). ObjTables consists of a format for describing schemas for spreadsheets, numerous data types for science, a syntax for indicating the class and attribute represented by each table and column in a workbook, and software for using schemas to rigorously validate, merge, split, compare, and revision datasets.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"MS Excel spreadsheet format consisting of a set of XML documents stored in a ZIP-compressed file.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SQLite format\", \"data\": {\"uri\": \"format_3621\"}, \"ch\": [{\"t\": \"Gemini SQLite format\", \"data\": {\"uri\": \"format_3622\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Data format used by the SQLite database conformant to the Gemini schema.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Data format used by the SQLite database.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"snpeffdb\", \"data\": {\"uri\": \"format_3624\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"An index of a genome database, indexed for use by the snpeff tool.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"netCDF\", \"data\": {\"uri\": \"format_3650\"}, \"ch\": [], \"es\": [\"ANDI-MS\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format used by netCDF software  library for writing and reading chromatography-MS data files.  Also used to store trajectory atom coordinates information, such as the ones obtained by Molecular Dynamics simulations.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"K-mer countgraph\", \"data\": {\"uri\": \"format_3665\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A list of k-mers and their occurences in a dataset. Can also be used as an implicit De Bruijn graph.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"COMBINE OMEX\", \"data\": {\"uri\": \"format_3686\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Open Modeling EXchange format (OMEX) is a ZIPped format for encapsulating all information necessary for a modeling and simulation project in systems biology.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SRA format\", \"data\": {\"uri\": \"format_3698\"}, \"ch\": [], \"es\": [\"SRA\", \"SRA archive format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"SRA archive format (SRA) is the archive format used for input to the NCBI Sequence Read Archive.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"VDB\", \"data\": {\"uri\": \"format_3699\"}, \"ch\": [], \"es\": [\"SRA native format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"VDB (\'vertical database\') is the native format used for export from the NCBI Sequence Read Archive.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Tabix index file format\", \"data\": {\"uri\": \"format_3700\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Index file format used by the samtools package to index TAB-delimited genome position files.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"WIFF format\", \"data\": {\"uri\": \"format_3710\"}, \"ch\": [], \"es\": [\"wiff\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Mass spectrum file format from QSTAR and QTRAP instruments (ABI/Sciex).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Thermo RAW\", \"data\": {\"uri\": \"format_3712\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Proprietary file format for mass spectrometry data from Thermo Scientific.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"OME-TIFF\", \"data\": {\"uri\": \"format_3727\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Image file format used by the Open Microscopy Environment (OME).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BTrack\", \"data\": {\"uri\": \"format_3776\"}, \"ch\": [], \"es\": [\"BTrack (GTrack ecosystem of formats)\", \"BTrack format\", \"BioXSD/GTrack BTrack\", \"BioXSD|GTrack BTrack\", \"GTrack|BTrack|GSuite BTrack\", \"GTrack|GSuite|BTrack BTrack\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"BTrack is an HDF5-based binary format for genome or sequence feature tracks and their collections, suitable for integrative multi-track analysis. BTrack is a binary, compressed alternative to the GTrack and GSuite formats.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"proBAM\", \"data\": {\"uri\": \"format_3826\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \". proBAM is an adaptation of BAM (format_2572), which was extended to meet specific requirements entailed by proteomics data.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"ARB\", \"data\": {\"uri\": \"format_3830\"}, \"ch\": [], \"es\": [\"ARB binary format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Binary format used by the ARB software suite\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"ibd\", \"data\": {\"uri\": \"format_3839\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"ibd is a data format for mass spectrometry imaging data.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"MSAML\", \"data\": {\"uri\": \"format_3849\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A set of XML compliant markup components for describing multiple sequence alignments.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Waters RAW\", \"data\": {\"uri\": \"format_3858\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Proprietary file format for mass spectrometry data from Waters.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"HDF\", \"data\": {\"uri\": \"format_3873\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"HDF is the name of a set of file formats and libraries designed to store and organize large amounts of numerical data, originally developed at the National Center for Supercomputing Applications at the University of Illinois.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"PCAzip\", \"data\": {\"uri\": \"format_3874\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PCAZip format is a binary compressed file to store atom coordinates based on Essential Dynamics (ED) and Principal Component Analysis (PCA).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"XTC\", \"data\": {\"uri\": \"format_3875\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Portable binary format for trajectories produced by GROMACS package.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"TNG\", \"data\": {\"uri\": \"format_3876\"}, \"ch\": [], \"es\": [\"Trajectory Next Generation format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Trajectory Next Generation (TNG) is a format for storage of molecular simulation data. It is designed and implemented by the GROMACS development group, and it is called to be the substitute of the XTC format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BinPos\", \"data\": {\"uri\": \"format_3885\"}, \"ch\": [], \"es\": [\"Scripps Research Institute BinPos\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Scripps Research Institute BinPos format is a binary formatted file to store atom coordinates.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"msh\", \"data\": {\"uri\": \"format_3911\"}, \"ch\": [], \"es\": [\"Mash sketch\", \"min-hash sketch\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Mash sketch is a format for sequence / sequence checksum information. To make a sketch, each k-mer in a sequence is hashed, which creates a pseudo-random identifier. By sorting these hashes, a small subset from the top of the sorted list can represent the entire sequence.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Zarr\", \"data\": {\"uri\": \"format_3915\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The Zarr format is an implementation of chunked, compressed, N-dimensional arrays for storing data.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Docker image format\", \"data\": {\"uri\": \"format_3973\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A Docker image is a file, comprised of multiple layers, that is used to execute code in a Docker container. An image is essentially built from the instructions for a complete and executable version of an application, which relies on the host OS kernel.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"TAR format\", \"data\": {\"uri\": \"format_3981\"}, \"ch\": [], \"es\": [\"TAR\", \"Tarball\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"TAR archive file format generated by the Unix-based utility tar.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"WMV\", \"data\": {\"uri\": \"format_3986\"}, \"ch\": [], \"es\": [\"Windows Media Video format\", \"Windows movie file format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The proprietary native video format of various Microsoft programs such as Windows Media Player.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"ZIP format\", \"data\": {\"uri\": \"format_3987\"}, \"ch\": [], \"es\": [\"ZIP\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"ZIP is an archive file format that supports lossless data compression.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"LSM\", \"data\": {\"uri\": \"format_3988\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Zeiss\' proprietary image format based on TIFF.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GZIP format\", \"data\": {\"uri\": \"format_3989\"}, \"ch\": [], \"es\": [\"GNU Zip\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"GNU zip compressed file format common to Unix-based operating systems.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"AVI\", \"data\": {\"uri\": \"format_3990\"}, \"ch\": [], \"es\": [\"Audio Video Interleaved\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Audio Video Interleaved (AVI) format is a multimedia container format for AVI files, that allows synchronous audio-with-video playback.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"TrackDB\", \"data\": {\"uri\": \"format_3991\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A declaration file format for UCSC browsers track dataset display charateristics.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Stereolithography format\", \"data\": {\"uri\": \"format_3993\"}, \"ch\": [], \"es\": [\"stl\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"STL is a file format native to the stereolithography CAD software created by 3D Systems.  The format is used to save and share surface-rendered 3D images and also for 3D printing.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"U3D\", \"data\": {\"uri\": \"format_3994\"}, \"ch\": [], \"es\": [\"Universal 3D\", \"Universal 3D format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"U3D (Universal 3D) is a compressed file format and data structure for 3D computer graphics. It contains 3D model information such as triangle meshes, lighting, shading, motion data, lines and points with color and structure.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Texture file format\", \"data\": {\"uri\": \"format_3995\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Bitmap image format used for storing textures.\", \"hi\