\": [], \"co\": [], \"d\": \"Format used by the HMMER package for of an alignment of a hidden Markov model against a sequence database.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Data format for a sequence-profile alignment.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Article format\", \"data\": {\"uri\": \"format_2020\"}, \"ch\": [{\"t\": \"pmc\", \"data\": {\"uri\": \"format_1739\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Article format of the PubMed Central database.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"medline\", \"data\": {\"uri\": \"format_2194\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Abstract format used by MedLine database.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [\"Literature format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Data format for a full-text scientific article.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Text mining report format\", \"data\": {\"uri\": \"format_2021\"}, \"ch\": [{\"t\": \"iHOP format\", \"data\": {\"uri\": \"format_1740\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The format of iHOP (Information Hyperlinked over Proteins) text-mining result.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Data format of a report from text mining.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Enzyme kinetics report format\", \"data\": {\"uri\": \"format_2027\"}, \"ch\": [{\"t\": \"findkm\", \"data\": {\"uri\": \"format_1582\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A report format for the kinetics of enzyme-catalysed reaction(s) in a format generated by EMBOSS findkm. This includes Michaelis Menten plot, Hanes Woolf plot, Michaelis Menten constant (Km) and maximum velocity (Vmax).\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Data 