i\": \"format_4007\"}, \"ch\": [], \"es\": [\"MATLAB\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The file format for MATLAB scripts or functions.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of a workflow.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Tertiary structure format\", \"data\": {\"uri\": \"format_2033\"}, \"ch\": [{\"t\": \"PDB database entry format\", \"data\": {\"uri\": \"format_1475\"}, \"ch\": [{\"t\": \"PDB\", \"data\": {\"uri\": \"format_1476\"}, \"ch\": [], \"es\": [\"PDB format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Entry format of PDB database in PDB format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"mmCIF\", \"data\": {\"uri\": \"format_1477\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Entry format of PDB database in mmCIF format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"PDBML\", \"data\": {\"uri\": \"format_1478\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Entry format of PDB database in PDBML (XML) format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"pdbatom\", \"data\": {\"uri\": \"format_1950\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PDB sequence format (ATOM lines).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"pdbatomnuc\", \"data\": {\"uri\": \"format_1951\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PDB nucleotide sequence format (ATOM lines).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"pdbseqresnuc\", \"data\": {\"uri\": \"format_1952\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PDB nucleotide sequence format (SEQRES lines).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"pdbseqres\", \"data\": {\"uri\": \"format_1953\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PDB sequence format (SEQRES lines).\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [\"PDB entry