, \"ht\": []}, {\"t\": \"pcx\", \"data\": {\"uri\": \"format_3595\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PCX is an image file format that uses a simple form of run-length encoding. It is lossless.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"ppm\", \"data\": {\"uri\": \"format_3596\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The PPM format is a lowest common denominator color image file format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"psd\", \"data\": {\"uri\": \"format_3597\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PSD (Photoshop Document) is a proprietary file that allows the user to work with the images\' individual layers even after the file has been saved.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"xbm\", \"data\": {\"uri\": \"format_3598\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"X BitMap is a plain text binary image format used by the X Window System used for storing cursor and icon bitmaps used in the X GUI.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"xpm\", \"data\": {\"uri\": \"format_3599\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"X PixMap (XPM) is an image file format used by the X Window System, it is intended primarily for creating icon pixmaps, and supports transparent pixels.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"rgb\", \"data\": {\"uri\": \"format_3600\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"RGB file format is the native raster graphics file format for Silicon Graphics workstations.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"pbm\", \"data\": {\"uri\": \"format_3601\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The PBM format is a lowest common denominator monochrome file format. It serves as the common language of a large family of bitmap image conversion filters.\", \"hi\": [], \"ho\": [], \"h