b\": [], \"co\": [], \"d\": \"Systems Biology Markup Language (SBML), the standard XML format for models of biological processes such as for example metabolism, cell signaling, and gene regulation.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BioPAX\", \"data\": {\"uri\": \"format_3156\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"BioPAX is an exchange format for pathway data, with its data model defined in OWL.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"CopasiML\", \"data\": {\"uri\": \"format_3239\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"CopasiML, the native format of COPASI.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"CellML\", \"data\": {\"uri\": \"format_3240\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"CellML, the format for mathematical models of biological and other networks.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"sif\", \"data\": {\"uri\": \"format_3619\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"SIF (simple interaction file) Format - a network/pathway format used for instance in cytoscape.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GPML\", \"data\": {\"uri\": \"format_3657\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Graphical Pathway Markup Language (GPML) is an XML format used for exchanging biological pathways.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"COMBINE OMEX\", \"data\": {\"uri\": \"format_3686\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Open Modeling EXchange format (OMEX) is a ZIPped format for encapsulating all information necessary for a modeling and simulation project in systems biology.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SBtab\", \"data\": {\"uri\": \"format_3688\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"SBtab is a tabular format for biochemical network models.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BCML\", \"data\": {\"uri\": \"format_3689\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Biological Connection Markup Language (BCML) is an XML format for biological pathways.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SBGN-ML\", \"data\": {\"uri\": \"format_3692\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"SBGN-ML is an XML format for Systems Biology Graphical Notation (SBGN) diagrams of biological pathways or networks.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"VisML\", \"data\": {\"uri\": \"format_3821\"}, \"ch\": [], \"es\": [\"VisANT xml\", \"VisANT xml format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Default XML format of VisANT, containing all the network information.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GML\", \"data\": {\"uri\": \"format_3822\"}, \"ch\": [], \"es\": [\"GML format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"GML (Graph Modeling Language) is a text file format supporting network data with a very easy syntax. It is used by Graphlet, Pajek, yEd, LEDA and NetworkX.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"KGML\", \"data\": {\"uri\": \"format_3847\"}, \"ch\": [], \"es\": [\"KEGG Markup Language\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The KEGG Markup Language (KGML) is an exchange format of the KEGG pathway maps, which is converted from internally used KGML+ (KGML+SVG) format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"NeuroML\", \"data\": {\"uri\": \"format_3971\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A model description language for computational neuroscience.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BNGL\", \"data\": {\"uri\": \"format_3972\"}, \"ch\": [], \"es\": [\"BioNetGen Language\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"BioNetGen is a format for the specification and simulation of rule-based models of biochemical systems, including signal transduction, metabolic, and genetic regulatory networks.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Data format for a biological pathway or network.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Sequence-profile alignment format\", \"data\": {\"uri\": \"format_2014\"}, \"ch\": [{\"t\": \"Sequence-MEME profile alignment\", \"data\": {\"uri\": \"format_1419\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format for alignment of molecular sequences to MEME profiles (position-dependent scoring matrices) as generated by the MAST tool from the MEME package.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"HMMER profile alignment (sequences versus HMMs)\", \"data\": {\"uri\": \"format_1421\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format used by the HMMER package for an alignment of a sequence against a hidden Markov model database.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"HMMER profile alignment (HMM versus sequences)\", \"data\": {\"uri\": \"format_1422\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format used by the HMMER package for of an alignment of a hidden Markov model against a sequence database.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Data format for a sequence-profile alignment.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Article format\", \"data\": {\"uri\": \"format_2020\"}, \"ch\": [{\"t\": \"pmc\", \"data\": {\"uri\": \"format_1739\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Article format of the PubMed Central database.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"medline\", \"data\": {\"uri\": \"format_2194\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Abstract format used by MedLine database.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [\"Literature format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Data format for a full-text scientific article.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Text mining report format\", \"data\": {\"uri\": \"format_2021\"}, \"ch\": [{\"t\": \"iHOP format\", \"data\": {\"uri\": \"format_1740\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The format of iHOP (Information Hyperlinked over Proteins) text-mining result.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Data format of a report from text mining.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Enzyme kinetics report format\", \"data\": {\"uri\": \"format_2027\"}, \"ch\": [{\"t\": \"findkm\", \"data\": {\"uri\": \"format_1582\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A report format for the kinetics of enzyme-catalysed reaction(s) in a format generated by EMBOSS findkm. This includes Michaelis Menten plot, Hanes Woolf plot, Michaelis Menten constant (Km) and maximum velocity (Vmax).\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Data format for reports on enzyme kinetics.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Chemical data format\", \"data\": {\"uri\": \"format_2030\"}, \"ch\": [{\"t\": \"HET group dictionary entry format\", \"data\": {\"uri\": \"format_1705\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The format of an entry from the HET group dictionary (HET groups from PDB files).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"SDF\", \"data\": {\"uri\": \"format_3814\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"SDF is one of a family of chemical-data file formats developed by MDL Information Systems; it is intended especially for structural information.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Molfile\", \"data\": {\"uri\": \"format_3815\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"An MDL Molfile is a file format for holding information about the atoms, bonds, connectivity and coordinates of a molecule.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Mol2\", \"data\": {\"uri\": \"format_3816\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Complete, portable representation of a SYBYL molecule. ASCII file which contains all the information needed to reconstruct a SYBYL molecule.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BcForms\", \"data\": {\"uri\": \"format_3951\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"BcForms is a format for abstractly describing the molecular structure (atoms and bonds) of macromolecular complexes as a collection of subunits and crosslinks. Each subunit can be described with BpForms (format_3909) or SMILES (data_2301). BcForms uses an ontology of crosslinks to abstract the chemical details of crosslinks from the descriptions of complexes (see https://bpforms.org/crosslink.html).\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [\"Chemical compound annotation format\", \"Chemical structure format\", \"Small molecule report format\", \"Small molecule structure format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of a report on a chemical compound.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Gene annotation format\", \"data\": {\"uri\": \"format_2031\"}, \"ch\": [{\"t\": \"est2genome format\", \"data\": {\"uri\": \"format_1316\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of a report on exon-intron structure generated by EMBOSS est2genome.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"OrthoXML\", \"data\": {\"uri\": \"format_3850\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"OrthoXML is designed broadly to allow the storage and comparison of orthology data from any ortholog database. It establishes a structure for describing orthology relationships while still allowing flexibility for database-specific information to be encapsulated in the same format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"WEGO\", \"data\": {\"uri\": \"format_3979\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"WEGO native format used by the Web Gene Ontology Annotation Plot application.   Tab-delimited format with gene names and others GO IDs (columns) with one annotation record per line.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [\"Gene features format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of a report on a particular locus, gene, gene system or groups of genes.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Workflow format\", \"data\": {\"uri\": \"format_2032\"}, \"ch\": [{\"t\": \"Taverna workflow format\", \"data\": {\"uri\": \"format_1665\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of Taverna workflows.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"KNIME datatable format\", \"data\": {\"uri\": \"format_3765\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Data table formatted such that it can be passed/streamed within the KNIME platform.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"CWL\", \"data\": {\"uri\": \"format_3857\"}, \"ch\": [], \"es\": [\"Common Workflow Language\", \"CommonWL\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Common Workflow Language (CWL) format for description of command-line tools and workflows.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"gxformat2\", \"data\": {\"uri\": \"format_3985\"}, \"ch\": [], \"es\": [\"Galaxy workflow format\", \"GalaxyWF\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"An emerging format for high-level Galaxy workflow description.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Python script\", \"data\": {\"uri\": \"format_3996\"}, \"ch\": [], \"es\": [\"Python\", \"Python program\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format for scripts writtenin Python - a widely used high-level programming language for general-purpose programming.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Perl script\", \"data\": {\"uri\": \"format_3998\"}, \"ch\": [], \"es\": [\"Perl\", \"Perl program\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format for scripts written in Perl - a family of high-level, general-purpose, interpreted, dynamic programming languages.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"R script\", \"data\": {\"uri\": \"format_3999\"}, \"ch\": [], \"es\": [\"R\", \"R program\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format for scripts written in the R language - an open source programming language and software environment for statistical computing and graphics that is supported by the R Foundation for Statistical Computing.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"R markdown\", \"data\": {\"uri\": \"format_4000\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"A file format for making dynamic documents (R Markdown scripts) with the R language.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"MATLAB script\", \"data\": {\"uri\": \"format_4007\"}, \"ch\": [], \"es\": [\"MATLAB\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The file format for MATLAB scripts or functions.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of a workflow.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Tertiary structure format\", \"data\": {\"uri\": \"format_2033\"}, \"ch\": [{\"t\": \"PDB database entry format\", \"data\": {\"uri\": \"format_1475\"}, \"ch\": [{\"t\": \"PDB\", \"data\": {\"uri\": \"format_1476\"}, \"ch\": [], \"es\": [\"PDB format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Entry format of PDB database in PDB format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"mmCIF\", \"data\": {\"uri\": \"format_1477\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Entry format of PDB database in mmCIF format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"PDBML\", \"data\": {\"uri\": \"format_1478\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Entry format of PDB database in PDBML (XML) format.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"pdbatom\", \"data\": {\"uri\": \"format_1950\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PDB sequence format (ATOM lines).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"pdbatomnuc\", \"data\": {\"uri\": \"format_1951\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PDB nucleotide sequence format (ATOM lines).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"pdbseqresnuc\", \"data\": {\"uri\": \"format_1952\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PDB nucleotide sequence format (SEQRES lines).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"pdbseqres\", \"data\": {\"uri\": \"format_1953\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PDB sequence format (SEQRES lines).\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [\"PDB entry format\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of an entry (or part of an entry) from the PDB database.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"XYZ\", \"data\": {\"uri\": \"format_3877\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The XYZ chemical file format is widely supported by many programs, although many slightly different XYZ file formats coexist (Tinker XYZ, UniChem XYZ, etc.). Basic information stored for each atom in the system are x, y and z coordinates and atom element/atomic number.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"mdcrd\", \"data\": {\"uri\": \"format_3878\"}, \"ch\": [], \"es\": [\"AMBER trajectory format\", \"inpcrd\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"AMBER trajectory (also called mdcrd), with 10 coordinates per line and format F8.3 (fixed point notation with field width 8 and 3 decimal places).\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GROMACS top\", \"data\": {\"uri\": \"format_3880\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"GROMACS MD package top textual files define an entire structure system topology, either directly, or by including itp files.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"AMBER top\", \"data\": {\"uri\": \"format_3881\"}, \"ch\": [], \"es\": [\"AMBER Parm\", \"AMBER Parm7\", \"Parm7\", \"Prmtop\", \"Prmtop7\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"AMBER Prmtop file (version 7) is a structure topology text file divided in several sections designed to be parsed easily using simple Fortran code. Each section contains particular topology information, such as atom name, charge, mass, angles, dihedrals, etc.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"PSF\", \"data\": {\"uri\": \"format_3882\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"X-Plor Protein Structure Files (PSF) are structure topology files used by NAMD and CHARMM molecular simulations programs. PSF files contain six main sections of interest: atoms, bonds, angles, dihedrals, improper dihedrals (force terms used to maintain planarity) and cross-terms.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"GROMACS itp\", \"data\": {\"uri\": \"format_3883\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"GROMACS itp files (include topology) contain structure topology information, and are tipically included in GROMACS topology files (GROMACS top). Itp files are used to define individual (or multiple) components of a topology as a separate file. This is particularly useful if there is a molecule that is used frequently, and also reduces the size of the system topology file, splitting it in different parts.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"RST\", \"data\": {\"uri\": \"format_3886\"}, \"ch\": [], \"es\": [\"restrt\", \"rst7\"], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"AMBER coordinate/restart file with 6 coordinates per line and decimal format F12.7 (fixed point notation with field width 12 and 7 decimal places)\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"CHARMM rtf\", \"data\": {\"uri\": \"format_3887\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of CHARMM Residue Topology Files (RTF), which define groups by including the atoms, the properties of the group, and bond and charge information.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"trr\", \"data\": {\"uri\": \"format_3910\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of trr files that contain the trajectory of a simulation experiment used by GROMACS.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Data format for a molecular tertiary structure.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Chemical formula format\", \"data\": {\"uri\": \"format_2035\"}, \"ch\": [{\"t\": \"SMILES\", \"data\": {\"uri\": \"format_1196\"}, \"ch\": [{\"t\": \"smarts\", \"data\": {\"uri\": \"format_1200\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"SMILES ARbitrary Target Specification (SMARTS) format for chemical structure specification, which is a subset of the SMILES line notation.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Chemical structure specified in Simplified Molecular Input Line Entry System (SMILES) line notation.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"InChI\", \"data\": {\"uri\": \"format_1197\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Chemical structure specified in IUPAC International Chemical Identifier (InChI) line notation.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"mf\", \"data\": {\"uri\": \"format_1198\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Chemical structure specified by Molecular Formula (MF), including a count of each element in a compound.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"InChIKey\", \"data\": {\"uri\": \"format_1199\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"The InChIKey (hashed InChI) is a fixed length (25 character) condensed digital representation of an InChI chemical structure specification. It uniquely identifies a chemical compound.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"BpForms\", \"data\": {\"uri\": \"format_3909\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"BpForms is a string format for concretely representing the primary structures of biopolymers, including DNA, RNA, and proteins that include non-canonical nucleic and amino acids. See https://www.bpforms.org for more information.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Text format of a chemical formula.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Phylogenetic character data format\", \"data\": {\"uri\": \"format_2036\"}, \"ch\": [{\"t\": \"Phylogenetic continuous quantitative character format\", \"data\": {\"uri\": \"format_2037\"}, \"ch\": [{\"t\": \"Phylip continuous quantitative characters\", \"data\": {\"uri\": \"format_1430\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PHYLIP file format for continuous quantitative character data.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Phylip character frequencies format\", \"data\": {\"uri\": \"format_1432\"}, \"ch\": [], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"PHYLIP file format for phylogenetics character frequency data.\", \"hi\": [], \"ho\": [], \"ht\": []}], \"es\": [], \"ns\": [], \"rb\": [], \"co\": [], \"d\": \"Format of phylogenetic continuous quantitative character data.\", \"hi\": [], \"ho\": [], \"ht\": []}, {\"t\": \"Phylogenetic discrete states format\", \"data\": {\"uri\": \"format_2038\"}, \"