\": \"Format||Textual format||PSL\", \"k\": \"format_1915||format_2330||format_3007\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||PSL\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3007\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||PSL\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3007\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Multiple Alignment Format (MAF) supporting alignments of whole genomes with rearrangements, directions, multiple pieces to the alignment, and so forth.\", \"n\": \"MAF\", \"ns\": [], \"u\": \"format_3008\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||MAF\", \"k\": \"format_1915||format_2330||format_3008\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||MAF\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3008\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (text)||MAF\", \"k\": \"format_1915||format_2350||format_1921||format_2554||format_3008\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"genePred table format for gene prediction tracks.\", \"n\": \"genePred\", \"ns\": [], \"u\": \"format_3011\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||genePred\", \"k\": \"format_1915||format_2330||format_3011\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||genePred\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3011\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Personal Genome SNP (pgSnp) format for sequence variation tracks (indels and polymorphisms), supported by the UCSC Genome Browser.\", \"n\": \"pgSnp\", \"ns\": [], \"u\": \"format_3012\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||pgSnp\", \"k\": \"format_1915||format_2330||format_3012\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||pgSnp\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3012\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"axt format of alignments, typically produced from BLASTZ.\", \"n\": \"axt\", \"ns\": [], \"u\": \"format_3013\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||axt\", \"k\": \"format_1915||format_2330||format_3013\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||axt\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3013\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"LAV format of alignments generated by BLASTZ and LASTZ.\", \"n\": \"LAV\", \"ns\": [], \"u\": \"format_3014\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||LAV\", \"k\": \"format_1915||format_2330||format_3014\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||LAV\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3014\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Pileup format of alignment of sequences (e.g. sequencing reads) to (a) reference sequence(s). Contains aligned bases per base of the reference sequence(s).\", \"n\": \"Pileup\", \"ns\": [], \"u\": \"format_3015\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Pileup\", \"k\": \"format_1915||format_2330||format_3015\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||Pileup\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3015\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Variant Call Format (VCF) for sequence variation (indels, polymorphisms, structural variation).\", \"n\": \"VCF\", \"ns\": [], \"u\": \"format_3016\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||VCF\", \"k\": \"format_1915||format_2330||format_3016\"}, {\"n\": \"Format||Format (by type of data)||Sequence variation annotation format||VCF\", \"k\": \"format_1915||format_2350||format_2921||format_3016\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GTrack is a generic and optimised tabular format for genome or sequence feature tracks. GTrack unifies the power of other track formats (e.g. GFF3, BED, WIG), and while optimised in size, adds more flexibility, customisation, and automation (\\\"machine understandability\\\").\", \"n\": \"GTrack\", \"ns\": [], \"u\": \"format_3164\", \"es\": [\"BioXSD/GTrack GTrack\", \"BioXSD|GTrack GTrack\", \"GTrack format\", \"GTrack|BTrack|GSuite GTrack\", \"GTrack|GSuite|BTrack GTrack\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GTrack\", \"k\": \"format_1915||format_2330||format_3164\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)||GTrack\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206||format_3164\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||GTrack\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3164\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Cytoband format for chromosome cytobands.\", \"n\": \"Cytoband format\", \"ns\": [], \"u\": \"format_3235\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Cytoband format\", \"k\": \"format_1915||format_2330||format_3235\"}, {\"n\": \"Format||Format (by type of data)||Sequence range format||Cytoband format\", \"k\": \"format_1915||format_2350||format_2078||format_3235\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Tabular Molecular Interaction format (MITAB), standardised by HUPO PSI MI.\", \"n\": \"PSI MI TAB (MITAB)\", \"ns\": [], \"u\": \"format_3242\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||PSI MI TAB (MITAB)\", \"k\": \"format_1915||format_2330||format_3242\"}, {\"n\": \"Format||Format (by type of data)||Protein interaction format||PSI MI TAB (MITAB)\", \"k\": \"format_1915||format_2350||format_2054||format_3242\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A human-readable encoding for the Web Ontology Language (OWL).\", \"n\": \"OWL Functional Syntax\", \"ns\": [], \"u\": \"format_3252\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||OWL Functional Syntax\", \"k\": \"format_1915||format_2330||format_3252\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||OWL format||OWL Functional Syntax\", \"k\": \"format_1915||format_2350||format_2195||format_2197||format_3252\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||OWL format||OWL Functional Syntax\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_2197||format_3252\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||OWL format||OWL Functional Syntax\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_2197||format_3252\"}, {\"n\": \"Format||RDF format||OWL format||OWL Functional Syntax\", \"k\": \"format_1915||format_2376||format_2197||format_3252\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A syntax for writing OWL class expressions.\", \"n\": \"Manchester OWL Syntax\", \"ns\": [], \"u\": \"format_3253\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Manchester OWL Syntax\", \"k\": \"format_1915||format_2330||format_3253\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||OWL format||Manchester OWL Syntax\", \"k\": \"format_1915||format_2350||format_2195||format_2197||format_3253\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||OWL format||Manchester OWL Syntax\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_2197||format_3253\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||OWL format||Manchester OWL Syntax\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_2197||format_3253\"}, {\"n\": \"Format||RDF format||OWL format||Manchester OWL Syntax\", \"k\": \"format_1915||format_2376||format_2197||format_3253\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A superset of the \\\"Description-Logic Knowledge Representation System Specification from the KRSS Group of the ARPA Knowledge Sharing Effort\\\".\", \"n\": \"KRSS2 Syntax\", \"ns\": [], \"u\": \"format_3254\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||KRSS2 Syntax\", \"k\": \"format_1915||format_2330||format_3254\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||KRSS2 Syntax\", \"k\": \"format_1915||format_2350||format_2195||format_3254\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The Terse RDF Triple Language (Turtle) is a human-friendly serialisation format for RDF (Resource Description Framework) graphs.\", \"n\": \"Turtle\", \"ns\": [], \"u\": \"format_3255\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Turtle\", \"k\": \"format_1915||format_2330||format_3255\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||Turtle\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_3255\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||Turtle\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_3255\"}, {\"n\": \"Format||RDF format||Turtle\", \"k\": \"format_1915||format_2376||format_3255\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A plain text serialisation format for RDF (Resource Description Framework) graphs, and a subset of the Turtle (Terse RDF Triple Language) format.\", \"n\": \"N-Triples\", \"ns\": [], \"u\": \"format_3256\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||N-Triples\", \"k\": \"format_1915||format_2330||format_3256\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||N-Triples\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_3256\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||N-Triples\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_3256\"}, {\"n\": \"Format||RDF format||N-Triples\", \"k\": \"format_1915||format_2376||format_3256\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A shorthand non-XML serialisation of Resource Description Framework model, designed with human-readability in mind.\", \"n\": \"Notation3\", \"ns\": [], \"u\": \"format_3257\", \"es\": [\"N3\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Notation3\", \"k\": \"format_1915||format_2330||format_3257\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||Notation3\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_3257\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||Notation3\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_3257\"}, {\"n\": \"Format||RDF format||Notation3\", \"k\": \"format_1915||format_2376||format_3257\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The PED/MAP file describes data used by the Plink package.\", \"n\": \"PED/MAP\", \"ns\": [], \"u\": \"format_3288\", \"es\": [\"Plink PED/MAP\"], \"ch\": [{\"n\": \"MAP\", \"u\": \"format_3285\"}, {\"n\": \"PED\", \"u\": \"format_3286\"}], \"p\": [{\"n\": \"Format||Textual format||PED/MAP\", \"k\": \"format_1915||format_2330||format_3288\"}, {\"n\": \"Format||Format (by type of data)||Individual genetic data format||PED/MAP\", \"k\": \"format_1915||format_2350||format_3287||format_3288\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The MAP file describes SNPs and is used by the Plink package.\", \"n\": \"MAP\", \"ns\": [], \"u\": \"format_3285\", \"es\": [\"Plink MAP\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||PED/MAP||MAP\", \"k\": \"format_1915||format_2330||format_3288||format_3285\"}, {\"n\": \"Format||Format (by type of data)||Individual genetic data format||PED/MAP||MAP\", \"k\": \"format_1915||format_2350||format_3287||format_3288||format_3285\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The PED file describes individuals and genetic data and is used by the Plink package.\", \"n\": \"PED\", \"ns\": [], \"u\": \"format_3286\", \"es\": [\"Plink PED\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||PED/MAP||PED\", \"k\": \"format_1915||format_2330||format_3288||format_3286\"}, {\"n\": \"Format||Format (by type of data)||Individual genetic data format||PED/MAP||PED\", \"k\": \"format_1915||format_2350||format_3287||format_3288||format_3286\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"File format of a CT (Connectivity Table) file from the RNAstructure package.\", \"n\": \"CT\", \"ns\": [], \"u\": \"format_3309\", \"es\": [\"Connect format\", \"Connectivity Table file format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||CT\", \"k\": \"format_1915||format_2330||format_3309\"}, {\"n\": \"Format||Format (by type of data)||RNA secondary structure format||CT\", \"k\": \"format_1915||format_2350||format_2076||format_3309\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"XRNA old input style format.\", \"n\": \"SS\", \"ns\": [], \"u\": \"format_3310\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||SS\", \"k\": \"format_1915||format_2330||format_3310\"}, {\"n\": \"Format||Format (by type of data)||RNA secondary structure format||SS\", \"k\": \"format_1915||format_2350||format_2076||format_3310\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format for the Genetic Data Environment (GDE).\", \"n\": \"GDE\", \"ns\": [], \"u\": \"format_3312\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GDE\", \"k\": \"format_1915||format_2330||format_3312\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (text)||GDE\", \"k\": \"format_1915||format_2350||format_1919||format_2551||format_3312\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of the cytoscape input file of gene expression ratios or values are specified over one or more experiments.\", \"n\": \"Cytoscape input file format\", \"ns\": [], \"u\": \"format_3477\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Cytoscape input file format\", \"k\": \"format_1915||format_2330||format_3477\"}, {\"n\": \"Format||Format (by type of data)||Gene expression report format||Cytoscape input file format\", \"k\": \"format_1915||format_2350||format_2058||format_3477\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Some format based on the GCG format.\", \"n\": \"GCG format variant\", \"ns\": [], \"u\": \"format_3486\", \"es\": [], \"ch\": [{\"n\": \"GCG\", \"u\": \"format_1935\"}, {\"n\": \"GCG MSF\", \"u\": \"format_1947\"}, {\"n\": \"RSF\", \"u\": \"format_3485\"}], \"p\": [{\"n\": \"Format||Textual format||GCG format variant\", \"k\": \"format_1915||format_2330||format_3486\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (text)||GCG format variant\", \"k\": \"format_1915||format_2350||format_1919||format_2551||format_3486\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (text)||GCG format variant\", \"k\": \"format_1915||format_2350||format_1921||format_2554||format_3486\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GCG sequence file format.\", \"n\": \"GCG\", \"ns\": [], \"u\": \"format_1935\", \"es\": [\"GCG SSF\"], \"ch\": [], \"p\": {\"n\": \"Format||Textual format||GCG format variant||GCG\", \"k\": \"format_1915||format_2330||format_3486||format_1935\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GCG MSF (multiple sequence file) file format.\", \"n\": \"GCG MSF\", \"ns\": [], \"u\": \"format_1947\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GCG format variant||GCG MSF\", \"k\": \"format_1915||format_2330||format_3486||format_1947\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (text)||GCG format variant||GCG MSF\", \"k\": \"format_1915||format_2350||format_1919||format_2551||format_3486||format_1947\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (text)||GCG format variant||GCG MSF\", \"k\": \"format_1915||format_2350||format_1921||format_2554||format_3486||format_1947\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Rich sequence format.\", \"n\": \"RSF\", \"ns\": [], \"u\": \"format_3485\", \"es\": [\"GCG RSF\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GCG format variant||RSF\", \"k\": \"format_1915||format_2330||format_3486||format_3485\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (text)||GCG format variant||RSF\", \"k\": \"format_1915||format_2350||format_1919||format_2551||format_3486||format_3485\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (text)||GCG format variant||RSF\", \"k\": \"format_1915||format_2350||format_1921||format_2554||format_3486||format_3485\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Ensembl standard format for variation data.\", \"n\": \"Ensembl variation file format\", \"ns\": [], \"u\": \"format_3499\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Ensembl variation file format\", \"k\": \"format_1915||format_2330||format_3499\"}, {\"n\": \"Format||Format (by type of data)||Sequence variation annotation format||Ensembl variation file format\", \"k\": \"format_1915||format_2350||format_2921||format_3499\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Text-based tagged file format for medical images generated using the MetaImage software package.\", \"n\": \"mhd\", \"ns\": [], \"u\": \"format_3550\", \"es\": [\"Metalmage format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||mhd\", \"k\": \"format_1915||format_2330||format_3550\"}, {\"n\": \"Format||Format (by type of data)||Image format||mhd\", \"k\": \"format_1915||format_2350||format_3547||format_3550\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Nearly Raw Rasta Data format designed to support scientific visualisation and image processing involving N-dimensional raster data.\", \"n\": \"nrrd\", \"ns\": [], \"u\": \"format_3551\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||nrrd\", \"k\": \"format_1915||format_2330||format_3551\"}, {\"n\": \"Format||Format (by type of data)||Image format||nrrd\", \"k\": \"format_1915||format_2350||format_3547||format_3551\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"File format used for scripts written in the R programming language for execution within the R software environment, typically for statistical computation and graphics.\", \"n\": \"R file format\", \"ns\": [], \"u\": \"format_3554\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||R file format\", \"k\": \"format_1915||format_2330||format_3554\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"File format used for scripts for the Statistical Package for the Social Sciences.\", \"n\": \"SPSS\", \"ns\": [], \"u\": \"format_3555\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||SPSS\", \"k\": \"format_1915||format_2330||format_3555\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Reporter Code Count-A data file (.csv) output by the Nanostring nCounter Digital Analyzer, which contains gene sample information, probe information and probe counts.\", \"n\": \"rcc\", \"ns\": [], \"u\": \"format_3580\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||rcc\", \"k\": \"format_1915||format_2330||format_3580\"}, {\"n\": \"Format||Format (by type of data)||Gene expression report format||rcc\", \"k\": \"format_1915||format_2350||format_2058||format_3580\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"ARFF (Attribute-Relation File Format) is an ASCII text file format that describes a list of instances sharing a set of attributes.\", \"n\": \"arff\", \"ns\": [], \"u\": \"format_3581\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||arff\", \"k\": \"format_1915||format_2330||format_3581\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"AFG is a single text-based file assembly format  that holds read and consensus information together\", \"n\": \"afg\", \"ns\": [], \"u\": \"format_3582\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||afg\", \"k\": \"format_1915||format_2330||format_3582\"}, {\"n\": \"Format||Format (by type of data)||Sequence assembly format||Sequence assembly format (text)||afg\", \"k\": \"format_1915||format_2350||format_2055||format_2561||format_3582\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The bedGraph format allows display of continuous-valued data in track format. This display type is useful for probability scores and transcriptome data\", \"n\": \"bedgraph\", \"ns\": [], \"u\": \"format_3583\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||bedgraph\", \"k\": \"format_1915||format_2330||format_3583\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||bedgraph\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3583\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Tabular format of chromosome names and sizes used by Galaxy.\", \"n\": \"chrominfo\", \"ns\": [], \"u\": \"format_3587\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Textual format||chrominfo\", \"k\": \"format_1915||format_2330||format_3587\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Custom Sequence annotation track format used by Galaxy.\", \"n\": \"customtrack\", \"ns\": [], \"u\": \"format_3588\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||customtrack\", \"k\": \"format_1915||format_2330||format_3588\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||customtrack\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3588\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences).\", \"n\": \"qual\", \"ns\": [], \"u\": \"format_3607\", \"es\": [], \"ch\": [{\"n\": \"qualsolexa\", \"u\": \"format_3608\"}, {\"n\": \"qualillumina\", \"u\": \"format_3609\"}, {\"n\": \"qualsolid\", \"u\": \"format_3610\"}, {\"n\": \"qual454\", \"u\": \"format_3611\"}], \"p\": {\"n\": \"Format||Textual format||qual\", \"k\": \"format_1915||format_2330||format_3607\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) for Solexa/Illumina 1.0 format.\", \"n\": \"qualsolexa\", \"ns\": [], \"u\": \"format_3608\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Textual format||qual||qualsolexa\", \"k\": \"format_1915||format_2330||format_3607||format_3608\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) from Illumina 1.5 and before Illumina 1.8.\", \"n\": \"qualillumina\", \"ns\": [], \"u\": \"format_3609\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Textual format||qual||qualillumina\", \"k\": \"format_1915||format_2330||format_3607||format_3609\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) for SOLiD data.\", \"n\": \"qualsolid\", \"ns\": [], \"u\": \"format_3610\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Textual format||qual||qualsolid\", \"k\": \"format_1915||format_2330||format_3607||format_3610\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"FASTQ format subset for Phred sequencing quality score data only (no sequences) from 454 sequencers.\", \"n\": \"qual454\", \"ns\": [], \"u\": \"format_3611\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Textual format||qual||qual454\", \"k\": \"format_1915||format_2330||format_3607||format_3611\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"mzTab is a tab-delimited format for mass spectrometry-based proteomics and metabolomics results.\", \"n\": \"mzTab\", \"ns\": [], \"u\": \"format_3681\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||mzTab\", \"k\": \"format_1915||format_2330||format_3681\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||mzTab\", \"k\": \"format_1915||format_2350||format_3245||format_3681\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The Investigation / Study / Assay (ISA) tab-delimited (TAB) format incorporates metadata from\\nexperiments employing a combination of technologies.\", \"n\": \"ISA-TAB\", \"ns\": [], \"u\": \"format_3687\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||ISA-TAB\", \"k\": \"format_1915||format_2330||format_3687\"}, {\"n\": \"Format||Format (by type of data)||Gene expression report format||ISA-TAB\", \"k\": \"format_1915||format_2350||format_2058||format_3687\"}, {\"n\": \"Format||Format (by type of data)||Experiment annotation format||ISA-TAB\", \"k\": \"format_1915||format_2350||format_3167||format_3687\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"SBtab is a tabular format for biochemical network models.\", \"n\": \"SBtab\", \"ns\": [], \"u\": \"format_3688\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||SBtab\", \"k\": \"format_1915||format_2330||format_3688\"}, {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||SBtab\", \"k\": \"format_1915||format_2350||format_2013||format_3688\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Biological Expression Language (BEL) is a textual format for representing scientific findings in life sciences in a computable form.\", \"n\": \"BEL\", \"ns\": [], \"u\": \"format_3691\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||BEL\", \"k\": \"format_1915||format_2330||format_3691\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"AGP is a tabular format for a sequence assembly (a contig, a scaffold/supercontig, or a chromosome).\", \"n\": \"AGP\", \"ns\": [], \"u\": \"format_3693\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||AGP\", \"k\": \"format_1915||format_2330||format_3693\"}, {\"n\": \"Format||Format (by type of data)||Sequence assembly format||AGP\", \"k\": \"format_1915||format_2350||format_2055||format_3693\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"PostScript format\", \"n\": \"PS\", \"ns\": [], \"u\": \"format_3696\", \"es\": [\"PostScript\"], \"ch\": [{\"n\": \"EPS\", \"u\": \"format_3466\"}], \"p\": [{\"n\": \"Format||Textual format||PS\", \"k\": \"format_1915||format_2330||format_3696\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Encapsulated PostScript format\", \"n\": \"EPS\", \"ns\": [], \"u\": \"format_3466\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||PS||EPS\", \"k\": \"format_1915||format_2330||format_3696||format_3466\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Tab-delimited text files of GenePattern that contain a column for each sample, a row for each gene, and an expression value for each gene in each sample.\", \"n\": \"GCT/Res format\", \"ns\": [], \"u\": \"format_3709\", \"es\": [\"GCT format\", \"Res format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GCT/Res format\", \"k\": \"format_1915||format_2330||format_3709\"}, {\"n\": \"Format||Format (by type of data)||Gene expression report format||GCT/Res format\", \"k\": \"format_1915||format_2350||format_2058||format_3709\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"\\\"Raw\\\" result file from Mascot database search.\", \"n\": \"Mascot .dat file\", \"ns\": [], \"u\": \"format_3713\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Mascot .dat file\", \"k\": \"format_1915||format_2330||format_3713\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||Mascot .dat file\", \"k\": \"format_1915||format_2350||format_3245||format_3713\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of peak list files from Andromeda search engine (MaxQuant) that consist of arbitrarily many spectra.\", \"n\": \"MaxQuant APL peaklist format\", \"ns\": [], \"u\": \"format_3714\", \"es\": [\"MaxQuant APL\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||MaxQuant APL peaklist format\", \"k\": \"format_1915||format_2330||format_3714\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||MaxQuant APL peaklist format\", \"k\": \"format_1915||format_2350||format_3245||format_3714\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The LocARNA PP format combines sequence or alignment information and (respectively, single or consensus) ensemble probabilities into an PP 2.0 record.\", \"n\": \"LocARNA PP\", \"ns\": [], \"u\": \"format_3728\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||LocARNA PP\", \"k\": \"format_1915||format_2330||format_3728\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Input format used by the Database of Genotypes and Phenotypes (dbGaP).\", \"n\": \"dbGaP format\", \"ns\": [], \"u\": \"format_3729\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||dbGaP format\", \"k\": \"format_1915||format_2330||format_3729\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The BIological Observation Matrix (BIOM) is a format for representing biological sample by observation contingency tables in broad areas of comparative omics. The primary use of this format is to represent OTU tables and metagenome tables.\", \"n\": \"BIOM format\", \"ns\": [], \"u\": \"format_3746\", \"es\": [\"BIological Observation Matrix format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||BIOM format\", \"k\": \"format_1915||format_2330||format_3746\"}, {\"n\": \"Format||Format (by type of data)||Biodiversity data format||BIOM format\", \"k\": \"format_1915||format_2350||format_3706||format_3746\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Tabular data represented as values in a text file delimited by some character.\", \"n\": \"DSV\", \"ns\": [], \"u\": \"format_3751\", \"es\": [\"Delimiter-separated values\"], \"ch\": [{\"n\": \"TSV\", \"u\": \"format_3475\"}, {\"n\": \"CSV\", \"u\": \"format_3752\"}], \"p\": [{\"n\": \"Format||Textual format||DSV\", \"k\": \"format_1915||format_2330||format_3751\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Tabular data represented as tab-separated values in a text file.\", \"n\": \"TSV\", \"ns\": [], \"u\": \"format_3475\", \"es\": [\"Tab-delimited\", \"Tab-separated values\"], \"ch\": [{\"n\": \"MAGE-TAB\", \"u\": \"format_3162\"}, {\"n\": \"WEGO\", \"u\": \"format_3979\"}, {\"n\": \"RPKM\", \"u\": \"format_3980\"}], \"p\": [{\"n\": \"Format||Textual format||DSV||TSV\", \"k\": \"format_1915||format_2330||format_3751||format_3475\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"MAGE-TAB textual format for microarray expression data, standardised by MGED (now FGED).\", \"n\": \"MAGE-TAB\", \"ns\": [], \"u\": \"format_3162\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||DSV||TSV||MAGE-TAB\", \"k\": \"format_1915||format_2330||format_3751||format_3475||format_3162\"}, {\"n\": \"Format||Format (by type of data)||Gene expression report format||MAGE-TAB\", \"k\": \"format_1915||format_2350||format_2058||format_3162\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"WEGO native format used by the Web Gene Ontology Annotation Plot application.   Tab-delimited format with gene names and others GO IDs (columns) with one annotation record per line.\", \"n\": \"WEGO\", \"ns\": [], \"u\": \"format_3979\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||DSV||TSV||WEGO\", \"k\": \"format_1915||format_2330||format_3751||format_3475||format_3979\"}, {\"n\": \"Format||Format (by type of data)||Gene annotation format||WEGO\", \"k\": \"format_1915||format_2350||format_2031||format_3979\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Tab-delimited format for gene expression levels table, calculated as Reads Per Kilobase per Million (RPKM) mapped reads.\", \"n\": \"RPKM\", \"ns\": [], \"u\": \"format_3980\", \"es\": [\"Gene expression levels table format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||DSV||TSV||RPKM\", \"k\": \"format_1915||format_2330||format_3751||format_3475||format_3980\"}, {\"n\": \"Format||Format (by type of data)||Gene expression report format||RPKM\", \"k\": \"format_1915||format_2350||format_2058||format_3980\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Tabular data represented as comma-separated values in a text file.\", \"n\": \"CSV\", \"ns\": [], \"u\": \"format_3752\", \"es\": [\"Comma-separated values\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||DSV||CSV\", \"k\": \"format_1915||format_2330||format_3751||format_3752\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"\\\"Raw\\\" result file from SEQUEST database search.\", \"n\": \"SEQUEST .out file\", \"ns\": [], \"u\": \"format_3758\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||SEQUEST .out file\", \"k\": \"format_1915||format_2330||format_3758\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||SEQUEST .out file\", \"k\": \"format_1915||format_2350||format_3245||format_3758\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GSuite is a tabular format for collections of genome or sequence feature tracks, suitable for integrative multi-track analysis. GSuite contains links to genome/sequence tracks, with additional metadata.\", \"n\": \"GSuite\", \"ns\": [], \"u\": \"format_3775\", \"es\": [\"BioXSD/GTrack GSuite\", \"BioXSD|GTrack GSuite\", \"GSuite (GTrack ecosystem of formats)\", \"GSuite format\", \"GTrack|BTrack|GSuite GSuite\", \"GTrack|GSuite|BTrack GSuite\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GSuite\", \"k\": \"format_1915||format_2330||format_3775\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||GSuite\", \"k\": \"format_1915||format_2350||format_1920||format_3775\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The FAO/Bioversity/IPGRI Multi-Crop Passport Descriptors (MCPD) is an international standard format for exchange of germplasm information.\", \"n\": \"MCPD\", \"ns\": [\"IPGRI MCPD\", \"MCPD V.1\", \"MCPD V.2\"], \"u\": \"format_3777\", \"es\": [\"Bioversity MCPD\", \"FAO MCPD\", \"MCPD format\", \"Multi-Crop Passport Descriptors\", \"Multi-Crop Passport Descriptors format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||MCPD\", \"k\": \"format_1915||format_2330||format_3777\"}, {\"n\": \"Format||Format (by type of data)||Biodiversity data format||MCPD\", \"k\": \"format_1915||format_2350||format_3706||format_3777\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Native textual export format of annotated scientific text from PubTator.\", \"n\": \"PubTator format\", \"ns\": [], \"u\": \"format_3783\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||PubTator format\", \"k\": \"format_1915||format_2330||format_3783\"}, {\"n\": \"Format||Format (by type of data)||Annotated text format||PubTator format\", \"k\": \"format_1915||format_2350||format_3780||format_3783\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A family of similar formats of text annotation, used by BRAT and other tools, known as BioNLP Shared Task format (BioNLP 2009 Shared Task on Event Extraction, BioNLP Shared Task 2011, BioNLP Shared Task 2013), BRAT format, BRAT standoff format, and similar.\", \"n\": \"BioNLP Shared Task format\", \"ns\": [], \"u\": \"format_3785\", \"es\": [\"BRAT format\", \"BRAT standoff format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||BioNLP Shared Task format\", \"k\": \"format_1915||format_2330||format_3785\"}, {\"n\": \"Format||Format (by type of data)||Annotated text format||BioNLP Shared Task format\", \"k\": \"format_1915||format_2350||format_3780||format_3785\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"SQL (Structured Query Language) is the de-facto standard query language (format of queries) for querying and manipulating data in relational databases.\", \"n\": \"SQL\", \"ns\": [], \"u\": \"format_3788\", \"es\": [\"Structured Query Language\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||SQL\", \"k\": \"format_1915||format_2330||format_3788\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"XQuery (XML Query) is a query language (format of queries) for querying and manipulating structured and unstructured data, usually in the form of XML, text, and with vendor-specific extensions for other data formats (JSON, binary, etc.).\", \"n\": \"XQuery\", \"ns\": [], \"u\": \"format_3789\", \"es\": [\"XML Query\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||XQuery\", \"k\": \"format_1915||format_2330||format_3789\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"SPARQL (SPARQL Protocol and RDF Query Language) is a semantic query language for querying and manipulating data stored in Resource Description Framework (RDF) format.\", \"n\": \"SPARQL\", \"ns\": [], \"u\": \"format_3790\", \"es\": [\"SPARQL Protocol and RDF Query Language\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||SPARQL\", \"k\": \"format_1915||format_2330||format_3790\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The GEN file format contains genetic data and describes SNPs.\", \"n\": \"GEN\", \"ns\": [], \"u\": \"format_3812\", \"es\": [\"Genotype file format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GEN\", \"k\": \"format_1915||format_2330||format_3812\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||GEN\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3812\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The SAMPLE file format contains information about each individual i.e. individual IDs, covariates, phenotypes and missing data proportions, from a GWAS study.\", \"n\": \"SAMPLE file format\", \"ns\": [], \"u\": \"format_3813\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||SAMPLE file format\", \"k\": \"format_1915||format_2330||format_3813\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"SDF is one of a family of chemical-data file formats developed by MDL Information Systems; it is intended especially for structural information.\", \"n\": \"SDF\", \"ns\": [], \"u\": \"format_3814\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||SDF\", \"k\": \"format_1915||format_2330||format_3814\"}, {\"n\": \"Format||Format (by type of data)||Chemical data format||SDF\", \"k\": \"format_1915||format_2350||format_2030||format_3814\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"An MDL Molfile is a file format for holding information about the atoms, bonds, connectivity and coordinates of a molecule.\", \"n\": \"Molfile\", \"ns\": [], \"u\": \"format_3815\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Molfile\", \"k\": \"format_1915||format_2330||format_3815\"}, {\"n\": \"Format||Format (by type of data)||Chemical data format||Molfile\", \"k\": \"format_1915||format_2350||format_2030||format_3815\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Complete, portable representation of a SYBYL molecule. ASCII file which contains all the information needed to reconstruct a SYBYL molecule.\", \"n\": \"Mol2\", \"ns\": [], \"u\": \"format_3816\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Mol2\", \"k\": \"format_1915||format_2330||format_3816\"}, {\"n\": \"Format||Format (by type of data)||Chemical data format||Mol2\", \"k\": \"format_1915||format_2350||format_2030||format_3816\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"format for the LaTeX document preparation system\", \"n\": \"latex\", \"ns\": [], \"u\": \"format_3817\", \"es\": [\"LaTeX format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||latex\", \"k\": \"format_1915||format_2330||format_3817\"}, {\"n\": \"Format||Format (by type of data)||Document format||latex\", \"k\": \"format_1915||format_2350||format_3507||format_3817\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Tab-delimited text file format used by Eland - the read-mapping program distributed by Illumina with its sequencing analysis pipeline - which maps short Solexa sequence reads to the human reference genome.\", \"n\": \"ELAND format\", \"ns\": [], \"u\": \"format_3818\", \"es\": [\"ELAND\", \"eland\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||ELAND format\", \"k\": \"format_1915||format_2330||format_3818\"}, {\"n\": \"Format||Format (by type of data)||Sequence assembly format||Sequence assembly format (text)||ELAND format\", \"k\": \"format_1915||format_2350||format_2055||format_2561||format_3818\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GML (Graph Modeling Language) is a text file format supporting network data with a very easy syntax. It is used by Graphlet, Pajek, yEd, LEDA and NetworkX.\", \"n\": \"GML\", \"ns\": [], \"u\": \"format_3822\", \"es\": [\"GML format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GML\", \"k\": \"format_1915||format_2330||format_3822\"}, {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||GML\", \"k\": \"format_1915||format_2350||format_2013||format_3822\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"FASTG is a format for faithfully representing genome assemblies in the face of allelic polymorphism and assembly uncertainty.\", \"n\": \"FASTG\", \"ns\": [], \"u\": \"format_3823\", \"es\": [\"FASTG assembly graph format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||FASTG\", \"k\": \"format_1915||format_2330||format_3823\"}, {\"n\": \"Format||Format (by type of data)||Sequence assembly format||Sequence assembly format (text)||FASTG\", \"k\": \"format_1915||format_2350||format_2055||format_2561||format_3823\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \". proBED is an adaptation of BED (format_3003), which was extended to meet specific requirements entailed by proteomics data.\", \"n\": \"proBED\", \"ns\": [], \"u\": \"format_3827\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||proBED\", \"k\": \"format_1915||format_2330||format_3827\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||proBED\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3827\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GenePix Results (GPR) text file format developed by Axon Instruments that is used to save GenePix Results data.\", \"n\": \"GPR\", \"ns\": [], \"u\": \"format_3829\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GPR\", \"k\": \"format_1915||format_2330||format_3829\"}, {\"n\": \"Format||Format (by type of data)||Raw microarray data format||GPR\", \"k\": \"format_1915||format_2350||format_3828||format_3829\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A standardized file format for data exchange in mass spectrometry, initially developed for infrared spectrometry.\", \"n\": \"JCAMP-DX\", \"ns\": [], \"u\": \"format_3859\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||JCAMP-DX\", \"k\": \"format_1915||format_2330||format_3859\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||JCAMP-DX\", \"k\": \"format_1915||format_2350||format_3245||format_3859\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The XYZ chemical file format is widely supported by many programs, although many slightly different XYZ file formats coexist (Tinker XYZ, UniChem XYZ, etc.). Basic information stored for each atom in the system are x, y and z coordinates and atom element/atomic number.\", \"n\": \"XYZ\", \"ns\": [], \"u\": \"format_3877\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||XYZ\", \"k\": \"format_1915||format_2330||format_3877\"}, {\"n\": \"Format||Format (by type of data)||Tertiary structure format||XYZ\", \"k\": \"format_1915||format_2350||format_2033||format_3877\"}, {\"n\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (text)||XYZ\", \"k\": \"format_1915||format_2350||format_3866||format_3868||format_3877\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"AMBER trajectory (also called mdcrd), with 10 coordinates per line and format F8.3 (fixed point notation with field width 8 and 3 decimal places).\", \"n\": \"mdcrd\", \"ns\": [], \"u\": \"format_3878\", \"es\": [\"AMBER trajectory format\", \"inpcrd\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||mdcrd\", \"k\": \"format_1915||format_2330||format_3878\"}, {\"n\": \"Format||Format (by type of data)||Tertiary structure format||mdcrd\", \"k\": \"format_1915||format_2350||format_2033||format_3878\"}, {\"n\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (text)||mdcrd\", \"k\": \"format_1915||format_2350||format_3866||format_3868||format_3878\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GROMACS MD package top textual files define an entire structure system topology, either directly, or by including itp files.\", \"n\": \"GROMACS top\", \"ns\": [], \"u\": \"format_3880\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GROMACS top\", \"k\": \"format_1915||format_2330||format_3880\"}, {\"n\": \"Format||Format (by type of data)||Tertiary structure format||GROMACS top\", \"k\": \"format_1915||format_2350||format_2033||format_3880\"}, {\"n\": \"Format||Format (by type of data)||Topology format||GROMACS top\", \"k\": \"format_1915||format_2350||format_3879||format_3880\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"AMBER Prmtop file (version 7) is a structure topology text file divided in several sections designed to be parsed easily using simple Fortran code. Each section contains particular topology information, such as atom name, charge, mass, angles, dihedrals, etc.\", \"n\": \"AMBER top\", \"ns\": [], \"u\": \"format_3881\", \"es\": [\"AMBER Parm\", \"AMBER Parm7\", \"Parm7\", \"Prmtop\", \"Prmtop7\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||AMBER top\", \"k\": \"format_1915||format_2330||format_3881\"}, {\"n\": \"Format||Format (by type of data)||Tertiary structure format||AMBER top\", \"k\": \"format_1915||format_2350||format_2033||format_3881\"}, {\"n\": \"Format||Format (by type of data)||Topology format||AMBER top\", \"k\": \"format_1915||format_2350||format_3879||format_3881\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"X-Plor Protein Structure Files (PSF) are structure topology files used by NAMD and CHARMM molecular simulations programs. PSF files contain six main sections of interest: atoms, bonds, angles, dihedrals, improper dihedrals (force terms used to maintain planarity) and cross-terms.\", \"n\": \"PSF\", \"ns\": [], \"u\": \"format_3882\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||PSF\", \"k\": \"format_1915||format_2330||format_3882\"}, {\"n\": \"Format||Format (by type of data)||Tertiary structure format||PSF\", \"k\": \"format_1915||format_2350||format_2033||format_3882\"}, {\"n\": \"Format||Format (by type of data)||Topology format||PSF\", \"k\": \"format_1915||format_2350||format_3879||format_3882\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GROMACS itp files (include topology) contain structure topology information, and are tipically included in GROMACS topology files (GROMACS top). Itp files are used to define individual (or multiple) components of a topology as a separate file. This is particularly useful if there is a molecule that is used frequently, and also reduces the size of the system topology file, splitting it in different parts.\", \"n\": \"GROMACS itp\", \"ns\": [], \"u\": \"format_3883\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GROMACS itp\", \"k\": \"format_1915||format_2330||format_3883\"}, {\"n\": \"Format||Format (by type of data)||Tertiary structure format||GROMACS itp\", \"k\": \"format_1915||format_2350||format_2033||format_3883\"}, {\"n\": \"Format||Format (by type of data)||Topology format||GROMACS itp\", \"k\": \"format_1915||format_2350||format_3879||format_3883\"}, {\"n\": \"Format||Format (by type of data)||FF parameter format||GROMACS itp\", \"k\": \"format_1915||format_2350||format_3884||format_3883\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"AMBER coordinate/restart file with 6 coordinates per line and decimal format F12.7 (fixed point notation with field width 12 and 7 decimal places)\", \"n\": \"RST\", \"ns\": [], \"u\": \"format_3886\", \"es\": [\"restrt\", \"rst7\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||RST\", \"k\": \"format_1915||format_2330||format_3886\"}, {\"n\": \"Format||Format (by type of data)||Tertiary structure format||RST\", \"k\": \"format_1915||format_2350||format_2033||format_3886\"}, {\"n\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (text)||RST\", \"k\": \"format_1915||format_2350||format_3866||format_3868||format_3886\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of CHARMM Residue Topology Files (RTF), which define groups by including the atoms, the properties of the group, and bond and charge information.\", \"n\": \"CHARMM rtf\", \"ns\": [], \"u\": \"format_3887\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||CHARMM rtf\", \"k\": \"format_1915||format_2330||format_3887\"}, {\"n\": \"Format||Format (by type of data)||Tertiary structure format||CHARMM rtf\", \"k\": \"format_1915||format_2350||format_2033||format_3887\"}, {\"n\": \"Format||Format (by type of data)||Topology format||CHARMM rtf\", \"k\": \"format_1915||format_2350||format_3879||format_3887\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"AMBER frcmod (Force field Modification) is a file format to store any modification to the standard force field needed for a particular molecule to be properly represented in the simulation.\", \"n\": \"AMBER frcmod\", \"ns\": [], \"u\": \"format_3888\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||AMBER frcmod\", \"k\": \"format_1915||format_2330||format_3888\"}, {\"n\": \"Format||Format (by type of data)||FF parameter format||AMBER frcmod\", \"k\": \"format_1915||format_2350||format_3884||format_3888\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"AMBER Object File Format library files (OFF library files) store residue libraries (forcefield residue parameters).\", \"n\": \"AMBER off\", \"ns\": [], \"u\": \"format_3889\", \"es\": [\"AMBER Object File Format\", \"AMBER lib\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||AMBER off\", \"k\": \"format_1915||format_2330||format_3889\"}, {\"n\": \"Format||Format (by type of data)||FF parameter format||AMBER off\", \"k\": \"format_1915||format_2350||format_3884||format_3889\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"MReData is a text based data standard for processed NMR data. It is relying on SDF molecule data and allows to store assignments of NMR peaks to molecule features.  The NMR-extracted data (or \\\"NMReDATA\\\") includes: Chemical shift,scalar coupling, 2D correlation, assignment, etc.\", \"n\": \"NMReDATA\", \"ns\": [], \"u\": \"format_3906\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||NMReDATA\", \"k\": \"format_1915||format_2330||format_3906\"}, {\"n\": \"Format||Format (by type of data)||NMR data format||NMReDATA\", \"k\": \"format_1915||format_2350||format_3824||format_3906\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BpForms is a string format for concretely representing the primary structures of biopolymers, including DNA, RNA, and proteins that include non-canonical nucleic and amino acids. See https://www.bpforms.org for more information.\", \"n\": \"BpForms\", \"ns\": [], \"u\": \"format_3909\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||BpForms\", \"k\": \"format_1915||format_2330||format_3909\"}, {\"n\": \"Format||Format (by type of data)||Chemical formula format||BpForms\", \"k\": \"format_1915||format_2350||format_2035||format_3909\"}, {\"n\": \"Format||Format (by type of data)||Raw sequence format||BpForms\", \"k\": \"format_1915||format_2350||format_2571||format_3909\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of trr files that contain the trajectory of a simulation experiment used by GROMACS.\", \"n\": \"trr\", \"ns\": [], \"u\": \"format_3910\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||trr\", \"k\": \"format_1915||format_2330||format_3910\"}, {\"n\": \"Format||Format (by type of data)||Tertiary structure format||trr\", \"k\": \"format_1915||format_2350||format_2033||format_3910\"}, {\"n\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (text)||trr\", \"k\": \"format_1915||format_2350||format_3866||format_3868||format_3910\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The Matrix Market matrix (MTX) format stores numerical or pattern matrices in a dense (array format) or sparse (coordinate format) representation.\", \"n\": \"MTX\", \"ns\": [], \"u\": \"format_3916\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||MTX\", \"k\": \"format_1915||format_2330||format_3916\"}, {\"n\": \"Format||Format (by type of data)||Gene expression report format||MTX\", \"k\": \"format_1915||format_2350||format_2058||format_3916\"}, {\"n\": \"Format||Format (by type of data)||Matrix format||MTX\", \"k\": \"format_1915||format_2350||format_3033||format_3916\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BcForms is a format for abstractly describing the molecular structure (atoms and bonds) of macromolecular complexes as a collection of subunits and crosslinks. Each subunit can be described with BpForms (format_3909) or SMILES (data_2301). BcForms uses an ontology of crosslinks to abstract the chemical details of crosslinks from the descriptions of complexes (see https://bpforms.org/crosslink.html).\", \"n\": \"BcForms\", \"ns\": [], \"u\": \"format_3951\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||BcForms\", \"k\": \"format_1915||format_2330||format_3951\"}, {\"n\": \"Format||Format (by type of data)||Chemical data format||BcForms\", \"k\": \"format_1915||format_2350||format_2030||format_3951\"}, {\"n\": \"Format||Format (by type of data)||Protein report format||BcForms\", \"k\": \"format_1915||format_2350||format_2062||format_3951\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"N-Quads is a line-based, plain text format for encoding an RDF dataset. It includes information about the graph each triple belongs to.\", \"n\": \"N-Quads\", \"ns\": [], \"u\": \"format_3956\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||N-Quads\", \"k\": \"format_1915||format_2330||format_3956\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||N-Quads\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_3956\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||N-Quads\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_3956\"}, {\"n\": \"Format||RDF format||N-Quads\", \"k\": \"format_1915||format_2376||format_3956\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BioNetGen is a format for the specification and simulation of rule-based models of biochemical systems, including signal transduction, metabolic, and genetic regulatory networks.\", \"n\": \"BNGL\", \"ns\": [], \"u\": \"format_3972\", \"es\": [\"BioNetGen Language\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||BNGL\", \"k\": \"format_1915||format_2330||format_3972\"}, {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||BNGL\", \"k\": \"format_1915||format_2350||format_2013||format_3972\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Graphical Fragment Assembly captures sequence graphs as the product of an assembly, a representation of variation in genomes, splice graphs in genes, or even overlap between reads from long-read sequencing technology.\", \"n\": \"GFA 1\", \"ns\": [], \"u\": \"format_3975\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GFA 1\", \"k\": \"format_1915||format_2330||format_3975\"}, {\"n\": \"Format||Format (by type of data)||Sequence assembly format||Sequence assembly format (text)||GFA 1\", \"k\": \"format_1915||format_2350||format_2055||format_2561||format_3975\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Graphical Fragment Assembly captures sequence graphs as the product of an assembly, a representation of variation in genomes, splice graphs in genes, or even overlap between reads from long-read sequencing technology.\", \"n\": \"GFA 2\", \"ns\": [], \"u\": \"format_3976\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GFA 2\", \"k\": \"format_1915||format_2330||format_3976\"}, {\"n\": \"Format||Format (by type of data)||Sequence assembly format||Sequence assembly format (text)||GFA 2\", \"k\": \"format_1915||format_2350||format_2055||format_2561||format_3976\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The CONTIG format used for output of the SOAPdenovo alignment program. It contains contig sequences generated without using mate pair information.\", \"n\": \"CONTIG\", \"ns\": [], \"u\": \"format_3978\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||CONTIG\", \"k\": \"format_1915||format_2330||format_3978\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (text)||CONTIG\", \"k\": \"format_1915||format_2350||format_1919||format_2551||format_3978\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The CHAIN format describes a pairwise alignment that allow gaps in both sequences simultaneously and is used by the UCSC Genome Browser.\", \"n\": \"CHAIN\", \"ns\": [], \"u\": \"format_3982\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||CHAIN\", \"k\": \"format_1915||format_2330||format_3982\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||CHAIN\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3982\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The NET file format is used to describe the data that underlie the net alignment annotations in the UCSC Genome Browser.\", \"n\": \"NET\", \"ns\": [], \"u\": \"format_3983\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||NET\", \"k\": \"format_1915||format_2330||format_3983\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||NET\", \"k\": \"format_1915||format_2350||format_1920||format_3983\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of QMAP files generated for methylation data from an internal BGI pipeline.\", \"n\": \"QMAP\", \"ns\": [], \"u\": \"format_3984\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||QMAP\", \"k\": \"format_1915||format_2330||format_3984\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||QMAP\", \"k\": \"format_1915||format_2350||format_1920||format_3984\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"An emerging format for high-level Galaxy workflow description.\", \"n\": \"gxformat2\", \"ns\": [], \"u\": \"format_3985\", \"es\": [\"Galaxy workflow format\", \"GalaxyWF\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||gxformat2\", \"k\": \"format_1915||format_2330||format_3985\"}, {\"n\": \"Format||Format (by type of data)||Workflow format||gxformat2\", \"k\": \"format_1915||format_2350||format_2032||format_3985\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Compact Idiosyncratic Gapped Alignment Report format is a compressed (run-length encoded) pairwise alignment format. It is useful for representing long (e.g. genomic) pairwise alignments.\", \"n\": \"CIGAR format\", \"ns\": [], \"u\": \"format_3992\", \"es\": [\"CIGAR\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||CIGAR format\", \"k\": \"format_1915||format_2330||format_3992\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||CIGAR format\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3992\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format for scripts writtenin Python - a widely used high-level programming language for general-purpose programming.\", \"n\": \"Python script\", \"ns\": [], \"u\": \"format_3996\", \"es\": [\"Python\", \"Python program\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Python script\", \"k\": \"format_1915||format_2330||format_3996\"}, {\"n\": \"Format||Format (by type of data)||Workflow format||Python script\", \"k\": \"format_1915||format_2350||format_2032||format_3996\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format for scripts written in Perl - a family of high-level, general-purpose, interpreted, dynamic programming languages.\", \"n\": \"Perl script\", \"ns\": [], \"u\": \"format_3998\", \"es\": [\"Perl\", \"Perl program\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Perl script\", \"k\": \"format_1915||format_2330||format_3998\"}, {\"n\": \"Format||Format (by type of data)||Workflow format||Perl script\", \"k\": \"format_1915||format_2350||format_2032||format_3998\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format for scripts written in the R language - an open source programming language and software environment for statistical computing and graphics that is supported by the R Foundation for Statistical Computing.\", \"n\": \"R script\", \"ns\": [], \"u\": \"format_3999\", \"es\": [\"R\", \"R program\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||R script\", \"k\": \"format_1915||format_2330||format_3999\"}, {\"n\": \"Format||Format (by type of data)||Workflow format||R script\", \"k\": \"format_1915||format_2350||format_2032||format_3999\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A file format for making dynamic documents (R Markdown scripts) with the R language.\", \"n\": \"R markdown\", \"ns\": [], \"u\": \"format_4000\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||R markdown\", \"k\": \"format_1915||format_2330||format_4000\"}, {\"n\": \"Format||Format (by type of data)||Workflow format||R markdown\", \"k\": \"format_1915||format_2350||format_2032||format_4000\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A configuration file used by various programs to store settings that are specific to their respective software.\", \"n\": \"Configuration file format\", \"ns\": [], \"u\": \"format_4005\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Configuration file format\", \"k\": \"format_1915||format_2330||format_4005\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The file format for MATLAB scripts or functions.\", \"n\": \"MATLAB script\", \"ns\":