null}, {\"d\": \"The CONTIG format used for output of the SOAPdenovo alignment program. It contains contig sequences generated without using mate pair information.\", \"n\": \"CONTIG\", \"ns\": [], \"u\": \"format_3978\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (text)||CONTIG\", \"k\": \"format_1915||format_2350||format_1919||format_2551||format_3978\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Data format for a molecular sequence record.\", \"n\": \"Sequence record format (XML)\", \"ns\": [], \"u\": \"format_2552\", \"es\": [], \"ch\": [{\"n\": \"DAS format\", \"u\": \"format_1967\"}, {\"n\": \"dasdna\", \"u\": \"format_1968\"}, {\"n\": \"BSML\", \"u\": \"format_3487\"}, {\"n\": \"UniProtKB XML\", \"u\": \"format_3770\"}, {\"n\": \"BEAST\", \"u\": \"format_3843\"}, {\"n\": \"Chado-XML\", \"u\": \"format_3844\"}, {\"n\": \"OrthoXML\", \"u\": \"format_3850\"}, {\"n\": \"SeqXML\", \"u\": \"format_3852\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)\", \"k\": \"format_1915||format_2350||format_1919||format_2552\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"DAS sequence (XML) format (any type).\", \"n\": \"DAS format\", \"ns\": [], \"u\": \"format_1967\", \"es\": [\"das sequence format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||DAS format\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_1967\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"DAS sequence (XML) format (nucleotide-only).\", \"n\": \"dasdna\", \"ns\": [], \"u\": \"format_1968\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||dasdna\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_1968\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Bioinformatics Sequence Markup Language format.\", \"n\": \"BSML\", \"ns\": [], \"u\": \"format_3487\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||BSML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3487\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"UniProtKB XML sequence features format is an XML format available for downloading UniProt entries.\", \"n\": \"UniProtKB XML\", \"ns\": [], \"u\": \"format_3770\", \"es\": [\"UniProt XML\", \"UniProt XML format\", \"UniProtKB XML format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||UniProtKB XML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3770\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"XML input file format for BEAST Software (Bayesian Evolutionary Analysis Sampling Trees).\", \"n\": \"BEAST\", \"ns\": [], \"u\": \"format_3843\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||BEAST\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3843\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Chado-XML format is a direct mapping of the Chado relational schema into XML.\", \"n\": \"Chado-XML\", \"ns\": [], \"u\": \"format_3844\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||Chado-XML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3844\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"OrthoXML is designed broadly to allow the storage and comparison of orthology data from any ortholog database. It establishes a structure for describing orthology relationships while still allowing flexibility for database-specific information to be encapsulated in the same format.\", \"n\": \"OrthoXML\", \"ns\": [], \"u\": \"format_3850\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||OrthoXML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3850\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"SeqXML is an XML Schema to describe biological sequences, developed by the Stockholm Bioinformatics Centre.\", \"n\": \"SeqXML\", \"ns\": [], \"u\": \"format_3852\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||SeqXML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3852\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A format resembling GenBank entry (plain text) format.\", \"n\": \"GenBank-like format\", \"ns\": [], \"u\": \"format_2559\", \"es\": [], \"ch\": [{\"n\": \"GenBank-like format (text)\", \"u\": \"format_2205\"}, {\"n\": \"GenBank-HTML\", \"u\": \"format_2532\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence record format||GenBank-like format\", \"k\": \"format_1915||format_2350||format_1919||format_2559\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A text format resembling GenBank entry (plain text) format.\", \"n\": \"GenBank-like format (text)\", \"ns\": [], \"u\": \"format_2205\", \"es\": [], \"ch\": [{\"n\": \"GenBank format\", \"u\": \"format_1936\"}, {\"n\": \"genpept\", \"u\": \"format_1937\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||GenBank-like format||GenBank-like format (text)\", \"k\": \"format_1915||format_2350||format_1919||format_2559||format_2205\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Genbank entry format.\", \"n\": \"GenBank format\", \"ns\": [], \"u\": \"format_1936\", \"es\": [\"GenBank\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||GenBank-like format||GenBank-like format (text)||