554||format_2922||format_1988\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Pearson MARKX3 alignment format.\", \"n\": \"markx3\", \"ns\": [], \"u\": \"format_1989\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (text)||markx0 variant||markx3\", \"k\": \"format_1915||format_2350||format_1921||format_2554||format_2922||format_1989\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Some variant of Mega format for (typically aligned) sequences.\", \"n\": \"mega variant\", \"ns\": [], \"u\": \"format_2923\", \"es\": [], \"ch\": [{\"n\": \"mega\", \"u\": \"format_1991\"}, {\"n\": \"meganon\", \"u\": \"format_1992\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (text)||mega variant\", \"k\": \"format_1915||format_2350||format_1921||format_2554||format_2923\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Mega format for (typically aligned) sequences.\", \"n\": \"mega\", \"ns\": [], \"u\": \"format_1991\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (text)||mega variant||mega\", \"k\": \"format_1915||format_2350||format_1921||format_2554||format_2923||format_1991\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Mega non-interleaved format for (typically aligned) sequences.\", \"n\": \"meganon\", \"ns\": [], \"u\": \"format_1992\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (text)||mega variant||meganon\", \"k\": \"format_1915||format_2350||format_1921||format_2554||format_2923||format_1992\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Some variant of Phylip format for (aligned) sequences.\", \"n\": \"Phylip format variant\", \"ns\": [], \"u\": \"format_2924\", \"es\": [], \"ch\": [{\"n\": \"PHYLIP format\", \"u\": \"format_1997\"}, {\"n\": \"PHYLIP sequential\", \"u\": \"format_1998\"}, {\"n\"