o\": null}, {\"d\": \"The CONTIG format used for output of the SOAPdenovo alignment program. It contains contig sequences generated without using mate pair information.\", \"n\": \"CONTIG\", \"ns\": [], \"u\": \"format_3978\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (text)||CONTIG\", \"k\": \"format_1915||format_2350||format_1919||format_2551||format_3978\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Data format for a molecular sequence record.\", \"n\": \"Sequence record format (XML)\", \"ns\": [], \"u\": \"format_2552\", \"es\": [], \"ch\": [{\"n\": \"DAS format\", \"u\": \"format_1967\"}, {\"n\": \"dasdna\", \"u\": \"format_1968\"}, {\"n\": \"BSML\", \"u\": \"format_3487\"}, {\"n\": \"UniProtKB XML\", \"u\": \"format_3770\"}, {\"n\": \"BEAST\", \"u\": \"format_3843\"}, {\"n\": \"Chado-XML\", \"u\": \"format_3844\"}, {\"n\": \"OrthoXML\", \"u\": \"format_3850\"}, {\"n\": \"SeqXML\", \"u\": \"format_3852\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)\", \"k\": \"format_1915||format_2350||format_1919||format_2552\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"DAS sequence (XML) format (any type).\", \"n\": \"DAS format\", \"ns\": [], \"u\": \"format_1967\", \"es\": [\"das sequence format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||DAS format\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_1967\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"DAS sequence (XML) format (nucleotide-only).\", \"n\": \"dasdna\", \"ns\": [], \"u\": \"format_1968\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||dasdna\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_1968\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Bioinformatics Sequence Markup Language format.\", \"n\": \"BSML\", \"ns\": [], \"u\": \"format_3487\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||BSML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3487\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"UniProtKB XML sequence features format is an XML format available for downloading UniProt entries.\", \"n\": \"UniProtKB XML\", \"ns\": [], \"u\": \"format_3770\", \"es\": [\"UniProt XML\", \"UniProt XML format\", \"UniProtKB XML format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||UniProtKB XML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3770\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"XML input file format for BEAST Software (Bayesian Evolutionary Analysis Sampling Trees).\", \"n\": \"BEAST\", \"ns\": [], \"u\": \"format_3843\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||BEAST\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3843\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Chado-XML format is a direct mapping of the Chado relational schema into XML.\", \"n\": \"Chado-XML\", \"ns\": [], \"u\": \"format_3844\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||Chado-XML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3844\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"OrthoXML is designed broadly to allow the storage and comparison of orthology data from any ortholog database. It establishes a structure for describing orthology relationships while still allowing flexibility for database-specific information to be encapsulated in the same format.\", \"n\": \"OrthoXML\", \"ns\": [], \"u\": \"format_3850\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||OrthoXML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3850\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"SeqXML is an XML Schema to describe biological sequences, developed by the Stockholm Bioinformatics Centre.\", \"n\": \"SeqXML\", \"ns\": [], \"u\": \"format_3852\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||SeqXML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3852\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A format resembling GenBank entry (plain text) format.\", \"n\": \"GenBank-like format\", \"ns\": [], \"u\": \"format_2559\", \"es\": [], \"ch\": [{\"n\": \"GenBank-like format (text)\", \"u\": \"format_2205\"}, {\"n\": \"GenBank-HTML\", \"u\": \"format_2532\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence record format||GenBank-like format\", \"k\": \"format_1915||format_2350||format_1919||format_2559\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A text format resembling GenBank entry (plain text) format.\", \"n\": \"GenBank-like format (text)\", \"ns\": [], \"u\": \"format_2205\", \"es\": [], \"ch\": [{\"n\": \"GenBank format\", \"u\": \"format_1936\"}, {\"n\": \"genpept\", \"u\": \"format_1937\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||GenBank-like format||GenBank-like format (text)\", \"k\": \"format_1915||format_2350||format_1919||format_2559||format_2205\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Genbank entry format.\", \"n\": \"GenBank format\", \"ns\": [], \"u\": \"format_1936\", \"es\": [\"GenBank\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||GenBank-like format||GenBank-like format (text)||GenBank format\", \"k\": \"format_1915||format_2350||format_1919||format_2559||format_2205||format_1936\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Genpept protein entry format.\", \"n\": \"genpept\", \"ns\": [], \"u\": \"format_1937\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||GenBank-like format||GenBank-like format (text)||genpept\", \"k\": \"format_1915||format_2350||format_1919||format_2559||format_2205||format_1937\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Genbank entry format wrapped in HTML elements.\", \"n\": \"GenBank-HTML\", \"ns\": [], \"u\": \"format_2532\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence record format||GenBank-like format||GenBank-HTML\", \"k\": \"format_1915||format_2350||format_1919||format_2559||format_2532\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BioJSON is a BioXSD-schema-based JSON format of sequence-based data and some other common data - sequence records, alignments, feature records, references to resources, and more - optimised for integrative bioinformatics, web applications and APIs, and object-oriented programming.\", \"n\": \"BioJSON (BioXSD)\", \"ns\": [], \"u\": \"format_3772\", \"es\": [\"BioJSON (BioXSD data model)\", \"BioJSON format (BioXSD)\", \"BioXSD BioJSON\", \"BioXSD BioJSON format\", \"BioXSD JSON\", \"BioXSD JSON format\", \"BioXSD in JSON\", \"BioXSD in JSON format\", \"BioXSD+JSON\", \"BioXSD/GTrack BioJSON\", \"BioXSD|BioJSON|BioYAML BioJSON\", \"BioXSD|GTrack BioJSON\"], \"ch\": [], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence record format||BioJSON (BioXSD)\", \"k\": \"format_1915||format_2350||format_1919||format_3772\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||BioJSON (BioXSD)\", \"k\": \"format_1915||format_2350||format_1920||format_3772\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||BioJSON (BioXSD)\", \"k\": \"format_1915||format_2350||format_1921||format_3772\"}, {\"n\": \"Format||Format (by type of data)||Raw sequence format||BioJSON (BioXSD)\", \"k\": \"format_1915||format_2350||format_2571||format_3772\"}, {\"n\": \"Format||JSON||BioJSON (BioXSD)\", \"k\": \"format_1915||format_3464||format_3772\"}, {\"n\": \"Format||YAML||JSON||BioJSON (BioXSD)\", \"k\": \"format_1915||format_3750||format_3464||format_3772\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BioYAML is a BioXSD-schema-based YAML format of sequence-based data and some other common data - sequence records, alignments, feature records, references to resources, and more - optimised for integrative bioinformatics, web APIs, human readability and editting, and object-oriented programming.\", \"n\": \"BioYAML\", \"ns\": [], \"u\": \"format_3773\", \"es\": [\"BioXSD BioYAML\", \"BioXSD BioYAML format\", \"BioXSD YAML\", \"BioXSD YAML format\", \"BioXSD in YAML\", \"BioXSD in YAML format\", \"BioXSD+YAML\", \"BioXSD/GTrack BioYAML\", \"BioXSD|BioJSON|BioYAML BioYAML\", \"BioXSD|GTrack BioYAML\", \"BioYAML (BioXSD data model)\", \"BioYAML (BioXSD)\", \"BioYAML format\", \"BioYAML format (BioXSD)\"], \"ch\": [], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence record format||BioYAML\", \"k\": \"format_1915||format_2350||format_1919||format_3773\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||BioYAML\", \"k\": \"format_1915||format_2350||format_1920||format_3773\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||BioYAML\", \"k\": \"format_1915||format_2350||format_1921||format_3773\"}, {\"n\": \"Format||Format (by type of data)||Raw sequence format||BioYAML\", \"k\": \"format_1915||format_2350||format_2571||format_3773\"}, {\"n\": \"Format||YAML||BioYAML\", \"k\": \"format_1915||format_3750||format_3773\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Data format for molecular sequence feature information.\", \"n\": \"Sequence feature annotation format\", \"ns\": [], \"u\": \"format_1920\", \"es\": [], \"ch\": [{\"n\": \"debug-feat\", \"u\": \"format_1979\"}, {\"n\": \"BioXSD (XML)\", \"u\": \"format_2352\"}, {\"n\": \"Sequence feature table format\", \"u\": \"format_2548\"}, {\"n\": \"Sequence annotation track format\", \"u\": \"format_2919\"}, {\"n\": \"BioJSON (BioXSD)\", \"u\": \"format_3772\"}, {\"n\": \"BioYAML\", \"u\": \"format_3773\"}, {\"n\": \"BioJSON (Jalview)\", \"u\": \"format_3774\"}, {\"n\": \"GSuite\", \"u\": \"format_3775\"}, {\"n\": \"BTrack\", \"u\": \"format_3776\"}, {\"n\": \"PSDML\", \"u\": \"format_3851\"}, {\"n\": \"UniParc XML\", \"u\": \"format_3853\"}, {\"n\": \"UniRef XML\", \"u\": \"format_3854\"}, {\"n\": \"NET\", \"u\": \"format_3983\"}, {\"n\": \"QMAP\", \"u\": \"format_3984\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence feature annotation format\", \"k\": \"format_1915||format_2350||format_1920\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"EMBOSS debugging trace feature format of full internal data content.\", \"n\": \"debug-feat\", \"ns\": [], \"u\": \"format_1979\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||debug-feat\", \"k\": \"format_1915||format_2350||format_1920||format_1979\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BioXSD-schema-based XML format of sequence-based data and some other common data - sequence records, alignments, feature records, references to resources, and more - optimised for integrative bioinformatics, Web services, and object-oriented programming.\", \"n\": \"BioXSD (XML)\", \"ns\": [], \"u\": \"format_2352\", \"es\": [\"BioXSD XML\", \"BioXSD XML format\", \"BioXSD in XML\", \"BioXSD in XML format\", \"BioXSD+XML\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||BioXSD (XML)\", \"k\": \"format_1915||format_2350||format_1920||format_2352\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format for a sequence feature table.\", \"n\": \"Sequence feature table format\", \"ns\": [], \"u\": \"format_2548\", \"es\": [], \"ch\": [{\"n\": \"Sequence feature table format (text)\", \"u\": \"format_2206\"}, {\"n\": \"uniprotkb-like format\", \"u\": \"format_2547\"}, {\"n\": \"Sequence feature table format (XML)\", \"u\": \"format_2553\"}, {\"n\": \"BTrack\", \"u\": \"format_3776\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format\", \"k\": \"format_1915||format_2350||format_1920||format_2548\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Text format for a sequence feature table.\", \"n\": \"Sequence feature table format (text)\", \"ns\": [], \"u\": \"format_2206\", \"es\": [], \"ch\": [{\"n\": \"EMBL format\", \"u\": \"format_1927\"}, {\"n\": \"GenBank format\", \"u\": \"format_1936\"}, {\"n\": \"GFF\", \"u\": \"format_2305\"}, {\"n\": \"GTrack\", \"u\": \"format_3164\"}, {\"n\": \"Sequin format\", \"u\": \"format_3701\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"EMBL entry format.\", \"n\": \"EMBL format\", \"ns\": [], \"u\": \"format_1927\", \"es\": [\"EMBL\", \"EMBL sequence format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)||EMBL format\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206||format_1927\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Genbank entry format.\", \"n\": \"GenBank format\", \"ns\": [], \"u\": \"format_1936\", \"es\": [\"GenBank\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)||GenBank format\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206||format_1936\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GFF feature format (of indeterminate version).\", \"n\": \"GFF\", \"ns\": [], \"u\": \"format_2305\", \"es\": [], \"ch\": [{\"n\": \"GFF2\", \"u\": \"format_1974\"}, {\"n\": \"GFF3\", \"u\": \"format_1975\"}, {\"n\": \"GTF\", \"u\": \"format_2306\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)||GFF\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206||format_2305\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"General Feature Format (GFF) of sequence features.\", \"n\": \"GFF2\", \"ns\": [], \"u\": \"format_1974\", \"es\": [], \"ch\": [{\"n\": \"GFF2-seq\", \"u\": \"format_1938\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)||GFF||GFF2\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206||format_2305||format_1974\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GFF feature file format with sequence in the header.\", \"n\": \"GFF2-seq\", \"ns\": [], \"u\": \"format_1938\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)||GFF||GFF2||GFF2-seq\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206||format_2305||format_1974||format_1938\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Generic Feature Format version 3 (GFF3) of sequence features.\", \"n\": \"GFF3\", \"ns\": [], \"u\": \"format_1975\", \"es\": [], \"ch\": [{\"n\": \"GFF3-seq\", \"u\": \"format_1939\"}, {\"n\": \"GVF\", \"u\": \"format_3019\"}, {\"n\": \"mirGFF3\", \"u\": \"format_3864\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)||GFF||GFF3\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206||format_2305||format_1975\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GFF3 feature file format with sequence.\", \"n\": \"GFF3-seq\", \"ns\": [], \"u\": \"format_1939\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)||GFF||GFF3||GFF3-seq\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206||format_2305||format_1975||format_1939\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Genome Variation Format (GVF). A GFF3-compatible format with defined header and attribute tags for sequence variation.\", \"n\": \"GVF\", \"ns\": [], \"u\": \"format_3019\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)||GFF||GFF3||GVF\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206||format_2305||format_1975||format_3019\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"mirGFF3 is a common format for microRNA data resulting from small-RNA RNA-Seq workflows.\", \"n\": \"mirGFF3\", \"ns\": [], \"u\": \"format_3864\", \"es\": [\"miRTop format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)||GFF||GFF3||mirGFF3\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206||format_2305||format_1975||format_3864\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Gene Transfer Format (GTF), a restricted version of GFF.\", \"n\": \"GTF\", \"ns\": [], \"u\": \"format_2306\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)||GFF||GTF\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206||format_2305||format_2306\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GTrack is a generic and optimised tabular format for genome or sequence feature tracks. GTrack unifies the power of other track formats (e.g. GFF3, BED, WIG), and while optimised in size, adds more flexibility, customisation, and automation (\\\"machine understandability\\\").\", \"n\": \"GTrack\", \"ns\": [], \"u\": \"format_3164\", \"es\": [\"BioXSD/GTrack GTrack\", \"BioXSD|GTrack GTrack\", \"GTrack format\", \"GTrack|BTrack|GSuite GTrack\", \"GTrack|GSuite|BTrack GTrack\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)||GTrack\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206||format_3164\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A five-column, tab-delimited table of feature locations and qualifiers for importing annotation into an existing Sequin submission (an NCBI tool for submitting and updating GenBank entries).\", \"n\": \"Sequin format\", \"ns\": [], \"u\": \"format_3701\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)||Sequin format\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206||format_3701\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A sequence format resembling uniprotkb entry format.\", \"n\": \"uniprotkb-like format\", \"ns\": [], \"u\": \"format_2547\", \"es\": [], \"ch\": [{\"n\": \"UniProt-like (text)\", \"u\": \"format_2187\"}, {\"n\": \"UniProtKB XML\", \"u\": \"format_3770\"}, {\"n\": \"UniProtKB RDF\", \"u\": \"format_3771\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||uniprotkb-like format\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2547\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A text sequence format resembling uniprotkb entry format.\", \"n\": \"UniProt-like (text)\", \"ns\": [], \"u\": \"format_2187\", \"es\": [], \"ch\": [{\"n\": \"UniProtKB format\", \"u\": \"format_1963\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||uniprotkb-like format||UniProt-like (text)\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2547||format_2187\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"UniProtKB entry sequence format.\", \"n\": \"UniProtKB format\", \"ns\": [], \"u\": \"format_1963\", \"es\": [\"SwissProt format\", \"UniProt format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||uniprotkb-like format||UniProt-like (text)||UniProtKB format\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2547||format_2187||format_1963\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"UniProtKB XML sequence features format is an XML format available for downloading UniProt entries.\", \"n\": \"UniProtKB XML\", \"ns\": [], \"u\": \"format_3770\", \"es\": [\"UniProt XML\", \"UniProt XML format\", \"UniProtKB XML format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||uniprotkb-like format||UniProtKB XML\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2547||format_3770\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"UniProtKB RDF sequence features format is an RDF format available for downloading UniProt entries (in RDF/XML).\", \"n\": \"UniProtKB RDF\", \"ns\": [\"UniProt RDF/XML\", \"UniProt RDF/XML format\", \"UniProtKB RDF/XML\", \"UniProtKB RDF/XML format\"], \"u\": \"format_3771\", \"es\": [\"UniProt RDF\", \"UniProt RDF format\", \"UniProtKB RDF format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||uniprotkb-like format||UniProtKB RDF\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2547||format_3771\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"XML format for a sequence feature table.\", \"n\": \"Sequence feature table format (XML)\", \"ns\": [], \"u\": \"format_2553\", \"es\": [], \"ch\": [{\"n\": \"DASGFF\", \"u\": \"format_1978\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (XML)\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2553\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"DAS GFF (XML) feature format.\", \"n\": \"DASGFF\", \"ns\": [], \"u\": \"format_1978\", \"es\": [\"DASGFF feature\", \"das feature\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (XML)||DASGFF\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2553||format_1978\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BTrack is an HDF5-based binary format for genome or sequence feature tracks and their collections, suitable for integrative multi-track analysis. BTrack is a binary, compressed alternative to the GTrack and GSuite formats.\", \"n\": \"BTrack\", \"ns\": [], \"u\": \"format_3776\", \"es\": [\"BTrack (GTrack ecosystem of formats)\", \"BTrack format\", \"BioXSD/GTrack BTrack\", \"BioXSD|GTrack BTrack\", \"GTrack|BTrack|GSuite BTrack\", \"GTrack|GSuite|BTrack BTrack\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||BTrack\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_3776\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of a sequence annotation track.\", \"n\": \"Sequence annotation track format\", \"ns\": [], \"u\": \"format_2919\", \"es\": [], \"ch\": [{\"n\": \"BED\", \"u\": \"format_3003\"}, {\"n\": \"bigBed\", \"u\": \"format_3004\"}, {\"n\": \"WIG\", \"u\": \"format_3005\"}, {\"n\": \"bigWig\", \"u\": \"format_3006\"}, {\"n\": \"PSL\", \"u\": \"format_3007\"}, {\"n\": \"MAF\", \"u\": \"format_3008\"}, {\"n\": \"genePred\", \"u\": \"format_3011\"}, {\"n\": \"pgSnp\", \"u\": \"format_3012\"}, {\"n\": \"GTrack\", \"u\": \"format_3164\"}, {\"n\": \"bedgraph\", \"u\": \"format_3583\"}, {\"n\": \"customtrack\", \"u\": \"format_3588\"}, {\"n\": \"BTrack\", \"u\": \"format_3776\"}, {\"n\": \"GEN\", \"u\": \"format_3812\"}, {\"n\": \"proBED\", \"u\": \"format_3827\"}, {\"n\": \"TrackDB\", \"u\": \"format_3991\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format\", \"k\": \"format_1915||format_2350||format_1920||format_2919\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Browser Extensible Data (BED) format of sequence annotation track, typically to be displayed in a genome browser.\", \"n\": \"BED\", \"ns\": [], \"u\": \"format_3003\", \"es\": [], \"ch\": [{\"n\": \"bedstrict\", \"u\": \"format_3584\"}, {\"n\": \"chrominfo\", \"u\": \"format_3587\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||BED\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3003\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Browser Extensible Data (BED) format of sequence annotation track that strictly does not contain non-standard fields beyond the first 3 columns.\", \"n\": \"bedstrict\", \"ns\": [], \"u\": \"format_3584\", \"es\": [], \"ch\": [{\"n\": \"bed6\", \"u\": \"format_3585\"}, {\"n\": \"bed12\", \"u\": \"format_3586\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||BED||bedstrict\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3003||format_3584\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BED file format where each feature is described by chromosome, start, end, name, score, and strand.\", \"n\": \"bed6\", \"ns\": [], \"u\": \"format_3585\", \"es\": [], \"ch\": [{\"n\": \"ENCODE peak format\", \"u\": \"format_3612\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||BED||bedstrict||bed6\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3003||format_3584||format_3585\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Human ENCODE peak format.\", \"n\": \"ENCODE peak format\", \"ns\": [], \"u\": \"format_3612\", \"es\": [], \"ch\": [{\"n\": \"ENCODE narrow peak format\", \"u\": \"format_3613\"}, {\"n\": \"ENCODE broad peak format\", \"u\": \"format_3614\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||BED||bedstrict||bed6||ENCODE peak format\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3003||format_3584||format_3585||format_3612\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Human ENCODE narrow peak format.\", \"n\": \"ENCODE narrow peak format\", \"ns\": [], \"u\": \"format_3613\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||BED||bedstrict||bed6||ENCODE peak format||ENCODE narrow peak format\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3003||format_3584||format_3585||format_3612||format_3613\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Human ENCODE broad peak format.\", \"n\": \"ENCODE broad peak format\", \"ns\": [], \"u\": \"format_3614\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||BED||bedstrict||bed6||ENCODE peak format||ENCODE broad peak format\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3003||format_3584||format_3585||format_3612||format_3614\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A BED file where each feature is described by all twelve columns.\", \"n\": \"bed12\", \"ns\": [], \"u\": \"format_3586\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||BED||bedstrict||bed12\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3003||format_3584||format_3586\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Tabular format of chromosome names and sizes used by Galaxy.\", \"n\": \"chrominfo\", \"ns\": [], \"u\": \"format_3587\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||BED||chrominfo\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3003||format_3587\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"bigBed format for large sequence annotation tracks, similar to textual BED format.\", \"n\": \"bigBed\", \"ns\": [], \"u\": \"format_3004\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||bigBed\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3004\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Wiggle format (WIG) of a sequence annotation track that consists of a value for each sequence position. Typically to be displayed in a genome browser.\", \"n\": \"WIG\", \"ns\": [], \"u\": \"format_3005\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||WIG\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3005\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"bigWig format for large sequence annotation tracks that consist of a value for each sequence position. Similar to textual WIG format.\", \"n\": \"bigWig\", \"ns\": [], \"u\": \"format_3006\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||bigWig\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3006\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"PSL format of alignments, typically generated by BLAT or psLayout. Can be displayed in a genome browser like a sequence annotation track.\", \"n\": \"PSL\", \"ns\": [], \"u\": \"format_3007\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||PSL\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3007\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Multiple Alignment Format (MAF) supporting alignments of whole genomes with rearrangements, directions, multiple pieces to the alignment, and so forth.\", \"n\": \"MAF\", \"ns\": [], \"u\": \"format_3008\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||MAF\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3008\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"genePred table format for gene prediction tracks.\", \"n\": \"genePred\", \"ns\": [], \"u\": \"format_3011\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||genePred\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3011\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Personal Genome SNP (pgSnp) format for sequence variation tracks (indels and polymorphisms), supported by the UCSC Genome Browser.\", \"n\": \"pgSnp\", \"ns\": [], \"u\": \"format_3012\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||pgSnp\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3012\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GTrack is a generic and optimised tabular format for genome or sequence feature tracks. GTrack unifies the power of other track formats (e.g. GFF3, BED, WIG), and while optimised in size, adds more flexibility, customisation, and automation (\\\"machine understandability\\\").\", \"n\": \"GTrack\", \"ns\": [], \"u\": \"format_3164\", \"es\": [\"BioXSD/GTrack GTrack\", \"BioXSD|GTrack GTrack\", \"GTrack format\", \"GTrack|BTrack|GSuite GTrack\", \"GTrack|GSuite|BTrack GTrack\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||GTrack\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3164\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The bedGraph format allows display of continuous-valued data in track format. This display type is useful for probability scores and transcriptome data\", \"n\": \"bedgraph\", \"ns\": [], \"u\": \"format_3583\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||bedgraph\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3583\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Custom Sequence annotation track format used by Galaxy.\", \"n\": \"customtrack\", \"ns\": [], \"u\": \"format_3588\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||customtrack\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3588\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BTrack is an HDF5-based binary format for genome or sequence feature tracks and their collections, suitable for integrative multi-track analysis. BTrack is a binary, compressed alternative to the GTrack and GSuite formats.\", \"n\": \"BTrack\", \"ns\": [], \"u\": \"format_3776\", \"es\": [\"BTrack (GTrack ecosystem of formats)\", \"BTrack format\", \"BioXSD/GTrack BTrack\", \"BioXSD|GTrack BTrack\", \"GTrack|BTrack|GSuite BTrack\", \"GTrack|GSuite|BTrack BTrack\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||BTrack\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3776\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The GEN file format contains genetic data and describes SNPs.\", \"n\": \"GEN\", \"ns\": [], \"u\": \"format_3812\", \"es\": [\"Genotype file format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||GEN\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3812\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \". proBED is an adaptation of BED (format_3003), which was extended to meet specific requirements entailed by proteomics data.\", \"n\": \"proBED\", \"ns\": [], \"u\": \"format_3827\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||proBED\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3827\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A declaration file format for UCSC browsers track dataset display charateristics.\", \"n\": \"TrackDB\", \"ns\": [], \"u\": \"format_3991\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||TrackDB\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3991\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BioJSON is a BioXSD-schema-based JSON format of sequence-based data and some other common data - sequence records, alignments, feature records, references to resources, and more - optimised for integrative bioinformatics, web applications and APIs, and object-oriented programming.\", \"n\": \"BioJSON (BioXSD)\", \"ns\": [], \"u\": \"format_3772\", \"es\": [\"BioJSON (BioXSD data model)\", \"BioJSON format (BioXSD)\", \"BioXSD BioJSON\", \"BioXSD BioJSON format\", \"BioXSD JSON\", \"BioXSD JSON format\", \"BioXSD in JSON\", \"BioXSD in JSON format\", \"BioXSD+JSON\", \"BioXSD/GTrack BioJSON\", \"BioXSD|BioJSON|BioYAML BioJSON\", \"BioXSD|GTrack BioJSON\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||BioJSON (BioXSD)\", \"k\": \"format_1915||format_2350||format_1920||format_3772\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BioYAML is a BioXSD-schema-based YAML format of sequence-based data and some other common data - sequence records, alignments, feature records, references to resources, and more - optimised for integrative bioinformatics, web APIs, human readability and editting, and object-oriented programming.\", \"n\": \"BioYAML\", \"ns\": [], \"u\": \"format_3773\", \"es\": [\"BioXSD BioYAML\", \"BioXSD BioYAML format\", \"BioXSD YAML\", \"BioXSD YAML format\", \"BioXSD in YAML\", \"BioXSD in YAML format\", \"BioXSD+YAML\", \"BioXSD/GTrack BioYAML\", \"BioXSD|BioJSON|BioYAML BioYAML\", \"BioXSD|GTrack BioYAML\", \"BioYAML (BioXSD data model)\", \"BioYAML (BioXSD)\", \"BioYAML format\", \"BioYAML format (BioXSD)\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||BioYAML\", \"k\": \"format_1915||format_2350||format_1920||format_3773\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BioJSON is a JSON format of single multiple sequence alignments, with their annotations, features, and custom visualisation and application settings for the Jalview workbench.\", \"n\": \"BioJSON (Jalview)\", \"ns\": [], \"u\": \"format_3774\", \"es\": [\"BioJSON format (Jalview)\", \"JSON (Jalview)\", \"JSON format (Jalview)\", \"Jalview BioJSON\", \"Jalview BioJSON format\", \"Jalview JSON\", \"Jalview JSON format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||BioJSON (Jalview)\", \"k\": \"format_1915||format_2350||format_1920||format_3774\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||BioJSON (Jalview)\", \"k\": \"format_1915||format_2350||format_1921||format_3774\"}, {\"n\": \"Format||JSON||BioJSON (Jalview)\", \"k\": \"format_1915||format_3464||format_3774\"}, {\"n\": \"Format||YAML||JSON||BioJSON (Jalview)\", \"k\": \"format_1915||format_3750||format_3464||format_3774\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GSuite is a tabular format for collections of genome or sequence feature tracks, suitable for integrative multi-track analysis. GSuite contains links to genome/sequence tracks, with additional metadata.\", \"n\": \"GSuite\", \"ns\": [], \"u\": \"format_3775\", \"es\": [\"BioXSD/GTrack GSuite\", \"BioXSD|GTrack GSuite\", \"GSuite (GTrack ecosystem of formats)\", \"GSuite format\", \"GTrack|BTrack|GSuite GSuite\", \"GTrack|GSuite|BTrack GSuite\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||GSuite\", \"k\": \"format_1915||format_2350||format_1920||format_3775\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"