: [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (text)||csfasta\", \"k\": \"format_1915||format_2350||format_1921||format_2554||format_3589\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The A2M format is used as the primary format for multiple alignments of protein or nucleic-acid sequences in the SAM suite of tools. It is a small modification of FASTA format for sequences and is compatible with most tools that read FASTA.\", \"n\": \"XMFA\", \"ns\": [], \"u\": \"format_3811\", \"es\": [\"alignment format\", \"eXtended Multi-FastA format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (text)||XMFA\", \"k\": \"format_1915||format_2350||format_1921||format_2554||format_3811\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"XML format for molecular sequence alignment information.\", \"n\": \"Alignment format (XML)\", \"ns\": [], \"u\": \"format_2555\", \"es\": [], \"ch\": [{\"n\": \"BioXSD (XML)\", \"u\": \"format_2352\"}, {\"n\": \"HSAML\", \"u\": \"format_3845\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (XML)\", \"k\": \"format_1915||format_2350||format_1921||format_2555\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BioXSD-schema-based XML format of sequence-based data and some other common data - sequence records, alignments, feature records, references to resources, and more - optimised for integrative bioinformatics, Web services, and object-oriented programming.\", \"n\": \"BioXSD (XML)\", \"ns\": [], \"u\": \"format_2352\", \"es\": [\"BioXSD XML\", \"BioXSD XML format\", \"BioXSD in XML\", \"BioXSD in XML format\", \"BioXSD+XML\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (XML)||BioXSD (XML)\", \"k\": \"format_1915||format_2350||format_1921||format_2555||format_2352\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"An alignment format generated by PRANK/PRANKSTER consisting of four elements: newick, nodes, selection and model.\", \"n\": \"HSAML\", \"ns\": [], \"u\": \"format_3845\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (XML)||HSAML\", \"k\": \"format_1915||format_2350||format_1921||format_2555||format_3845\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Data format for molecular sequence alignment information that can hold sequence alignment(s) of only 2 sequences.\", \"n\": \"Alignment format (pair only)\", \"ns\": [], \"u\": \"format_2920\", \"es\": [], \"ch\": [{\"n\": \"srspair\", \"u\": \"format_2003\"}, {\"n\": \"BAM\", \"u\": \"format_2572\"}, {\"n\": \"SAM\", \"u\": \"format_2573\"}, {\"n\": \"PSL\", \"u\": \"format_3007\"}, {\"n\": \"axt\", \"u\": \"format_3013\"}, {\"n\": \"LAV\", \"u\": \"format_3014\"}, {\"n\": \"Pileup\", \"u\": \"format_3015\"}, {\"n\": \"EBI Application Result XML\", \"u\": \"format_3157\"}, {\"n\": \"CRAM\", \"u\": \"format_3462\"}, {\"n\": \"proBAM\", \"u\": \"format_3826\"}, {\"n\": \"CHAIN\", \"u\": \"format_3982\"}, {\"n\": \"CIGAR format\", \"u\": \"format_3992\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)\", \"k\": \"format_1915||format_2350||format_1921||format_2920\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Simple sequence pair (alignment) format for SRS.\", \"n\": \"srspair\", \"ns\": [], \"u\": \"format_2003\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||srspair\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_2003\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BAM format, the binary, BGZF-formatted compressed version of SAM format for alignment of nucleotide sequences (e.g. sequencing reads) to (a) reference sequence(s). May contain base-call and alignment qualities and other data.\", \"n\": \"BAM\", \"ns\": [], \"u\": \"format_2572\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||BAM\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_2572\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Sequence Alignment/Map (SAM) format for alignment of nucleotide sequences (e.g. sequencing reads) to (a) reference sequence(s). May contain base-call and alignment qualities and other data.\", \"n\": \"SAM\", \"ns\": [], \"u\": \"format_2573\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||SAM\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_2573\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"PSL format of alignments, typically generated by BLAT or psLayout. Can be displayed in a genome browser like a sequence annotation track.\", \"n\": \"PSL\", \"ns\": [], \"u\": \"format_3007\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||PSL\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3007\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"axt format of alignments, typically produced from BLASTZ.\", \"n\": \"axt\", \"ns\": [], \"u\": \"format_3013\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||axt\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3013\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"LAV format of alignments generated by BLASTZ and LASTZ.\", \"n\": \"LAV\", \"ns\": [], \"u\": \"format_3014\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||LAV\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3014\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Pileup format of alignment of sequences (e.g. sequencing reads) to (a) reference sequence(s). Contains aligned bases per base of the reference sequence(s).\", \"n\": \"Pileup\", \"ns\": [], \"u\": \"format_3015\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||Pileup\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3015\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"EBI Application Result XML is a format returned by sequence similarity search Web services at EBI.\", \"n\": \"EBI Application Result XML\", \"ns\": [], \"u\": \"format_3157\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||EBI Application Result XML\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3157\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Reference-based compression of alignment format\", \"n\": \"CRAM\", \"ns\": [], \"u\": \"format_3462\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||CRAM\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3462\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \". proBAM is an adaptation of BAM (format_2572), which was extended to meet specific requirements entailed by proteomics data.\", \"n\": \"proBAM\", \"ns\": [], \"u\": \"format_3826\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||proBAM\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3826\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The CHAIN format describes a pairwise alignment that allow gaps in both sequences simultaneously and is used by the UCSC Genome Browser.\", \"n\": \"CHAIN\", \"ns\": [], \"u\": \"format_3982\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||CHAIN\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3982\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Compact Idiosyncratic Gapped Alignment Report format is a compressed (run-length encoded) pairwise alignment format. It is useful for representing long (e.g. genomic) pairwise alignments.\", \"n\": \"CIGAR format\", \"ns\": [], \"u\": \"format_3992\", \"es\": [\"CIGAR\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||CIGAR format\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3992\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"RNA Markup Language.\", \"n\": \"RNAML\", \"ns\": [], \"u\": \"format_3311\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||RNAML\", \"k\": \"format_1915||format_2350||format_1921||format_3311\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BioJSON is a BioXSD-schema-based JSON format of sequence-based data and some other common data - sequence records, alignments, feature records, references to resources, and more - optimised for integrative bioinformatics, web applications and APIs, and object-oriented programming.\", \"n\": \"BioJSON (BioXSD)\", \"ns\": [], \"u\": \"format_3772\", \"es\": [\"BioJSON (BioXSD data model)\", \"BioJSON format (BioXSD)\", \"BioXSD BioJSON\", \"BioXSD BioJSON format\", \"BioXSD JSON\", \"BioXSD JSON format\", \"BioXSD in JSON\", \"BioXSD in JSON format\", \"BioXSD+JSON\", \"BioXSD/GTrack BioJSON\", \"BioXSD|BioJSON|BioYAML BioJSON\", \"BioXSD|GTrack BioJSON\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||BioJSON (BioXSD)\", \"k\": \"format_1915||format_2350||format_1921||format_3772\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BioYAML is a BioXSD-schema-based YAML format of sequence-based data and some other common data - sequence records, alignments, feature records, references to resources, and more - optimised for integrative bioinformatics, web APIs, human readability and editting, and object-oriented programming.\", \"n\": \"BioYAML\", \"ns\": [], \"u\": \"format_3773\", \"es\": [\"BioXSD BioYAML\", \"BioXSD BioYAML format\", \"BioXSD YAML\", \"BioXSD YAML format\", \"BioXSD in YAML\", \"BioXSD in YAML format\", \"BioXSD+YAML\", \"BioXSD/GTrack BioYAML\", \"BioXSD|BioJSON|BioYAML BioYAML\", \"BioXSD|GTrack BioYAML\", \"BioYAML (BioXSD data model)\", \"BioYAML (BioXSD)\", \"BioYAML format\", \"BioYAML format (BioXSD)\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||BioYAML\", \"k\": \"format_1915||format_2350||format_1921||format_3773\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BioJSON is a JSON format of single multiple sequence alignments, with their annotations, features, and custom visualisation and application settings for the Jalview workbench.\", \"n\": \"BioJSON (Jalview)\", \"ns\": [], \"u\": \"format_3774\", \"es\": [\"BioJSON format (Jalview)\", \"JSON (Jalview)\", \"JSON format (Jalview)\", \"Jalview BioJSON\", \"Jalview BioJSON format\", \"Jalview JSON\", \"Jalview JSON format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||BioJSON (Jalview)\", \"k\": \"format_1915||format_2350||format_1921||format_3774\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Binary format used by the ARB software suite\", \"n\": \"ARB\", \"ns\": [], \"u\": \"format_3830\", \"es\": [\"ARB binary format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||ARB\", \"k\": \"format_1915||format_2350||format_1921||format_3830\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A set of XML compliant markup components for describing multiple sequence alignments.\", \"n\": \"MSAML\", \"ns\": [], \"u\": \"format_3849\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Alignment format||MSAML\", \"k\": \"format_1915||format_2350||format_1921||format_3849\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Data format for a phylogenetic tree.\", \"n\": \"Phylogenetic tree format\", \"ns\": [], \"u\": \"format_2006\", \"es\": [], \"ch\": [{\"n\": \"Phylogenetic tree format (text)\", \"u\": \"format_2556\"}, {\"n\": \"Phylogenetic tree format (XML)\", \"u\": \"format_2557\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Phylogenetic tree format\", \"k\": \"format_1915||format_2350||format_2006\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Text format for a phylogenetic tree.\", \"n\": \"Phylogenetic tree format (text)\", \"ns\": [], \"u\": \"format_2556\", \"es\": [], \"ch\": [{\"n\": \"ClustalW dendrogram\", \"u\": \"format_1424\"}, {\"n\": \"Phylip tree raw\", \"u\": \"format_1425\"}, {\"n\": \"Phylip tree format\", \"u\": \"format_1435\"}, {\"n\": \"TreeBASE format\", \"u\": \"format_1436\"}, {\"n\": \"TreeFam format\", \"u\": \"format_1437\"}, {\"n\": \"newick\", \"u\": \"format_1910\"}, {\"n\": \"TreeCon format\", \"u\": \"format_1911\"}, {\"n\": \"Nexus format\", \"u\": \"format_1912\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (text)\", \"k\": \"format_1915||format_2350||format_2006||format_2556\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Dendrogram (tree file) format generated by ClustalW.\", \"n\": \"ClustalW dendrogram\", \"ns\": [], \"u\": \"format_1424\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (text)||ClustalW dendrogram\", \"k\": \"format_1915||format_2350||format_2006||format_2556||format_1424\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Raw data file format used by Phylip from which a phylogenetic tree is directly generated or plotted.\", \"n\": \"Phylip tree raw\", \"ns\": [], \"u\": \"format_1425\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (text)||Phylip tree raw\", \"k\": \"format_1915||format_2350||format_2006||format_2556||format_1425\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Phylogenetic tree data format used by the PHYLIP program.\", \"n\": \"Phylip tree format\", \"ns\": [], \"u\": \"format_1435\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (text)||Phylip tree format\", \"k\": \"format_1915||format_2350||format_2006||format_2556||format_1435\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The format of an entry from the TreeBASE database of phylogenetic data.\", \"n\": \"TreeBASE format\", \"ns\": [], \"u\": \"format_1436\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (text)||TreeBASE format\", \"k\": \"format_1915||format_2350||format_2006||format_2556||format_1436\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The format of an entry from the TreeFam database of phylogenetic data.\", \"n\": \"TreeFam format\", \"ns\": [], \"u\": \"format_1437\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (text)||TreeFam format\", \"k\": \"format_1915||format_2350||format_2006||format_2556||format_1437\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Phylogenetic tree Newick (text) format.\", \"n\": \"newick\", \"ns\": [], \"u\": \"format_1910\", \"es\": [\"nh\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (text)||newick\", \"k\": \"format_1915||format_2350||format_2006||format_2556||format_1910\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Phylogenetic tree TreeCon (text) format.\", \"n\": \"TreeCon format\", \"ns\": [], \"u\": \"format_1911\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (text)||TreeCon format\", \"k\": \"format_1915||format_2350||format_2006||format_2556||format_1911\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Phylogenetic tree Nexus (text) format.\", \"n\": \"Nexus format\", \"ns\": [], \"u\": \"format_1912\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (text)||Nexus format\", \"k\": \"format_1915||format_2350||format_2006||format_2556||format_1912\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"XML format for a phylogenetic tree.\", \"n\": \"Phylogenetic tree format (XML)\", \"ns\": [], \"u\": \"format_2557\", \"es\": [], \"ch\": [{\"n\": \"phyloXML\", \"u\": \"format_3159\"}, {\"n\": \"NeXML\", \"u\": \"format_3160\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (XML)\", \"k\": \"format_1915||format_2350||format_2006||format_2557\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"phyloXML is a standardised XML format for phylogenetic trees, networks, and associated data.\", \"n\": \"phyloXML\", \"ns\": [], \"u\": \"format_3159\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (XML)||phyloXML\", \"k\": \"format_1915||format_2350||format_2006||format_2557||format_3159\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"NeXML is a standardised XML format for rich phyloinformatic data.\", \"n\": \"NeXML\", \"ns\": [], \"u\": \"format_3160\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (XML)||NeXML\", \"k\": \"format_1915||format_2350||format_2006||format_2557||format_3160\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Data format for a biological pathway or network.\", \"n\": \"Biological pathway or network format\", \"ns\": [], \"u\": \"format_2013\", \"es\": [], \"ch\": [{\"n\": \"SBML\", \"u\": \"format_2585\"}, {\"n\": \"BioPAX\", \"u\": \"format_3156\"}, {\"n\": \"CopasiML\", \"u\": \"format_3239\"}, {\"n\": \"CellML\", \"u\": \"format_3240\"}, {\"n\": \"sif\", \"u\": \"format_3619\"}, {\"n\": \"GPML\", \"u\": \"format_3657\"}, {\"n\": \"COMBINE OMEX\", \"u\": \"format_3686\"}, {\"n\": \"SBtab\", \"u\": \"format_3688\"}, {\"n\": \"BCML\", \"u\": \"format_3689\"}, {\"n\": \"SBGN-ML\", \"u\": \"format_3692\"}, {\"n\": \"VisML\", \"u\": \"format_3821\"}, {\"n\": \"GML\", \"u\": \"format_3822\"}, {\"n\": \"KGML\", \"u\": \"format_3847\"}, {\"n\": \"NeuroML\", \"u\": \"format_3971\"}, {\"n\": \"BNGL\", \"u\": \"format_3972\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Biological pathway or network format\", \"k\": \"format_1915||format_2350||format_2013\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Systems Biology Markup Language (SBML), the standard XML format for models of biological processes such as for example metabolism, cell signaling, and gene regulation.\", \"n\": \"SBML\", \"ns\": [], \"u\": \"format_2585\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||SBML\", \"k\": \"format_1915||format_2350||format_2013||format_2585\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BioPAX is an exchange format for pathway data, with its data model defined in OWL.\", \"n\": \"BioPAX\", \"ns\": [], \"u\": \"format_3156\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Format (by type of data)||Biological pathway or network format||BioPAX\", \"k\": \"format_1915||format_2350||format_2013||format_3156\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"CopasiML, the native format of COPASI.\", \"n\": \"CopasiML\", \"ns\": [], \"u\": \"format_3239\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||CopasiML\", \"k\": \"format_1915||format_2350||format_2013||format_3239\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"CellML, the format for mathematical models of biological and other networks.\", \"n\": \"CellML\", \"ns\": [], \"u\": \"format_3240\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||CellML\", \"k\": \"format_1915||format_2350||format_2013||format_3240\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"SIF (simple interaction file) Format - a network/pathway format used for instance in cytoscape.\", \"n\": \"sif\", \"ns\": [], \"u\": \"format_3619\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Format (by type of data)||Biological pathway or network format||sif\", \"k\": \"format_1915||format_2350||format_2013||format_3619\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Graphical Pathway Markup Language (GPML) is an XML format used for exchanging biological pathways.\", \"n\": \"GPML\", \"ns\": [], \"u\": \"format_3657\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||GPML\", \"k\": \"format_1915||format_2350||format_2013||format_3657\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Open Modeling EXchange format (OMEX) is a ZIPped format for encapsulating all information necessary for a modeling and simulation project in systems biology.\", \"n\": \"COMBINE OMEX\", \"ns\": [], \"u\": \"format_3686\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||COMBINE OMEX\", \"k\": \"format_1915||format_2350||format_2013||format_3686\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"SBtab is a tabular format for biochemical network models.\", \"n\": \"SBtab\", \"ns\": [], \"u\": \"format_3688\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||SBtab\", \"k\": \"format_1915||format_2350||format_2013||format_3688\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Biological Connection Markup Language (BCML) is an XML format for biological pathways.\", \"n\": \"BCML\", \"ns\": [], \"u\": \"format_3689\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||BCML\", \"k\": \"format_1915||format_2350||format_2013||format_3689\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"SBGN-ML is an XML format for Systems Biology Graphical Notation (SBGN) diagrams of biological pathways or networks.\", \"n\": \"SBGN-ML\", \"ns\": [], \"u\": \"format_3692\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||SBGN-ML\", \"k\": \"format_1915||format_2350||format_2013||format_3692\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Default XML format of VisANT, containing all the network information.\", \"n\": \"VisML\", \"ns\": [], \"u\": \"format_3821\", \"es\": [\"VisANT xml\", \"VisANT xml format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||VisML\", \"k\": \"format_1915||format_2350||format_2013||format_3821\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GML (Graph Modeling Language) is a text file format supporting network data with a very easy syntax. It is used by Graphlet, Pajek, yEd, LEDA and NetworkX.\", \"n\": \"GML\", \"ns\": [], \"u\": \"format_3822\", \"es\": [\"GML format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||GML\", \"k\": \"format_1915||format_2350||format_2013||format_3822\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The KEGG Markup Language (KGML) is an exchange format of the KEGG pathway maps, which is converted from internally used KGML+ (KGML+SVG) format.\", \"n\": \"KGML\", \"ns\": [], \"u\": \"format_3847\", \"es\": [\"KEGG Markup Language\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||KGML\", \"k\": \"format_1915||format_2350||format_2013||format_3847\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A model description language for computational neuroscience.\", \"n\": \"NeuroML\", \"ns\": [], \"u\": \"format_3971\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||NeuroML\", \"k\": \"format_1915||format_2350||format_2013||format_3971\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BioNetGen is a format for the specification and simulation of rule-based models of biochemical systems, including signal transduction, metabolic, and genetic regulatory networks.\", \"n\": \"BNGL\", \"ns\": [], \"u\": \"format_3972\", \"es\": [\"BioNetGen Language\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||BNGL\", \"k\": \"format_1915||format_2350||format_2013||format_3972\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Data format for a sequence-profile alignment.\", \"n\": \"Sequence-profile alignment format\", \"ns\": [], \"u\": \"format_2014\", \"es\": [], \"ch\": [{\"n\": \"Sequence-MEME profile alignment\", \"u\": \"format_1419\"}, {\"n\": \"HMMER profile alignment (sequences versus HMMs)\", \"u\": \"format_1421\"}, {\"n\": \"HMMER profile alignment (HMM versus sequences)\", \"u\": \"format_1422\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence-profile alignment format\", \"k\": \"format_1915||format_2350||format_2014\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format for alignment of molecular sequences to MEME profiles (position-dependent scoring matrices) as generated by the MAST tool from the MEME package.\", \"n\": \"Sequence-MEME profile alignment\", \"ns\": [], \"u\": \"format_1419\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence-profile alignment format||Sequence-MEME profile alignment\", \"k\": \"format_1915||format_2350||format_2014||format_1419\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format used by the HMMER package for an alignment of a sequence against a hidden Markov model database.\", \"n\": \"HMMER profile alignment (sequences versus HMMs)\", \"ns\": [], \"u\": \"format_1421\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence-profile alignment format||HMMER profile alignment (sequences versus HMMs)\", \"k\": \"format_1915||format_2350||format_2014||format_1421\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format used by the HMMER package for of an alignment of a hidden Markov model against a sequence database.\", \"n\": \"HMMER profile alignment (HMM versus sequences)\", \"ns\": [], \"u\": \"format_1422\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence-profile alignment format||HMMER profile alignment (HMM versus sequences)\", \"k\": \"format_1915||format_2350||format_2014||format_1422\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Data format for a full-text scientific article.\", \"n\": \"Article format\", \"ns\": [], \"u\": \"format_2020\", \"es\": [\"Literature format\"], \"ch\": [{\"n\": \"pmc\", \"u\": \"format_1739\"}, {\"n\": \"medline\", \"u\": \"format_2194\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Article format\", \"k\": \"format_1915||format_2350||format_2020\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Article format of the PubMed Central database.\", \"n\": \"pmc\", \"ns\": [], \"u\": \"format_1739\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Article format||pmc\", \"k\": \"format_1915||format_2350||format_2020||format_1739\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Abstract format used by MedLine database.\", \"n\": \"medline\", \"ns\": [], \"u\": \"format_2194\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Article format||medline\", \"k\": \"format_1915||format_2350||format_2020||format_2194\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Data format of a report from text mining.\", \"n\": \"Text mining report format\", \"ns\": [], \"u\": \"format_2021\", \"es\": [], \"ch\": [{\"n\": \"iHOP format\", \"u\": \"format_1740\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Text mining report format\", \"k\": \"format_1915||format_2350||format_2021\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The format of iHOP (Information Hyperlinked over Proteins) text-mining result.\", \"n\": \"iHOP format\", \"ns\": [], \"u\": \"format_1740\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Text mining report format||iHOP format\", \"k\": \"format_1915||format_2350||format_2021||format_1740\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Data format for reports on enzyme kinetics.\", \"n\": \"Enzyme kinetics report format\", \"ns\": [], \"u\": \"format_2027\", \"es\": [], \"ch\": [{\"n\": \"findkm\", \"u\": \"format_1582\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Enzyme kinetics report format\", \"k\": \"format_1915||format_2350||format_2027\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A report format for the kinetics of enzyme-catalysed reaction(s) in a format generated by EMBOSS findkm. This includes Michaelis Menten plot, Hanes Woolf plot, Michaelis Menten constant (Km) and maximum velocity (Vmax).\", \"n\": \"findkm\", \"ns\": [], \"u\": \"format_1582\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Enzyme kinetics report format||findkm\", \"k\": \"format_1915||format_2350||format_2027||format_1582\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of a report on a chemical compound.\", \"n\": \"Chemical data format\", \"ns\": [], \"u\": \"format_2030\", \"es\": [\"Chemical compound annotation format\", \"Chemical structure format\", \"Small molecule report format\", \"Small molecule structure format\"], \"ch\": [{\"n\": \"HET group dictionary entry format\", \"u\": \"format_1705\"}, {\"n\": \"SDF\", \"u\": \"format_3814\"}, {\"n\": \"Molfile\", \"u\": \"format_3815\"}, {\"n\": \"Mol2\", \"u\": \"format_3816\"}, {\"n\": \"BcForms\", \"u\": \"format_3951\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Chemical data format\", \"k\": \"format_1915||format_2350||format_2030\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The format of an entry from the HET group dictionary (HET groups from PDB files).\", \"n\": \"HET group dictionary entry format\", \"ns\": [], \"u\": \"format_1705\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Chemical data format||HET group dictionary entry format\", \"k\": \"format_1915||format_2350||format_2030||format_1705\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"SDF is one of a family of chemical-data file formats developed by MDL Information Systems; it is intended especially for structural information.\", \"n\": \"SDF\", \"ns\": [], \"u\": \"format_3814\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Chemical data format||SDF\", \"k\": \"format_1915||format_2350||format_2030||format_3814\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"An MDL Molfile is a file format for holding information about the atoms, bonds, connectivity and coordinates of a molecule.\", \"n\": \"Molfile\", \"ns\": [], \"u\": \"format_3815\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Chemical data format||Molfile\", \"k\": \"format_1915||format_2350||format_2030||format_3815\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Complete, portable representation of a SYBYL molecule. ASCII file which contains all the information needed to reconstruct a SYBYL molecule.\", \"n\": \"Mol2\", \"ns\": [], \"u\": \"format_3816\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Chemical data format||Mol2\", \"k\": \"format_1915||format_2350||format_2030||format_3816\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BcForms is a format for abstractly describing the molecular structure (atoms and bonds) of macromolecular complexes as a collection of subunits and crosslinks. Each subunit can be described with BpForms (format_3909) or SMILES (data_2301). BcForms uses an ontology of crosslinks to abstract the chemical details of crosslinks from the descriptions of complexes (see https://bpforms.org/crosslink.html).\", \"n\": \"BcForms\", \"ns\": [], \"u\": \"format_3951\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Chemical data format||BcForms\", \"k\": \"format_1915||format_2350||format_2030||format_3951\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of a report on a particular locus, gene, gene system or groups of genes.\", \"n\": \"Gene annotation format\", \"ns\": [], \"u\": \"format_2031\", \"es\": [\"Gene features format\"], \"ch\": [{\"n\": \"est2genome format\", \"u\": \"format_1316\"}, {\"n\": \"OrthoXML\", \"u\": \"format_3850\"}, {\"n\": \"WEGO\", \"u\": \"format_3979\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Gene annotation format\", \"k\": \"format_1915||format_2350||format_2031\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of a report on exon-intron structure generated by EMBOSS est2genome.\", \"n\": \"est2genome format\", \"ns\": [], \"u\": \"format_1316\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene annotation format||est2genome format\", \"k\": \"format_1915||format_2350||format_2031||format_1316\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"OrthoXML is designed broadly to allow the storage and comparison of orthology data from any ortholog database. It establishes a structure for describing orthology relationships while still allowing flexibility for database-specific information to be encapsulated in the same format.\", \"n\": \"OrthoXML\", \"ns\": [], \"u\": \"format_3850\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene annotation format||OrthoXML\", \"k\": \"format_1915||format_2350||format_2031||format_3850\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"WEGO native format used by the Web Gene Ontology Annotation Plot application.   Tab-delimited format with gene names and others GO IDs (columns) with one annotation record per line.\", \"n\": \"WEGO\", \"ns\": [], \"u\": \"format_3979\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene annotation format||WEGO\", \"k\": \"format_1915||format_2350||format_2031||format_3979\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of a workflow.\", \"n\": \"Workflow format\", \"ns\": [], \"u\": \"format_2032\", \"es\": [], \"ch\": [{\"n\": \"Taverna workflow format\", \"u\": \"format_1665\"}, {\"n\": \"KNIME datatable format\", \"u\": \"format_3765\"}, {\"n\": \"CWL\", \"u\": \"format_3857\"}, {\"n\": \"gxformat2\", \"u\": \"format_3985\"}, {\"n\": \"Python script\", \"u\": \"format_3996\"}, {\"n\": \"Perl script\", \"u\": \"format_3998\"}, {\"n\": \"R script\", \"u\": \"format_3999\"}, {\"n\": \"R markdown\", \"u\": \"format_4000\"}, {\"n\": \"MATLAB script\", \"u\": \"format_4007\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Workflow format\", \"k\": \"format_1915||format_2350||format_2032\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of Taverna workflows.\", \"n\": \"Taverna workflow format\", \"ns\": [], \"u\": \"format_1665\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Workflow format||Taverna workflow format\", \"k\": \"format_1915||format_2350||format_2032||format_1665\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Data table formatted such that it can be passed/streamed within the KNIME platform.\", \"n\": \"KNIME datatable format\", \"ns\": [], \"u\": \"format_3765\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Format (by type of data)||Workflow format||KNIME datatable format\", \"k\": \"format_1915||format_2350||format_2032||format_3765\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Common Workflow Language (CWL) format for description of command-line tools and workflows.\", \"n\": \"CWL\", \"ns\": [], \"u\": \"format_3857\", \"es\": [\"Common Workflow Language\", \"CommonWL\"], \"ch\": [], \"p\": [{\"n\": \"Format||Format (by type of data)||Workflow format||CWL\", \"k\": \"format_1915||format_2350||format_2032||format_3857\"}, {\"n\": \"Format||YAML||CWL\", \"k\": \"format_1915||format_3750||format_3857\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"An emerging format for high-level Galaxy workflow description.\", \"n\": \"gxformat2\", \"ns\": [], \"u\": \"format_3985\", \"es\": [\"Galaxy workflow format\", \"GalaxyWF\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Workflow format||gxformat2\", \"k\": \"format_1915||format_2350||format_2032||format_3985\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format for scripts writtenin Python - a widely used high-level programming language for general-purpose programming.\", \"n\": \"Python script\", \"ns\": [], \"u\": \"format_3996\", \"es\": [\"Python\", \"Python program\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Workflow format||Python script\", \"k\": \"format_1915||format_2350||format_2032||format_3996\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format for scripts written in Perl - a family of high-level, general-purpose, interpreted, dynamic programming languages.\", \"n\": \"Perl script\", \"ns\": [], \"u\": \"format_3998\", \"es\": [\"Perl\", \"Perl program\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Workflow format||Perl script\", \"k\": \"format_1915||format_2350||format_2032||format_3998\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format for scripts written in the R language - an open source programming language and software environment for statistical computing and graphics that is supported by the R Foundation for Statistical Computing.\", \"n\": \"R script\", \"ns\": [], \"u\": \"format_3999\", \"es\": [\"R\", \"R program\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Workflow format||R script\", \"k\": \"format_1915||format_2350||format_2032||format_3999\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"A file format for making dynamic documents (R Markdown scripts) with the R language.\", \"n\": \"R markdown\", \"ns\": [], \"u\": \"format_4000\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Workflow format||R markdown\", \"k\": \"format_1915||format_2350||format_2032||format_4000\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The file format for MATLAB scripts or functions.\", \"n\": \"MATLAB script\", \"ns\": [], \"u\": \"format_4007\", \"es\": [\"MATLAB\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Workflow format||MATLAB script\", \"k\": \"format_1915||format_2350||format_2032||format_4007\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Data format for a molecular tertiary structure.\", \"n\": \"Tertiary structure format\", \"ns\": [], \"u\": \"format_2033\", \"es\": [], \"ch\": [{\"n\": \"PDB database entry format\", \"u\": \"format_1475\"}, {\"n\": \"XYZ\", \"u\": \"format_3877\"}, {\"n\": \"mdcrd\", \"u\": \"format_3878\"}, {\"n\": \"GROMACS top\", \"u\": \"format_3880\"}, {\"n\": \"AMBER top\", \"u\": \"format_3881\"}, {\"n\": \"PSF\", \"u\": \"format_3882\"}, {\"n\": \"GROMACS itp\", \"u\": \"format_3883\"}, {\"n\": \"RST\", \"u\": \"format_3886\"}, {\"n\": \"CHARMM rtf\", \"u\": \"format_3887\"}, {\"n\": \"trr\", \"u\": \"format_3910\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Tertiary structure format\", \"k\": \"format_1915||format_2350||format_2033\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of an entry (or part of an entry) from the PDB database.\", \"n\": \"PDB database entry format\", \"ns\": [], \"u\": \"format_1475\", \"es\": [\"PDB entry format\"], \"ch\": [{\"n\": \"PDB\", \"u\": \"format_1476\"}, {\"n\": \"mmCIF\", \"u\": \"format_1477\"}, {\"n\": \"PDBML\", \"u\": \"format_1478\"}, {\"n\": \"pdbatom\", \"u\": \"format_1950\"}, {\"n\": \"pdbatomnuc\", \"u\": \"format_1951\"}, {\"n\": \"pdbseqresnuc\", \"u\": \"format_1952\"}, {\"n\": \"pdbseqres\", \"u\": \"format_1953\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Tertiary structure format||PDB database entry format\", \"k\": \"format_1915||format_2350||format_2033||format_1475\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Entry format of PDB database in PDB format.\", \"n\": \"PDB\", \"ns\": [], \"u\": \"format_1476\", \"es\": [\"PDB format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||PDB database entry format||PDB\", \"k\": \"format_1915||format_2350||format_2033||format_1475||format_1476\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Entry format of PDB database in mmCIF format.\", \"n\": \"mmCIF\", \"ns\": [], \"u\": \"format_1477\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||PDB database entry format||mmCIF\", \"k\": \"format_1915||format_2350||format_2033||format_1475||format_1477\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Entry format of PDB database in PDBML (XML) format.\", \"n\": \"PDBML\", \"ns\": [], \"u\": \"format_1478\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||PDB database entry format||PDBML\", \"k\": \"format_1915||format_2350||format_2033||format_1475||format_1478\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"PDB sequence format (ATOM lines).\", \"n\": \"pdbatom\", \"ns\": [], \"u\": \"format_1950\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||PDB database entry format||pdbatom\", \"k\": \"format_1915||format_2350||format_2033||format_1475||format_1950\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"PDB nucleotide sequence format (ATOM lines).\", \"n\": \"pdbatomnuc\", \"ns\": [], \"u\": \"format_1951\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||PDB database entry format||pdbatomnuc\", \"k\": \"format_1915||format_2350||format_2033||format_1475||format_1951\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"PDB nucleotide sequence format (SEQRES lines).\", \"n\": \"pdbseqresnuc\", \"ns\": [], \"u\": \"format_1952\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||PDB database entry format||pdbseqresnuc\", \"k\": \"format_1915||format_2350||format_2033||format_1475||format_1952\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"PDB sequence format (SEQRES lines).\", \"n\": \"pdbseqres\", \"ns\": [], \"u\": \"format_1953\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||PDB database entry format||pdbseqres\", \"k\": \"format_1915||format_2350||format_2033||format_1475||format_1953\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The XYZ chemical file format is widely supported by many programs, although many slightly different XYZ file formats coexist (Tinker XYZ, UniChem XYZ, etc.). Basic information stored for each atom in the system are x, y and z coordinates and atom element/atomic number.\", \"n\": \"XYZ\", \"ns\": [], \"u\": \"format_3877\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||XYZ\", \"k\": \"format_1915||format_2350||format_2033||format_3877\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"AMBER trajectory (also called mdcrd), with 10 coordinates per line and format F8.3 (fixed point notation with field width 8 and 3 decimal places).\", \"n\": \"mdcrd\", \"ns\": [], \"u\": \"format_3878\", \"es\": [\"AMBER trajectory format\", \"inpcrd\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||mdcrd\", \"k\": \"format_1915||format_2350||format_2033||format_3878\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GROMACS MD package top textual files define an entire structure system topology, either directly, or by including itp files.\", \"n\": \"GROMACS top\", \"ns\": [], \"u\": \"format_3880\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||GROMACS top\", \"k\": \"format_1915||format_2350||format_2033||format_3880\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"AMBER Prmtop file (version 7) is a structure topology text file divided in several sections designed to be parsed easily using simple Fortran code. Each section contains particular topology information, such as atom name, charge, mass, angles, dihedrals, etc.\", \"n\": \"AMBER top\", \"ns\": [], \"u\": \"format_3881\", \"es\": [\"AMBER Parm\", \"AMBER Parm7\", \"Parm7\", \"Prmtop\", \"Prmtop7\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||AMBER top\", \"k\": \"format_1915||format_2350||format_2033||format_3881\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"X-Plor Protein Structure Files (PSF) are structure topology files used by NAMD and CHARMM molecular simulations programs. PSF files contain six main sections of interest: atoms, bonds, angles, dihedrals, improper dihedrals (force terms used to maintain planarity) and cross-terms.\", \"n\": \"PSF\", \"ns\": [], \"u\": \"format_3882\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||PSF\", \"k\": \"format_1915||format_2350||format_2033||format_3882\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"GROMACS itp files (include topology) contain structure topology information, and are tipically included in GROMACS topology files (GROMACS top). Itp files are used to define individual (or multiple) components of a topology as a separate file. This is particularly useful if there is a molecule that is used frequently, and also reduces the size of the system topology file, splitting it in different parts.\", \"n\": \"GROMACS itp\", \"ns\": [], \"u\": \"format_3883\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||GROMACS itp\", \"k\": \"format_1915||format_2350||format_2033||format_3883\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"AMBER coordinate/restart file with 6 coordinates per line and decimal format F12.7 (fixed point notation with field width 12 and 7 decimal places)\", \"n\": \"RST\", \"ns\": [], \"u\": \"format_3886\", \"es\": [\"restrt\", \"rst7\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||RST\", \"k\": \"format_1915||format_2350||format_2033||format_3886\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of CHARMM Residue Topology Files (RTF), which define groups by including the atoms, the properties of the group, and bond and charge information.\", \"n\": \"CHARMM rtf\", \"ns\": [], \"u\": \"format_3887\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||CHARMM rtf\", \"k\": \"format_1915||format_2350||format_2033||format_3887\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of trr files that contain the trajectory of a simulation experiment used by GROMACS.\", \"n\": \"trr\", \"ns\": [], \"u\": \"format_3910\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Tertiary structure format||trr\", \"k\": \"format_1915||format_2350||format_2033||format_3910\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Text format of a chemical formula.\", \"n\": \"Chemical formula format\", \"ns\": [], \"u\": \"format_2035\", \"es\": [], \"ch\": [{\"n\": \"SMILES\", \"u\": \"format_1196\"}, {\"n\": \"InChI\", \"u\": \"format_1197\"}, {\"n\": \"mf\", \"u\": \"format_1198\"}, {\"n\": \"InChIKey\", \"u\": \"format_1199\"}, {\"n\": \"BpForms\", \"u\": \"format_3909\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Chemical formula format\", \"k\": \"format_1915||format_2350||format_2035\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Chemical structure specified in Simplified Molecular Input Line Entry System (SMILES) line notation.\", \"n\": \"SMILES\", \"ns\": [], \"u\": \"format_1196\", \"es\": [], \"ch\": [{\"n\": \"smarts\", \"u\": \"format_1200\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Chemical formula format||SMILES\", \"k\": \"format_1915||format_2350||format_2035||format_1196\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"SMILES ARbitrary Target Specification (SMARTS) format for chemical structure specification, which is a subset of the SMILES line notation.\", \"n\": \"smarts\", \"ns\": [], \"u\": \"format_1200\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Chemical formula format||SMILES||smarts\", \"k\": \"format_1915||format_2350||format_2035||format_1196||format_1200\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Chemical structure specified in IUPAC International Chemical Identifier (InChI) line notation.\", \"n\": \"InChI\", \"ns\": [], \"u\": \"format_1197\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Chemical formula format||InChI\", \"k\": \"format_1915||format_2350||format_2035||format_1197\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Chemical structure specified by Molecular Formula (MF), including a count of each element in a compound.\", \"n\": \"mf\", \"ns\": [], \"u\": \"format_1198\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Chemical formula format||mf\", \"k\": \"format_1915||format_2350||format_2035||format_1198\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The InChIKey (hashed InChI) is a fixed length (25 character) condensed digital representation of an InChI chemical structure specification. It uniquely identifies a chemical compound.\", \"n\": \"InChIKey\", \"ns\": [], \"u\": \"format_1199\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Chemical formula format||InChIKey\", \"k\": \"format_1915||format_2350||format_2035||format_1199\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BpForms is a string format for concretely representing the primary structures of biopolymers, including DNA, RNA, and proteins that include non-canonical nucleic and amino acids. See https://www.bpforms.org for more information.\", \"n\": \"BpForms\", \"ns\": [], \"u\": \"format_3909\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Chemical formula format||BpForms\", \"k\": \"format_1915||format_2350||format_2035||format_3909\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of raw (unplotted) phylogenetic data.\", \"n\": \"Phylogenetic character data format\", \"ns\": [], \"u\": \"format_2036\", \"es\": [], \"ch\": [{\"n\": \"Phylogenetic continuous quantitative character format\", \"u\": \"format_2037\"}, {\"n\": \"Phylogenetic discrete states format\", \"u\": \"format_2038\"}, {\"n\": \"Phylogenetic tree report (cliques) format\", \"u\": \"format_2039\"}, {\"n\": \"Phylogenetic tree report (invariants) format\", \"u\": \"format_2040\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Phylogenetic character data format\", \"k\": \"format_1915||format_2350||format_2036\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of phylogenetic continuous quantitative character data.\", \"n\": \"Phylogenetic continuous quantitative character format\", \"ns\": [], \"u\": \"format_2037\", \"es\": [], \"ch\": [{\"n\": \"Phylip continuous quantitative characters\", \"u\": \"format_1430\"}, {\"n\": \"Phylip character frequencies format\", \"u\": \"format_1432\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Phylogenetic character data format||Phylogenetic continuous quantitative character format\", \"k\": \"format_1915||format_2350||format_2036||format_2037\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"PHYLIP file format for continuous quantitative character data.\", \"n\": \"Phylip continuous quantitative characters\", \"ns\": [], \"u\": \"format_1430\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic character data format||Phylogenetic continuous quantitative character format||Phylip continuous quantitative characters\", \"k\": \"format_1915||format_2350||format_2036||format_2037||format_1430\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"PHYLIP file format for phylogenetics character frequency data.\", \"n\": \"Phylip character frequencies format\", \"ns\": [], \"u\": \"format_1432\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic character data format||Phylogenetic continuous quantitative character format||Phylip character frequencies format\", \"k\": \"format_1915||format_2350||format_2036||format_2037||format_1432\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of phylogenetic discrete states data.\", \"n\": \"Phylogenetic discrete states format\", \"ns\": [], \"u\": \"format_2038\", \"es\": [], \"ch\": [{\"n\": \"Phylip discrete states format\", \"u\": \"format_1433\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Phylogenetic character data format||Phylogenetic discrete states format\", \"k\": \"format_1915||format_2350||format_2036||format_2038\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of PHYLIP discrete states data.\", \"n\": \"Phylip discrete states format\", \"ns\": [], \"u\": \"format_1433\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic character data format||Phylogenetic discrete states format||Phylip discrete states format\", \"k\": \"format_1915||format_2350||format_2036||format_2038||format_1433\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of phylogenetic cliques data.\", \"n\": \"Phylogenetic tree report (cliques) format\", \"ns\": [], \"u\": \"format_2039\", \"es\": [], \"ch\": [{\"n\": \"Phylip cliques format\", \"u\": \"format_1434\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Phylogenetic character data format||Phylogenetic tree report (cliques) format\", \"k\": \"format_1915||format_2350||format_2036||format_2039\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of PHYLIP cliques data.\", \"n\": \"Phylip cliques format\", \"ns\": [], \"u\": \"format_1434\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic character data format||Phylogenetic tree report (cliques) format||Phylip cliques format\", \"k\": \"format_1915||format_2350||format_2036||format_2039||format_1434\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of phylogenetic invariants data.\", \"n\": \"Phylogenetic tree report (invariants) format\", \"ns\": [], \"u\": \"format_2040\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Format (by type of data)||Phylogenetic character data format||Phylogenetic tree report (invariants) format\", \"k\": \"format_1915||format_2350||format_2036||format_2040\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format for phylogenetic tree distance data.\", \"n\": \"Phylogenetic tree report (tree distances) format\", \"ns\": [], \"u\": \"format_2049\", \"es\": [], \"ch\": [{\"n\": \"Phylip tree distance format\", \"u\": \"format_1445\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Phylogenetic tree report (tree distances) format\", \"k\": \"format_1915||format_2350||format_2049\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format for distances, such as Branch Score distance, between two or more phylogenetic trees as used by the Phylip package.\", \"n\": \"Phylip tree distance format\", \"ns\": [], \"u\": \"format_1445\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Phylogenetic tree report (tree distances) format||Phylip tree distance format\", \"k\": \"format_1915||format_2350||format_2049||format_1445\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format for reports on a protein family.\", \"n\": \"Protein family report format\", \"ns\": [], \"u\": \"format_2052\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Format (by type of data)||Protein family report format\", \"k\": \"format_1915||format_2350||format_2052\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format for molecular interaction data.\", \"n\": \"Protein interaction format\", \"ns\": [], \"u\": \"format_2054\", \"es\": [], \"ch\": [{\"n\": \"STRING entry format (XML)\", \"u\": \"format_2304\"}, {\"n\": \"PSI MI XML (MIF)\", \"u\": \"format_3158\"}, {\"n\": \"PSI MI TAB (MITAB)\", \"u\": \"format_3242\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Protein interaction format\", \"k\": \"format_1915||format_2350||format_2054\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Entry format (XML) for the STRING database of protein interaction.\", \"n\": \"STRING entry format (XML)\", \"ns\": [], \"u\": \"format_2304\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Protein interaction format||STRING entry format (XML)\", \"k\": \"format_1915||format_2350||format_2054||format_2304\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"XML Molecular Interaction Format (MIF), standardised by HUPO PSI MI.\", \"n\": \"PSI MI XML (MIF)\", \"ns\": [], \"u\": \"format_3158\", \"es\": [\"MIF\"], \"ch\": [{\"n\": \"PSI-PAR\", \"u\": \"format_3243\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Protein interaction format||PSI MI XML (MIF)\", \"k\": \"format_1915||format_2350||format_2054||format_3158\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Protein affinity format (PSI-PAR), standardised by HUPO PSI MI. It is compatible with PSI MI XML (MIF) and uses the same XML Schema.\", \"n\": \"PSI-PAR\", \"ns\": [], \"u\": \"format_3243\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Protein interaction format||PSI MI XML (MIF)||PSI-PAR\", \"k\": \"format_1915||format_2350||format_2054||format_3158||format_3243\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Tabular Molecular Interaction format (MITAB), standardised by HUPO PSI MI.\", \"n\": \"PSI MI TAB (MITAB)\", \"ns\": [], \"u\": \"format_3242\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Protein interaction format||PSI MI TAB (MITAB)\", \"k\": \"format_1915||format_2350||format_2054||format_3242\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format for sequence assembly data.\", \"n\": \"Sequence assembly format\", \"ns\": [], \"u\": \"format_2055\", \"es\": [], \"ch\": [{\"n\": \"Sequence assembly format (text)\", \"u\": \"format_2561\"}, {\"n\": \"ACE\", \"u\": \"format_3001\"}, {\"n\": \"AGP\", \"u\": \"format_3693\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence assembly format\", \"k\": \"format_1915||format_2350||format_2055\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Text format for sequence assembly data.\", \"n\": \"Sequence assembly format (text)\", \"ns\": [], \"u\": \"format_2561\", \"es\": [], \"ch\": [{\"n\": \"CAF\", \"u\": \"format_1630\"}, {\"n\": \"EXP\", \"u\": \"format_1631\"}, {\"n\": \"afg\", \"u\": \"format_3582\"}, {\"n\": \"ELAND format\", \"u\": \"format_3818\"}, {\"n\": \"FASTG\", \"u\": \"format_3823\"}, {\"n\": \"GFA 1\", \"u\": \"format_3975\"}, {\"n\": \"GFA 2\", \"u\": \"format_3976\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Sequence assembly format||Sequence assembly format (text)\", \"k\": \"format_1915||format_2350||format_2055||format_2561\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Common Assembly Format (CAF). A sequence assembly format including contigs, base-call qualities, and other metadata.\", \"n\": \"CAF\", \"ns\": [], \"u\": \"format_1630\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence assembly format||Sequence assembly format (text)||CAF\", \"k\": \"format_1915||format_2350||format_2055||format_2561||format_1630\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Sequence assembly project file EXP format.\", \"n\": \"EXP\", \"ns\": [], \"u\": \"format_1631\", \"es\": [\"Affymetrix EXP format\", \"EXP\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence assembly format||Sequence assembly format (text)||EXP\", \"k\": \"format_1915||format_2350||format_2055||format_2561||format_1631\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"AFG is a single text-based file assembly format  that holds read and consensus information together\", \"n\": \"afg\", \"ns\": [], \"u\": \"format_3582\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence assembly format||Sequence assembly format (text)||afg\", \"k\": \"format_1915||format_2350||format_2055||format_2561||format_3582\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Tab-delimited text file format used by Eland - the read-mapping program distributed by Illumina with its sequencing analysis pipeline - which maps short Solexa sequence reads to the human reference genome.\", \"n\": \"ELAND format\", \"ns\": [], \"u\": \"format_3818\", \"es\": [\"ELAND\", \"eland\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence assembly format||Sequence assembly format (text)||ELAND format\", \"k\": \"format_1915||format_2350||format_2055||format_2561||format_3818\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"FASTG is a format for faithfully representing genome assemblies in the face of allelic polymorphism and assembly uncertainty.\", \"n\": \"FASTG\", \"ns\": [], \"u\": \"format_3823\", \"es\": [\"FASTG assembly graph format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence assembly format||Sequence assembly format (text)||FASTG\", \"k\": \"format_1915||format_2350||format_2055||format_2561||format_3823\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Graphical Fragment Assembly captures sequence graphs as the product of an assembly, a representation of variation in genomes, splice graphs in genes, or even overlap between reads from long-read sequencing technology.\", \"n\": \"GFA 1\", \"ns\": [], \"u\": \"format_3975\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence assembly format||Sequence assembly format (text)||GFA 1\", \"k\": \"format_1915||format_2350||format_2055||format_2561||format_3975\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Graphical Fragment Assembly captures sequence graphs as the product of an assembly, a representation of variation in genomes, splice graphs in genes, or even overlap between reads from long-read sequencing technology.\", \"n\": \"GFA 2\", \"ns\": [], \"u\": \"format_3976\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence assembly format||Sequence assembly format (text)||GFA 2\", \"k\": \"format_1915||format_2350||format_2055||format_2561||format_3976\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"ACE sequence assembly format including contigs, base-call qualities, and other metadata (version Aug 1998 and onwards).\", \"n\": \"ACE\", \"ns\": [], \"u\": \"format_3001\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence assembly format||ACE\", \"k\": \"format_1915||format_2350||format_2055||format_3001\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"AGP is a tabular format for a sequence assembly (a contig, a scaffold/supercontig, or a chromosome).\", \"n\": \"AGP\", \"ns\": [], \"u\": \"format_3693\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Sequence assembly format||AGP\", \"k\": \"format_1915||format_2350||format_2055||format_3693\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of a file of gene expression data, e.g. a gene expression matrix or profile.\", \"n\": \"Gene expression report format\", \"ns\": [], \"u\": \"format_2058\", \"es\": [\"Gene expression data format\"], \"ch\": [{\"n\": \"dat\", \"u\": \"format_1637\"}, {\"n\": \"cel\", \"u\": \"format_1638\"}, {\"n\": \"CHP\", \"u\": \"format_1644\"}, {\"n\": \"MAGE-ML\", \"u\": \"format_3161\"}, {\"n\": \"MAGE-TAB\", \"u\": \"format_3162\"}, {\"n\": \"Cytoscape input file format\", \"u\": \"format_3477\"}, {\"n\": \"IDAT\", \"u\": \"format_3578\"}, {\"n\": \"rcc\", \"u\": \"format_3580\"}, {\"n\": \"ISA-TAB\", \"u\": \"format_3687\"}, {\"n\": \"GCT/Res format\", \"u\": \"format_3709\"}, {\"n\": \"Loom\", \"u\": \"format_3913\"}, {\"n\": \"Zarr\", \"u\": \"format_3915\"}, {\"n\": \"MTX\", \"u\": \"format_3916\"}, {\"n\": \"RPKM\", \"u\": \"format_3980\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Gene expression report format\", \"k\": \"format_1915||format_2350||format_2058\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of Affymetrix data file of raw image data.\", \"n\": \"dat\", \"ns\": [], \"u\": \"format_1637\", \"es\": [\"Affymetrix image data file format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene expression report format||dat\", \"k\": \"format_1915||format_2350||format_2058||format_1637\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of Affymetrix data file of information about (raw) expression levels of the individual probes.\", \"n\": \"cel\", \"ns\": [], \"u\": \"format_1638\", \"es\": [\"Affymetrix probe raw data format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene expression report format||cel\", \"k\": \"format_1915||format_2350||format_2058||format_1638\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of Affymetrix data file of information about (normalised) expression levels of the individual probes.\", \"n\": \"CHP\", \"ns\": [], \"u\": \"format_1644\", \"es\": [\"Affymetrix probe normalised data format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene expression report format||CHP\", \"k\": \"format_1915||format_2350||format_2058||format_1644\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"MAGE-ML XML format for microarray expression data, standardised by MGED (now FGED).\", \"n\": \"MAGE-ML\", \"ns\": [], \"u\": \"format_3161\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene expression report format||MAGE-ML\", \"k\": \"format_1915||format_2350||format_2058||format_3161\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"MAGE-TAB textual format for microarray expression data, standardised by MGED (now FGED).\", \"n\": \"MAGE-TAB\", \"ns\": [], \"u\": \"format_3162\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene expression report format||MAGE-TAB\", \"k\": \"format_1915||format_2350||format_2058||format_3162\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of the cytoscape input file of gene expression ratios or values are specified over one or more experiments.\", \"n\": \"Cytoscape input file format\", \"ns\": [], \"u\": \"format_3477\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene expression report format||Cytoscape input file format\", \"k\": \"format_1915||format_2350||format_2058||format_3477\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Proprietary file format for (raw) BeadArray data used by genomewide profiling platforms from Illumina Inc. This format is output directly from the scanner and stores summary intensities for each probe-type on an array.\", \"n\": \"IDAT\", \"ns\": [], \"u\": \"format_3578\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene expression report format||IDAT\", \"k\": \"format_1915||format_2350||format_2058||format_3578\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Reporter Code Count-A data file (.csv) output by the Nanostring nCounter Digital Analyzer, which contains gene sample information, probe information and probe counts.\", \"n\": \"rcc\", \"ns\": [], \"u\": \"format_3580\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene expression report format||rcc\", \"k\": \"format_1915||format_2350||format_2058||format_3580\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The Investigation / Study / Assay (ISA) tab-delimited (TAB) format incorporates metadata from\\nexperiments employing a combination of technologies.\", \"n\": \"ISA-TAB\", \"ns\": [], \"u\": \"format_3687\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene expression report format||ISA-TAB\", \"k\": \"format_1915||format_2350||format_2058||format_3687\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Tab-delimited text files of GenePattern that contain a column for each sample, a row for each gene, and an expression value for each gene in each sample.\", \"n\": \"GCT/Res format\", \"ns\": [], \"u\": \"format_3709\", \"es\": [\"GCT format\", \"Res format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene expression report format||GCT/Res format\", \"k\": \"format_1915||format_2350||format_2058||format_3709\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The Loom file format is based on HDF5, a standard for storing large numerical datasets. The Loom format is designed to efficiently hold large omics datasets. Typically, such data takes the form of a large matrix of numbers, along with metadata for the rows and columns.\", \"n\": \"Loom\", \"ns\": [], \"u\": \"format_3913\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene expression report format||Loom\", \"k\": \"format_1915||format_2350||format_2058||format_3913\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The Zarr format is an implementation of chunked, compressed, N-dimensional arrays for storing data.\", \"n\": \"Zarr\", \"ns\": [], \"u\": \"format_3915\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene expression report format||Zarr\", \"k\": \"format_1915||format_2350||format_2058||format_3915\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"The Matrix Market matrix (MTX) format stores numerical or pattern matrices in a dense (array format) or sparse (coordinate format) representation.\", \"n\": \"MTX\", \"ns\": [], \"u\": \"format_3916\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene expression report format||MTX\", \"k\": \"format_1915||format_2350||format_2058||format_3916\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Tab-delimited format for gene expression levels table, calculated as Reads Per Kilobase per Million (RPKM) mapped reads.\", \"n\": \"RPKM\", \"ns\": [], \"u\": \"format_3980\", \"es\": [\"Gene expression levels table format\"], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Gene expression report format||RPKM\", \"k\": \"format_1915||format_2350||format_2058||format_3980\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of a map of (typically one) molecular sequence annotated with features.\", \"n\": \"Map format\", \"ns\": [], \"u\": \"format_2060\", \"es\": [], \"ch\": [{\"n\": \"PlasMapper TextMap\", \"u\": \"format_1861\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Map format\", \"k\": \"format_1915||format_2350||format_2060\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Map of a plasmid (circular DNA) in PlasMapper TextMap format.\", \"n\": \"PlasMapper TextMap\", \"ns\": [], \"u\": \"format_1861\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Map format||PlasMapper TextMap\", \"k\": \"format_1915||format_2350||format_2060||format_1861\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of a report on PCR primers or hybridisation oligos in a nucleic acid sequence.\", \"n\": \"Nucleic acid features (primers) format\", \"ns\": [], \"u\": \"format_2061\", \"es\": [], \"ch\": [{\"n\": \"Primer3 primer\", \"u\": \"format_1627\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Nucleic acid features (primers) format\", \"k\": \"format_1915||format_2350||format_2061\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Report format on PCR primers and hybridisation oligos as generated by Whitehead primer3 program.\", \"n\": \"Primer3 primer\", \"ns\": [], \"u\": \"format_1627\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Nucleic acid features (primers) format||Primer3 primer\", \"k\": \"format_1915||format_2350||format_2061||format_1627\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of a report of general information about a specific protein.\", \"n\": \"Protein report format\", \"ns\": [], \"u\": \"format_2062\", \"es\": [], \"ch\": [{\"n\": \"BcForms\", \"u\": \"format_3951\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Protein report format\", \"k\": \"format_1915||format_2350||format_2062\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"BcForms is a format for abstractly describing the molecular structure (atoms and bonds) of macromolecular complexes as a collection of subunits and crosslinks. Each subunit can be described with BpForms (format_3909) or SMILES (data_2301). BcForms uses an ontology of crosslinks to abstract the chemical details of crosslinks from the descriptions of complexes (see https://bpforms.org/crosslink.html).\", \"n\": \"BcForms\", \"ns\": [], \"u\": \"format_3951\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Protein report format||BcForms\", \"k\": \"format_1915||format_2350||format_2062||format_3951\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of a report on the quality of a protein three-dimensional model.\", \"n\": \"Protein structure report (quality evaluation) format\", \"ns\": [], \"u\": \"format_2065\", \"es\": [], \"ch\": [{\"n\": \"Pcons report format\", \"u\": \"format_1551\"}, {\"n\": \"ProQ report format\", \"u\": \"format_1552\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Protein structure report (quality evaluation) format\", \"k\": \"format_1915||format_2350||format_2065\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of output of the Pcons Model Quality Assessment Program (MQAP).\", \"n\": \"Pcons report format\", \"ns\": [], \"u\": \"format_1551\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Protein structure report (quality evaluation) format||Pcons report format\", \"k\": \"format_1915||format_2350||format_2065||format_1551\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of output of the ProQ protein model quality predictor.\", \"n\": \"ProQ report format\", \"ns\": [], \"u\": \"format_1552\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Protein structure report (quality evaluation) format||ProQ report format\", \"k\": \"format_1915||format_2350||format_2065||format_1552\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of a report on sequence hits and associated data from searching a sequence database.\", \"n\": \"Database hits (sequence) format\", \"ns\": [], \"u\": \"format_2066\", \"es\": [], \"ch\": [{\"n\": \"FASTA search results format\", \"u\": \"format_1332\"}, {\"n\": \"BLAST results\", \"u\": \"format_1333\"}, {\"n\": \"mspcrunch\", \"u\": \"format_1334\"}, {\"n\": \"Smith-Waterman format\", \"u\": \"format_1335\"}, {\"n\": \"dhf\", \"u\": \"format_1336\"}, {\"n\": \"lhf\", \"u\": \"format_1337\"}, {\"n\": \"InterPro hits format\", \"u\": \"format_1341\"}, {\"n\": \"EBI Application Result XML\", \"u\": \"format_3157\"}], \"p\": [{\"n\": \"Format||Format (by type of data)||Database hits (sequence) format\", \"k\": \"format_1915||format_2350||format_2066\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of results of a sequence database search using FASTA.\", \"n\": \"FASTA search results format\", \"ns\": [], \"u\": \"format_1332\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Database hits (sequence) format||FASTA search results format\", \"k\": \"format_1915||format_2350||format_2066||format_1332\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of results of a sequence database search using some variant of BLAST.\", \"n\": \"BLAST results\", \"ns\": [], \"u\": \"format_1333\", \"es\": [], \"ch\": [{\"n\": \"BLAST XML results format\", \"u\": \"format_3331\"}, {\"n\": \"BLAST XML v2 results format\", \"u\": \"format_3836\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Database hits (sequence) format||BLAST results\", \"k\": \"format_1915||format_2350||format_2066||format_1333\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"XML format as produced by the NCBI Blast package\", \"n\": \"BLAST XML results format\", \"ns\": [], \"u\": \"format_3331\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Database hits (sequence) format||BLAST results||BLAST XML results format\", \"k\": \"format_1915||format_2350||format_2066||format_1333||format_3331\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"XML format as produced by the NCBI Blast package v2.\", \"n\": \"BLAST XML v2 results format\", \"ns\": [], \"u\": \"format_3836\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Database hits (sequence) format||BLAST results||BLAST XML v2 results format\", \"k\": \"format_1915||format_2350||format_2066||format_1333||format_3836\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of results of a sequence database search using some variant of MSPCrunch.\", \"n\": \"mspcrunch\", \"ns\": [], \"u\": \"format_1334\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Database hits (sequence) format||mspcrunch\", \"k\": \"format_1915||format_2350||format_2066||format_1334\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of results of a sequence database search using some variant of Smith Waterman.\", \"n\": \"Smith-Waterman format\", \"ns\": [], \"u\": \"format_1335\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Database hits (sequence) format||Smith-Waterman format\", \"k\": \"format_1915||format_2350||format_2066||format_1335\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of EMBASSY domain hits file (DHF) of hits (sequences) with domain classification information.\", \"n\": \"dhf\", \"ns\": [], \"u\": \"format_1336\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Database hits (sequence) format||dhf\", \"k\": \"format_1915||format_2350||format_2066||format_1336\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of EMBASSY ligand hits file (LHF) of database hits (sequences) with ligand classification information.\", \"n\": \"lhf\", \"ns\": [], \"u\": \"format_1337\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Database hits (sequence) format||lhf\", \"k\": \"format_1915||format_2350||format_2066||format_1337\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Results format for searches of the InterPro database.\", \"n\": \"InterPro hits format\", \"ns\": [], \"u\": \"format_1341\", \"es\": [], \"ch\": [{\"n\": \"InterPro protein view report format\", \"u\": \"format_1342\"}, {\"n\": \"InterPro match table format\", \"u\": \"format_1343\"}], \"p\": {\"n\": \"Format||Format (by type of data)||Database hits (sequence) format||InterPro hits format\", \"k\": \"format_1915||format_2350||format_2066||format_1341\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of results of a search of the InterPro database showing matches of query protein sequence(s) to InterPro entries.\", \"n\": \"InterPro protein view report format\", \"ns\": [], \"u\": \"format_1342\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Database hits (sequence) format||InterPro hits format||InterPro protein view report format\", \"k\": \"format_1915||format_2350||format_2066||format_1341||format_1342\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of results of a search of the InterPro database showing matches between protein sequence(s) and signatures for an InterPro entry.\", \"n\": \"InterPro match table format\", \"ns\": [], \"u\": \"format_1343\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Database hits (sequence) format||InterPro hits format||InterPro match table format\", \"k\": \"format_1915||format_2350||format_2066||format_1341||format_1343\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"EBI Application Result XML is a format returned by sequence similarity search Web services at EBI.\", \"n\": \"EBI Application Result XML\", \"ns\": [], \"u\": \"format_3157\", \"es\": [], \"ch\": [], \"p\": {\"n\": \"Format||Format (by type of data)||Database hits (sequence) format||EBI Application Result XML\", \"k\": \"format_1915||format_2350||format_2066||format_3157\"}, \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Format of a matrix of genetic distances between molecular sequences.\", \"n\": \"Sequence distance matrix format\", \"ns\":