mat_2350||format_2195||format_3254\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3255\": {\"d\": \"The Terse RDF Triple Language (Turtle) is a human-friendly serialisation format for RDF (Resource Description Framework) graphs.\", \"n\": \"Turtle\", \"ns\": [], \"u\": \"format_3255\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Turtle\", \"k\": \"format_1915||format_2330||format_3255\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||Turtle\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_3255\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||Turtle\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_3255\"}, {\"n\": \"Format||RDF format||Turtle\", \"k\": \"format_1915||format_2376||format_3255\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3256\": {\"d\": \"A plain text serialisation format for RDF (Resource Description Framework) graphs, and a subset of the Turtle (Terse RDF Triple Language) format.\", \"n\": \"N-Triples\", \"ns\": [], \"u\": \"format_3256\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||N-Triples\", \"k\": \"format_1915||format_2330||format_3256\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||N-Triples\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_3256\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||N-Triples\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_3256\"}, {\"n\": \"Format||RDF format||N-Triples\", \"k\": \"format_1915||format_2376||format_3256\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3257\": {\"d\": \"A shorthand non-XML serialisation of Resource Description Framework model, designed with human-readability in mind.\", \"n\": \"Notation3\", \"ns\": [], \"u\": \"format_3257\", \"es\": [\"N3\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Notation3\", \"k\": \"format_1915||format_2330||format_3257\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||Notation3\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_3257\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||Notation3\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_3257\"}, {\"n\": \"Format||RDF format||Notation3\", \"k\": \"format_1915||format_2376||format_3257\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3288\": {\"d\": \"The PED/MAP file describes data used by the Plink package.\", \"n\": \"PED/MAP\", \"ns\": [], \"u\": \"format_3288\", \"es\": [\"Plink PED/MAP\"], \"ch\": [{\"n\": \"MAP\", \"u\": \"format_3285\"}, {\"n\": \"PED\", \"u\": \"format_3286\"}], \"p\": [{\"n\": \"Format||Textual format||PED/MAP\", \"k\": \"format_1915||format_2330||format_3288\"}, {\"n\": \"Format||Format (by type of data)||Individual genetic data format||PED/MAP\", \"k\": \"format_1915||format_2350||format_3287||format_3288\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3285\": {\"d\": \"The MAP file describes SNPs and is used by the Plink package.\", \"n\": \"MAP\", \"ns\": [], \"u\": \"format_3285\", \"es\": [\"Plink MAP\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||PED/MAP||MAP\", \"k\": \"format_1915||format_2330||format_3288||format_3285\"}, {\"n\": \"Format||Format (by type of data)||Individual genetic data format||PED/MAP||MAP\", \"k\": \"format_1915||format_2350||format_3287||format_3288||format_3285\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3286\": {\"d\": \"The PED file describes individuals and genetic data and is used by the Plink package.\", \"n\": \"PED\", \"ns\": [], \"u\": \"format_3286\", \"es\": [\"Plink PED\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||PED/MAP||PED\", \"k\": \"format_1915||format_2330||format_3288||format_3286\"}, {\"n\": \"Format||Format (by type of data)||Individual genetic data format||PED/MAP||PED\", \"k\": \"forma