": [{\"n\": \"Format||Textual format||pgSnp\", \"k\": \"format_1915||format_2330||format_3012\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||pgSnp\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3012\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3013\": {\"d\": \"axt format of alignments, typically produced from BLASTZ.\", \"n\": \"axt\", \"ns\": [], \"u\": \"format_3013\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||axt\", \"k\": \"format_1915||format_2330||format_3013\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||axt\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3013\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3014\": {\"d\": \"LAV format of alignments generated by BLASTZ and LASTZ.\", \"n\": \"LAV\", \"ns\": [], \"u\": \"format_3014\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||LAV\", \"k\": \"format_1915||format_2330||format_3014\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||LAV\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3014\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3015\": {\"d\": \"Pileup format of alignment of sequences (e.g. sequencing reads) to (a) reference sequence(s). Contains aligned bases per base of the reference sequence(s).\", \"n\": \"Pileup\", \"ns\": [], \"u\": \"format_3015\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Pileup\", \"k\": \"format_1915||format_2330||format_3015\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||Pileup\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3015\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3016\": {\"d\": \"Variant Call Format (VCF) for sequence variation (indels, polymorphisms, structural variation).\", \"n\": \"VCF\", \"ns\": [], \"u\": \"format_3016\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||VCF\", \"k\": \"format_1915||format_2330||format_3016\"}, {\"n\": \"Format||Format (by type of data)||Sequence variation annotation format||VCF\", \"k\": \"format_1915||format_2350||format_2921||format_3016\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3164\": {\"d\": \"GTrack is a generic and optimised tabular format for genome or sequence feature tracks. GTrack unifies the power of other track formats (e.g. GFF3, BED, WIG), and while optimised in size, adds more flexibility, customisation, and automation (\\\"machine understandability\\\").\", \"n\": \"GTrack\", \"ns\": [], \"u\": \"format_3164\", \"es\": [\"BioXSD/GTrack GTrack\", \"BioXSD|GTrack GTrack\", \"GTrack format\", \"GTrack|BTrack|GSuite GTrack\", \"GTrack|GSuite|BTrack GTrack\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GTrack\", \"k\": \"format_1915||format_2330||format_3164\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||Sequence feature table format (text)||GTrack\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2206||format_3164\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||GTrack\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3164\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3235\": {\"d\": \"Cytoband format for chromosome cytobands.\", \"n\": \"Cytoband format\", \"ns\": [], \"u\": \"format_3235\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Cytoband format\", \"k\": \"format_1915||format_2330||format_3235\"}, {\"n\": \"Format||Format (by type of data)||Sequence range format||Cytoband format\", \"k\": \"format_1915||format_2350||format_2078||format_3235\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3242\": {\"d\": \"Tabular Molecular Interaction format (MITAB), standardised by HUPO PSI MI.\", \"n\": \"PSI MI TAB (MITAB)\", \"ns\": [], \"u\": \"format_3242\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||PSI MI TAB (MITAB)\", \"k\": \"format_1915||format_2330||format_3242\"}, {\"n\": \"Format||Format (by type of data)||Protein interaction format||PSI MI TAB (MITAB)\", \"k\": \"format_1915||format_2350||format_2054||format_3242\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3252\": {\"d\": \"A human-readable encoding for the Web Ontology Language (OWL).\", \"n\": \"OWL Functional Syntax\", \"ns\": [], \"u\": \"format_3252\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||OWL Functional Syntax\", \"k\": \"format_1915||format_2330||format_3252\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||OWL format||OWL Functional Syntax\", \"k\": \"format_1915||format_2350||format_2195||format_2197||format_3252\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||OWL format||OWL Functional Syntax\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_2197||format_3252\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||OWL format||OWL Functional Syntax\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_2197||format_3252\"}, {\"n\": \"Format||RDF format||OWL format||OWL Functional Syntax\", \"k\": \"format_1915||format_2376||format_2197||format_3252\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3253\": {\"d\": \"A syntax for writing OWL class expressions.\", \"n\": \"Manchester OWL Syntax\", \"ns\": [], \"u\": \"format_3253\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Manchester OWL Syntax\", \"k\": \"format_1915||format_2330||format_3253\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||OWL format||Manchester OWL Syntax\", \"k\": \"format_1915||format_2350||format_2195||format_2197||format_3253\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||OWL format||Manchester OWL Syntax\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_2197||format_3253\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||OWL format||Manchester OWL Syntax\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_2197||format_3253\"}, {\"n\": \"Format||RDF format||OWL format||Manchester OWL Syntax\", \"k\": \"format_1915||format_2376||format_2197||format_3253\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3254\": {\"d\": \"A superset of the \\\"Description-Logic Knowledge Representation System Specification from the KRSS Group of the ARPA Knowledge Sharing Effort\\\".\", \"n\": \"KRSS2 Syntax\", \"ns\": [], \"u\": \"format_3254\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||KRSS2 Syntax\", \"k\": \"format_1915||format_2330||format_3254\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||KRSS2 Syntax\", \"k\": \"format_1915||format_2350||format_2195||format_3254\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3255\": {\"d\": \"The Terse RDF Triple Language (Turtle) is a human-friendly serialisation format for RDF (Resource Description Framework) graphs.\", \"n\": \"Turtle\", \"ns\": [], \"u\": \"format_3255\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Turtle\", \"k\": \"format_1915||format_2330||format_3255\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||Turtle\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_3255\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||Turtle\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_3255\"}, {\"n\": \"Format||RDF format||Turtle\", \"k\": \"format_1915||format_2376||format_3255\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3256\": {\"d\": \"A plain text serialisation format for RDF (Resource Description Framework) graphs, and a subset of the Turtle (Terse RDF Triple Language) format.\", \"n\": \"N-Triples\", \"ns\": [], \"u\": \"format_3256\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||N-Triples\", \"k\": \"format_1915||format_2330||format_3256\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||N-Triples\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_3256\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||N-Triples\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_3256\"}, {\"n\": \"Format||RDF format||N-Triples\", \"k\": \"format_1915||format_2376||format_3256\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3257\": {\"d\": \"A shorthand non-XML serialisation of Resource Description Framework model, designed with human-readability in mind.\", \"n\": \"Notation3\", \"ns\": [], \"u\": \"format_3257\", \"es\": [\"N3\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Notation3\", \"k\": \"format_1915||format_2330||format_3257\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||Notation3\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_3257\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||Notation3\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_3257\"}, {\"n\": \"Format||RDF format||Notation3\", \"k\": \"format_1915||format_2376||format_3257\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3288\": {\"d\": \"The PED/MAP file describes data used by the Plink package.\", \"n\": \"PED/MAP\", \"ns\": [], \"u\": \"format_3288\", \"es\": [\"Plink PED/MAP\"], \"ch\": [{\"n\": \"MAP\", \"u\": \"format_3285\"}, {\"n\": \"PED\", \"u\": \"format_3286\"}], \"p\": [{\"n\": \"Format||Textual format||PED/MAP\", \"k\": \"format_1915||format_2330||format_3288\"}, {\"n\": \"Format||Format (by type of data)||Individual genetic data format||PED/MAP\", \"k\": \"format_1915||format_2350||format_3287||format_3288\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3285\": {\"d\": \"The MAP file describes SNPs and is used by the Plink package.\", \"n\": \"MAP\", \"ns\": [], \"u\": \"format_3285\", \"es\": [\"Plink MAP\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||PED/MAP||MAP\", \"k\": \"format_1915||format_2330||format_3288||format_3285\"}, {\"n\": \"Format||Format (by type of data)||Individual genetic data format||PED/MAP||MAP\", \"k\": \"format_1915||format_2350||format_3287||format_3288||format_3285\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3286\": {\"d\": \"The PED file describes individuals and genetic data and is used by the Plink package.\", \"n\": \"PED\", \"ns\": [], \"u\": \"format_3286\", \"es\": [\"Plink PED\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||PED/MAP||PED\", \"k\": \"format_1915||format_2330||format_3288||format_3286\"}, {\"n\": \"Format||Format (by type of data)||Individual genetic data format||PED/MAP||PED\", \"k\": \"format_1915||format_2350||format_3287||format_3288||format_3286\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3309\": {\"d\": \"File format of a CT (Connectivity Table) file from the RNAstructure package.\", \"n\": \"CT\", \"ns\": [], \"u\": \"format_3309\", \"es\": [\"Connect format\", \"Connectivity Table file format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||CT\", \"k\": \"format_1915||format_2330||format_3309\"}, {\"n\": \"Format||Format (by type of data)||RNA secondary structure format||CT\", \"k\": \"format_1915||format_2350||format_2076||format_3309\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3310\": {\"d\": \"XRNA old input style format.\", \"n\": \"SS\", \"ns\": [], \"u\": \"format_3310\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||SS\", \"k\": \"format_1915||format_2330||format_3310\"}, {\"n\": \"Format||Format (by type of data)||RNA secondary structure format||SS\", \"k\": \"format_1915||format_2350||format_2076||format_3310\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3312\": {\"d\": \"Format for the Genetic Data Environment (GDE).\", \"n\": \"GDE\", \"ns\": [], \"u\": \"format_3312\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||GDE\", \"k\": \"format_1915||format_2330||format_3312\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (text)||GDE\", \"k\": \"format_1915||format_2350||format_1919||format_2551||format_3312\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3477\": {\"d\": \"Format of the cytoscape input file of gene expression ratios or values are specified over one or more experiments.\", \"n\": \"Cytoscape input file format\", \"ns\": [], \"u\": \"format_3477\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Textual format||Cytoscape input file format\", \"k\": \"format_1915||format_2330||format_3477\"}, {\"n\": \"Format||Format (by type of data)||Gene expression report format||Cytoscape input file format\", \"k\": \"format_1915||format_2350||format_2058||format_3477\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3486\": {\"d\": \"Some format based on the GCG format.\", \"n\": \"GCG format variant\", \"ns\": [], \"u\": \"format_3486\", \"es\": [], \"ch\": [{\"n\": \"GCG\", \"u\": \"format_1935\"}, {\"n\": \"GCG MSF\", \"u\": \"format_1947\"}, {\"n\": \"RSF\", \"u\": \"format_3485\"}], \"p\": [{\"n\": \"Format||Textual format||GCG format variant\", \"k\": \"format_1915||format_2330||format_3486\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (text)||GCG format variant\", \"k\": \"format_1915||format_2350||format_1919||format_2551||format_3486\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (text)||GCG format variant\", \"k\": \"format_1915||format_2350||format_1921||format_2554||format_3486\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_1947\": {\"d\": \"GCG MSF (multiple sequence file) file format.\", \"n\":