||format_3158||format_3243\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3159\": {\"d\": \"phyloXML is a standardised XML format for phylogenetic trees, networks, and associated data.\", \"n\": \"phyloXML\", \"ns\": [], \"u\": \"format_3159\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||phyloXML\", \"k\": \"format_1915||format_2332||format_3159\"}, {\"n\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (XML)||phyloXML\", \"k\": \"format_1915||format_2350||format_2006||format_2557||format_3159\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3160\": {\"d\": \"NeXML is a standardised XML format for rich phyloinformatic data.\", \"n\": \"NeXML\", \"ns\": [], \"u\": \"format_3160\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||NeXML\", \"k\": \"format_1915||format_2332||format_3160\"}, {\"n\": \"Format||Format (by type of data)||Phylogenetic tree format||Phylogenetic tree format (XML)||NeXML\", \"k\": \"format_1915||format_2350||format_2006||format_2557||format_3160\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3161\": {\"d\": \"MAGE-ML XML format for microarray expression data, standardised by MGED (now FGED).\", \"n\": \"MAGE-ML\", \"ns\": [], \"u\": \"format_3161\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||MAGE-ML\", \"k\": \"format_1915||format_2332||format_3161\"}, {\"n\": \"Format||Format (by type of data)||Gene expression report format||MAGE-ML\", \"k\": \"format_1915||format_2350||format_2058||format_3161\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3163\": {\"d\": \"GCDML XML format for genome and metagenome metadata according to MIGS/MIMS/MIMARKS information standards, standardised by the Genomic Standards Consortium (GSC).\", \"n\": \"GCDML\", \"ns\": [], \"u\": \"format_3163\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||GCDML\", \"k\": \"format_1915||format_2332||format_3163\"}, {\"n\": \"Format||Format (by type of data)||Experiment annotation format||GCDML\", \"k\": \"format_1915||format_2350||format_3167||format_3163\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3239\": {\"d\": \"CopasiML, the native format of COPASI.\", \"n\": \"CopasiML\", \"ns\": [], \"u\": \"format_3239\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||CopasiML\", \"k\": \"format_1915||format_2332||format_3239\"}, {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||CopasiML\", \"k\": \"format_1915||format_2350||format_2013||format_3239\"}, {\"n\": \"Format||Format (by type of data)||Biological pathway or network report format||CopasiML\", \"k\": \"format_1915||format_2350||format_3166||format_3239\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3240\": {\"d\": \"CellML, the format for mathematical models of biological and other networks.\", \"n\": \"CellML\", \"ns\": [], \"u\": \"format_3240\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||CellML\", \"k\": \"format_1915||format_2332||format_3240\"}, {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||CellML\", \"k\": \"format_1915||format_2350||format_2013||format_3240\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3244\": {\"d\": \"mzML format for raw spectrometer output data, standardised by HUPO PSI MSS.\", \"n\": \"mzML\", \"ns\": [], \"u\": \"format_3244\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||mzML\", \"k\": \"format_1915||format_2332||format_3244\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||mzML\", \"k\": \"format_1915||format_2350||format_3245||format_3244\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3246\": {\"d\": \"TraML (Transition Markup Language) is the format for mass spectrometry transitions, standardised by HUPO PSI MSS.\", \"n\": \"TraML\", \"ns\": [], \"u\": \"format_3246\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||TraML\", \"k\": \"format_1915||format_2332||format_3246\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||TraML\", \"k\": \"format_1915||format_2350||format_3245||format_3246\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3247\": {\"d\": \"mzIdentML is the exchange format for peptides and proteins identified from mass spectra, standardised by HUPO PSI PI. It can be used for outputs of proteomics search engines.\", \"n\": \"mzIdentML\", \"ns\": [], \"u\": \"format_3247\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||mzIdentML\", \"k\": \"format_1915||format_2332||format_3247\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||mzIdentML\", \"k\": \"format_1915||format_2350||format_3245||format_3247\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3248\": {\"d\": \"mzQuantML is the format for quantitation values associated with peptides, proteins and small molecules from mass spectra, standardised by HUPO PSI PI. It can be used for outputs of quantitation software for proteomics.\", \"n\": \"mzQuantML\", \"ns\": [], \"u\": \"format_3248\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||mzQuantML\", \"k\": \"format_1915||format_2332||format_3248\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||mzQuantML\", \"k\": \"format_1915||format_2350||format_3245||format_3248\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3249\": {\"d\": \"GelML is the format for describing the process of gel electrophoresis, standardised by HUPO PSI PS.\", \"n\": \"GelML\", \"ns\": [], \"u\": \"format_3249\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||GelML\", \"k\": \"format_1915||format_2332||format_3249\"}, {\"n\": \"Format||Format (by type of data)||Experiment annotation format||GelML\", \"k\": \"format_1915||format_2350||format_3167||format_3249\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3250\": {\"d\": \"spML is the format for describing proteomics sample processing, other than using gels, prior to mass spectrometric protein identification, standardised by HUPO PSI PS. It may also be applicable for metabolomics.\", \"n\": \"spML\", \"ns\": [], \"u\": \"format_3250\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||spML\", \"k\": \"format_1915||format_2332||format_3250\"}, {\"n\": \"Format||Format (by type of data)||Experiment annotation format||spML\", \"k\": \"format_1915||format_2350||format_3167||format_3250\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3261\": {\"d\": \"Resource Description Framework (RDF) XML format.\", \"n\": \"RDF/XML\", \"ns\": [], \"u\": \"format_3261\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||RDF/XML\", \"k\": \"format_1915||format_2332||format_3261\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||RDF/XML\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_3261\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||RDF/XML\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_3261\"}, {\"n\": \"Format||RDF format||RDF/XML\", \"k\": \"format_1915||format_2376||format_3261\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3262\": {\"d\": \"OWL ontology XML serialisation format.\", \"n\": \"OWL/XML\", \"ns\": [\"OWL\"], \"u\": \"format_3262\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||OWL/XML\", \"k\": \"format_1915||format_2332||format_3262\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||OWL format||OWL/XML\", \"k\": \"format_1915||format_2350||format_2195||format_2197||format_3262\"}, {\"n\": \"Format||Format (by type of data)||Ontology format||RDF format||OWL format||OWL/XML\", \"k\": \"format_1915||format_2350||format_2195||format_2376||format_2197||format_3262\"}, {\"n\": \"Format||Format (by type of data)||Linked data format||RDF format||OWL format||OWL/XML\", \"k\": \"format_1915||format_2350||format_3748||format_2376||format_2197||format_3262\"}, {\"n\": \"Format||RDF format||OWL format||OWL/XML\", \"k\": \"format_1915||format_2376||format_2197||format_3262\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3311\": {\"d\": \"RNA Markup Language.\", \"n\": \"RNAML\", \"ns\": [], \"u\": \"format_3311\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||RNAML\", \"k\": \"format_1915||format_2332||format_3311\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||RNAML\", \"k\": \"format_1915||format_2350||format_1921||format_3311\"}, {\"n\": \"Format||Format (by type of data)||RNA secondary structure format||RNAML\", \"k\": \"format_1915||format_2350||format_2076||format_3311\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3468\": {\"d\": \"Microsoft Excel spreadsheet format.\", \"n\": \"xls\", \"ns\": [], \"u\": \"format_3468\", \"es\": [\"Microsoft Excel format\"], \"ch\": [], \"p\": [{\"n\": \"Format||XML||xls\", \"k\": \"format_1915||format_2332||format_3468\"}, {\"n\": \"Format||Format (by type of data)||Document format||xls\", \"k\": \"format_1915||format_2350||format_3507||format_3468\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3487\": {\"d\": \"Bioinformatics Sequence Markup Language format.\", \"n\": \"BSML\", \"ns\": [], \"u\": \"format_3487\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||BSML\", \"k\": \"format_1915||format_2332||format_3487\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||BSML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3487\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3506\": {\"d\": \"Microsoft Word format.\", \"n\": \"docx\", \"ns\": [], \"u\": \"format_3506\", \"es\": [\"Microsoft Word format\", \"doc\"], \"ch\": [], \"p\": [{\"n\": \"Format||XML||docx\", \"k\": \"format_1915||format_2332||format_3506\"}, {\"n\": \"Format||Format (by type of data)||Document format||docx\", \"k\": \"format_1915||format_2350||format_3507||format_3506\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3604\": {\"d\": \"Scalable Vector Graphics (SVG) is an XML-based vector image format for two-dimensional graphics with support for interactivity and animation.\", \"n\": \"SVG\", \"ns\": [], \"u\": \"format_3604\", \"es\": [\"Scalable Vector Graphics\"], \"ch\": [], \"p\": [{\"n\": \"Format||XML||SVG\", \"k\": \"format_1915||format_2332||format_3604\"}, {\"n\": \"Format||Format (by type of data)||Image format||SVG\", \"k\": \"format_1915||format_2350||format_3547||format_3604\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3655\": {\"d\": \"Open data format for the storage, exchange, and processing of peptide sequence assignments of MS/MS scans, intended to provide a common data output format for many different MS/MS search engines and subsequent peptide-level analyses.\", \"n\": \"pepXML\", \"ns\": [], \"u\": \"format_3655\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||pepXML\", \"k\": \"format_1915||format_2332||format_3655\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||pepXML\", \"k\": \"format_1915||format_2350||format_3245||format_3655\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3657\": {\"d\": \"Graphical Pathway Markup Language (GPML) is an XML format used for exchanging biological pathways.\", \"n\": \"GPML\", \"ns\": [], \"u\": \"format_3657\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||GPML\", \"k\": \"format_1915||format_2332||format_3657\"}, {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||GPML\", \"k\": \"format_1915||format_2350||format_2013||format_3657\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3682\": {\"d\": \"imzML metadata is a data format for mass spectrometry imaging metadata.\", \"n\": \"imzML metadata file\", \"ns\": [], \"u\": \"format_3682\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||imzML metadata file\", \"k\": \"format_1915||format_2332||format_3682\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||imzML metadata file\", \"k\": \"format_1915||format_2350||format_3245||format_3682\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3683\": {\"d\": \"qcML is an XML format for quality-related data of mass spectrometry and other high-throughput measurements.\", \"n\": \"qcML\", \"ns\": [], \"u\": \"format_3683\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||qcML\", \"k\": \"format_1915||format_2332||format_3683\"}, {\"n\": \"Format||Format (by type of data)||Experiment annotation format||qcML\", \"k\": \"format_1915||format_2350||format_3167||format_3683\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||qcML\", \"k\": \"format_1915||format_2350||format_3245||format_3683\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3684\": {\"d\": \"PRIDE XML is an XML format for mass spectra, peptide and protein identifications, and metadata about a corresponding measurement, sample, experiment.\", \"n\": \"PRIDE XML\", \"ns\": [], \"u\": \"format_3684\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||PRIDE XML\", \"k\": \"format_1915||format_2332||format_3684\"}, {\"n\": \"Format||Format (by type of data)||Experiment annotation format||PRIDE XML\", \"k\": \"format_1915||format_2350||format_3167||format_3684\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||PRIDE XML\", \"k\": \"format_1915||format_2350||format_3245||format_3684\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3685\": {\"d\": \"Simulation Experiment Description Markup Language (SED-ML) is an XML format for encoding simulation setups, according to the MIASE (Minimum Information About a Simulation Experiment) requirements.\", \"n\": \"SED-ML\", \"ns\": [], \"u\": \"format_3685\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||SED-ML\", \"k\": \"format_1915||format_2332||format_3685\"}, {\"n\": \"Format||Format (by type of data)||Experiment annotation format||SED-ML\", \"k\": \"format_1915||format_2350||format_3167||format_3685\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3689\": {\"d\": \"Biological Connection Markup Language (BCML) is an XML format for biological pathways.\", \"n\": \"BCML\", \"ns\": [], \"u\": \"format_3689\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||BCML\", \"k\": \"format_1915||format_2332||format_3689\"}, {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||BCML\", \"k\": \"format_1915||format_2350||format_2013||format_3689\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3690\": {\"d\": \"Biological Dynamics Markup Language (BDML) is an XML format for quantitative data describing biological dynamics.\", \"n\": \"BDML\", \"ns\": [], \"u\": \"format_3690\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||BDML\", \"k\": \"format_1915||format_2332||format_3690\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3692\": {\"d\": \"SBGN-ML is an XML format for Systems Biology Graphical Notation (SBGN) diagrams of biological pathways or networks.\", \"n\": \"SBGN-ML\", \"ns\": [], \"u\": \"format_3692\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||SBGN-ML\", \"k\": \"format_1915||format_2332||format_3692\"}, {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||SBGN-ML\", \"k\": \"format_1915||format_2350||format_2013||format_3692\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3711\": {\"d\": \"Output format used by X! series search engines that is based on the XML language BIOML.\", \"n\": \"X!Tandem XML\", \"ns\": [], \"u\": \"format_3711\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||X!Tandem XML\", \"k\": \"format_1915||format_2332||format_3711\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||X!Tandem XML\", \"k\": \"format_1915||format_2350||format_3245||format_3711\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3725\": {\"d\": \"Synthetic Biology Open Language (SBOL) is an XML format for the specification and exchange of biological design information in synthetic biology.\", \"n\": \"SBOL\", \"ns\": [], \"u\": \"format_3725\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||SBOL\", \"k\": \"format_1915||format_2332||format_3725\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3726\": {\"d\": \"PMML uses XML to represent mining models. The structure of the models is described by an XML Schema.\", \"n\": \"PMML\", \"ns\": [], \"u\": \"format_3726\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||PMML\", \"k\": \"format_1915||format_2332||format_3726\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3747\": {\"d\": \"A format for storage, exchange, and processing of protein identifications created from ms/ms-derived peptide sequence data.\", \"n\": \"protXML\", \"ns\": [], \"u\": \"format_3747\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||protXML\", \"k\": \"format_1915||format_2332||format_3747\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||protXML\", \"k\": \"format_1915||format_2350||format_3245||format_3747\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3764\": {\"d\": \"XML file format for files containing information about peptide identifications from mass spectrometry data analysis carried out with OpenMS.\", \"n\": \"idXML\", \"ns\": [], \"u\": \"format_3764\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||idXML\", \"k\": \"format_1915||format_2332||format_3764\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||idXML\", \"k\": \"format_1915||format_2350||format_3245||format_3764\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3770\": {\"d\": \"UniProtKB XML sequence features format is an XML format available for downloading UniProt entries.\", \"n\": \"UniProtKB XML\", \"ns\": [], \"u\": \"format_3770\", \"es\": [\"UniProt XML\", \"UniProt XML format\", \"UniProtKB XML format\"], \"ch\": [], \"p\": [{\"n\": \"Format||XML||UniProtKB XML\", \"k\": \"format_1915||format_2332||format_3770\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||uniprotkb-like format||UniProtKB XML\", \"k\": \"format_1915||format_2350||format_1919||format_2547||format_3770\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||UniProtKB XML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3770\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||uniprotkb-like format||UniProtKB XML\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_2547||format_3770\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3782\": {\"d\": \"BioC is a standardised XML format for sharing and integrating text data and annotations.\", \"n\": \"BioC\", \"ns\": [], \"u\": \"format_3782\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||BioC\", \"k\": \"format_1915||format_2332||format_3782\"}, {\"n\": \"Format||Format (by type of data)||Annotated text format||BioC\", \"k\": \"format_1915||format_2350||format_3780||format_3782\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3804\": {\"d\": \"XML format for XML Schema.\", \"n\": \"xsd\", \"ns\": [], \"u\": \"format_3804\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||xsd\", \"k\": \"format_1915||format_2332||format_3804\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3821\": {\"d\": \"Default XML format of VisANT, containing all the network information.\", \"n\": \"VisML\", \"ns\": [], \"u\": \"format_3821\", \"es\": [\"VisANT xml\", \"VisANT xml format\"], \"ch\": [], \"p\": [{\"n\": \"Format||XML||VisML\", \"k\": \"format_1915||format_2332||format_3821\"}, {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||VisML\", \"k\": \"format_1915||format_2350||format_2013||format_3821\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3825\": {\"d\": \"nmrML is an MSI supported XML-based open access format for metabolomics NMR raw and processed spectral data. It is accompanies by an nmrCV (controlled vocabulary) to allow ontology-based annotations.\", \"n\": \"nmrML\", \"ns\": [], \"u\": \"format_3825\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||nmrML\", \"k\": \"format_1915||format_2332||format_3825\"}, {\"n\": \"Format||Format (by type of data)||NMR data format||nmrML\", \"k\": \"format_1915||format_2350||format_3824||format_3825\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3832\": {\"d\": \"OpenMS format for grouping features in one map or across several maps.\", \"n\": \"consensusXML\", \"ns\": [], \"u\": \"format_3832\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||consensusXML\", \"k\": \"format_1915||format_2332||format_3832\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||consensusXML\", \"k\": \"format_1915||format_2350||format_3245||format_3832\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3833\": {\"d\": \"OpenMS format for quantitation results (LC/MS features).\", \"n\": \"featureXML\", \"ns\": [], \"u\": \"format_3833\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||featureXML\", \"k\": \"format_1915||format_2332||format_3833\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||featureXML\", \"k\": \"format_1915||format_2350||format_3245||format_3833\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3834\": {\"d\": \"Now deprecated data format of the HUPO Proteomics Standards Initiative.  Replaced by mzML (format_3244).\", \"n\": \"mzData\", \"ns\": [], \"u\": \"format_3834\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||mzData\", \"k\": \"format_1915||format_2332||format_3834\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||mzData\", \"k\": \"format_1915||format_2350||format_3245||format_3834\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3835\": {\"d\": \"Format supported by the Tide tool for identifying peptides from tandem mass spectra.\", \"n\": \"TIDE TXT\", \"ns\": [], \"u\": \"format_3835\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||TIDE TXT\", \"k\": \"format_1915||format_2332||format_3835\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||TIDE TXT\", \"k\": \"format_1915||format_2350||format_3245||format_3835\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3838\": {\"d\": \"Microsoft Powerpoint format.\", \"n\": \"pptx\", \"ns\": [], \"u\": \"format_3838\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||pptx\", \"k\": \"format_1915||format_2332||format_3838\"}, {\"n\": \"Format||Format (by type of data)||Image format||pptx\", \"k\": \"format_1915||format_2350||format_3547||format_3838\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3843\": {\"d\": \"XML input file format for BEAST Software (Bayesian Evolutionary Analysis Sampling Trees).\", \"n\": \"BEAST\", \"ns\": [], \"u\": \"format_3843\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||BEAST\", \"k\": \"format_1915||format_2332||format_3843\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||BEAST\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3843\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3844\": {\"d\": \"Chado-XML format is a direct mapping of the Chado relational schema into XML.\", \"n\": \"Chado-XML\", \"ns\": [], \"u\": \"format_3844\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||Chado-XML\", \"k\": \"format_1915||format_2332||format_3844\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||Chado-XML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3844\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3845\": {\"d\": \"An alignment format generated by PRANK/PRANKSTER consisting of four elements: newick, nodes, selection and model.\", \"n\": \"HSAML\", \"ns\": [], \"u\": \"format_3845\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||HSAML\", \"k\": \"format_1915||format_2332||format_3845\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (XML)||HSAML\", \"k\": \"format_1915||format_2350||format_1921||format_2555||format_3845\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3846\": {\"d\": \"Output xml file from the InterProScan sequence analysis application.\", \"n\": \"InterProScan XML\", \"ns\": [], \"u\": \"format_3846\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||InterProScan XML\", \"k\": \"format_1915||format_2332||format_3846\"}, {\"n\": \"Format||Format (by type of data)||Protein domain classification format||InterProScan XML\", \"k\": \"format_1915||format_2350||format_3097||format_3846\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3847\": {\"d\": \"The KEGG Markup Language (KGML) is an exchange format of the KEGG pathway maps, which is converted from internally used KGML+ (KGML+SVG) format.\", \"n\": \"KGML\", \"ns\": [], \"u\": \"format_3847\", \"es\": [\"KEGG Markup Language\"], \"ch\": [], \"p\": [{\"n\": \"Format||XML||KGML\", \"k\": \"format_1915||format_2332||format_3847\"}, {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||KGML\", \"k\": \"format_1915||format_2350||format_2013||format_3847\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3848\": {\"d\": \"XML format for collected entries from biobliographic databases MEDLINE and PubMed.\", \"n\": \"PubMed XML\", \"ns\": [], \"u\": \"format_3848\", \"es\": [\"MEDLINE XML\"], \"ch\": [], \"p\": [{\"n\": \"Format||XML||PubMed XML\", \"k\": \"format_1915||format_2332||format_3848\"}, {\"n\": \"Format||Format (by type of data)||Bibliographic reference format||PubMed XML\", \"k\": \"format_1915||format_2350||format_2848||format_3848\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3850\": {\"d\": \"OrthoXML is designed broadly to allow the storage and comparison of orthology data from any ortholog database. It establishes a structure for describing orthology relationships while still allowing flexibility for database-specific information to be encapsulated in the same format.\", \"n\": \"OrthoXML\", \"ns\": [], \"u\": \"format_3850\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||OrthoXML\", \"k\": \"format_1915||format_2332||format_3850\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||OrthoXML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3850\"}, {\"n\": \"Format||Format (by type of data)||Gene annotation format||OrthoXML\", \"k\": \"format_1915||format_2350||format_2031||format_3850\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3851\": {\"d\": \"Tree structure of Protein Sequence Database Markup Language generated using Matra software.\", \"n\": \"PSDML\", \"ns\": [], \"u\": \"format_3851\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||PSDML\", \"k\": \"format_1915||format_2332||format_3851\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||PSDML\", \"k\": \"format_1915||format_2350||format_1920||format_3851\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3852\": {\"d\": \"SeqXML is an XML Schema to describe biological sequences, developed by the Stockholm Bioinformatics Centre.\", \"n\": \"SeqXML\", \"ns\": [], \"u\": \"format_3852\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||SeqXML\", \"k\": \"format_1915||format_2332||format_3852\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence record format (XML)||SeqXML\", \"k\": \"format_1915||format_2350||format_1919||format_2552||format_3852\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3853\": {\"d\": \"XML format for the UniParc database.\", \"n\": \"UniParc XML\", \"ns\": [], \"u\": \"format_3853\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||UniParc XML\", \"k\": \"format_1915||format_2332||format_3853\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||UniParc XML\", \"k\": \"format_1915||format_2350||format_1920||format_3853\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3854\": {\"d\": \"XML format for the UniRef reference clusters.\", \"n\": \"UniRef XML\", \"ns\": [], \"u\": \"format_3854\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||UniRef XML\", \"k\": \"format_1915||format_2332||format_3854\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||UniRef XML\", \"k\": \"format_1915||format_2350||format_1920||format_3854\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3971\": {\"d\": \"A model description language for computational neuroscience.\", \"n\": \"NeuroML\", \"ns\": [], \"u\": \"format_3971\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||XML||NeuroML\", \"k\": \"format_1915||format_2332||format_3971\"}, {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||NeuroML\", \"k\": \"format_1915||format_2350||format_2013||format_3971\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_2333\": {\"d\": \"Binary format.\", \"n\": \"Binary format\", \"ns\": [], \"u\": \"format_2333\", \"es\": [], \"ch\": [{\"n\": \"ABI\", \"u\": \"format_1628\"}, {\"n\": \"SCF\", \"u\": \"format_1632\"}, {\"n\": \"BAM\", \"u\": \"format_2572\"}, {\"n\": \"AB1\", \"u\": \"format_3000\"}, {\"n\": \"bigBed\", \"u\": \"format_3004\"}, {\"n\": \"bigWig\", \"u\": \"format_3006\"}, {\"n\": \"2bit\", \"u\": \"format_3009\"}, {\"n\": \".nib\", \"u\": \"format_3010\"}, {\"n\": \"SRF\", \"u\": \"format_3017\"}, {\"n\": \"ZTR\", \"u\": \"format_3018\"}, {\"n\": \"BCF\", \"u\": \"format_3020\"}, {\"n\": \"SFF\", \"u\": \"format_3284\"}, {\"n\": \"BAI\", \"u\": \"format_3327\"}, {\"n\": \"CRAM\", \"u\": \"format_3462\"}, {\"n\": \"GIF\", \"u\": \"format_3467\"}, {\"n\": \"ebwt\", \"u\": \"format_3484\"}, {\"n\": \"ebwtl\", \"u\": \"format_3491\"}, {\"n\": \"PDF\", \"u\": \"format_3508\"}, {\"n\": \"DICOM format\", \"u\": \"format_3548\"}, {\"n\": \"nii\", \"u\": \"format_3549\"