 \"u\": \"format_3973\"}, {\"n\": \"TAR format\", \"u\": \"format_3981\"}, {\"n\": \"WMV\", \"u\": \"format_3986\"}, {\"n\": \"ZIP format\", \"u\": \"format_3987\"}, {\"n\": \"LSM\", \"u\": \"format_3988\"}, {\"n\": \"GZIP format\", \"u\": \"format_3989\"}, {\"n\": \"AVI\", \"u\": \"format_3990\"}, {\"n\": \"TrackDB\", \"u\": \"format_3991\"}, {\"n\": \"Stereolithography format\", \"u\": \"format_3993\"}, {\"n\": \"U3D\", \"u\": \"format_3994\"}, {\"n\": \"Texture file format\", \"u\": \"format_3995\"}, {\"n\": \"MPEG-4\", \"u\": \"format_3997\"}, {\"n\": \"NIFTI format\", \"u\": \"format_4001\"}, {\"n\": \"pickle\", \"u\": \"format_4002\"}, {\"n\": \"NumPy format\", \"u\": \"format_4003\"}, {\"n\": \"SimTools repertoire file format\", \"u\": \"format_4004\"}, {\"n\": \"Zstandard format\", \"u\": \"format_4006\"}], \"p\": [{\"n\": \"Format||Binary format\", \"k\": \"format_1915||format_2333\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_1628\": {\"d\": \"A format of raw sequence read data from an Applied Biosystems sequencing machine.\", \"n\": \"ABI\", \"ns\": [], \"u\": \"format_1628\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||ABI\", \"k\": \"format_1915||format_2333||format_1628\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||ABI\", \"k\": \"format_1915||format_2350||format_1919||format_2057||format_1628\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_1632\": {\"d\": \"Staden Chromatogram Files format (SCF) of base-called sequence reads, qualities, and other metadata.\", \"n\": \"SCF\", \"ns\": [], \"u\": \"format_1632\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||SCF\", \"k\": \"format_1915||format_2333||format_1632\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||SCF\", \"k\": \"format_1915||format_2350||format_1919||format_2057||format_1632\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_2572\": {\"d\": \"BAM format, the binary, BGZF-formatted compressed version of SAM format for alignment of nucleotide sequences (e.g. sequencing reads) to (a) reference sequence(s). May contain base-call and alignment qualities and other data.\", \"n\": \"BAM\", \"ns\": [], \"u\": \"format_2572\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||BAM\", \"k\": \"format_1915||format_2333||format_2572\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||BAM\", \"k\": \"format_1915||format_2350||format_1919||format_2057||format_2572\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||BAM\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_2572\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3000\": {\"d\": \"AB1 binary format of raw DNA sequence reads (output of Applied Biosystems\' sequencing analysis software). Contains an electropherogram and the DNA base sequence.\", \"n\": \"AB1\", \"ns\": [], \"u\": \"format_3000\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||AB1\", \"k\": \"format_1915||format_2333||format_3000\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||AB1\", \"k\": \"format_1915||format_2350||format_1919||format_2057||format_3000\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3004\": {\"d\": \"bigBed format for large sequence annotation tracks, similar to textual BED format.\", \"n\": \"bigBed\", \"ns\": [], \"u\": \"format_3004\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||bigBed\", \"k\": \"format_1915||format_2333||format_3004\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||bigBed\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3004\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3006\": {\"d\": \"bigWig format for large sequence annotation tracks that consist of a value for each sequence position. Similar to textual WIG format.\", \"n\": \"bigWig\", \"ns\": [], \"u\": \"format_3006\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||bigWig\", \"k\": \"format_1915||format_2333||format_3006\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||bigWig\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3006\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3009\": {\"d\": \"2bit binary format of nucleotide sequences using 2 bits per nucleotide. In addition encodes unknown nucleotides and lower-case \'masking\'.\", \"n\": \"2bit\", \"ns\": [], \"u\": \"format_3009\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||2bit\", \"k\": \"format_1915||format_2333||format_3009\"}, {\"n\": \"Format||Format (by type of data)||Raw sequence format||2bit\", \"k\": \"format_1915||format_2350||format_2571||format_3009\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3010\": {\"d\": \".nib (nibble) binary format of a nucleotide sequence using 4 bits per nucleotide (including unknown) and its lower-case \'masking\'.\", \"n\": \".nib\", \"ns\": [], \"u\": \"format_3010\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||.nib\", \"k\": \"format_1915||format_2333||format_3010\"}, {\"n\": \"Format||Format (by type of data)||Raw sequence format||.nib\", \"k\": \"format_1915||format_2350||format_2571||format_3010\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3017\": {\"d\": \"Sequence Read Format (SRF) of sequence trace data. Supports submission to the NCBI Short Read Archive.\", \"n\": \"SRF\", \"ns\": [], \"u\": \"format_3017\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||SRF\", \"k\": \"format_1915||format_2333||format_3017\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||SRF\", \"k\": \"format_1915||format_2350||format_1919||format_2057||format_3017\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3018\": {\"d\": \"ZTR format for storing chromatogram data from DNA sequencing instruments.\", \"n\": \"ZTR\", \"ns\": [], \"u\": \"format_3018\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||ZTR\", \"k\": \"format_1915||format_2333||format_3018\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||ZTR\", \"k\": \"format_1915||format_2350||format_1919||format_2057||format_3018\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3020\": {\"d\": \"BCF, the binary version of Variant Call Format (VCF) for sequence variation (indels, polymorphisms, structural variation).\", \"n\": \"BCF\", \"ns\": [], \"u\": \"format_3020\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||BCF\", \"k\": \"format_1915||format_2333||format_3020\"}, {\"n\": \"Format||Format (by type of data)||Sequence variation annotation format||BCF\", \"k\": \"format_1915||format_2350||format_2921||format_3020\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3284\": {\"d\": \"Standard flowgram format (SFF) is a binary file format used to encode results of pyrosequencing from the 454 Life Sciences platform for high-throughput sequencing.\", \"n\": \"SFF\", \"ns\": [], \"u\": \"format_3284\", \"es\": [\"Standard flowgram format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||SFF\", \"k\": \"format_1915||format_2333||format_3284\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||SFF\", \"k\": \"format_1915||format_2350||format_1919||format_2057||format_3284\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3327\": {\"d\": \"BAM indexing format\", \"n\": \"BAI\", \"ns\": [], \"u\": \"format_3327\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||BAI\", \"k\": \"format_1915||format_2333||format_3327\"}, {\"n\": \"Format||Format (by type of data)||Data index format||BAI\", \"k\": \"format_1915||format_2350||format_3326||format_3327\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3462\": {\"d\": \"Reference-based compression of alignment format\", \"n\": \"CRAM\", \"ns\": [], \"u\": \"format_3462\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||CRAM\", \"k\": \"format_1915||format_2333||format_3462\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||CRAM\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3462\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3467\": {\"d\": \"Graphics Interchange Format.\", \"n\": \"GIF\", \"ns\": [], \"u\": \"format_3467\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||GIF\", \"k\": \"format_1915||format_2333||format_3467\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3484\": {\"d\": \"Bowtie format for indexed reference genome for \\\"small\\\" genomes.\", \"n\": \"ebwt\", \"ns\": [], \"u\": \"format_3484\", \"es\": [\"Bowtie index format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||ebwt\", \"k\": \"format_1915||format_2333||format_3484\"}, {\"n\": \"Format||Format (by type of data)||Data index format||ebwt\", \"k\": \"format_1915||format_2350||format_3326||format_3484\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3491\": {\"d\": \"Bowtie format for indexed reference genome for \\\"large\\\" genomes.\", \"n\": \"ebwtl\", \"ns\": [], \"u\": \"format_3491\", \"es\": [\"Bowtie long index format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||ebwtl\", \"k\": \"format_1915||format_2333||format_3491\"}, {\"n\": \"Format||Format (by type of data)||Data index format||ebwtl\", \"k\": \"format_1915||format_2350||format_3326||format_3491\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3508\": {\"d\": \"Portable Document Format\", \"n\": \"PDF\", \"ns\": [], \"u\": \"format_3508\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||PDF\", \"k\": \"format_1915||format_2333||format_3508\"}, {\"n\": \"Format||Format (by type of data)||Document format||PDF\", \"k\": \"format_1915||format_2350||format_3507||format_3508\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3548\": {\"d\": \"Medical image format corresponding to the Digital Imaging and Communications in Medicine (DICOM) standard.\", \"n\": \"DICOM format\", \"ns\": [], \"u\": \"format_3548\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||DICOM format\", \"k\": \"format_1915||format_2333||format_3548\"}, {\"n\": \"Format||Format (by type of data)||Image format||DICOM format\", \"k\": \"format_1915||format_2350||format_3547||format_3548\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3549\": {\"d\": \"Medical image and metadata format of the Neuroimaging Informatics Technology Initiative.\", \"n\": \"nii\", \"ns\": [], \"u\": \"format_3549\", \"es\": [\"NIfTI-1 format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||nii\", \"k\": \"format_1915||format_2333||format_3549\"}, {\"n\": \"Format||Format (by type of data)||Image format||nii\", \"k\": \"format_1915||format_2350||format_3547||format_3549\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3578\": {\"d\": \"Proprietary file format for (raw) BeadArray data used by genomewide profiling platforms from Illumina Inc. This format is output directly from the scanner and stores summary intensities for each probe-type on an array.\", \"n\": \"IDAT\", \"ns\": [], \"u\": \"format_3578\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||IDAT\", \"k\": \"format_1915||format_2333||format_3578\"}, {\"n\": \"Format||Format (by type of data)||Gene expression report format||IDAT\", \"k\": \"format_1915||format_2350||format_2058||format_3578\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3579\": {\"d\": \"Joint Picture Group file format for lossy graphics file.\", \"n\": \"JPG\", \"ns\": [], \"u\": \"format_3579\", \"es\": [\"JPEG\", \"jpeg\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||JPG\", \"k\": \"format_1915||format_2333||format_3579\"}, {\"n\": \"Format||Format (by type of data)||Image format||JPG\", \"k\": \"format_1915||format_2350||format_3547||format_3579\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3590\": {\"d\": \"HDF5 is a data model, library, and file format for storing and managing data, based on Hierarchical Data Format (HDF).\", \"n\": \"HDF5\", \"ns\": [], \"u\": \"format_3590\", \"es\": [\"h5\"], \"ch\": [{\"n\": \"Loom\", \"u\": \"format_3913\"}], \"p\": [{\"n\": \"Format||Binary format||HDF5\", \"k\": \"format_1915||format_2333||format_3590\"}, {\"n\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||HDF5\", \"k\": \"format_1915||format_2350||format_3866||format_3867||format_3590\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3913\": {\"d\": \"The Loom file format is based on HDF5, a standard for storing large numerical datasets. The Loom format is designed to efficiently hold large omics datasets. Typically, such data takes the form of a large matrix of numbers, along with metadata for the rows and columns.\", \"n\": \"Loom\", \"ns\": [], \"u\": \"format_3913\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||HDF5||Loom\", \"k\": \"format_1915||format_2333||format_3590||format_3913\"}, {\"n\": \"Format||Format (by type of data)||Gene expression report format||Loom\", \"k\": \"format_1915||format_2350||format_2058||format_3913\"}, {\"n\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||HDF5||Loom\", \"k\": \"format_1915||format_2350||format_3866||format_3867||format_3590||format_3913\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3591\": {\"d\": \"A versatile bitmap format.\", \"n\": \"TIFF\", \"ns\": [], \"u\": \"format_3591\", \"es\": [\"tiff\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||TIFF\", \"k\": \"format_1915||format_2333||format_3591\"}, {\"n\": \"Format||Format (by type of data)||Image format||TIFF\", \"k\": \"format_1915||format_2350||format_3547||format_3591\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3592\": {\"d\": \"Standard bitmap storage format in the Microsoft Windows environment.\", \"n\": \"BMP\", \"ns\": [], \"u\": \"format_3592\", \"es\": [\"bmp\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||BMP\", \"k\": \"format_1915||format_2333||format_3592\"}, {\"n\": \"Format||Format (by type of data)||Image format||BMP\", \"k\": \"format_1915||format_2350||format_3547||format_3592\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3593\": {\"d\": \"IM is a format used by LabEye and other applications based on the IFUNC image processing library.\", \"n\": \"im\", \"ns\": [], \"u\": \"format_3593\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||im\", \"k\": \"format_1915||format_2333||format_3593\"}, {\"n\": \"Format||Format (by type of data)||Image format||im\", \"k\": \"format_1915||format_2350||format_3547||format_3593\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3594\": {\"d\": \"Photo CD format, which is the highest resolution format for images on a CD.\", \"n\": \"pcd\", \"ns\": [], \"u\": \"format_3594\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||pcd\", \"k\": \"format_1915||format_2333||format_3594\"}, {\"n\": \"Format||Format (by type of data)||Image format||pcd\", \"k\": \"format_1915||format_2350||format_3547||format_3594\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3595\": {\"d\": \"PCX is an image file format that uses a simple form of run-length encoding. It is lossless.\", \"n\": \"pcx\", \"ns\": [], \"u\": \"format_3595\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||pcx\", \"k\": \"format_1915||format_2333||format_3595\"}, {\"n\": \"Format||Format (by type of data)||Image format||pcx\", \"k\": \"format_1915||format_2350||format_3547||format_3595\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3596\": {\"d\": \"The PPM format is a lowest common denominator color image file format.\", \"n\": \"ppm\", \"ns\": [], \"u\": \"format_3596\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||ppm\", \"k\": \"format_1915||format_2333||format_3596\"}, {\"n\": \"Format||Format (by type of data)||Image format||ppm\", \"k\": \"format_1915||format_2350||format_3547||format_3596\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3597\": {\"d\": \"PSD (Photoshop Document) is a proprietary file that allows the user to work with the images\' individual layers even after the file has been saved.\", \"n\": \"psd\", \"ns\": [], \"u\": \"format_3597\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||psd\", \"k\": \"format_1915||format_2333||format_3597\"}, {\"n\": \"Format||Format (by type of data)||Image format||psd\", \"k\": \"format_1915||format_2350||format_3547||format_3597\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3598\": {\"d\": \"X BitMap is a plain text binary image format used by the X Window System used for storing cursor and icon bitmaps used in the X GUI.\", \"n\": \"xbm\", \"ns\": [], \"u\": \"format_3598\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||xbm\", \"k\": \"format_1915||format_2333||format_3598\"}, {\"n\": \"Format||Format (by type of data)||Image format||xbm\", \"k\": \"format_1915||format_2350||format_3547||format_3598\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3599\": {\"d\": \"X PixMap (XPM) is an image file format used by the X Window System, it is intended primarily for creating icon pixmaps, and supports transparent pixels.\", \"n\": \"xpm\", \"ns\": [], \"u\": \"format_3599\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||xpm\", \"k\": \"format_1915||format_2333||format_3599\"}, {\"n\": \"Format||Format (by type of data)||Image format||xpm\", \"k\": \"format_1915||format_2350||format_3547||format_3599\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3600\": {\"d\": \"RGB file format is the native raster graphics file format for Silicon Graphics workstations.\", \"n\": \"rgb\", \"ns\": [], \"u\": \"format_3600\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||rgb\", \"k\": \"format_1915||format_2333||format_3600\"}, {\"n\": \"Format||Format (by type of data)||Image format||rgb\", \"k\": \"format_1915||format_2350||format_3547||format_3600\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3601\": {\"d\": \"The PBM format is a lowest common denominator monochrome file format. It serves as the common language of a large family of bitmap image conversion filters.\", \"n\": \"pbm\", \"ns\": [], \"u\": \"format_3601\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||pbm\", \"k\": \"format_1915||format_2333||format_3601\"}, {\"n\": \"Format||Format (by type of data)||Image format||pbm\", \"k\": \"format_1915||format_2350||format_3547||format_3601\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3602\": {\"d\": \"The PGM format is a lowest common denominator grayscale file format.\", \"n\": \"pgm\", \"ns\": [], \"u\": \"format_3602\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||pgm\", \"k\": \"format_1915||format_2333||format_3602\"}, {\"n\": \"Format||Format (by type of data)||Image format||pgm\", \"k\": \"format_1915||format_2350||format_3547||format_3602\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3603\": {\"d\": \"PNG is a file format for image compression.\", \"n\": \"PNG\", \"ns\": [], \"u\": \"format_3603\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||PNG\", \"k\": \"format_1915||format_2333||format_3603\"}, {\"n\": \"Format||Format (by type of data)||Image format||PNG\", \"k\": \"format_1915||format_2350||format_3547||format_3603\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3605\": {\"d\": \"Sun Raster is a raster graphics file format used on SunOS by Sun Microsystems\", \"n\": \"rast\", \"ns\": [], \"u\": \"format_3605\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||rast\", \"k\": \"format_1915||format_2333||format_3605\"}, {\"n\": \"Format||Format (by type of data)||Image format||rast\", \"k\": \"format_1915||format_2350||format_3547||format_3605\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3615\": {\"d\": \"Blocked GNU Zip format.\", \"n\": \"bgzip\", \"ns\": [], \"u\": \"format_3615\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||bgzip\", \"k\": \"format_1915||format_2333||format_3615\"}, {\"n\": \"Format||Format (by type of data)||Image format||bgzip\", \"k\": \"format_1915||format_2350||format_3547||format_3615\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3616\": {\"d\": \"TAB-delimited genome position file index format.\", \"n\": \"tabix\", \"ns\": [], \"u\": \"format_3616\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||tabix\", \"k\": \"format_1915||format_2333||format_3616\"}, {\"n\": \"Format||Format (by type of data)||Image format||tabix\", \"k\": \"format_1915||format_2350||format_3547||format_3616\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3620\": {\"d\": \"MS Excel spreadsheet format consisting of a set of XML documents stored in a ZIP-compressed file.\", \"n\": \"xlsx\", \"ns\": [], \"u\": \"format_3620\", \"es\": [], \"ch\": [{\"n\": \"ObjTables\", \"u\": \"format_3977\"}], \"p\": [{\"n\": \"Format||Binary format||xlsx\", \"k\": \"format_1915||format_2333||format_3620\"}, {\"n\": \"Format||Format (by type of data)||Document format||xlsx\", \"k\": \"format_1915||format_2350||format_3507||format_3620\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3977\": {\"d\": \"ObjTables is a toolkit for creating re-usable datasets that are both human and machine-readable, combining the ease of spreadsheets (e.g., Excel workbooks) with the rigor of schemas (classes, their attributes, the type of each attribute, and the possible relationships between instances of classes). ObjTables consists of a format for describing schemas for spreadsheets, numerous data types for science, a syntax for indicating the class and attribute represented by each table and column in a workbook, and software for using schemas to rigorously validate, merge, split, compare, and revision datasets.\", \"n\": \"ObjTables\", \"ns\": [], \"u\": \"format_3977\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||xlsx||ObjTables\", \"k\": \"format_1915||format_2333||format_3620||format_3977\"}, {\"n\": \"Format||Format (by type of data)||Document format||xlsx||ObjTables\", \"k\": \"format_1915||format_2350||format_3507||format_3620||format_3977\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3621\": {\"d\": \"Data format used by the SQLite database.\", \"n\": \"SQLite format\", \"ns\": [], \"u\": \"format_3621\", \"es\": [], \"ch\": [{\"n\": \"Gemini SQLite format\", \"u\": \"format_3622\"}], \"p\": [{\"n\": \"Format||Binary format||SQLite format\", \"k\": \"format_1915||format_2333||format_3621\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3622\": {\"d\": \"Data format used by the SQLite database conformant to the Gemini schema.\", \"n\": \"Gemini SQLite format\", \"ns\": [], \"u\": \"format_3622\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||SQLite format||Gemini SQLite format\", \"k\": \"format_1915||format_2333||format_3621||format_3622\"}, {\"n\": \"Format||Format (by type of data)||Sequence variation annotation format||Gemini SQLite format\", \"k\": \"format_1915||format_2350||format_2921||format_3622\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3624\": {\"d\": \"An index of a genome database, indexed for use by the snpeff tool.\", \"n\": \"snpeffdb\", \"ns\": [], \"u\": \"format_3624\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||snpeffdb\", \"k\": \"format_1915||format_2333||format_3624\"}, {\"n\": \"Format||Format (by type of data)||Data index format||snpeffdb\", \"k\": \"format_1915||format_2350||format_3326||format_3624\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3650\": {\"d\": \"Format used by netCDF software  library for writing and reading chromatography-MS data files.  Also used to store trajectory atom coordinates information, such as the ones obtained by Molecular Dynamics simulations.\", \"n\": \"netCDF\", \"ns\": [], \"u\": \"format_3650\", \"es\": [\"ANDI-MS\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||netCDF\", \"k\": \"format_1915||format_2333||format_3650\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||netCDF\", \"k\": \"format_1915||format_2350||format_3245||format_3650\"}, {\"n\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||netCDF\", \"k\": \"format_1915||format_2350||format_3866||format_3867||format_3650\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3665\": {\"d\": \"A list of k-mers and their occurences in a dataset. Can also be used as an implicit De Bruijn graph.\", \"n\": \"K-mer countgraph\", \"ns\": [], \"u\": \"format_3665\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||K-mer countgraph\", \"k\": \"format_1915||format_2333||format_3665\"}, {\"n\": \"Format||Format (by type of data)||Graph format||K-mer countgraph\", \"k\": \"format_1915||format_2350||format_3617||format_3665\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3686\": {\"d\": \"Open Modeling EXchange format (OMEX) is a ZIPped format for encapsulating all information necessary for a modeling and simulation project in systems biology.\", \"n\": \"COMBINE OMEX\", \"ns\": [], \"u\": \"format_3686\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||COMBINE OMEX\", \"k\": \"format_1915||format_2333||format_3686\"}, {\"n\": \"Format||Format (by type of data)||Biological pathway or network format||COMBINE OMEX\", \"k\": \"format_1915||format_2350||format_2013||format_3686\"}, {\"n\": \"Format||Format (by type of data)||Experiment annotation format||COMBINE OMEX\", \"k\": \"format_1915||format_2350||format_3167||format_3686\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3698\": {\"d\": \"SRA archive format (SRA) is the archive format used for input to the NCBI Sequence Read Archive.\", \"n\": \"SRA format\", \"ns\": [], \"u\": \"format_3698\", \"es\": [\"SRA\", \"SRA archive format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||SRA format\", \"k\": \"format_1915||format_2333||format_3698\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3699\": {\"d\": \"VDB (\'vertical database\') is the native format used for export from the NCBI Sequence Read Archive.\", \"n\": \"VDB\", \"ns\": [], \"u\": \"format_3699\", \"es\": [\"SRA native format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||VDB\", \"k\": \"format_1915||format_2333||format_3699\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3700\": {\"d\": \"Index file format used by the samtools package to index TAB-delimited genome position files.\", \"n\": \"Tabix index file format\", \"ns\": [], \"u\": \"format_3700\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||Tabix index file format\", \"k\": \"format_1915||format_2333||format_3700\"}, {\"n\": \"Format||Format (by type of data)||Data index format||Tabix index file format\", \"k\": \"format_1915||format_2350||format_3326||format_3700\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3710\": {\"d\": \"Mass spectrum file format from QSTAR and QTRAP instruments (ABI/Sciex).\", \"n\": \"WIFF format\", \"ns\": [], \"u\": \"format_3710\", \"es\": [\"wiff\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||WIFF format\", \"k\": \"format_1915||format_2333||format_3710\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||WIFF format\", \"k\": \"format_1915||format_2350||format_3245||format_3710\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3712\": {\"d\": \"Proprietary file format for mass spectrometry data from Thermo Scientific.\", \"n\": \"Thermo RAW\", \"ns\": [], \"u\": \"format_3712\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||Thermo RAW\", \"k\": \"format_1915||format_2333||format_3712\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||Thermo RAW\", \"k\": \"format_1915||format_2350||format_3245||format_3712\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3727\": {\"d\": \"Image file format used by the Open Microscopy Environment (OME).\", \"n\": \"OME-TIFF\", \"ns\": [], \"u\": \"format_3727\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||OME-TIFF\", \"k\": \"format_1915||format_2333||format_3727\"}, {\"n\": \"Format||Format (by type of data)||Image format||OME-TIFF\", \"k\": \"format_1915||format_2350||format_3547||format_3727\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3776\": {\"d\": \"BTrack is an HDF5-based binary format for genome or sequence feature tracks and their collections, suitable for integrative multi-track analysis. BTrack is a binary, compressed alternative to the GTrack and GSuite formats.\", \"n\": \"BTrack\", \"ns\": [], \"u\": \"format_3776\", \"es\": [\"BTrack (GTrack ecosystem of formats)\", \"BTrack format\", \"BioXSD/GTrack BTrack\", \"BioXSD|GTrack BTrack\", \"GTrack|BTrack|GSuite BTrack\", \"GTrack|GSuite|BTrack BTrack\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||BTrack\", \"k\": \"format_1915||format_2333||format_3776\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence feature table format||BTrack\", \"k\": \"format_1915||format_2350||format_1920||format_2548||format_3776\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||BTrack\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3776\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||BTrack\", \"k\": \"format_1915||format_2350||format_1920||format_3776\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3826\": {\"d\": \". proBAM is an adaptation of BAM (format_2572), which was extended to meet specific requirements entailed by proteomics data.\", \"n\": \"proBAM\", \"ns\": [], \"u\": \"format_3826\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||proBAM\", \"k\": \"format_1915||format_2333||format_3826\"}, {\"n\": \"Format||Format (by type of data)||Sequence record format||Sequence trace format||proBAM\", \"k\": \"format_1915||format_2350||format_1919||format_2057||format_3826\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||Alignment format (pair only)||proBAM\", \"k\": \"format_1915||format_2350||format_1921||format_2920||format_3826\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3830\": {\"d\": \"Binary format used by the ARB software suite\", \"n\": \"ARB\", \"ns\": [], \"u\": \"format_3830\", \"es\": [\"ARB binary format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||ARB\", \"k\": \"format_1915||format_2333||format_3830\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||ARB\", \"k\": \"format_1915||format_2350||format_1921||format_3830\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3839\": {\"d\": \"ibd is a data format for mass spectrometry imaging data.\", \"n\": \"ibd\", \"ns\": [], \"u\": \"format_3839\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||ibd\", \"k\": \"format_1915||format_2333||format_3839\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||ibd\", \"k\": \"format_1915||format_2350||format_3245||format_3839\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3849\": {\"d\": \"A set of XML compliant markup components for describing multiple sequence alignments.\", \"n\": \"MSAML\", \"ns\": [], \"u\": \"format_3849\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||MSAML\", \"k\": \"format_1915||format_2333||format_3849\"}, {\"n\": \"Format||Format (by type of data)||Alignment format||MSAML\", \"k\": \"format_1915||format_2350||format_1921||format_3849\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3858\": {\"d\": \"Proprietary file format for mass spectrometry data from Waters.\", \"n\": \"Waters RAW\", \"ns\": [], \"u\": \"format_3858\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||Waters RAW\", \"k\": \"format_1915||format_2333||format_3858\"}, {\"n\": \"Format||Format (by type of data)||Mass spectrometry data format||Waters RAW\", \"k\": \"format_1915||format_2350||format_3245||format_3858\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3873\": {\"d\": \"HDF is the name of a set of file formats and libraries designed to store and organize large amounts of numerical data, originally developed at the National Center for Supercomputing Applications at the University of Illinois.\", \"n\": \"HDF\", \"ns\": [], \"u\": \"format_3873\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||HDF\", \"k\": \"format_1915||format_2333||format_3873\"}, {\"n\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||HDF\", \"k\": \"format_1915||format_2350||format_3866||format_3867||format_3873\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3874\": {\"d\": \"PCAZip format is a binary compressed file to store atom coordinates based on Essential Dynamics (ED) and Principal Component Analysis (PCA).\", \"n\": \"PCAzip\", \"ns\": [], \"u\": \"format_3874\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||PCAzip\", \"k\": \"format_1915||format_2333||format_3874\"}, {\"n\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||PCAzip\", \"k\": \"format_1915||format_2350||format_3866||format_3867||format_3874\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3875\": {\"d\": \"Portable binary format for trajectories produced by GROMACS package.\", \"n\": \"XTC\", \"ns\": [], \"u\": \"format_3875\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||XTC\", \"k\": \"format_1915||format_2333||format_3875\"}, {\"n\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||XTC\", \"k\": \"format_1915||format_2350||format_3866||format_3867||format_3875\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3876\": {\"d\": \"Trajectory Next Generation (TNG) is a format for storage of molecular simulation data. It is designed and implemented by the GROMACS development group, and it is called to be the substitute of the XTC format.\", \"n\": \"TNG\", \"ns\": [], \"u\": \"format_3876\", \"es\": [\"Trajectory Next Generation format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||TNG\", \"k\": \"format_1915||format_2333||format_3876\"}, {\"n\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||TNG\", \"k\": \"format_1915||format_2350||format_3866||format_3867||format_3876\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3885\": {\"d\": \"Scripps Research Institute BinPos format is a binary formatted file to store atom coordinates.\", \"n\": \"BinPos\", \"ns\": [], \"u\": \"format_3885\", \"es\": [\"Scripps Research Institute BinPos\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||BinPos\", \"k\": \"format_1915||format_2333||format_3885\"}, {\"n\": \"Format||Format (by type of data)||Trajectory format||Trajectory format (binary)||BinPos\", \"k\": \"format_1915||format_2350||format_3866||format_3867||format_3885\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3911\": {\"d\": \"Mash sketch is a format for sequence / sequence checksum information. To make a sketch, each k-mer in a sequence is hashed, which creates a pseudo-random identifier. By sorting these hashes, a small subset from the top of the sorted list can represent the entire sequence.\", \"n\": \"msh\", \"ns\": [], \"u\": \"format_3911\", \"es\": [\"Mash sketch\", \"min-hash sketch\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||msh\", \"k\": \"format_1915||format_2333||format_3911\"}, {\"n\": \"Format||Format (by type of data)||Raw sequence format||msh\", \"k\": \"format_1915||format_2350||format_2571||format_3911\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3915\": {\"d\": \"The Zarr format is an implementation of chunked, compressed, N-dimensional arrays for storing data.\", \"n\": \"Zarr\", \"ns\": [], \"u\": \"format_3915\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||Zarr\", \"k\": \"format_1915||format_2333||format_3915\"}, {\"n\": \"Format||Format (by type of data)||Gene expression report format||Zarr\", \"k\": \"format_1915||format_2350||format_2058||format_3915\"}, {\"n\": \"Format||Format (by type of data)||Matrix format||Zarr\", \"k\": \"format_1915||format_2350||format_3033||format_3915\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3973\": {\"d\": \"A Docker image is a file, comprised of multiple layers, that is used to execute code in a Docker container. An image is essentially built from the instructions for a complete and executable version of an application, which relies on the host OS kernel.\", \"n\": \"Docker image format\", \"ns\": [], \"u\": \"format_3973\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||Docker image format\", \"k\": \"format_1915||format_2333||format_3973\"}, {\"n\": \"Format||Format (by type of data)||Raw sequence format||Docker image format\", \"k\": \"format_1915||format_2350||format_2571||format_3973\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3981\": {\"d\": \"TAR archive file format generated by the Unix-based utility tar.\", \"n\": \"TAR format\", \"ns\": [], \"u\": \"format_3981\", \"es\": [\"TAR\", \"Tarball\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||TAR format\", \"k\": \"format_1915||format_2333||format_3981\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3986\": {\"d\": \"The proprietary native video format of various Microsoft programs such as Windows Media Player.\", \"n\": \"WMV\", \"ns\": [], \"u\": \"format_3986\", \"es\": [\"Windows Media Video format\", \"Windows movie file format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||WMV\", \"k\": \"format_1915||format_2333||format_3986\"}, {\"n\": \"Format||Format (by type of data)||Image format||WMV\", \"k\": \"format_1915||format_2350||format_3547||format_3986\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3987\": {\"d\": \"ZIP is an archive file format that supports lossless data compression.\", \"n\": \"ZIP format\", \"ns\": [], \"u\": \"format_3987\", \"es\": [\"ZIP\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||ZIP format\", \"k\": \"format_1915||format_2333||format_3987\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3988\": {\"d\": \"Zeiss\' proprietary image format based on TIFF.\", \"n\": \"LSM\", \"ns\": [], \"u\": \"format_3988\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||LSM\", \"k\": \"format_1915||format_2333||format_3988\"}, {\"n\": \"Format||Format (by type of data)||Image format||LSM\", \"k\": \"format_1915||format_2350||format_3547||format_3988\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3989\": {\"d\": \"GNU zip compressed file format common to Unix-based operating systems.\", \"n\": \"GZIP format\", \"ns\": [], \"u\": \"format_3989\", \"es\": [\"GNU Zip\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||GZIP format\", \"k\": \"format_1915||format_2333||format_3989\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3990\": {\"d\": \"Audio Video Interleaved (AVI) format is a multimedia container format for AVI files, that allows synchronous audio-with-video playback.\", \"n\": \"AVI\", \"ns\": [], \"u\": \"format_3990\", \"es\": [\"Audio Video Interleaved\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||AVI\", \"k\": \"format_1915||format_2333||format_3990\"}, {\"n\": \"Format||Format (by type of data)||Image format||AVI\", \"k\": \"format_1915||format_2350||format_3547||format_3990\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3991\": {\"d\": \"A declaration file format for UCSC browsers track dataset display charateristics.\", \"n\": \"TrackDB\", \"ns\": [], \"u\": \"format_3991\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||TrackDB\", \"k\": \"format_1915||format_2333||format_3991\"}, {\"n\": \"Format||Format (by type of data)||Sequence feature annotation format||Sequence annotation track format||TrackDB\", \"k\": \"format_1915||format_2350||format_1920||format_2919||format_3991\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3993\": {\"d\": \"STL is a file format native to the stereolithography CAD software created by 3D Systems.  The format is used to save and share surface-rendered 3D images and also for 3D printing.\", \"n\": \"Stereolithography format\", \"ns\": [], \"u\": \"format_3993\", \"es\": [\"stl\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||Stereolithography format\", \"k\": \"format_1915||format_2333||format_3993\"}, {\"n\": \"Format||Format (by type of data)||Image format||Stereolithography format\", \"k\": \"format_1915||format_2350||format_3547||format_3993\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3994\": {\"d\": \"U3D (Universal 3D) is a compressed file format and data structure for 3D computer graphics. It contains 3D model information such as triangle meshes, lighting, shading, motion data, lines and points with color and structure.\", \"n\": \"U3D\", \"ns\": [], \"u\": \"format_3994\", \"es\": [\"Universal 3D\", \"Universal 3D format\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||U3D\", \"k\": \"format_1915||format_2333||format_3994\"}, {\"n\": \"Format||Format (by type of data)||Image format||U3D\", \"k\": \"format_1915||format_2350||format_3547||format_3994\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3995\": {\"d\": \"Bitmap image format used for storing textures.\", \"n\": \"Texture file format\", \"ns\": [], \"u\": \"format_3995\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||Texture file format\", \"k\": \"format_1915||format_2333||format_3995\"}, {\"n\": \"Format||Format (by type of data)||Image format||Texture file format\", \"k\": \"format_1915||format_2350||format_3547||format_3995\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_3997\": {\"d\": \"A digital multimedia container format most commonly used to store video and audio.\", \"n\": \"MPEG-4\", \"ns\": [], \"u\": \"format_3997\", \"es\": [\"MP4\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||MPEG-4\", \"k\": \"format_1915||format_2333||format_3997\"}, {\"n\": \"Format||Format (by type of data)||Image format||MPEG-4\", \"k\": \"format_1915||format_2350||format_3547||format_3997\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_4001\": {\"d\": \"An open file format from the Neuroimaging Informatics Technology Initiative (NIfTI) commonly used to store brain imaging data obtained using Magnetic Resonance Imaging (MRI) methods.\", \"n\": \"NIFTI format\", \"ns\": [], \"u\": \"format_4001\", \"es\": [\"NIFTI\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||NIFTI format\", \"k\": \"format_1915||format_2333||format_4001\"}, {\"n\": \"Format||Format (by type of data)||Image format||NIFTI format\", \"k\": \"format_1915||format_2350||format_3547||format_4001\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_4002\": {\"d\": \"Format used by Python pickle module for serializing and de-serializing a Python object structure.\", \"n\": \"pickle\", \"ns\": [], \"u\": \"format_4002\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||pickle\", \"k\": \"format_1915||format_2333||format_4002\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"format_4003\": {\"d\": \"The standard binary file format used by NumPy - a fundamental package for scientific computing with Python - for persisting a single arbitrary NumPy array on disk. The format stores all of the shape and dtype information necessary to reconstruct the array correctly.\", \"n\": \"NumPy format\", \"ns\": [], \"u\": \"format_4003\", \"es\": [\"NumPy\"], \"ch\": [], \"p\": [{\"n\": \"Format||Binary format||NumPy 