.org/2002/07/owl#deprecatedclass||operation_2513\"}], \"name\": \"Sequence generation (nucleic acid)\", \"uri\": \"http://edamontology.org/operation_2513\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Generate a protein sequence by some means.\", \"path\": [{\"name\": \"Deprecated||Sequence generation (protein)\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_2514\"}], \"name\": \"Sequence generation (protein)\", \"uri\": \"http://edamontology.org/operation_2514\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Visualise, format or render a nucleic acid sequence.\", \"path\": [{\"name\": \"Deprecated||Nucleic acid sequence visualisation\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_2515\"}], \"name\": \"Nucleic acid sequence visualisation\", \"uri\": \"http://edamontology.org/operation_2515\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Visualise, format or render a protein sequence.\", \"path\": [{\"name\": \"Deprecated||Protein sequence visualisation\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_2516\"}], \"name\": \"Protein sequence visualisation\", \"uri\": \"http://edamontology.org/operation_2516\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Process (read and / or write) nucleic acid tertiary structure data.\", \"path\": [{\"name\": \"Deprecated||Structure processing (nucleic acid)\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_2519\"}], \"name\": \"Structure processing (nucleic acid)\", \"uri\": \"http://edamontology.org/operation_2519\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Process (read and / or write) a DNA map of some type.\", \"path\": [{\"name\": \"Deprecated||Map data processing\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||oper