ical pathway map\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_0947\"}], \"name\": \"Biological pathway map\", \"uri\": \"http://edamontology.org/data_0947\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A definition of a data resource serving one or more types of data, including metadata and links to the resource or data proper.\", \"path\": [{\"name\": \"Deprecated||Data resource definition\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_0948\"}], \"name\": \"Data resource definition\", \"uri\": \"http://edamontology.org/data_0948\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Resource definition for an EMBOSS database.\", \"path\": [{\"name\": \"Deprecated||EMBOSS database resource definition\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_0952\"}], \"name\": \"EMBOSS database resource definition\", \"uri\": \"http://edamontology.org/data_0952\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Information on a version of software or data, for example name, version number and release date.\", \"path\": [{\"name\": \"Deprecated||Version information\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_0953\"}], \"name\": \"Version information\", \"uri\": \"http://edamontology.org/data_0953\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Textual metadata on a submitted or completed job.\", \"path\": [{\"name\": \"Deprecated||Job metadata\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_0959\"}], \"name\": \"Job metadata\", \"uri\": \"http://edamontology.org/data_0959\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"An informative report about a specific scent.\", \"path\": [{\"name\": \"Deprecated||Scent annotation\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_0964\"}], \"name\": \"Scent annotation\", \"uri\": \"http://edamontology.org/data_0964\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"An identifier of a biological entity or phenomenon.\", \"path\": [{\"name\": \"Deprecated||Entity identifier\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_0974\"}], \"name\": \"Entity identifier\", \"uri\": \"http://edamontology.org/data_0974\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"An identifier of a data resource.\", \"path\": [{\"name\": \"Deprecated||Data resource identifier\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_0975\"}], \"name\": \"Data resource identifier\", \"uri\": \"http://edamontology.org/data_0975\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Name or other identifier of a discrete entity (any biological thing with a distinct, discrete physical existence).\", \"path\": [{\"name\": \"Deprecated||Discrete entity identifier\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_0978\"}], \"name\": \"Discrete entity identifier\", \"uri\": \"http://edamontology.org/data_0978\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Name or other identifier of an entity feature (a physical part or region of a discrete biological entity, or a feature that can be mapped to such a thing).\", \"path\": [{\"name\": \"Deprecated||Entity feature identifier\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_0979\"}], \"name\": \"Entity feature identifier\", \"uri\": \"http://edamontology.org/data_0979\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Name or other identifier of a collection of discrete biological entities.\", \"path\": [{\"name\": \"Deprecated||Entity collection identifier\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_0980\