exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"The type of a BLAST sequence alignment.\", \"path\": [{\"name\": \"Deprecated||BLAST sequence alignment type\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1121\"}], \"name\": \"BLAST sequence alignment type\", \"uri\": \"http://edamontology.org/data_1121\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A label (text token) describing the type of a phylogenetic tree.\", \"path\": [{\"name\": \"Deprecated||Phylogenetic tree type\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1122\"}], \"name\": \"Phylogenetic tree type\", \"uri\": \"http://edamontology.org/data_1122\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A label (text token) describing the type of a comparison matrix.\", \"path\": [{\"name\": \"Deprecated||Comparison matrix type\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1125\"}], \"name\": \"Comparison matrix type\", \"uri\": \"http://edamontology.org/data_1125\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Identifier of an entry from the HIVDB database.\", \"path\": [{\"name\": \"Deprecated||HIVDB identifier\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1152\"}], \"name\": \"HIVDB identifier\", \"uri\": \"http://edamontology.org/data_1152\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Identifier of an entry from the aMAZE database.\", \"path\": [{\"name\": \"Deprecated||Pathway ID (aMAZE)\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1156\"}], \"name\": \"Pathway ID (aMAZE)\", \"uri\": \"http://edamontology.org/data_1156\", \"exact_synonyms\": [\"aMAZE ID\"], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A file of intermediate results from a PSIBLAST search that is used for priming the search in the next PSIBLAST iteration.\", \"path\": [{\"name\": \"Deprecated||Psiblast checkpoint file\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1236\"}], \"name\": \"Psiblast checkpoint file\", \"uri\": \"http://edamontology.org/data_1236\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Sequences generated by HMMER package in FASTA-style format.\", \"path\": [{\"name\": \"Deprecated||HMMER synthetic sequences set\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1237\"}], \"name\": \"HMMER synthetic sequences set\", \"uri\": \"http://edamontology.org/data_1237\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"File of sequence vectors used by EMBOSS vectorstrip application, or any file in same format.\", \"path\": [{\"name\": \"Deprecated||vectorstrip cloning vector definition file\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1241\"}], \"name\": \"vectorstrip cloning vector definition file\", \"uri\": \"http://edamontology.org/data_1241\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A library of nucleotide sequences to avoid during hybridisation events. Hybridisation of the internal oligo to sequences in this library is avoided, rather than priming from them. The file is in a restricted FASTA format.\", \"path\": [{\"name\": \"Deprecated||Primer3 internal oligo mishybridizing library\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1242\"}], \"name\": \"Primer3 internal oligo mishybridizing library\", \"uri\": \"http://edamontology.org/data_1242\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"A nucleotide sequence library of sequences to avoid during amplification (for example repetitive sequences, or possibly the sequences of genes in a gene family that should not be amplified. The file must is in a restricted FASTA format.\", \"p