7/owl#deprecatedclass||topic_0660\"}], \"name\": \"rRNA\", \"uri\": \"http://edamontology.org/topic_0660\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"One or more transfer RNA (tRNA) sequences.\", \"path\": [{\"name\": \"Deprecated||tRNA\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0663\"}], \"name\": \"tRNA\", \"uri\": \"http://edamontology.org/topic_0663\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Protein secondary structure or secondary structure alignments.\", \"path\": [{\"name\": \"Deprecated||Protein secondary structure\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0694\"}], \"name\": \"Protein secondary structure\", \"uri\": \"http://edamontology.org/topic_0694\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"RNA secondary or tertiary structure and alignments.\", \"path\": [{\"name\": \"Deprecated||RNA structure\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0697\"}], \"name\": \"RNA structure\", \"uri\": \"http://edamontology.org/topic_0697\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Protein tertiary structures.\", \"path\": [{\"name\": \"Deprecated||Protein tertiary structure\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0698\"}], \"name\": \"Protein tertiary structure\", \"uri\": \"http://edamontology.org/topic_0698\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Classification of nucleic acid sequences and structures.\", \"path\": [{\"name\": \"Deprecated||Nucleic acid classification\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0722\"}], \"name\": \"Nucleic acid classification\", \"uri\": \"http://edamontology.org/topic_0722\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, {\"definition\": \"Primarily the classifi