, \"name\": \"Database entry identifier\", \"uri\": \"http://edamontology.org/data_1062\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1065\": {\"definition\": \"Identifier of a sequence signature (motif or profile) for example from a database of sequence patterns.\", \"path\": [{\"name\": \"Deprecated||Sequence signature identifier\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1065\"}], \"name\": \"Sequence signature identifier\", \"uri\": \"http://edamontology.org/data_1065\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1067\": {\"definition\": \"Identifier of a phylogenetic distance matrix.\", \"path\": [{\"name\": \"Deprecated||Phylogenetic distance matrix identifier\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1067\"}], \"name\": \"Phylogenetic distance matrix identifier\", \"uri\": \"http://edamontology.org/data_1067\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1094\": {\"definition\": \"A label (text token) describing a type of molecular sequence.\", \"path\": [{\"name\": \"Deprecated||Sequence type\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1094\"}], \"name\": \"Sequence type\", \"uri\": \"http://edamontology.org/data_1094\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1099\": {\"definition\": \"Accession number of a UniProt (protein sequence) database entry. May contain version or isoform number.\", \"path\": [{\"name\": \"Deprecated||UniProt accession (extended)\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1099\"}], \"name\": \"UniProt accession (extended)\", \"uri\": \"http://edamontology.org/data_1099\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1101\": {\"definition\": \"Identifier of a TREMBL sequence database entry.\", \"path\": [{\"name\": \"Deprecated||TREMBL accession\", \"key\": \"http://www.w3.org/2002/07/o