rg/data_1122\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1125\": {\"definition\": \"A label (text token) describing the type of a comparison matrix.\", \"path\": [{\"name\": \"Deprecated||Comparison matrix type\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1125\"}], \"name\": \"Comparison matrix type\", \"uri\": \"http://edamontology.org/data_1125\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1152\": {\"definition\": \"Identifier of an entry from the HIVDB database.\", \"path\": [{\"name\": \"Deprecated||HIVDB identifier\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1152\"}], \"name\": \"HIVDB identifier\", \"uri\": \"http://edamontology.org/data_1152\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1156\": {\"definition\": \"Identifier of an entry from the aMAZE database.\", \"path\": [{\"name\": \"Deprecated||Pathway ID (aMAZE)\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1156\"}], \"name\": \"Pathway ID (aMAZE)\", \"uri\": \"http://edamontology.org/data_1156\", \"exact_synonyms\": [\"aMAZE ID\"], \"narrow_synonyms\": [], \"children\": []}, \"data_1236\": {\"definition\": \"A file of intermediate results from a PSIBLAST search that is used for priming the search in the next PSIBLAST iteration.\", \"path\": [{\"name\": \"Deprecated||Psiblast checkpoint file\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1236\"}], \"name\": \"Psiblast checkpoint file\", \"uri\": \"http://edamontology.org/data_1236\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1237\": {\"definition\": \"Sequences generated by HMMER package in FASTA-style format.\", \"path\": [{\"name\": \"Deprecated||HMMER synthetic sequences set\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1237\"}], \"name\": \"HMMER synthetic sequences set\", \"uri\": \"http://edamontology.org/data_1237\", \