"], \"narrow_synonyms\": [], \"children\": []}, \"data_1906\": {\"definition\": \"A stretch of DNA that is closely linked to the genes underlying a quantitative trait (a phenotype that varies in degree and depends upon the interactions between multiple genes and their environment).\", \"path\": [{\"name\": \"Deprecated||Quantitative trait locus\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1906\"}], \"name\": \"Quantitative trait locus\", \"uri\": \"http://edamontology.org/data_1906\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_2009\": {\"definition\": \"A name for a genetic locus conforming to a scheme that names loci (such as predicted genes) depending on their position in a molecular sequence, for example a completely sequenced genome or chromosome.\", \"path\": [{\"name\": \"Deprecated||Ordered locus name\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_2009\"}], \"name\": \"Ordered locus name\", \"uri\": \"http://edamontology.org/data_2009\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_2018\": {\"definition\": \"A human-readable collection of information which (typically) is generated or collated by hand and which describes a biological entity, phenomena or associated primary (e.g. sequence or structural) data, as distinct from the primary data itself and computer-generated reports derived from it.\", \"path\": [{\"name\": \"Deprecated||Annotation\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_2018\"}], \"name\": \"Annotation\", \"uri\": \"http://edamontology.org/data_2018\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_2022\": {\"definition\": \"Data used by the Vienna RNA analysis package.\", \"path\": [{\"name\": \"Deprecated||Vienna RNA structural data\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_2022\"}], \"name\": \"Vienna RNA structural data\", \"uri\": \"http://edamontology.org/data_202