\": \"http://edamontology.org/operation_3189\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3190\": {\"definition\": \"Trim sequences (typically from an automated DNA sequencer) to remove sequence-specific end regions, typically contamination from vector sequences.\", \"path\": [{\"name\": \"Deprecated||Trim vector\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3190\"}], \"name\": \"Trim vector\", \"uri\": \"http://edamontology.org/operation_3190\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3191\": {\"definition\": \"Trim sequences (typically from an automated DNA sequencer) to remove the sequence ends that extend beyond an assembled reference sequence.\", \"path\": [{\"name\": \"Deprecated||Trim to reference\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3191\"}], \"name\": \"Trim to reference\", \"uri\": \"http://edamontology.org/operation_3191\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3201\": {\"definition\": \"Identify single nucleotide change in base positions in sequencing data that differ from a reference genome and which might, especially by reference to population frequency or functional data, indicate a polymorphism.\", \"path\": [{\"name\": \"Deprecated||SNP calling\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3201\"}], \"name\": \"SNP calling\", \"uri\": \"http://edamontology.org/operation_3201\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3202\": {\"definition\": \"Detect mutations in multiple DNA sequences, for example, from the alignment and comparison of the fluorescent traces produced by DNA sequencing hardware.\", \"path\": [{\"name\": \"Deprecated||Polymorphism detection\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3202\"}], \"name\": \"Polymorphism detection\", \"uri\": \"http://edamontology.org/ope