2\"}], \"name\": \"Database entry identifier\", \"uri\": \"http://edamontology.org/data_1062\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1065\": {\"definition\": \"Identifier of a sequence signature (motif or profile) for example from a database of sequence patterns.\", \"path\": [{\"name\": \"Deprecated||Sequence signature identifier\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1065\"}], \"name\": \"Sequence signature identifier\", \"uri\": \"http://edamontology.org/data_1065\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1067\": {\"definition\": \"Identifier of a phylogenetic distance matrix.\", \"path\": [{\"name\": \"Deprecated||Phylogenetic distance matrix identifier\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1067\"}], \"name\": \"Phylogenetic distance matrix identifier\", \"uri\": \"http://edamontology.org/data_1067\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1094\": {\"definition\": \"A label (text token) describing a type of molecular sequence.\", \"path\": [{\"name\": \"Deprecated||Sequence type\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1094\"}], \"name\": \"Sequence type\", \"uri\": \"http://edamontology.org/data_1094\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1099\": {\"definition\": \"Accession number of a UniProt (protein sequence) database entry. May contain version or isoform number.\", \"path\": [{\"name\": \"Deprecated||UniProt accession (extended)\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1099\"}], \"name\": \"UniProt accession (extended)\", \"uri\": \"http://edamontology.org/data_1099\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1101\": {\"definition\": \"Identifier of a TREMBL sequence database entry.\", \"path\": [{\"name\": \"Deprecated||TREMBL accession\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1101\"}], \"name\": \"TREMBL accession\", \"uri\": \"http://edamontology.org/data_1101\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1110\": {\"definition\": \"The EMBOSS type of a molecular sequence.\", \"path\": [{\"name\": \"Deprecated||EMBOSS sequence type\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1110\"}], \"name\": \"EMBOSS sequence type\", \"uri\": \"http://edamontology.org/data_1110\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1111\": {\"definition\": \"List of EMBOSS Uniform Sequence Addresses (EMBOSS listfile).\", \"path\": [{\"name\": \"Deprecated||EMBOSS listfile\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1111\"}], \"name\": \"EMBOSS listfile\", \"uri\": \"http://edamontology.org/data_1111\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1120\": {\"definition\": \"A label (text token) describing the type of a sequence alignment.\", \"path\": [{\"name\": \"Deprecated||Sequence alignment type\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1120\"}], \"name\": \"Sequence alignment type\", \"uri\": \"http://edamontology.org/data_1120\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1121\": {\"definition\": \"The type of a BLAST sequence alignment.\", \"path\": [{\"name\": \"Deprecated||BLAST sequence alignment type\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1121\"}], \"name\": \"BLAST sequence alignment type\", \"uri\": \"http://edamontology.org/data_1121\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1122\": {\"definition\": \"A label (text token) describing the type of a phylogenetic tree.\", \"path\": [{\"name\": \"Deprecated||Phylogenetic tree type\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1122\"}], \"name\": \"Phylogenetic tree type\", \"uri\": \"http://edamontology.org/data_1122\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1125\": {\"definition\": \"A label (text token) describing the type of a comparison matrix.\", \"path\": [{\"name\": \"Deprecated||Comparison matrix type\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1125\"}], \"name\": \"Comparison matrix type\", \"uri\": \"http://edamontology.org/data_1125\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1152\": {\"definition\": \"Identifier of an entry from the HIVDB database.\", \"path\": [{\"name\": \"Deprecated||HIVDB identifier\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1152\"}], \"name\": \"HIVDB identifier\", \"uri\": \"http://edamontology.org/data_1152\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1156\": {\"definition\": \"Identifier of an entry from the aMAZE database.\", \"path\": [{\"name\": \"Deprecated||Pathway ID (aMAZE)\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1156\"}], \"name\": \"Pathway ID (aMAZE)\", \"uri\": \"http://edamontology.org/data_1156\", \"exact_synonyms\": [\"aMAZE ID\"], \"narrow_synonyms\": [], \"children\": []}, \"data_1236\": {\"definition\": \"A file of intermediate results from a PSIBLAST search that is used for priming the search in the next PSIBLAST iteration.\", \"path\": [{\"name\": \"Deprecated||Psiblast checkpoint file\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1236\"}], \"name\": \"Psiblast checkpoint file\", \"uri\": \"http://edamontology.org/data_1236\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"data_1237\": {\"definition\": \"Sequences generated by HMMER package in FASTA-style format.\", \"path\": [{\"name\": \"Deprecated||HMMER synthetic sequences set\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||data_1237\"}], \"name\": \"HMMER synthetic sequences set\", \"uri\": \"http://edamontology.org/data_1237