h\": [{\"name\": \"Deprecated||Prediction and recognition (protein)\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3023\"}], \"name\": \"Prediction and recognition (protein)\", \"uri\": \"http://edamontology.org/operation_3023\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3024\": {\"definition\": \"Predict, recognise, detect or identify some properties of nucleic acids.\", \"path\": [{\"name\": \"Deprecated||Prediction and recognition (nucleic acid)\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3024\"}], \"name\": \"Prediction and recognition (nucleic acid)\", \"uri\": \"http://edamontology.org/operation_3024\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3083\": {\"definition\": \"Render (visualise) a biological pathway or network.\", \"path\": [{\"name\": \"Deprecated||Pathway or network visualisation\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3083\"}], \"name\": \"Pathway or network visualisation\", \"uri\": \"http://edamontology.org/operation_3083\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3084\": {\"definition\": \"Predict general (non-positional) functional properties of a protein from analysing its sequence.\", \"path\": [{\"name\": \"Deprecated||Protein function prediction (from sequence)\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3084\"}], \"name\": \"Protein function prediction (from sequence)\", \"uri\": \"http://edamontology.org/operation_3084\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3087\": {\"definition\": \"Predict, recognise and identify functional or other key sites within protein sequences, typically by scanning for known motifs, patterns and regular expressions.\", \"path\": [{\"name\": \"Deprecated||Protein sequence feature detection\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclas