\"uri\": \"http://edamontology.org/operation_3189\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3190\": {\"definition\": \"Trim sequences (typically from an automated DNA sequencer) to remove sequence-specific end regions, typically contamination from vector sequences.\", \"path\": [{\"name\": \"Deprecated||Trim vector\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3190\"}], \"name\": \"Trim vector\", \"uri\": \"http://edamontology.org/operation_3190\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3191\": {\"definition\": \"Trim sequences (typically from an automated DNA sequencer) to remove the sequence ends that extend beyond an assembled reference sequence.\", \"path\": [{\"name\": \"Deprecated||Trim to reference\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3191\"}], \"name\": \"Trim to reference\", \"uri\": \"http://edamontology.org/operation_3191\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3201\": {\"definition\": \"Identify single nucleotide change in base positions in sequencing data that differ from a reference genome and which might, especially by reference to population frequency or functional data, indicate a polymorphism.\", \"path\": [{\"name\": \"Deprecated||SNP calling\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3201\"}], \"name\": \"SNP calling\", \"uri\": \"http://edamontology.org/operation_3201\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3202\": {\"definition\": \"Detect mutations in multiple DNA sequences, for example, from the alignment and comparison of the fluorescent traces produced by DNA sequencing hardware.\", \"path\": [{\"name\": \"Deprecated||Polymorphism detection\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3202\"}], \"name\": \"Polymorphism detection\", \"uri\": \"http://edamontology.org/operation_3202\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3205\": {\"definition\": \"Determine cytosine methylation status of specific positions in a nucleic acid sequences.\", \"path\": [{\"name\": \"Deprecated||Methylation calling\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3205\"}], \"name\": \"Methylation calling\", \"uri\": \"http://edamontology.org/operation_3205\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3212\": {\"definition\": \"Generate an index of a genome sequence using the Burrows-Wheeler algorithm.\", \"path\": [{\"name\": \"Deprecated||Genome indexing (Burrows-Wheeler)\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3212\"}], \"name\": \"Genome indexing (Burrows-Wheeler)\", \"uri\": \"http://edamontology.org/operation_3212\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3213\": {\"definition\": \"Generate an index of a genome sequence using a suffix arrays algorithm.\", \"path\": [{\"name\": \"Deprecated||Genome indexing (suffix arrays)\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3213\"}], \"name\": \"Genome indexing (suffix arrays)\", \"uri\": \"http://edamontology.org/operation_3213\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3224\": {\"definition\": \"Analyse gene expression patterns (typically from DNA microarray datasets) to identify sets of genes that are associated with a specific trait, condition, clinical outcome etc.\", \"path\": [{\"name\": \"Deprecated||Gene set testing\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3224\"}], \"name\": \"Gene set testing\", \"uri\": \"http://edamontology.org/operation_3224\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3259\": {\"definition\": \"Infer a transcriptome sequence without the aid of a reference genome, i.e. by comparing short sequences (reads) to each other.\", \"path\": [{\"name\": \"Deprecated||Transcriptome assembly (de novo)\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3259\"}], \"name\": \"Transcriptome assembly (de novo)\", \"uri\": \"http://edamontology.org/operation_3259\", \"exact_synonyms\": [\"de novo transcriptome assembly\"], \"narrow_synonyms\": [], \"children\": []}, \"operation_3260\": {\"definition\": \"Infer a transcriptome sequence by mapping short reads to a reference genome.\", \"path\": [{\"name\": \"Deprecated||Transcriptome assembly (mapping)\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3260\"}], \"name\": \"Transcriptome assembly (mapping)\", \"uri\": \"http://edamontology.org/operation_3260\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3289\": {\"definition\": \"Search for and retrieve a data identifier of some kind, e.g. a database entry accession.\", \"path\": [{\"name\": \"Deprecated||ID retrieval\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3289\"}], \"name\": \"ID retrieval\", \"uri\": \"http://edamontology.org/operation_3289\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3353\": {\"definition\": \"Compare two or more ontologies, e.g. identify differences.\", \"path\": [{\"name\": \"Deprecated||Ontology comparison\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3353\"}], \"name\": \"Ontology comparison\", \"uri\": \"http://edamontology.org/operation_3353\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"operation_3430\": {\"definition\": \"Predict, recognise and identify functional or other key sites within nucleic acid sequences, typically by scanning for known motifs, patterns and regular expressions.\", \"path\": [{\"name\": \"Deprecated||Nucleic acid sequence feature detection\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||ope