ms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_1811\": {\"definition\": \"Specific bacteria or archaea, e.g. information on a specific prokaryote genome including molecular sequences, genes and annotation.\", \"path\": [{\"name\": \"Deprecated||Prokaryotes and Archaea\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_1811\"}], \"name\": \"Prokaryotes and Archaea\", \"uri\": \"http://edamontology.org/topic_1811\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_2225\": {\"definition\": \"Protein data resources.\", \"path\": [{\"name\": \"Deprecated||Protein databases\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_2225\"}], \"name\": \"Protein databases\", \"uri\": \"http://edamontology.org/topic_2225\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_2226\": {\"definition\": \"Experimental methods for biomolecular structure determination, such as X-ray crystallography, nuclear magnetic resonance (NMR), circular dichroism (CD) spectroscopy, microscopy etc., including the assignment or modelling of molecular structure from such data.\", \"path\": [{\"name\": \"Deprecated||Structure determination\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_2226\"}], \"name\": \"Structure determination\", \"uri\": \"http://edamontology.org/topic_2226\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_2230\": {\"definition\": \"Topic focused on identifying, grouping, or naming things in a structured way according to some schema based on observable relationships.\", \"path\": [{\"name\": \"Deprecated||Classification\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_2230\"}], \"name\": \"Classification\", \"uri\": \"http://edamontology.org/topic_2230\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_2232\": {\"definition\": \"Lipoproteins (protein-lipid assemblies).\", \"path\": [{\"name\"