ms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_2953\": {\"definition\": \"Topic for the design of nucleic acid sequences with specific conformations.\", \"path\": [{\"name\": \"Deprecated||Nucleic acid design\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_2953\"}], \"name\": \"Nucleic acid design\", \"uri\": \"http://edamontology.org/topic_2953\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3032\": {\"definition\": \"The design of primers for PCR and DNA amplification or the design of molecular probes.\", \"path\": [{\"name\": \"Deprecated||Primer or probe design\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3032\"}], \"name\": \"Primer or probe design\", \"uri\": \"http://edamontology.org/topic_3032\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3038\": {\"definition\": \"Molecular secondary or tertiary (3D) structural data resources, typically of proteins and nucleic acids.\", \"path\": [{\"name\": \"Deprecated||Structure databases\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3038\"}], \"name\": \"Structure databases\", \"uri\": \"http://edamontology.org/topic_3038\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3039\": {\"definition\": \"Nucleic acid (secondary or tertiary) structure, such as whole structures, structural features and associated annotation.\", \"path\": [{\"name\": \"Deprecated||Nucleic acid structure\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3039\"}], \"name\": \"Nucleic acid structure\", \"uri\": \"http://edamontology.org/topic_3039\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3041\": {\"definition\": \"Molecular sequence data resources, including sequence sites, alignments, motifs and profiles.\", \"path\": [{\"name\": \"Deprecated||Sequence databases\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3041\"}], \"name\": \"Sequence databases\", \"uri\": \"http://edamontology.org/topic_3041\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3042\": {\"definition\": \"Nucleotide sequences and associated concepts such as sequence sites, alignments, motifs and profiles.\", \"path\": [{\"name\": \"Deprecated||Nucleic acid sequences\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3042\"}], \"name\": \"Nucleic acid sequences\", \"uri\": \"http://edamontology.org/topic_3042\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3043\": {\"definition\": \"Protein sequences and associated concepts such as sequence sites, alignments, motifs and profiles.\", \"path\": [{\"name\": \"Deprecated||Protein sequences\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3043\"}], \"name\": \"Protein sequences\", \"uri\": \"http://edamontology.org/topic_3043\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3044\": {\"definition\": \"Protein interaction networks\", \"path\": [{\"name\": \"Deprecated||Protein interaction networks\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3044\"}], \"name\": \"Protein interaction networks\", \"uri\": \"http://edamontology.org/topic_3044\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3048\": {\"definition\": \"Mammals, e.g. information on a specific mammal genome including molecular sequences, genes and annotation.\", \"path\": [{\"name\": \"Deprecated||Mammals\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3048\"}], \"name\": \"Mammals\", \"uri\": \"http://edamontology.org/topic_3048\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3052\": {\"definition\": \"The comparison, grouping together and classification of macromolecules on the basis of sequence similarity.\", \"path\": [{\"name\": \"Deprecated||Sequence clusters and classification\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3052\"}], \"name\": \"Sequence clusters and classification\", \"uri\": \"http://edamontology.org/topic_3052\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3060\": {\"definition\": \"Regulatory RNA sequences including microRNA (miRNA) and small interfering RNA (siRNA).\", \"path\": [{\"name\": \"Deprecated||Regulatory RNA\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3060\"}], \"name\": \"Regulatory RNA\", \"uri\": \"http://edamontology.org/topic_3060\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3061\": {\"definition\": \"The documentation of resources such as tools, services and databases and how to get help.\", \"path\": [{\"name\": \"Deprecated||Documentation and help\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3061\"}], \"name\": \"Documentation and help\", \"uri\": \"http://edamontology.org/topic_3061\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3062\": {\"definition\": \"The structural and functional organisation of genes and other genetic elements.\", \"path\": [{\"name\": \"Deprecated||Genetic organisation\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3062\"}], \"name\": \"Genetic organisation\", \"uri\": \"http://edamontology.org/topic_3062\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3072\": {\"definition\": \"The detection of the positional features, such as functional and other key sites, in molecular sequences.\", \"path\": [{\"name\": \"Deprecated||Sequence feature detection\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3072\"}], \"name\": \"Sequence feature detection\", \"uri\": \"http://edamontology.org/topic_3072\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3073\": {\"definition\": \"The detection of positional features such as functional sites in nucleotide sequences.\", \"path\": [{\"name\": \"Deprecated||Nucleic acid feature detection\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3073\"}], \"name\": \"Nucleic acid feature detection\", \"uri\": \"http://edamontology.org/topic_3073\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3074\": {\"definition\": \"The detection, identification and analysis of positional protein sequence features, such as functional sites.\", \"path\": [{\"name\": \"Deprecated||Protein feature detection\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3074\"}], \"name\": \"Protein feature detection\", \"uri\": \"http://edamontology.org/topic_3074\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3075\": {\"definition\": \"Topic for modelling biological systems in mathematical terms.\", \"path\": [{\"name\": \"Deprecated||Biological system modelling\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3075\"}], \"name\": \"Biological system modelling\", \"uri\": \"http://edamontology.org/topic_3075\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3078\": {\"definition\": \"Specific genes and/or their encoded proteins or a family or other grouping of related genes and proteins.\", \"path\": [{\"name\": \"Deprecated||Genes and proteins resources\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3078\"}], \"name\": \"Genes and proteins resources\", \"uri\": \"http://edamontology.org/topic_3078\", \"exact_synonyms\": [], \"narrow_synonyms\": [], \"children\": []}, \"topic_3118\": {\"definition\": \"Topological domains such as cytoplasmic regions in a protein.\", \"path\": [{\"name\": \"Deprecated||Protein topological domains\", \"key\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_3118\"}], \"name\": \"Protein topological domains\", \"uri\": \"http://edamontology.org/topic_3118\", \"exact_synonyms\": [],