ng\", \"ns\": [], \"u\": \"operation_3201\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||SNP calling\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3201\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Detect mutations in multiple DNA sequences, for example, from the alignment and comparison of the fluorescent traces produced by DNA sequencing hardware.\", \"n\": \"Polymorphism detection\", \"ns\": [], \"u\": \"operation_3202\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Polymorphism detection\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3202\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Determine cytosine methylation status of specific positions in a nucleic acid sequences.\", \"n\": \"Methylation calling\", \"ns\": [], \"u\": \"operation_3205\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Methylation calling\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3205\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Generate an index of a genome sequence using the Burrows-Wheeler algorithm.\", \"n\": \"Genome indexing (Burrows-Wheeler)\", \"ns\": [], \"u\": \"operation_3212\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Genome indexing (Burrows-Wheeler)\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3212\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Generate an index of a genome sequence using a suffix arrays algorithm.\", \"n\": \"Genome indexing (suffix arrays)\", \"ns\": [], \"u\": \"operation_3213\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Genome indexing (suffix arrays)\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3213\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Analyse gene expression patterns (typically from DNA microarray datasets) to identify sets of genes that are associated with a specific trait, condition, clinical outcome etc.\", \"n\": \"Gene set testing\", \"ns\": [], \"u\": \"operation_3224\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Gene set testing\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3224\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Infer a transcriptome sequence without the aid of a reference genome, i.e. by comparing short sequences (reads) to each other.\", \"n\": \"Transcriptome assembly (de novo)\", \"ns\": [], \"u\": \"operation_3259\", \"es\": [\"de novo transcriptome assembly\"], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Transcriptome assembly (de novo)\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3259\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Infer a transcriptome sequence by mapping short reads to a reference genome.\", \"n\": \"Transcriptome assembly (mapping)\", \"ns\": [], \"u\": \"operation_3260\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Transcriptome assembly (mapping)\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3260\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Search for and retrieve a data identifier of some kind, e.g. a database entry accession.\", \"n\": \"ID retrieval\", \"ns\": [], \"u\": \"operation_3289\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||ID retrieval\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3289\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Compare two or more ontologies, e.g. identify differences.\", \"n\": \"Ontology comparison\", \"ns\": [], \"u\": \"operation_3353\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Ontology comparison\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3353\"}], \"hi\": null, \"ht\": null, \"ho\": null}, {\"d\": \"Predict, recognise and identify functional or other key sites within nucleic acid sequences, typically by scanning for known motifs, patterns and regular expressions.\", \"n\": \"Nucleic acid se