"u\": \"operation_3191\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Trim to reference\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3191\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3201\": {\"d\": \"Identify single nucleotide change in base positions in sequencing data that differ from a reference genome and which might, especially by reference to population frequency or functional data, indicate a polymorphism.\", \"n\": \"SNP calling\", \"ns\": [], \"u\": \"operation_3201\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||SNP calling\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3201\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3202\": {\"d\": \"Detect mutations in multiple DNA sequences, for example, from the alignment and comparison of the fluorescent traces produced by DNA sequencing hardware.\", \"n\": \"Polymorphism detection\", \"ns\": [], \"u\": \"operation_3202\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Polymorphism detection\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3202\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3205\": {\"d\": \"Determine cytosine methylation status of specific positions in a nucleic acid sequences.\", \"n\": \"Methylation calling\", \"ns\": [], \"u\": \"operation_3205\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Methylation calling\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3205\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3212\": {\"d\": \"Generate an index of a genome sequence using the Burrows-Wheeler algorithm.\", \"n\": \"Genome indexing (Burrows-Wheeler)\", \"ns\": [], \"u\": \"operation_3212\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Genome indexing (Burrows-Wheeler)\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3212\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3213\": {\"d\": \"Generate an index of a genome sequence using a suffix arrays algorithm.\", \"n\": \"Genome indexing (suffix arrays)\", \"ns\": [], \"u\": \"operation_3213\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Genome indexing (suffix arrays)\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3213\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3224\": {\"d\": \"Analyse gene expression patterns (typically from DNA microarray datasets) to identify sets of genes that are associated with a specific trait, condition, clinical outcome etc.\", \"n\": \"Gene set testing\", \"ns\": [], \"u\": \"operation_3224\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Gene set testing\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3224\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3259\": {\"d\": \"Infer a transcriptome sequence without the aid of a reference genome, i.e. by comparing short sequences (reads) to each other.\", \"n\": \"Transcriptome assembly (de novo)\", \"ns\": [], \"u\": \"operation_3259\", \"es\": [\"de novo transcriptome assembly\"], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Transcriptome assembly (de novo)\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3259\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3260\": {\"d\": \"Infer a transcriptome sequence by mapping short reads to a reference genome.\", \"n\": \"Transcriptome assembly (mapping)\", \"ns\": [], \"u\": \"operation_3260\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Transcriptome assembly (mapping)\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3260\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3289\": {\"d\": \"Search for and retrieve a data identifier of some kind, e.g. a database entry accession.\", \"n\": \"ID retrieval\", \"ns\": [], \"u\": \"operation_3289\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||ID retrieval\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3289\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3353\": {\"d\": \"Compare two or more ontologies, e.g. identify differences.\", \"n\": \"Ontology comparison\", \"ns\": [], \"u\": \"operation_3353\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Ontology comparison\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3353\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3430\": {\"d\": \"Predict, recognise and identify functional or other key sites within nucleic acid sequences, typically by scanning for known motifs, patterns and regular expressions.\", \"n\": \"Nucleic acid sequence feature detection\", \"ns\": [], \"u\": \"operation_3430\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Nucleic acid sequence feature detection\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3430\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3433\": {\"d\": \"Construct some entity (typically a molecule sequence) from component pieces.\", \"n\": \"Assembly\", \"ns\": [], \"u\": \"operation_3433\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Assembly\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3433\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3439\": {\"d\": \"Predict a molecular pathway or network.\", \"n\": \"Pathway or network prediction\", \"ns\": [], \"u\": \"operation_3439\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Pathway or network prediction\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3439\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3440\": {\"d\": \"The process of assembling many short DNA sequences together such thay they represent the original chromosomes from which the DNA originated.\", \"n\": \"Genome assembly\", \"ns\": [], \"u\": \"operation_3440\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Genome assembly\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3440\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3441\": {\"d\": \"Generate a graph, or other visual representation, of data, showing the relationship between two or more variables.\", \"n\": \"Plotting\", \"ns\": [], \"u\": \"operation_3441\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Plotting\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3441\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3470\": {\"d\": \"Predict RNA secondary structure by analysis, e.g. probabilistic analysis, of the shape of RNA folds.\", \"n\": \"RNA secondary structure prediction (shape-based)\", \"ns\": [], \"u\": \"operation_3470\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||RNA secondary structure prediction (shape-based)\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3470\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3471\": {\"d\": \"Prediction of nucleic-acid folding using sequence alignments as a source of data.\", \"n\": \"Nucleic acid folding prediction (alignment-based)\", \"ns\": [], \"u\": \"operation_3471\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Nucleic acid folding prediction (alignment-based)\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3471\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3545\": {\"d\": \"Model some biological system using mathematical techniques including  dynamical systems, statistical models, differential equations, and game theoretic models.\", \"n\": \"Mathematical modelling\", \"ns\": [], \"u\": \"operation_3545\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Mathematical modelling\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3545\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3562\": {\"d\": \"Simulate the bevaviour of a biological pathway or network.\", \"n\": \"Network simulation\", \"ns\": [], \"u\": \"operation_3562\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Network simulation\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3562\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3648\": {\"d\": \"Statistical estimation of false discovery rate from score distribution for peptide-spectrum-matches, following a peptide database search.\", \"n\": \"Validation of peptide-spectrum matches\", \"ns\": [], \"u\": \"operation_3648\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Validation of peptide-spectrum matches\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3648\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"operation_3742\": {\"d\": \"The analysis, using any of diverse techniques, to identify genes that are differentially expressed under a given experimental setup.\", \"n\": \"Differential gene expression analysis\", \"ns\": [], \"u\": \"operation_3742\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Differential gene expression analysis\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||operation_3742\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0079\": {\"d\": \"The structures of reactants or products of metabolism, for example small molecules such as including vitamins, polyols, nucleotides and amino acids.\", \"n\": \"Metabolites\", \"ns\": [], \"u\": \"topic_0079\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Metabolites\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0079\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0083\": {\"d\": \"The alignment (equivalence between sites) of molecular sequences, structures or profiles (representing a sequence or structure alignment).\", \"n\": \"Alignment\", \"ns\": [], \"u\": \"topic_0083\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Alignment\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0083\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0090\": {\"d\": \"The search and query of data sources (typically databases or ontologies) in order to retrieve entries or other information.\", \"n\": \"Information retrieval\", \"ns\": [], \"u\": \"topic_0090\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Information retrieval\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0090\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0094\": {\"d\": \"The study of the thermodynamic properties of a nucleic acid.\", \"n\": \"Nucleic acid thermodynamics\", \"ns\": [], \"u\": \"topic_0094\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Nucleic acid thermodynamics\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0094\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0100\": {\"d\": \"Topic for the study of restriction enzymes, their cleavage sites and the restriction of nucleic acids.\", \"n\": \"Nucleic acid restriction\", \"ns\": [], \"u\": \"topic_0100\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Nucleic acid restriction\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0100\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0107\": {\"d\": \"The study of codon usage in nucleotide sequence(s), genetic codes and so on.\", \"n\": \"Genetic codes and codon usage\", \"ns\": [], \"u\": \"topic_0107\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Genetic codes and codon usage\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0107\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0109\": {\"d\": \"Methods that aims to identify, predict, model or analyse genes or gene structure in DNA sequences.\", \"n\": \"Gene finding\", \"ns\": [], \"u\": \"topic_0109\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Gene finding\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0109\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0110\": {\"d\": \"The transcription of DNA into mRNA.\", \"n\": \"Transcription\", \"ns\": [], \"u\": \"topic_0110\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Transcription\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0110\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0111\": {\"d\": \"Promoters in DNA sequences (region of DNA that facilitates the transcription of a particular gene by binding RNA polymerase and transcription factor proteins).\", \"n\": \"Promoters\", \"ns\": [], \"u\": \"topic_0111\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Promoters\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0111\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0112\": {\"d\": \"The folding (in 3D space) of nucleic acid molecules.\", \"n\": \"Nucleic acid folding\", \"ns\": [], \"u\": \"topic_0112\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Nucleic acid folding\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0112\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0133\": {\"d\": \"Two-dimensional gel electrophoresis image and related data.\", \"n\": \"Two-dimensional gel electrophoresis\", \"ns\": [], \"u\": \"topic_0133\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Two-dimensional gel electrophoresis\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0133\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0134\": {\"d\": \"An analytical chemistry technique that measures the mass-to-charge ratio and abundance of ions in the gas phase.\", \"n\": \"Mass spectrometry\", \"ns\": [], \"u\": \"topic_0134\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Mass spectrometry\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0134\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0135\": {\"d\": \"Protein microarray data.\", \"n\": \"Protein microarrays\", \"ns\": [], \"u\": \"topic_0135\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Protein microarrays\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0135\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0137\": {\"d\": \"The study of the hydrophobic, hydrophilic and charge properties of a protein.\", \"n\": \"Protein hydropathy\", \"ns\": [], \"u\": \"topic_0137\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Protein hydropathy\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0137\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0141\": {\"d\": \"Enzyme or chemical cleavage sites and proteolytic or mass calculations on a protein sequence.\", \"n\": \"Protein cleavage sites and proteolysis\", \"ns\": [], \"u\": \"topic_0141\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Protein cleavage sites and proteolysis\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0141\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0143\": {\"d\": \"The comparison of two or more protein structures.\", \"n\": \"Protein structure comparison\", \"ns\": [], \"u\": \"topic_0143\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Protein structure comparison\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0143\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0144\": {\"d\": \"The processing and analysis of inter-atomic or inter-residue interactions in protein (3D) structures.\", \"n\": \"Protein residue interactions\", \"ns\": [], \"u\": \"topic_0144\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Protein residue interactions\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0144\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0147\": {\"d\": \"Protein-protein interactions, individual interactions and networks, protein complexes, protein functional coupling etc.\", \"n\": \"Protein-protein interactions\", \"ns\": [], \"u\": \"topic_0147\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Protein-protein interactions\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0147\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0148\": {\"d\": \"Protein-ligand (small molecule) interactions.\", \"n\": \"Protein-ligand interactions\", \"ns\": [], \"u\": \"topic_0148\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Protein-ligand interactions\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0148\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0149\": {\"d\": \"Protein-DNA/RNA interactions.\", \"n\": \"Protein-nucleic acid interactions\", \"ns\": [], \"u\": \"topic_0149\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Protein-nucleic acid interactions\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0149\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0150\": {\"d\": \"The design of proteins with specific properties, typically by designing changes (via site-directed mutagenesis) to an existing protein.\", \"n\": \"Protein design\", \"ns\": [], \"u\": \"topic_0150\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Protein design\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0150\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0151\": {\"d\": \"G-protein coupled receptors (GPCRs).\", \"n\": \"G protein-coupled receptors (GPCR)\", \"ns\": [], \"u\": \"topic_0151\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||G protein-coupled receptors (GPCR)\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0151\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0156\": {\"d\": \"Edit, convert or otherwise change a molecular sequence, either randomly or specifically.\", \"n\": \"Sequence editing\", \"ns\": [], \"u\": \"topic_0156\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Sequence editing\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0156\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0158\": {\"d\": \"Conserved patterns (motifs) in molecular sequences, that (typically) describe functional or other key sites.\", \"n\": \"Sequence motifs\", \"ns\": [], \"u\": \"topic_0158\", \"es\": [\"Motifs\"], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Sequence motifs\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0158\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0159\": {\"d\": \"The comparison of two or more molecular sequences, for example sequence alignment and clustering.\", \"n\": \"Sequence comparison\", \"ns\": [], \"u\": \"topic_0159\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Sequence comparison\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0159\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0163\": {\"d\": \"Search and retrieve molecular sequences that are similar to a sequence-based query (typically a simple sequence).\", \"n\": \"Sequence database search\", \"ns\": [], \"u\": \"topic_0163\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Sequence database search\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0163\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0164\": {\"d\": \"The comparison and grouping together of molecular sequences on the basis of their similarities.\", \"n\": \"Sequence clustering\", \"ns\": [], \"u\": \"topic_0164\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Sequence clustering\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0164\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0167\": {\"d\": \"The processing, analysis or use of some type of structural (3D) profile or template; a computational entity (typically a numerical matrix) that is derived from and represents a structure or structure alignment.\", \"n\": \"Structural (3D) profiles\", \"ns\": [], \"u\": \"topic_0167\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Structural (3D) profiles\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0167\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0172\": {\"d\": \"The prediction, modelling, recognition or design of protein secondary or tertiary structure or other structural features.\", \"n\": \"Protein structure prediction\", \"ns\": [], \"u\": \"topic_0172\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecate