\": \"Threading\", \"ns\": [], \"u\": \"topic_0184\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Threading\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0184\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0188\": {\"d\": \"Sequence profiles; typically a positional, numerical matrix representing a sequence alignment.\", \"n\": \"Sequence profiles and HMMs\", \"ns\": [], \"u\": \"topic_0188\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Sequence profiles and HMMs\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0188\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0191\": {\"d\": \"The reconstruction of a phylogeny (evolutionary relatedness amongst organisms), for example, by building a phylogenetic tree.\", \"n\": \"Phylogeny reconstruction\", \"ns\": [], \"u\": \"topic_0191\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Phylogeny reconstruction\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0191\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0195\": {\"d\": \"Simulated polymerase chain reaction (PCR).\", \"n\": \"Virtual PCR\", \"ns\": [], \"u\": \"topic_0195\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Virtual PCR\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0195\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0200\": {\"d\": \"Microarrays, for example, to process microarray data or design probes and experiments.\", \"n\": \"Microarrays\", \"ns\": [], \"u\": \"topic_0200\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Microarrays\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_0200\"}], \"hi\": [], \"ho\": [], \"ht\": []}, \"topic_0210\": {\"d\": \"Information on a specific fish genome including molecular sequences, genes and annotation.\", \"n\": \"Fish\", \"ns\": [], \"u\": \"topic_0210\", \"es\": [], \"ch\": [], \"p\": [{\"n\": \"Deprecated||Fish\", \"k\": \"http://www.w3.org/2002/07/owl#deprecatedclass||topic_021