INSERT INTO `elixir_resource` VALUES (1,'mbinfo','biotools:mbinfo','MBInfo','none','https://github.com/MICommunity/psicquic','Search MBInfo database for interactions using a protein id.',NULL,NULL,NULL,NULL,1,1,0,0,0,NULL,NULL,NULL,NULL,NULL,'2025-08-27 14:15:22.235217','2025-08-27 14:15:22.240110',NULL,NULL,1,NULL,2),(2,'prolific','biotools:prolific','PROLIFIC','none','http://www.pharmaceutical-bioinformatics.de/prolific/184/','One-step solution to investigate available information on given protein names, sequences, similar proteins or sequences on the gene level.',NULL,NULL,NULL,NULL,1,1,0,0,0,NULL,NULL,NULL,NULL,NULL,'2025-08-27 14:16:04.683120','2025-08-27 14:16:04.688315',NULL,NULL,2,NULL,2),(3,'genes_by_organism','biotools:genes_by_organism','Genes by Organism','none','http://mango.ctegd.uga.edu/jkissingLab/SWS/ToxodbAnnotatedWebservices/SearchForGenes/TextIDsOrganism/Organism/GenesByTaxon.sawadl','A web service which allows users to search genes based on an organism or a list of organisms.',NULL,NULL,NULL,NULL,1,1,0,0,0,NULL,NULL,NULL,NULL,NULL,'2025-08-27 14:16:33.032919','2025-08-27 14:16:33.038613',NULL,NULL,3,NULL,2),(4,'tact','biotools:tact','TACT','none','http://jbirc.jbic.or.jp/tact/','Automated tool for conducting functional annotation of transcripts that integrates sequence similarity searches and functional motif predictions. It was originally developed as an automatic annotation pipeline for the Human Full-length cDNA Annotation Invitational (H-Inv) project.',NULL,NULL,NULL,NULL,0,1,0,0,0,NULL,NULL,NULL,NULL,NULL,'2025-08-27 14:17:06.769798','2025-08-27 14:20:25.738435',NULL,NULL,4,NULL,2),(5,'tact','biotools:tact','TACT','none','http://jbirc.jbic.or.jp/tact/','Automated tool for conducting functional annotation of transcripts that integrates sequence similarity searches and functional motif predictions. It was originally developed as an automatic annotation pipeline for the Human Full-length cDNA Annotation Invitational (H-Inv) project.',NULL,NULL,NULL,NULL,1,1,0,0,0,NULL,NULL,NULL,NULL,NULL,'2025-08-27 14:17:06.769798','2025-08-27 14:20:25.745840',NULL,NULL,5,NULL,2),(6,'rnaeditingatlas','biotools:rnaeditingatlas','RNAeditingAtlas','none','http://srv00.recas.ba.infn.it/editing/','An Atlas of RNA editing events in human tissues.',NULL,NULL,NULL,NULL,0,1,0,0,0,NULL,'Free of charge',NULL,'Emerging',NULL,'2025-08-27 14:20:50.716066','2025-08-27 14:21:08.973003',NULL,NULL,6,NULL,2),(7,'rnaeditingatlas','biotools:rnaeditingatlas','RNAeditingAtlas','none','http://srv00.recas.ba.infn.it/editing/','An Atlas of RNA editing events in human tissues.',NULL,NULL,NULL,NULL,1,1,0,0,0,NULL,'Free of charge',NULL,'Emerging',NULL,'2025-08-27 14:20:50.716066','2025-08-27 14:21:08.977887',NULL,NULL,7,NULL,2),(8,'extract','biotools:extract','EXTRACT','none','https://extract.jensenlab.org/','EXTRACT identifies genes/proteins, chemical compounds, organisms, environments, tissues, diseases, phenotypes and Gene Ontology terms mentioned in a given piece of text and maps them to their corresponding ontology/taxonomy entries.',NULL,NULL,NULL,NULL,1,1,0,0,0,NULL,'Free of charge',NULL,'Mature','BSD-2-Clause','2025-08-27 14:21:24.909536','2025-08-27 14:21:24.912046',NULL,NULL,8,NULL,2);
